-- 0289 naturaleza (inventario_naturaleza_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24164','espacio','Parque Natural de Babia y Luna, Hoz de las Palomas y Embalse de Barrios de Luna','Colosal paraje de montaña donde una inmensa lámina de agua de color turquesa permanente se encaja entre los monumentales farallones de roca caliza gris del Devónico. Las laderas verticales albergan sabinares albares relictos de gran valor fitogeográfico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24165','espacio','Cañón del río Selmo, estrechos de Sobrado y cuevas de pizarra','Impresionante desfiladero fluvial en los confines occidentales del Bierzo, excavado sobre pizarras y cuarcitas paleozoicas. Las paredes del cañón presentan pendientes   vertiginosas cubiertas de frondosos bosques de castaño centenario y encinares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24166','espacio','Vega baja del río Órbigo y confluencia del río Tuerto','Espacio aluvial horizontal donde confluyen dos importantes cursos hídricos leoneses sobre depósitos de gravas. Ofrece una panorámica de la amplitud de la cuenca sedimentaria con sotos de ribera estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24167','espacio','Gargantas del río Omaña y Valle de Amío','Entorno montañoso caracterizado por un relieve quebrado sobre materiales silíceos y calizas. El río Omaña discurre encajonado entre laderas escarpadas cubiertas de robledales de roble melojo y abedules con aguas de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24168','espacio','Terrazas del río Esla y llanuras bajas','Espacio plano de la cuenca sedimentaria compuesto por potentes depósitos de gravas y limos cuaternarios transportados por el Esla. Paisaje estrictamente horizontal de horizontes diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24206','espacio','Confluencia del río Sil y el Burbia y escarpes aluviales','Nudo hidrológico de gran valor contemplativo donde las aguas cristalinas del Burbia vierten en el curso del Sil. Ofrece una panorámica de amplias terrazas de cantos rodados flanqueadas por vertientes montañosas cubiertas de monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24169','espacio','Cañón del río Sil y gargantas del Bierzo Alto','Tramo fluvial donde el río Sil corta de forma sinuosa las estructuras de pizarras del Carbonífero, labrando   un valle encajonado de laderas de fuerte pendiente cubiertas de encinar mediterráneo y robledales residuales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24170','espacio','Valle del río Tremor, garganta de Albares y picos de cuarcita','Paisaje quebrado del Bierzo Alto caracterizado por valles profundos esculpidos sobre pizarras y areniscas. Ofrece una perspectiva visual salvaje de laderas boscosas de rebollo que caen de forma vertiginosa sobre los riachuelos de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24171','espacio','Cañón del río Valcarce y castañares de Trabadelo','Desfiladero de montaña atlántica labrado por el río Valcarce en el zócalo hercínico con pendientes pronunciadas. Alberga majestuosos e impenetrables bosques de castaños centenarios y masas de roble melojo de umbría bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','espacio','Sierra de la Cabrera, Lago de Truchillas y río Eria','Impresionante paisaje de alta montaña caracterizado por el Monumento Natural del Lago de Truchillas, una laguna perenne de origen glaciar encajada en un circo de pizarras y cuarcitas. Ofrece canchales de piedra, cascadas de montaña y un aislamiento visual salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24173','espacio','Riberas del río Órbigo y canales del Páramo','Tramo aluvial llano donde el río Órbigo discurre sobre depósitos de cantos rodados del Cuaternario. Ofrece una vista limpia y diáfana de la llanura de inundación con pequeñas alamedas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24174','espacio','Parameras del Páramo central y llanuras agrarias','Terreno estrictamente plano de la submeseta norte constituido por arcillas y arenas finas. Destaca únicamente por la regularidad de su horizonte despejado desprovisto de accidentes topográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24185','espacio','Valle del río Turienzo y rañas maragatas','Relieve de piedemonte caracterizado por colinas arcillo-arenosas con abundancia de cantos cuarcíticos estables sobre suelos rojizos. Ofrece visuales limpias interrumpidas por pequeños encinares fragmentados arbustivos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24175','espacio','Cuenca de la Sobarriba y lomas arcillosas','Relieve ondulado suave situado en el interfluvio de los ríos Porma y Torío compuesto por margas del Terciario. Destaca por sus oteros y cárcavas labradas por la escorrentía superficial de gran interés cromático ocre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24176','espacio','Llanuras del Páramo y horizontes de la meseta','Paisaje horizontal de la meseta meridional leonesa compuesto por depósitos aluviales antiguos. Presenta formas suaves de relieve plano con horizontes limpios de vegetación arbórea nativa compacta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24177','espacio','Hoces de Valdeteja (río Curueño), cascada de Faro y pico Bodón','Espectacular y colosal cañón fluvial labrado sobre la caliza de montaña carbonífera con paredes verticales de cientos de metros de caída limpia. Presenta espectaculares formaciones kársticas, saltos de agua cristalina y hayedos de umbría de un impacto contemplativo excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24178','espacio','Oteros del sur leonés y lomas arcilleras','Relieve de colinas bajas arcillosas sujetas a una intensa erosión que genera pequeñas cárcavas y valles secos. Ofrece una estampa austera de contrastes lumínicos sobre los pliegues del terreno desnudo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24179','espacio','Hoces del río Curueño (bajas), Peña Valdorria y saltos de agua','Entrada meridional a los cañones calcáreos de la cordillera Cantábrica. Ofrece imponentes murallones verticales calizos grises, una ribera prístina de sauces y chopos, y formaciones de lapiaces y oquedades naturales de disolución kárstica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24180','espacio','Cuenca alta del río Esla (este) y lomas sedimentarias','Plataforma sedimentaria con suaves ondulaciones de arenas y arcillas del Neógeno. El atractivo visual radica en la inmensidad de sus horizontes despejados y pequeños encinares marginales estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','espacio','Escarpes del río Cea y terrazas del sur','Frente de muelas arcilloso-calcáreas cortadas por la acción erosiva del cauce bajo del río Cea en el límite provincial con Zamora. Ofrece panorámicas despejadas de las amplias vegas desde los bordes de la plataforma tabular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24182','espacio','Valle del río Tuerto bajo y llanuras del Jerga','Tramo aluvial donde el río discurre sobre sedimentos cuaternarios finos en la transición maragata. Destaca por la horizontalidad de sus campos y las pequeñas formaciones de matorral mediterráneo de las lomas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24183','espacio','Valle del Alto Cea, pico Peñacorada y robledales de Valderrueda','Entorno montañoso caracterizado por el encajonamiento del río Cea entre potentes estructuras calizas y de pizarra del paleozoico. Ofrece frondosos bosques de roble melojo y hayedos que tapizan laderas de fuertes pendientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24184','espacio','Valle del río Samario y cordales de cuarcita','Paisaje quebrado de los Montes de León caracterizado por valles profundos esculpidos sobre pizarras y areniscas. Ofrece una perspectiva visual salvaje de laderas boscosas continuas que caen sobre arroyos de aguas hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24187','espacio','Lomas arcilleras del Páramo bajo y cuevas de tierra','Relieve ondulado muy suave de materiales arcillosos y margas del Terciario terminal. Ofrece un paisaje estepario diáfano caracterizado por los sutiles perfiles erosivos de sus colinas bajas redondeadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24188','espacio','Escarpes del río Esla (Las Terrazas de Valencia)','Colosales acantilados arcillo-arenosos de color ocre y rojizo labrados por la acción erosiva del río Esla sobre los materiales de la cuenca sedimentaria, configurando un frente vertical de gran impacto geométrico y visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24191','espacio','Llanuras de Tierra de Campos leonesa y arroyo del Olmo','Espacio estrictamente horizontal compuesto por arcillas y limos miocénicos sometidos a escorrentía superficial efímera. Destaca únicamente por la regularidad de su horizonte despejado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24189','espacio','Valle del arroyo de la Virgen y lomas del Páramo','Relieve suave de colinas bajas compuesto por sedimentos terciarios de la cuenca de León. Ofrece una estampa rural de formas redondeadas por la erosión hídrica superficial y pequeños encinares fragmentados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24190','espacio','Llanuras del sureste leonés y terrazas de arcilla','Terreno horizontal constituido por sedimentos finos arcillo-limosos desprovisto de accidentes topográficos notables o masas forestales continuas, de interés centrado en la inmensidad del llano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24193','espacio','Valle del río Curueño medio y estribaciones calizas','Espacio de transición geológica caracterizado por el encajonamiento del río Curueño en las faldas de la cordillera Cantábrica. Destaca por la pureza de su lecho aluvial y por sus densas formaciones de bosque de ribera y robledales de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','espacio','Riberas del río Cúa, Corral de los Lobos y encinares cantábricos','Entorno quebrado del Bierzo occidental donde el río Cúa esculpe un valle encajonado en materiales pizarrosos. Destaca por albergar un frondoso bosque de galería y raros reductos de encinar de clima atlántico mediterraneizado sobre escarpes rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24197','espacio','Vega del río Bernesga y confluencia con el Torío','Amplia llanura de inundación aluvial del Cuaternario donde se unen dos importantes cuencas fluviales leonesas. Ofrece una panorámica de terrazas llanas de gravas y limos flanqueadas por alamedas fragmentadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24198','espacio','Valle del río Valcarce alto, gargantas del Cenza y Ancares orientales','Paisaje montañoso atlántico en la entrada natural a Galicia configurado por profundos valles labrados sobre pizarras y micaesquistos hercínicos. Alberga masas densas de castañares viejos, robledales y un curso fluvial alpino de aguas procedentes de las altas cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24194','espacio','Monumento Natural de las Hoces de Vegacervera (río Torío)','Impresionante desfiladero fluvial con paredes verticales calizas colosales de más de 100 metros de caída limpia y angostura extrema que aprisiona el curso cristalino del río Torío. Las formaciones de lapiaces y callejones de roca en las cumbres superiores son de gran impacto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24199','espacio','Valle del río Porma, dehesa de robles y muelas de Candanedo','Espacio donde el valle fluvial del Porma se ensancha suavemente rodeado de colinas de calizas y areniscas. Ofrece una composición visual de gran verdor con masas compactas de roble melojo que tapizan las vertientes y ricas alisedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24201','espacio','Valle medio del río Porma y terrazas de aluvión','Amplio valle aluvial compuesto por potentes depósitos de gravas y limos cuaternarios transportados por el río Porma, ofreciendo una vista diáfana del cauce fluvial flanqueado por sauces, fresnos y chopos estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','espacio','Valle de Laciana (Reserva de la Biosfera), brañas de Leitariegos y pico Cornón','Espectacular entorno de alta montaña caracterizado por valles glaciares profundos esculpidos en pizarras y cuarcitas paleozoicas, rodeados de picos que rozan los 2.200 metros. Alberga masas forestales prístinas de roble melojo, abedules y acebedos de valor ecológico extremo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24203','espacio','Oteros orientales y lomas de arcilla','Relieve ondulado de colinas bajas arcillomargosas del Mioceno sujetas a una intensa erosión que genera pequeñas cárcavas y valles secos. Ofrece una estampa de contrastes lumínicos sobre el terreno labrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24205','espacio','Parameras del Páramo central y humedales de escorrentía','Altiplano estrictamente llano compuesto por potentes depósitos de gravas y arcillas cuaternarias cementadas. Presenta un relieve marcadamente horizontal de horizontes limpios con sutiles valles secos y lagunas estacionales naturalizadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24207','espacio','Vega baja del río Esla y terrazas fluviales','Espacio de llanura aluvial horizontal de sedimentación limosa y arenosa del Cuaternario. El valor contemplativo reside en la amplitud visual de la cuenca y en la presencia del soto de ribera fragmentado que marca los cursos hídricos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','espacio','Valle del Burbia, Garganta del Valcarce y umbrías de la Leitosa','Confluencia de dos colosales valles fluviales labrados sobre el zócalo pizarroso hercínico en la puerta de entrada a los Ancares. Ofrece imponentes laderas boscosas de castaños centenarios y robledales que caen sobre cauces rápidos de aguas transparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24210','espacio','Puerto de Manzanal y cabeceras del río Tuerto','Relieve quebrado que marca la transición geográfica natural entre la cuenca del Bierzo y la meseta leonesa sobre pizarras y areniscas. Ofrece una panorámica   limpia de laderas cubiertas de densos jarales y masas estables de pino silvestre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24211','espacio','Terrazas fluviales del río Esla meridional','Terreno horizontal desprovisto de accidentes topográficos notables constituido por limos y arenas cuaternarias transportados por el río Esla. Destaca únicamente por la fisonomía horizontal y diáfana del horizonte de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24901','espacio','Reserva de la Biosfera de Los Argüellos, Puerto de Pajares y Valle de Fontún','Entorno de alta montaña cantábrica de geología caliza monumental con imponentes crestas, canchales y picos de perfil alpino. Las laderas presentan vertiginosas pendientes cubiertas de hayedos maduros e impresionantes cascadas de montaña de aguas hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24212','espacio','Terrazas altas del río Esla y escarpes arcillosos','Frente de colinas arcillosas de la cuenca sedimentaria que han sido modeladas por la dinámica erosiva del río Esla. Ofrece una vista nítida del retroceso de las vertientes de la plataforma y un paisaje desprovisto de relieve abrupto severo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24213','espacio','Valle del río Cea medio y masas forestales de rebollo','Relieve ondulado de la meseta norte caracterizado por arenas silíceas y arcillas terciarias cubiertas por una masa continua de roble melojo. Ofrece una panorámica tranquila de formas redondeadas por la escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24214','espacio','Valle del río Tuerto medio y campiña de la Cepeda','Tramo de llanura aluvial encajada entre colinas bajas de cantos rodados cuaternarios cementados y arcillas. Su interés contemplativo radica en los perfiles erosivos de las laderas y los sutiles meandros que dibuja el río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24215','espacio','Valle del río Cea alto y terrazas aluviales','Paisaje característico de la plataforma sedimentaria leonesa con suaves ondulaciones de arcillas miocénicas. Ofrece horizontes abiertos y despejados sin relieves abruptos notables con pequeñas formaciones de alamedas ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24216','espacio','Valle del río Duerna alto y formaciones de rañas','Paisaje de piedemonte caracterizado por un relieve ondulado de arenas y arcillas con abundancia de cantos cuarcíticos estables sobre suelos rojizos de gran valor geológico meseteño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24217','espacio','Llanuras de las Matas y valles secos','Espacio estrictamente plano compuesto por arcillas y limos miocénicos sometidos a escorrentía superficial efímera. Destaca únicamente por la regularidad de su horizonte despejado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24218','espacio','Llanura aluvial del río Esla medio','Término municipal reducido asentado de forma horizontal sobre los depósitos de gravas y limos del curso medio del Esla. Destaca únicamente por la regularidad visual de su llanura de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24222','espacio','Valle bajo del río Torío y cerros calizos menores','Espacio de transición geológica caracterizado por el encajonamiento del río Torío en las colinas calcáreas   prelitorales de la capital leonesa. Ofrece visuales diáfanas del cauce fluvial flanqueado por sauces y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24223','espacio','Riberas del río Órbigo y canales de inundación','Tramo aluvial llano donde el río Órbigo discurre sobre depósitos de cantos rodados del Cuaternario. Ofrece una vista limpia y diáfana de la llanura de inundación con pequeñas alamedas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24224','espacio','Lomas del Órbigo occidental y arcillas de campiña','Relieve ondulado de la campiña leonesa moldeado sobre margas y sedimentos finos terciarios propensos a la erosión laminar, ofreciendo una visual despejada de la cuenca baja de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24225','espacio','Escarpes del río Porma y cerros de la Sobarriba','Frente de colinas arcillosas y margas del Mioceno que han sido cortadas de forma sinuosa por la dinámica erosiva del río Porma. Ofrece una vista de amplias terrazas aluviales de tonos ocres de gran valor estético.   León).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24227','espacio','Confluencia aluvial de los ríos Bernesga y Torío','Espacio estrictamente plano compuesto por depósitos de gravas y limos del Cuaternario en el fondo del valle leonés. Ofrece una visual despejada dominada por la horizontalidad del terreno y las pequeñas formaciones de sotos de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24228','espacio','Terrazas fluviales del río Órbigo y vegas bajas','Llanura de sedimentación aluvial caracterizada por relieves horizontales de cantos rodados y arenas finas. Permite observar la amplitud diáfana de la cuenca sedimentaria central leonesa y las alineaciones de vegetación ripícola estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24229','espacio','Cabecera del río Valderaduey y lomas arcillosas','Relieve ondulado de la campiña oriental leonesa, labrado sobre materiales arcillo-arenosos del Terciario propensos a la erosión laminar. Ofrece horizontes limpios de carácter estepario con sutiles contrastes cromáticos ocres en sus laderas.   ¡Objetivo cumplido con el máximo rigor! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','espacio','Forat d''Abella, riscos de Carreu y cañón del río Abella','Impresionante desfiladero y arco de roca natural horadado de forma monumental en las verticales paredes calizas de la Sierra de Carreu. Ofrece una fisonomía de estratos geológicos cuneiformes y cortados de piedra gris que dominan visualmente el fondo de la cuenca prepirenaica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','espacio','Desfiladero de Mont-rebei (vertiente oriental) y Sierra del Montsec d''Ares','Uno de los cañones fluviales más sobrecogedores y puros de la Península Ibérica, donde el río Noguera Ribagorzana corta en vertical murallones de piedra caliza de más de 500 metros de altura. La magnitud geológica del desfiladero mineral y la nitidez de sus estratos cretácicos configuran un paisaje sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','espacio','Ribera del río Sió y llanuras de la meseta de la Segarra','Tramo aluvial de llanura sedimentaria donde el río Sió discurre de forma perezosa sobre materiales arcillosos y de margas terciarias. Ofrece una composición visual diáfana de horizontes limpios con pequeñas hileras de sotos de ribera compuestos por álamos y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25038','espacio','Escarpes arcillosos del río Segre y llanuras de aluvión','Frente de terrazas fluviales cuaternarias e imponentes ripados de arcillas y limos miocénicos esculpidos por la dinámica erosiva del río Segre. Ofrece un paisaje llano elevado muy plástico por sus gradaciones cromáticas ocres y las amplias panorámicas sobre la vega fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90612','espacio','Umbrías de la Sierra del Cadí y riberas del río Segre','Vertiente de alta montaña prepirenaica caracterizada por los colosales contrafuertes y farallones de calizas del mesozoico que anuncian el macizo del Cadí. Alberga frondosos bosques de pino negro de umbría, canchales de piedra y cursos de agua hipertransparentes de montaña alta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90613','espacio','Meandro del río Segre y llanuras bajas sedimentarias','Terreno de llanura aluvial cuaternaria muy estable donde el río Segre ensancha su curso depositando gravas y arenas. Destaca por la regularidad visual del soto ribereño y la fisonomía diáfana de la cuenca baja de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90614','espacio','Riberas del río Noguera Ribagorzana (tramo bajo) y muelas de yeso','Espacio de transición geológica donde el curso fluvial erosiona los estratos de yeso cristalino y arcillas miocénicas creándose pequeños escarpes y badlands. Ofrece destellos minerales en las pendientes desnudas bajo la luz del sol.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90615','espacio','Parameras secas del Segrià sur','Altiplano horizontal severo de calizas lacustres y arcillas del terciario medio sometido a una acusada aridez estival. Ofrece una fisonomía esteparia austera de horizontes despejados con sutiles formas de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90616','espacio','Hoz del río Noguera Ribagorzana y compuertas del canal','Estrechamiento fluvial donde el río corta los últimos relieves calizos prepirenaicos antes de entrar en la gran cuenca sedimentaria. Ofrece una vista nítida de sotos ripícolas estables compuestos por alisos, sauces y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90617','espacio','Tossal de Mund y terrazas del río Segre','Pequeña elevación testigo de origen sedimentario que rompe de forma suave la monotonía de la llanura del Segre. Ofrece una visual limpia de la dinámica fluvial baja de sedimentación aluvial del Cuaternario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90618','espacio','Timoneda de Alfés y meandros del río Set','Excepcional e histórico altiplano calcáreo tabular de carácter estepario semiárido único en Cataluña, donde el río Set labra un valle encajonado en la roca viva. Presenta una textura desértica ruda de gran pureza geomorfológica y silencio visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25019','espacio','Llanura de la Litera leridana y balsas estacionales','Espacio plano de colinas de pendiente mínima compuesto por depósitos de arenas y arcillas miocénicas muy estables. El interés contemplativo se reduce a la inmensidad del horizonte llano mesetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25020','espacio','Espacio Natural de los Ribarrojos, meandros del Ebro y barranco de la Vall','Impresionante tramo donde el relieve de las Garrigues meridionales cae de forma abrupta hacia el lecho del río Ebro creando colosales desfiladeros y cortados calizos. Las vertientes escarpadas están tapizadas de un denso pinar mediterráneo virgen.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25021','espacio','Saso de Almenar y balsas del canal','Plataforma elevada compuesta por depósitos antiguos de gravas cuaternarias cementadas que define el norte de la comarca. Ofrece amplios horizontes visuales limpios desprovistos de relieve abrupto de consideración.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','espacio','Desfiladero del Mu (Río Segre) y Sierra de Carbonera','Espectacular y colosal cañón fluvial donde el río Segre fractura de forma sinuosa los murallones calcáreos de las sierras prepirenaicas marginales. Presenta imponentes paredes rocosas de más de 200 metros de caída libre, agujas de piedra y tobas calcáreas fósiles de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25023','espacio','Llanos de Alpicat y colinas de yesos menores','Terreno horizontal constituido por sedimentos finos terciarios en la periferia leridana con formas suaves modeladas por la escorrentía superficial. Paisaje horizontal de horizontes limpios y despejados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','espacio','Parque Natural del Alto Pirineo, circo glaciar de Saboredo y cabecera del Noguera Pallaresa','Uno de los santuarios ecológicos de alta montaña más colosales del Pirineo catalán, con valles glaciares profundos labrados en granitos y pizarras paleozoicas que superan los 2.800 metros de altitud. Alberga circos repletos de lagunas alpinas transparentes (estanys), canchales vertiginosos y bosques prístinos de pino negro.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25027','espacio','Llanura de Urgell y cuenca baja del río Ondara','Espacio marcadamente horizontal compuesto por depósitos sedimentarios cuaternarios de grano fino. Su valor estético radica en la inmensidad diáfana de un horizonte   limpio y plano, caracterizado por sutiles dinámicas de escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25029','espacio','Valle de la Femosa y lomas de Les Garrigues','Relieve de suaves muelas calcáreas y laderas arcillosas que limitan con la llanura de Urgell. Ofrece una estampa contemplativa de contrastes cromáticos entre los afloramientos de piedra caliza lacustre grisácea y los barrancos secos de tonos arcillosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25031','espacio','Valle de Arán y umbrías de la Sierra de Arres','Paisaje de alta montaña pirenaica asentado sobre imponentes vertientes de pizarras paleozoicas y esquistos que caen sobre el río Garona. Alberga majestuosos y densos bosques de abeto blanco y hayas relictas en valles colgados de origen glaciar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25032','espacio','Contrafuertes de la Sierra del Cadí y ribera del Segre','Término quebrado flanqueado por las monumentales e infranqueables paredes de roca caliza de la vertiente norte del Cadí. El paisaje ofrece profundos barrancos umbríos de gran pluviosidad, rodeados de masas estables de pino silvestre y canchales de piedra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','espacio','Desfiladero de Salgar y desfiladero del río Segre','Estrechamiento fluvial donde el río Segre corta las primeras muelas calizas del somontano prepirenaico. Ofrece interesantes fenómenos de disolución kárstica en la roca caliza viva, con abrigos y oquedades que se asoman de forma vertical sobre el lecho del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25036','espacio','Curso medio del río Set y lomas margosas','Cuenca erosiva de formas suaves labrada sobre materiales arcillosos y margas terciarias de la plataforma del Segrià sur. Destaca por el perfil de sus vertientes sujetas a erosión laminar y por las pequeñas masas arbustivas mediterráneas residuales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','espacio','Desfiladero de Collegats, río Noguera Pallaresa y fuente salada de Gerri','Uno de los cañones fluviales más sobrecogedores del Pirineo, flanqueado por colosales e imponentes paredes verticales de conglomerados rojizos erosionados en formas caprichosas (como la roca del Argentería). Cuenta además con una surgencia de agua hipersalina de gran valor hidrogeológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','espacio','Ripas de Balaguer (Río Segre) y llanura de aluvión','Frente de potentes terrazas fluviales elevadas compuestas por arcillas y yesos miocénicos cortadas de forma tajante por la acción del Segre. Ofrece un marcado contraste cromático y visual entre las áridas pendientes arcillosas y la verde vega de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25041','espacio','Llanuras fluviales del llano de Urgell','Terreno estrictamente horizontal constituido por sedimentos finos arcillo-limosos del Terciario central. Su interés estético se limita a la inmensidad diáfana de un horizonte completamente abierto y desprovisto de accidentes topográficos notables.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25042','espacio','Estrechos del Rialb, Forat de Bulí y cañón del río Rialb','Espectacular y angosto desfiladero kárstico labrado sobre potentes estratos de calizas eocénicas por aguas hipertransparentes. Presenta colosales paredes verticales que casi llegan a tocarse, cuevas e impresionantes formaciones de tobas calcáreas goteantes de gran valor botánico rupícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25046','espacio','Llanos de Belianes y cuenca del río Corb','Paisaje horizontal de transición hacia la cuenca de Urgell constituido por arcillas y sedimentos limosos cuaternarios finos. Destaca por sus horizontes completamente diáfanos y limpios donde las variaciones visuales dependen de las tonalidades de la tierra estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90620','espacio','Llanura aluvial del Urgell y balsas marginales','Espacio estrictamente plano compuesto por terrazas sedimentarias cuaternarias estables desprovistas de relieve abrupto notable. Ofrece una fisonomía horizontal uniforme con sutiles fenómenos de escorrentía superficial difusa en sus márgenes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25047','espacio','Llanos de Bellcaire y canal de Urgell (entorno basal)','Llanura de sedimentación cuaternaria de topografía regular y suave compuesta por limos y arenas finas transportadas por antiguos cauces. El interés visual se concentra en el diáfano horizonte lineal y la inmensidad de la cuenca sedimentaria.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25049','espacio','Sierra de Almenara (vertiente sur) y muelas arcillosas','Pequeño relieve elevado y tabular de origen sedimentario que interrumpe la monotonía del llano de Urgell, compuesto por calizas lacustres y margas. Ofrece una nítida visual de los procesos de erosión de las vertientes y amplias panorámicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25050','espacio','Valle de la Femosa y lomas del llano','Tramo aluvial donde la cubeta erosiva labra formas muy suaves sobre materiales del terciario medio. Permite la contemplación de un paisaje diáfano marcado por sutiles ondulaciones arcillosas y texturas de tierra desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25051','espacio','Parque Natural del Cadí-Moixeró, valle de la Llosa y riscos de Baltarga','Uno de los enclaves más colosales del Pirineo oriental, caracterizado por el abismal e imponente murallón calizo de la cara norte del Cadí. Cuenta con un majestuoso valle de modelado glaciar profundo flanqueado por densos bosques subalpinos de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25052','espacio','Llanuras aluviales del río Corb inferior','Término municipal asentado sobre sedimentos limosos de inundación cuaternaria de relieve estrictamente llano. Su valor contemplativo radica en la regularidad geométrica del relieve de la depresión central catalana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25053','espacio','Llanos del Segrià norte y balsas de escorrentía','Terreno horizontal con pendientes mínimas constituido por sedimentos miocénicos estables de la cuenca leridana. Presenta una fisonomía esteparia diáfana desprovista de accidentes geográficos notables o de masas forestales continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25055','espacio','Valle de la riera de Biosca y lomas de la Segarra','Paisaje de media montaña suave caracterizado por un relieve ondulado de calizas y margas con presencia de pequeños barrancos umbríos. Destaca por la armonía visual de sus formaciones de quejigar y la tranquilidad de sus pequeños cursos de agua.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25056','espacio','Valles de Valldebovera y riscos de las Garrigues meridionales','Relieve quebrado y áspero que marca la transición hacia el valle del Ebro, esculpido sobre estratos de calizas y arcillas oligocénicas. Destaca por el aislamiento visual de sus valles encajonados cubiertos por una masa densa y continua de pinar de pino blanco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25059','espacio','Bajo Arán, gargantas del río Garona y umbrías de Portet','Paisaje pirenaico axial caracterizado por un relieve de pendientes vertiginosas labrado en pizarras y granitos paleozoicos por la erosión glaciar. Alberga majestuosas masas continuas de hayedos y abetales puros que se asoman de forma vertical sobre el curso transparente del Garona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25060','espacio','Valle del río Llobregós y muelas de la Segarra norte','Corte erosivo suave que rompe la continuidad de las muelas calcáreas y de yesos en el límite con la Noguera. Ofrece una vista nítida de los estratos sedimentarios terciarios y pequeñas formaciones de matorral mediterráneo y quejigar arbustivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25061','espacio','Valle de Cabó, riscos de Ares y Sierra de Boumort','Profunda y aislada cuberta prepirenaica labrada en calizas mesozoicas, flanqueada por las imponentes paredes rocosas de la Sierra de Boumort. Ofrece un paisaje mineral agreste de gran fuerza visual con extensas tarteras, lapiaces altos y pinares de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25062','espacio','Desfiladero de Terradets (vertiente sur), Hoz de Doll y confluencia del Segre-Noguera Pallaresa','Uno de los nudos geomorfológicos más monumentales de Cataluña. Presenta colosales acantilados verticales de roca caliza jurásica de más de 300 metros que aprisionan los cursos de agua cristalina, y el pasillo geológico de Doll con sus estratos calcáreos cuneiformes perfectos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25063','espacio','Valle de Toran y desfiladeros del Bajo Arán','Extraordinario valle de montaña atlántica de aislamiento geográfico absoluto, encajonado de forma vertiginosa entre murallones de pizarras y esquistos negros. Sus laderas están tapizadas por selvas impenetrables de abetos y hayas centenarias, con arroyos torrenciales de aguas hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25904','espacio','Desfiladero de Terradets (vertiente norte) y riscos del Montsec d''Ares','Impresionante corte geológico donde el río Noguera Pallaresa quiebra en vertical el gran murallón calcáreo del Montsec. Ofrece una fisonomía monumental de paredes de piedra caliza gris desnudada de más de 500 metros de caída libre, ideal para la contemplación geológica pura.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25064','espacio','Riera de Madrona y lomas de yesos de la Ribera','Relieve de media montaña suave donde la riera excava formaciones margosas y yesíferas. Destaca por el contraste cromático de los taludes erosionados y pequeños rodales de quejigos y pinos que colonizan los estratos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25067','espacio','Valle de la Femosa y secanos de Mas de Melons','Paisaje árido y horizontal de las Garrigues bajas constituido por arcillas y calizas lacustres. Ofrece un paisaje estepario de horizontes limpios con sutiles formas de erosión remontante y vegetación arbustiva mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25068','espacio','Llanura aluvial del Pla d''Urgell','Terreno estrictamente plano de sedimentación cuaternaria caracterizado por la ausencia de elevaciones notables. El valor visual radica en la limpieza geométrica del horizonte y la inmensidad de la planicie.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25069','espacio','Riscos de la Sierra de la Casalta y ribera del Farfanya','Pequeño estrechamiento fluvial que corta muelas calizas del terciario inferior, dejando taludes y escarpes rocosos suaves. Ofrece una vista nítida de la degradación caliza y pequeñas oquedades kársticas aéreas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25071','espacio','Murallón norte de la Sierra del Cadí y valle de Cava','Impresionante paisaje alpino caracterizado por las verticales e imponentes crestas calcáreas de la cara norte del macizo del Cadí. Alberga espectaculares canales de avalanchas relictas, canchales vertiginosos de piedra gris y densos bosques de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25072','espacio','Valle del río Ondara y costeras de la Segarra','Relieve ondulado de la meseta central catalana modelado sobre arcillas y margas de tonos grisáceos. Destaca por los perfiles erosivos de sus vertientes y sutiles bandas geológicas expuestas por las escorrentías estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25073','espacio','Valle del río Set y barrancos arcillosos','Cuenca erosiva con muelas de cumbre plana compuestas por calizas y arcillas oligocénicas. Ofrece una fisonomía mediterránea ruda, con pequeños barrancos secos cubiertos de jarales y pino blanco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25074','espacio','Valle del río Corb y lomas calizas','Tramo donde el río Corb labra un valle encajonado entre colinas margocalizas de formas suaves.   Destaca por la armonía visual de sus vertientes y pequeños rodales de encinar mediterráneo bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25075','espacio','Valle del río Cardener y pinares del Solsonès','Espacio fluvial donde el río se encaja entre relieves montañosos de conglomerados y areniscas. Ofrece un paisaje verde continuo de masas forestales de pino laricio que flanquean un cauce de aguas tranquilas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','espacio','Desfiladero de Tresponts, río Segre y rocas de la Pansa','Colosal desfiladero fluvial donde el río Segre corta verticalmente murallones de roca caliza mesozoica de más de 300 metros de caída limpia. Destaca por la magnitud de sus estructuras tectónicas replegadas visibles y sus formaciones kársticas.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25163','espacio','Fuentes del Cardener y Port del Comte','Impresionante surgencia kárstica multifocal donde brotan con fuerza las aguas iniciales del río Cardener a los pies de las cumbres calcáreas de la Sierra del Port del Comte. El entorno destaca por sus imponentes canchales y la pureza visual de sus densos bosques subalpinos de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25161','espacio','Desfiladero de Erinyà, riscos de Pessonada y río Flamisell','Impresionante corte transversal sobre murallones calizos cretácicos labrado en vertical por las aguas del Flamisell. Ofrece una fisonomía geológica de enormes murallas de piedra rojiza y gris que flanquean pasillos minerales de gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25078','espacio','Confluencia del río Noguera Ribagorzana y el río Segre','Importante nudo hidrológico aluvial de la depresión central donde ambos ríos unifican sus cauces sobre amplias terrazas de gravas y limos cuaternarios. Destaca por el contraste cromático de sus extensas alamedas y sotos de galería estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','espacio','Sierra de Almenara (vertiente norte) y barranco de Escumó','Relieve de muelas y colinas tabulares compuestas por calizas lacustres y arcillas del oligoceno en el somontano de la Noguera. Ofrece visuales diáfanas y limpias que permiten contemplar los sutiles procesos de escorrentía superficial en las pendientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90902','espacio','Valle del río Set y lomas de Les Garrigues orientales','Paisaje de colinas bajas calizas y arcillosas suavizadas por procesos de erosión antigua, característico de la plataforma garriguense. Ofrece un relieve de formas tranquilas interrumpido por pequeños barrancos secos y matorral xerófilo mediterráneo.   L''Albií (L''Albió) - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25076','espacio','Valle del río Set y escarpes calizos de las tumbas','Tramo donde el río Set corta los estratos calcáreos de la comarca formando pequeños farallones y oquedades naturales de disolución superficial. Ofrece una fisonomía ruda de texturas de roca desnuda integrada en un entorno estepario mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25168','espacio','Llanuras aluviales de la fosa de Urgell','Espacio estrictamente plano de sedimentación cuaternaria fina depositada por antiguos flujos fluviales. Su valor estético se limita a la inmensidad lineal de su horizonte abierto y desprovisto de accidentes topográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25030','espacio','Gargantas del río Segre y escarpes graníticos de Aristot','Angosto cañón fluvial donde el río Segre se encaja de forma violenta abriendo una profunda brecha en el zócalo paleozoico prelitoral. Las orillas rocosas verticales de tonos oscuros y la fuerza de las corrientes ofrecen una estampa de gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','espacio','Valle del Noguera Ribagorzana, cañón de Escales y umbrías de Sirès','Cabecera fluvial de alta montaña pirenaica donde el río discurre encajonado entre colosales murallones calcáreos que marcan la entrada al Pirineo axial. Presenta   imponentes formaciones de lapiaces, grandes canchales y frondosos bosques mixtos de hayas y robles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25206','espacio','Valle de la riera de Juncosa y lomas margosas','Depresión erosiva de pendientes muy suaves labrada sobre arcillas oligocénicas en el sector occidental de las Garrigues. Destaca por el perfil geométrico de sus vertientes sujetas a erosión laminar y pequeños matorrales mediterráneos.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25253','espacio','Nacimiento del río Set y vertientes de la Sierra de la Llena','Relieve abrupto que delimita el sur de Les Garrigues, modelado sobre potentes estratos calcáreos y areniscas. Ofrece un paisaje mediterráneo de montaña de gran impacto visual, donde el río Set da sus primeros pasos entre encinares frondosos y canchales de piedra gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25153','espacio','Valle de la riera de Vallplana y muelas de Les Garrigues altas','Relieve ondulado caracterizado por muelas calizas de cumbre aplanada que caen hacia pequeñas depresiones arcillosas. Destaca por el contraste de las texturas de la caliza grisácea expuesta y la fisonomía de sus barrancos secos mediterráneos.   Els Omells de na Gaia - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25082','espacio','Parque Nacional de Aigüestortes i Estany de Sant Maurici, Encantats y Estany de Sant Maurici','Uno de los paisajes de alta montaña más colosales y perfectos de Europa, configurado por el modelado glaciar sobre granitos del Pirineo axial. Destaca por las agujas gemelas de Els Encantats, que caen a plomo sobre una inmensa lámina de agua turquesa rodeada de abetales prístinos y circos alpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25088','espacio','Valle del río Segre y riscos de las Anesas','Vertiente de montaña prepirenaica caracterizada por laderas de pendientes extremas compuestas por calizas mesozoicas y pizarras. Ofrece amplios horizontes diáfanos sobre el cauce encajonado del Segre y las imponentes crestas grises de la cara norte del Cadí.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25085','espacio','Valle del río Sió y lomas de la Alta Segarra','Relieve ondulado de la meseta central catalana modelado sobre arcillas y margas de tonos grisáceos y azulados. Destaca por la regularidad de sus vertientes y sutiles procesos de escorrentía que exponen bandas geológicas del Terciario superior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27005','espacio','Valle de Àneu, río Noguera Pallaresa y humedales de Esterri','Colosal cubeta de origen glaciar donde el río Noguera Pallaresa ensancha su lecho aluvial formando praderas húmedas de gran valor botánico. Flanqueado por imponentes vertientes forestales de pino negro y abeto, ofrece una perspectiva nítida de la alta montaña pirenaica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25087','espacio','Valle de Cardós y vertientes del monte de Pui','Término quebrado de alta montaña integrado en el Parque Natural del Alto Pirineo, labrado sobre pizarras paleozoicas oscuras. Presenta valles colgados con arroyos de deshielo atronadores y laderas umbrías tapizadas por densas masas de pino silvestre y abedules.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25089','espacio','Coma de Burg y umbrías del macizo de Santa Magdalena','Paisaje alpino aislado y virgen caracterizado por valles de perfil cóncavo esculpidos por la acción glaciar sobre el zócalo hercínico. Alberga prados alpinos altos, canchales vertiginosos de pizarra y frondosos bosques mixtos que muestran una gran potencia cromática estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25908','espacio','Desfiladero de Tresponts (vertiente este) y riscos de Alinyà','Monumental cañón fluvial donde el río Segre corta en vertical imponentes murallones calcáreos mesozoicos de más de 300 metros de caída limpia. El término destaca por sus espectaculares estructuras tectónicas replegadas y gigantescos farallones grises colonizados por aves rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25093','espacio','Llanura aluvial del Pla d''Urgell','Espacio estrictamente plano de sedimentación cuaternaria fina, caracterizado por la ausencia absoluta de accidentes topográficos o elevaciones notables. El valor visual radica en la limpieza lineal del diáfano horizonte y en la amplitud de la cuenca.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25094','espacio','Roca de Foradada, risco del Malany y río Segre','Impresionante monclinal y muela calcárea que emerge de forma abrupta en el somontano de la Noguera, caracterizada por un gran orificio natural en la roca (foradada) esculpido por la erosión eólica. Ofrece una vista nítida de los estratos replegados del anticlinal y del curso bajo del Segre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44105','espacio','Cara norte de la Sierra del Cadí y barranco de la Vansa','Relieve de alta montaña alpina configurado por los colosales contrafuertes de calizas triásicas del macizo del Cadí. Destaca por sus pendientes vertiginosas, canales de avalanchas cubiertas de pino negro y la pureza visual de sus canchales de piedra gris expuesta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25097','espacio','Valles de Fuleda y lomas calcáreas de Les Garrigues orientales','Relieve ondulado de la plataforma oligocénica caracterizado por muelas de cumbre plana y pequeños barrancos secos de laderas arcillosas. Ofrece una fisonomía ruda de matorral mediterráneo y pino blanco que contrasta con la textura pedregosa de la caliza gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25098','espacio','Desfiladero de Terradets (cola) y cuenca del río Conques','Espacio de transición geológica donde las aguas fluviales erosionan los materiales blandos de la cuenca antes del gran corte kárstico del Montsec. Ofrece amplios horizontes visuales limpios sobre badlands margosos grises y terrazas aluviales bien definidas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25912','espacio','Llanos del Segrià occidental y balsas de escorrentía','Terreno estrictamente horizontal compuesto por depósitos arcillo-limosos estables del Mioceno terminal. Su interés contemplativo radica en la regularidad lineal de su horizonte abierto y en los sutiles procesos de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25099','espacio','Llanura aluvial del Pla d''Urgell y balsas marginales','Espacio plano de sedimentación cuaternaria fina depositada por antiguos cauces fluviales, desprovisto de accidentes topográficos. Ofrece un horizonte diáfano e infinito de gran uniformidad visual lineal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25100','espacio','Macizo del Pedraforca (vertiente occidental) y Sierra del Cadí','Uno de los espectáculos de montaña más sobregogedores del Pirineo catalán, dominado por la colosal e icónica silueta de horca calcárea del Pedraforca, esculpida por la erosión diferencial y la crioclastia. El anfiteatro alpino presenta inmensos canchales verticales, praderas alpinas altas y densos bosques de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25103','espacio','Valle del río Ondara y lomas de la Segarra occidental','Cuenca erosiva suave labrada sobre materiales arcillosos y de margas grisáceas de la meseta central catalana. Destaca por la geometría de sus vertientes sujetas a erosión laminar y pequeños matorrales de romero y coscoja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25105','espacio','Barranco de la Vall Major y secanos de Granyena','Paisaje árido y quebrado constituido por arcillas y calizas lacustres oligocénicas en el sector occidental de las Garrigues. Ofrece una fisonomía esteparia mediterránea ruda de sutiles barrancos secos y matorral bajo xerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25109','espacio','Valle del río Corb y escarpes calizos de la Segarra alta','Impresionante tramo donde el río Corb labra un valle encajonado de vertientes escarpadas y terrazas de calizas y margas del Mioceno. La vista ofrece un gran   contraste geomorfológico entre los páramos calizos superiores desnudados y las laderas cubiertas de encinar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25110','espacio','Llanos de Guissona y cuenca del río Sió','Espacio marcadamente horizontal y diáfano de la meseta central de la Segarra, compuesto por arcillas y calizas lacustres. Ofrece un horizonte de líneas limpias donde se aprecian sutiles formas de escorrentía superficial y campos esteparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25111','espacio','Valle del río Agua de Ora, riscos de Busa y desfiladero de la Corva','Extraordinario relieve del Prepirineo caracterizado por imponentes murallones y escarpes de conglomerados oligocénicos de formas cuneiformes perfectas. El fondo del cañón alberga una ribera prístina de aguas frías flanqueada por un denso bosque mixto y pinares subalpinos de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25112','espacio','Embalse de Santa Ana (cola) y meandros del río Noguera Ribagorzana','Cañón fluvial de calizas jurásicas donde las aguas del río penetran estrechamente antes de remansarse. Ofrece una panorámica de amplias láminas de agua turquesa encajonadas entre laderas de matorral mediterráneo y pinares que colonizan los escarpes rocosos verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','espacio','Yacimiento de icnitas de Orcau, riscos de Carreu y barrancos margosos','Depresión tectónica del prepirenaico caracterizada por un relieve abarrancado de margas grises intensamente erosionadas en badlands. El horizonte norte está custodiado por imponentes murallones de roca caliza y afloramientos del Cretácico de gran valor contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25910','espacio','Cadí-Moixeró, Cadí occidental y Valle de Josa','Paisaje alpino de primer orden nacional dominado por el colosal e infranqueable muro calizo de la cara sur de la Sierra del Cadí. Presenta espectaculares valles glaciares de perfil cóncavo, inmensos canchales de piedra, fuentes de agua purísima y densos bosques subalpinos de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25118','espacio','Valle de la riera de Juncosa y riscos de la Sierra de la Llena','Relieve ondulado y rudo que marca el límite meridional de Les Garrigues, compuesto por potentes capas de calizas eocénicas y arcillas. Ofrece visuales limpias de barrancos secos y laderas escarpadas cubiertas de densas masas estables de pinar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25119','espacio','Banquetas del Canal de Urgell (entorno forestal de ribera) y llanura aluvial','Espacio estrictamente plano de sedimentación fina del Cuaternario donde destacan las hileras de sotos ripícolas naturalizados creados por las filtraciones de agua. Ofrece una horizontalidad diáfana dominada por alisedas, chopos y sauces estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25121','espacio','Valle de Arán (Bajo Arán), gargantas del río Garona y umbrías de Bausen','Relieve pirenaico axial extremo caracterizado por pendientes vertiginosas labradas sobre pizarras oscuras, esquistos y mármoles paleozoicos. Alberga una selva impenetrable de hayas y abetos de umbría que se asoman verticalmente sobre el curso rápido y cristalino del Garona.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25122','espacio','Llanura endorreica del Pla d''Urgell y fosas limosas','Espacio marcadamente horizontal compuesto por depósitos sedimentarios finos cuaternarios en el sector norte de la comarca. Ofrece una fisonomía llana y diáfana de horizontes lineales limpios donde destacan los sutiles procesos de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25123','espacio','Valle de Cardós, circo glaciar de Certascan y lago de Certascan','Extraordinario paisaje de alta montaña en pleno Parque Natural del Alto Pirineo, que alberga el lago natural de origen glaciar más extenso y profundo de la cordillera. Sus cumbres de micaesquistos y granito superan los 2.800 metros, rodeadas de cascadas atronadoras de deshielo, canchales y prados alpinos puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25124','espacio','Gargantas de la riera de Canalda, Salí de Cambrils y riscos de Espluga','Complejo quebrado del Solsonès caracterizado por profundos cortes fluviales excavados sobre conglomerados y calizas oligocénicas. Destaca por albergar un barranco salino natural de gran interés hidrogeológico con formaciones de tobas goteantes y densas masas de pino laricio en umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25125','espacio','Valle de la Vall Major y lomas de Les Garrigues meridionales','Altiplano ondulado y árido constituido por calizas lacustres y arcillas oligocénicas que sufren una fuerte erosión hídrica superficial. Ofrece una estampa esteparia mediterránea con barrancos secos cubiertos de matorral xerófilo de romero y coscoja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','espacio','Valle de la Llosa, lagunas de la Pera y picos de la Tossa Plana de Lles','Espectacular relieve alpino del Pirineo oriental caracterizado por valles de modelado glaciar profundo esculpidos en granitos y pizarras. Presenta circos glaciares repletos de lagunas transparentes, vertiginosos canchales de piedra y extensas masas forestales subalpinas de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25128','espacio','Desfiladero de Terradets (vertiente este) y riscos de Llimiana','Imponente muela y murallón calcáreo del Montsec de Rúbies que se asoma de forma totalmente vertical sobre el cañón del río Noguera Pallaresa. Ofrece una panorámica geomorfológica monumental de estratos del Cretácico superior expuestos de más de 400 metros de caída libre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25129','espacio','Llanos de Llobera y dehesas de quejigo del Solsonès sur','Relieve de transición entre la plataforma de la Segarra y el Prepirineo, caracterizado por colinas calizas suaves y pequeñas dolinas de disolución kárstica. Ofrece una armoniosa composición de pastizales atlánticos fragmentados con encinares montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25130','espacio','Valle del río Corb y lomas de la cuenca baja','Depresión erosiva de pendientes muy suaves labrada sobre materiales arcillosos y margas terciarias en la comarca del Urgell. Destaca por el perfil de sus vertientes sujetas a erosión laminar y pequeños bosquetes mediterráneos marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25131','espacio','Confluencia de los ríos Cinca y Segre (Espacio Natural del Aiguabarreig)','Extraordinario nudo hidrológico y aluvial de primer orden peninsular donde se fusionan de forma majestuosa los cauces del Segre y el Cinca sobre extensas terrazas de cantos rodados. Ofrece una panorámica nítida de islas de sedimentación fluvial y una de las masas de sotos ripícolas más densas del este nacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25134','espacio','Riberas del río Farfanya y llanuras del Segre','Tramo de llanura aluvial cuaternaria donde elFarfanya describe meandros suaves antes de verter sus aguas en el Segre. Destaca por la horizontalidad de sus suelos de sedimentación limosa y pequeñas choperas que marcan el curso del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25135','espacio','Llanos de Miralcamp y fosas del Pla d''Urgell','Terreno horizontal con pendientes mínimas constituido por depósitos arcillo-limosos del Terciario central. Su valor contemplativo se reduce a la inmensidad diáfana de un horizonte abierto desprovisto de accidentes geográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27009','espacio','Llanura aluvial de la fosa de Urgell central','Espacio estrictamente plano de sedimentación cuaternaria fina depositada por antiguos flujos fluviales fluviales. Presenta una fisonomía horizontal uniforme de horizontes lineales limpios donde el interés visual es exclusivamente basal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25139','espacio','Parque Natural del Cadí-Moixeró, riscos de Aguiló y riberas del río Segre','Impresionante paisaje alpino dominado por los colosales murallones calcáreos de la cara norte de la Sierra del Cadí. Presenta espectaculares canales de aludes, canchales vertiginosos de piedra gris, fuentes de montaña prístinas y frondosos bosques subalpinos de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25140','espacio','Valle de Castellbò, barrancos del río del Cantó y pinares de la umbría','Término quebrado de alta montaña prepirenaica labrado sobre pizarras paleozoicas y calizas que generan fuertes desniveles topográficos. Ofrece una vista nítida de valles de perfil cóncavo cubiertos por un espeso y continuo manto forestal de pino silvestre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25142','espacio','Meandros del río Segre inferior y llanuras aluviales','Espacio aluvial horizontal compuesto por terrazas fluviales cuaternarias de limos, arenas y gravas depositadas por el río Segre. Destaca por la observación contemplativa de la dinámica del cauce y sus pequeños retazos de sotos ripícolas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25143','espacio','Valle del río Cercavins y colinas de Montornès','Cuenca erosiva con muelas calizas de cumbre aplanada y barrancos arcillosos marginales que rompen de forma suave el relieve de la meseta. Ofrece una panorámica de texturas sedimentarias con pequeños retazos de quejigar y encinar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25145','espacio','Valle del río Corb y escarpes de Nalec','Tramo donde el río Corb excava un valle encajonado de vertientes suaves compuestos por calizas y margas del Mioceno. Destaca por la armonía visual de sus laderas y por los sutiles sotos ripícolas que acompañan el curso fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','espacio','Circo de Colomèrs, nacimiento del río Garona (Uelhs deth Garona) y Parque Nacional de Aigüestortes (vertiente norte)','Uno de los epicentros de alta montaña más colosales y perfectos del planeta, esculpido sobre el batolito granítico del Pirineo axial. Alberga el circo de Colomèrs con más de cincuenta lagunas alpinas transparentes interconectadas, vertiginosos canchales de piedra, abetales prístinos y el espectacular brote kárstico de los ojos del Garona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25146','espacio','Riscos de Busa, cañón del río Agua de Ora y Valle de Ora','Extraordinaria e imponente estructura geológica del Prepirineo caracterizada por colosales murallones de conglomerados oligocénicos con paredes de caída vertical de cientos de metros de altura (Busa). El río corre confinado en un desfiladero prístino de aguas transparentes color turquesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25149','espacio','Desfiladero de Oliana, río Segre y riscos de la Sierra de Turp','Cañón fluvial donde las aguas del Segre penetran estrechamente entre imponentes murallones calcáreos mesozoicos antes de ensancharse en la cuenca. Ofrece una espectacular panorámica de estructuras tectónicas replegadas visibles y vertiginosos paredones de piedra gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25150','espacio','Valle del río Llobregós y escarpes calizos de Oliola','Tramo donde la cubeta erosiva labra un valle encajonado cortando las muelas de calizas lacustres y yesos del somontano de la Noguera. Ofrece una vista nítida de los diferentes estratos sedimentarios terciarios y pequeños matorrales de romero y coscoja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25155','espacio','Desfiladero de Tresponts (vertiente oeste), peñón de Santa Fe y río Segre','Espectacular y colosal desfiladero fluvial donde el Segre rompe verticalmente las estructuras calcáreas   mesozoicas con paredes limpias de caída libre de más de 300 metros. El peñón de Santa Fe emerge como una colosal aguja caliza que domina visualmente toda la cuenca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25156','espacio','Desfiladero de Canelles, río Noguera Ribagorzana y cueva de los Vilars','Monumental desfiladero fluvial kárstico labrado sobre potentes estratos de calizas jurásicas, flanqueado por imponentes farallones rocosos que aprisionan el río en láminas de agua de color verde esmeralda. El relieve presenta callejones de roca, lapiaces y abrigos naturales de gran valor geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25157','espacio','Valle del río Sió y lomas de la Segarra baja','Depresión erosiva de formas suaves labrada sobre arcillas miocénicas en el sector norte de la meseta. Destaca por el perfil de sus vertientes sujetas a erosión laminar y por los sutiles sotos ripícolas que marcan el curso estacional del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25164','espacio','Llanos de Penelles y colinas de yesos menores','Terreno de colinas bajas arcilloso-yesíferas situado en el límite entre la Noguera y el Urgell. Presenta formas suaves moldeadas por la escorrentía superficial y texturas de tierra desnuda sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25165','espacio','Riscos de Honor, estrechos de la roca del Corb y Sierra de Turp','Impresionante paisaje prepirenaico caracterizado por gigantescos y caprichosos monolitos y agujas calcáreas modeladas por la erosión diferencial y el viento. Las paredes verticales de piedra gris albergan cuevas e interesantes formaciones de disolución kárstica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25166','espacio','Riera de San Sana y lomas calizas del Solsonès occidental','Relieve ondulado de media montaña suave caracterizado por materiales margocalizas del oligoceno. Ofrece una fisonomía tranquila de laderas cubiertas de densas masas de encinar montano y quejigar que conviven con pequeños barrancos umbríos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25167','espacio','Centro geográfico de Cataluña (Sierra de Pinós) y cabecera del río Cardener','Elevada cresta caliza y de areniscas eocénicas que conforma la divisoria de aguas de la meseta central catalana. Ofrece amplias panorámicas visuales diáfanas y limpias que abarcan desde los Pirineos a Montserrat, rodeada de espesas masas de pino laricio y encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25176','espacio','Secanos de Preixana y llanos de Urgell sur','Espacio estrictamente plano de arcillas miocénicas estables de carácter marcadamente estepario. Destaca únicamente por la regularidad de sus horizontes abiertos e infinitos desprovistos de relieve abrupto o formaciones forestales nativas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25177','espacio','Valle del río Sió y muelas arcillosas de la Noguera','Relieve de lomas bajas y plataformas sedimentarias terciarias que caen de forma pronunciada hacia el valle aluvial del río Sió. Ofrece una panorámica limpia de vertientes erosionadas y pequeños cañaverales ripícolas asociados al arroyo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90623','espacio','Llanura aluvial de la Cerdanya y riberas del río Segre','Tramo donde el río Segre ensancha su curso describiendo curvas suaves sobre sedimentos aluviales cuaternarios finos en el fondo de la fosa tectónica ceretana.   Ofrece una estampa tranquila de aguas calmas que reflejan las alamedas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25179','espacio','Valle de la Llosa (baja), riscos de Prullans y cueva de Anes','Vertiente montañoso-axial del Pirineo caracterizada por imponentes escarpes de roca caliza y pizarras que caen sobre el valle de la Cerdanya. Alberga la cueva de Anes con un interesante desarrollo kárstico y frondosos bosques de quejigos y pinos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25181','espacio','Llanos de Puigverd y cuenca del río Sió','Terreno horizontal constituido por materiales margosos miocénicos suavizados por la erosión laminar agrícola. Presenta un horizonte diáfano e infinito sin grandes accidentes topográficos notables o masas boscosas densas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25182','espacio','Llanura aluvial del Segrià oriental','Espacio plano de sedimentación fina cuaternaria desprovisto de accidentes geográficos notables. Su interés visual radica en la limpieza lineal del diáfano horizonte y en la regularidad de la cuenca baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','espacio','Valle del Noguera Pallaresa, cañón de Rialp y umbrías de la Sierra de las Banquetas','Cabecera fluvial de alta montaña pirenaica donde el río discurre rápido y encajonado en un lecho de cantos rodados, flanqueado por imponentes vertientes de pizarras paleozoicas oscuras cubiertas de frondosos bosques de pino silvestre y abedulares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25185','espacio','Congost de Tresponts (cola), riberas del río Segre y Valle de Tost','Espacio donde el valle aluvial del Segre se estrecha antes del gran desfiladero calcáreo prepirenaico. Ofrece una vista nítida de escarpes y terrazas rocosas, sotos ripícolas bien conservados y el encajonamiento absoluto del arroyo de Tost.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25186','espacio','Valle del río Negra y pinares de Riner','Cuenca erosiva labrada sobre conglomerados y areniscas eocénicas del Solsonès meridional. Ofrece un paisaje verde continuo de masas estables de pino laricio y encinares que acompañan el cauce de aguas tranquilas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25189','espacio','Llanos del Segrià central y terrazas fluviales menores','Terreno horizontal de colinas de pendiente mínima compuesto por arenas, limos y arcillas del Plioceno. Presenta formas suaves moldeadas por la escorrentía superficial sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25190','espacio','Riberas del embalse de Sant Antoni y barrancos colorados de Salàs','Espacio geológico muy plástico caracterizado por la presencia de cárcavas y barrancos excavados sobre arcillas y conglomerados de intensas tonalidades rojizas. El contraste visual con la gran lámina de agua permanente del embalse ofrece un alto valor estético.   San Guim de Freixenet (Sant Guim de Freixenet) - Puntuación: 52/100 • Paraje: Parameras de la Alta Segarra y nacimiento del río Corb.     Descripción: Altiplano calizo elevado que conforma la divisoria de aguas de la meseta central catalana, compuesto por calizas lacustres del oligoceno. Ofrece una fisonomía esteparia diáfana de horizontes infinitos con pequeños encinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25196','espacio','Desfiladero de Mont-rebei (vertiente norte) y Sierra del Montsec d''Ares','Uno de los santuarios geomorfológicos más monumentales de Europa. Un abismal desfiladero de paredes calizas del Cretácico totalmente verticales que caen a plomo más de 500 metros sobre las aguas del río Noguera Ribagorzana, en un entorno mineral sobrecogedor de valor planetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25197','espacio','Llanos de la Segarra y lomas margosas de la Plana','Relieve ondulado de la meseta central catalana modelado sobre arcillas y margas de tonos grisáceos. Destaca por el perfil geométrico de sus vertientes sujetas a erosión laminar y pequeños matorrales de coscoja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25193','espacio','Valle de Lord, riscos de las Edades y embalse de Llosa del Cavall','Espectacular y colosal composición geomorfológica donde el río Cardener se encaja entre imponentes murallones y agujas de conglomerados oligocénicos erosionados en formas de muelas cuneiformes perfectas, que mueren en una lámina de agua de color turquesa profundo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25902','espacio','Valle del río Corb y llanos sedimentarios','Cuenca erosiva de formas suaves labrada sobre materiales arcillosos y de margas de la comarca de Urgell. Destaca por la geometría de sus vertientes cultivadas y sutiles bandas geológicas expuestas por las escorrentías estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25194','espacio','Páramos de la Segarra alta y dehesas de Portell','Altiplano horizontal severo de calizas lacustres y arcillas del terciario medio que ofrece una fisonomía esteparia de horizontes limpios e infinitos, interrumpida por pequeños rodales estables de quejigar arbustivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25201','espacio','Valle del río de San Nicolau, riscos de El Diable y canchales de Erdo','Término quebrado de alta montaña prepirenaica labrado sobre pizarras paleozoicas y calizas que generan pendientes vertiginosas. Ofrece valles de perfil cóncavo cubiertos por un espeso y continuo manto forestal de pino silvestre y abedulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25200','espacio','Valle del río Set y escarpes de Sarroca','Tramo donde el río Set corta las muelas calcáreas de la plataforma meridional leridana formando pequeños farallones y oquedades de disolución. Ofrece un marcado contraste visual entre las áridas pendientes arcillosas de badlands y el lecho aluvial del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25202','espacio','Valle del río Flamisell y desfiladero de Reguard','Espacio fluvial encajonado de gran valor contemplativo donde el Flamisell corta las estructuras de conglomerados eocénicos del Pallars Jussà. Ofrece una composición visual de laderas de pendientes acusadas cubiertas de densa vegetación mediterráneo-atlántica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25204','espacio','Espacio Natural del Aiguabarreig y escarpes arcillosos de Seròs','Tramo del bajo Segre caracterizado por colosales ripados y acantilados arcillo-arenosos de color rojizo e intensos ocres debidos al modelado fluvial sobre el Mioceno. Ofrece una de las visuales desértico-fluviales más espectaculares y plásticas del este peninsular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90624','espacio','Llanura aluvial del Pla d''Urgell oriental','Espacio estrictamente plano de sedimentación cuaternaria fina desprovisto de elevaciones o accidentes topográficos notables, ofreciendo un horizonte diáfano e infinito de gran uniformidad visual lineal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25207','espacio','Cuenca del río Negra y muelas de conglomerados de Solsona','Relieve de somontano prepirenaico caracterizado por muelas erosionadas y profundos barrancos labrados en conglomerados oligocénicos. Ofrece un paisaje verde continuo de masas estables de pino laricio que conviven con pequeños robledales de hoja pequeña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25208','espacio','Parque Natural del Alto Pirineo, valle de Arcalís y pico del Orri','Término de alta montaña pirenaica que culmina en el colosal pico del Orri, ofreciendo panorámicas limpias de 360 grados de toda la cordillera. El relieve de pizarras y calizas presenta profundos valles de modelado glaciar cubiertos de hayedos y pinares de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','espacio','Valle del Noguera Pallaresa, desfiladero de Llavorsí y barranco de Verneda','Cabecera fluvial de alta montaña donde el río Noguera Pallaresa corre veloz y atronador encajonado en una   profunda garganta excavada sobre pizarras paleozoicas oscuras del zócalo hercínico. Ofrece majestuosos bosques de ribera mediterráneo-atlánticos mixtificados de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25210','espacio','Riberas del río Segre inferior y escarpes arcillosos','Frente de terrazas fluviales cuaternarias y lomas arcillo-limosas que han sido erosionadas de forma sinuosa por la dinámica del río Segre. Ofrece una vista de amplias llanuras de inundación aluvial y un paisaje diáfano de tonos ocres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25211','espacio','Meandro del río Segre y llanuras bajas sedimentarias','Terreno de llanura aluvial cuaternaria muy estable donde el río describe curvas perezosas depositando limos y arenas finas. Destaca por la regularidad visual del soto ribereño y la fisonomía diáfana de la cuenca baja de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25212','espacio','Llanos de Sunyer y cuenca del río Set terminal','Espacio horizontal de la plataforma del Segrià sur constituido por arcillas y sedimentos miocénicos finos propensos a la erosión laminar, desprovisto de relieves abruptos notables o formaciones forestales nativas compactas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25215','espacio','Desfiladero de Susterris y orillas del embalse de Sant Antoni','Cañón fluvial donde las aguas del Noguera Pallaresa penetran en formaciones calizas estrechas cretácicas antes de remansarse. Ofrece una panorámica de amplias láminas de agua encajonadas entre laderas de matorral mediterráneo y pinos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27013','espacio','Valle del río Ondara y lomas del somontano de Urgell','Paisaje típico de transición con muelas erosionadas y suaves barrancos labrados en materiales arcillosos y margas. Ofrece un gran interés visual por los contrastes lumínicos estacionales sobre la llanura cerealista y las vertientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25220','espacio','Riberas del río Segre y llanura aluvial de la Noguera','Tramo aluvial donde el valle fluvial se ensancha mostrando amplias terrazas aluviales compuestas por gravas, arenas y sedimentos del Cuaternario. Ofrece una perspectiva nítida del avance erosivo del río Segre flanqueado por alamedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25221','espacio','Confluencia de los tres valles (Cardós, Ferrera y Coma de Burg)','Extraordinario nudo geográfico de alta montaña pirenaica, donde convergen de forma majestuosa tres de las cuencas fluviales más importantes del Pallars Sobirá sobre un relieve quebrado de pizarras paleozoicas oscuras cubiertas de frondosos pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25222','espacio','Orillas del embalse de Rialb y lomas calizas','Espacio caracterizado por amplias láminas de agua remansadas que se adaptan a la fisonomía de colinas de calizas eocénicas y arcillas. Ofrece panorámicas de horizontes limpios donde el agua rompe de forma estética el paisaje prepirenaico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25223','espacio','Valle del río Llobregós, riscos de Llanera y muelas de yesos','Profundo corte erosivo que rompe el páramo calizo de la Segarra alta, dejando al descubierto potentes perfiles de margas y arcillas con cristales de yeso selenítico   en las laderas. Ofrece una vista nítida de los diferentes estratos geológicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25233','espacio','Llanos del Segrià norte','Terreno horizontal de colinas de pendiente mínima compuesto por arenas y arcillas miocénicas estables de la depresión central catalana, ofreciendo un paisaje de horizontes diáfanos sin accidentes topográficos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25228','espacio','Llanos de Torrefarrera y balsas de escorrentía','Espacio plano de sedimentación fina terciaria desprovisto de relieves abruptos notables o formaciones forestales compactas nativas. Ofrece una fisonomía horizontal de horizontes lineales limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90625','espacio','Valle de la riera de Sanaüja y lomas de la Segarra occidental','Relieve ondulado de la meseta central catalana modelado sobre arcillas y calizas lacustres. Destaca por la armonía visual de sus vertientes y pequeños rodales estables de quejigar y encinar mediterráneo bien conservados.   Torregrossa - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','espacio','Desfiladero de Terradets (vertiente norte), cuenca de Tremp y robledal de Tendrui','Impresionante cubeta tectónica prepirenaica caracterizada por un relieve abarrancado de margas que da paso al colosal corte kárstico de Terradets en las calizas del Montsec d''Ares. Alberga el robledal de Tendrui, una masa madura y pura de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25901','espacio','Río Noguera de Cardós, Valle de Estaron y umbrías del Parque Natural del Alto Pirineo','Impresionante valle fluvial de modelado glaciar profundo esculpido sobre pizarras hercínicas oscuras y esquistos metamórficos. Ofrece laderas de pendientes vertiginosas vestidas por densos abedulares, hayedos y pinares de pino negro que flanquean un cauce rápido de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','espacio','Parque Nacional de Aigüestortes i Estany de Sant Maurici (acceso occidental), Valle de San Nicolau y estanques de Cavallers','Uno de los santuarios de modelado glaciar más colosales y perfectos de la Tierra, esculpido sobre el batolito granítico del Pirineo axial. Alberga decenas de lagunas alpinas transparentes, circos glaciares majestuosos, cascadas de deshielo atronadoras y bosques prístinos subalpinos de pino negro de valor planetario.   Lleida).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25238','espacio','Valle del río Maldanell y lomas calizas de la sierra de Tallat','Relieve ondulado de la meseta central caracterizado por la alternancia de capas arcillosas y muelas de caliza lacustre grisácea. Destaca por el modelado de sus barrancos secos y la presencia de bosquetes mediterráneos de encina y pino blanco adaptados a la escasez de suelo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','espacio','Valle de Arán central, Artiga de Lin (zona sur), río Garona y circo de Colomèrs (acceso)','Monumental cabecera de valle pirenaico axial labrada sobre el batolito granítico y pizarras paleozoicas oscuras por la acción glaciar. Ofrece un paisaje alpino sobregogedor de picos calcáreos que rozan los 3.000 metros, cascadas atronadoras de deshielo y frondosas selvas de abeto blanco y hayas centenarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25249','espacio','Valle del río Llobregós y colinas de yeseras del oligoceno','Paisaje de transición suave caracterizado por colinas erosionadas de arcillas y potentes estratos de yeso cristalino de la cuenca media. El atractivo visual radica en los destellos minerales de las pendientes desnudas bajo el sol y las sutiles formas de escorrentía remontante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25254','espacio','Confluencia del río Corb con el río Segre y llanuras aluviales','Amplia llanura de inundación del Cuaternario donde se unifican las cuencas fluviales sobre potentes terrazas de gravas, arenas y limos sedimentarios. Ofrece un horizonte diáfano e infinito de gran uniformidad, flanqueado por ricas alomedas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25250','espacio','Desfiladero de Toloó, riscos de Meià y Sierra del Montsec de Rúbies','Uno de los espectáculos de falla y plegamiento geológico más monumentales del Prepirineo, caracterizado por colosales acantilados verticales de roca caliza jurásica de tonos grises y ocres. Sus desfiladeros estrechos, cuevas aéreas y agujas de piedra configuran un paisaje mineral sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25252','espacio','Estanque de Ivars y Vila-sana (vertiente oriental)','Sector copartícipe del complejo lagunar endorreico recuperado en la fosa leridana, asentado sobre sedimentos limosos cuaternarios finos. Ofrece una inmensa lámina de agua permanente rodeada de un frondoso cinturón perilagunar de carrizales, eneas y sauces de gran nitidez visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25255','espacio','Valle de Vinaixa y muelas calcáreas de Les Garrigues altas','Altiplano ondulado caracterizado por plataformas calcáreas tabulares que se cortan de forma nítida hacia pequeñas depresiones arcillosas. Ofrece una vista limpia de la estratificación sedimentaria del oligoceno, matorrales mediterráneos bajos y retazos de pinar.   ¡Objetivo cumplido! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90542','espacio','Serra do Xistral y valles de las turberas de cobertura','Impresionante relieve montañoso liso y redondeado compuesto por gneis y cuarcitas paleozoicas batido por constantes nieblas atlánticas. Alberga un ecosistema único en Europa de turberas de cobertura hiperhúmedas y brezales higrófilos que tapizan las laderas superiores de una plasticidad cromática verde perpetua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90543','espacio','Val do Ouro y cañón del río Ouro','Profundo tajo erosivo donde el río Ouro corta los bloques graníticos septentrionales antes de descender hacia el litoral cantábrico. Destaca por el aislamiento visual de sus valles encajonados cubiertos por frondosas masas relictas de robledal atlántico, sauces y canchales de piedra musgosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90544','espacio','Nacimiento del río Ulla y lomas del monte Farelo','Espacio de transición geológica donde las aguas iniciales del río Ulla brotan de fuentes cristalinas sobre un sustrato de esquistos metamórficos y granitos degradados. El paisaje destaca por la pureza atmosférica y visual de sus bosques de galería dominados por el ameneiro y el fresno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90545','espacio','Fraga de Marronda y cabecera del río Eo','Espectacular y denso bosque atlántico autóctono considerado uno de los principales reductos de haya (Fagus sylvatica) en el límite suroccidental de su distribución europea. El relieve de fuertes pendientes fluviales y pizarras paleozoicas ofrece un entorno de umbría forestal prístina de enorme fuerza botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','espacio','Acantilados de San Cosme, Punta Anguieira y costa de afloramientos de esquistos','Tramo litoral cantábrico de gran valor contemplativo caracterizado por imponentes frentes rocosos de abrasión marina esculpidos sobre esquistos y pizarras replegadas. Destaca por las geoformas debidas al oleaje, puntas minerales desnudas y arrecifes sumergiéndose en aguas transparentes y puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28001','espacio','Desfiladero del río Navia, Os Ancares leonesesgallegos y cañón de Gatín','Monumental desfiladero fluvial donde el río Navia y sus afluentes tajan el zócalo hercínico calcáreo y de pizarra con laderas de pendientes extremas. El paisaje destaca por la fisonomía quebrada de sus pasillos minerales de roca viva y espesos encinares cantábricos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','espacio','Confluencia de los ríos Ladra y Parga e islas aluviales de Insuas del Ladra','Excepcional e histórico complejo hidrológico de la llanura chairega compuesto por una red de canales fluviales divagantes, lagunas intermitentes y depósitos de arenas finas cuaternarias. Ofrece un paisaje acuático interior de gran sosiego visual rodeado de densas alisedas higrófilas inundables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','espacio','Valle de Lemos, riberas del río Mao y colinas arcillosas','Depresión erosiva de formas suaves labrada sobre materiales terciarios y sedimentos finos arcillo-limosos en el somontano lucense. Ofrece una composición visual diáfana de lomas redondeadas que alternan con pequeñas choperas que marcan el curso del agua estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','espacio','Cañón del río Miño y gargantas del embalse de Peares','Impresionante corte geológico donde el río Miño se encajona de forma monumental describiendo profundos meandros cerrados sobre murallones de roca granítica vertical. Las abruptas laderas de umbría están colonizadas de forma natural por densos robledales y matorral atlántico escarpado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','espacio','Llanura de la Terra Chá y lagunas de Azúmara','Espacio estrictamente horizontal correspondiente a una gran cuenca sedimentaria cuaternaria de relieve llano y liso. Ofrece extensos horizontes lineales limpios donde se aprecian sutiles formas de escorrentía superficial y pequeños humedales estacionales perilagunares.   Lugo).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','espacio','Serra de Pena, nacimiento del río Chamoso y cuevas kársticas de interior','Relieve ondulado y de media montaña labrado sobre calizas del Cámbrico e intermitencias de pizarras paleozoicas. Destaca por sus sutiles sumideros kársticos, pequeños valles de umbría y frondosas masas forestales autóctonas dominadas por el castaño y el roble.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','espacio','Parque Natural de Os Ancares, picos de Tres Bispos, Mustallar y valles glaciares de cabecera','Uno de los paisajes montañosos más grandiosos y puros del noroeste peninsular, modelado por glaciares cuaternarios sobre pizarras, cuarcitas y calizas. Presenta pendientes de una verticalidad colosal, imponentes   canchales de piedra y selvas atlánticas impenetrables de acebos, abedules y robles melojos de valor planetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90041','espacio','Ensenada de San Ciprián, acantilados de Punta Atalaia e Islas de San Clemente','Costa cantábrica abrupta caracterizada por colosales afloramientos graníticos redondeados y esculpidos de forma violenta por el oleaje y el viento marítimo. Ofrece una fisonomía costera mineral descarnada y pura, con islotes rocosos desprovistos de arena que rompen de manera espectacular hacia el mar abierto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','espacio','Ribera Sacra, meandro de Cabo do Mundo y cañón del río Miño','Impresionante y colosal desfiladero fluvial donde el río Miño traza meandros encajonados sobre murallones verticales de roca granítica de más de 300 metros de caída. Ofrece una de las estampas de relieve y agua más perfectas del país, con laderas boscosas de umbría absoluta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90552','espacio','Llanura aluvial del río Miño y humedales de Chamoso','Espacio de transición aluvial caracterizado por terrazas fluviales estables de cantos rodados, limos y arenas cuaternarias. Ofrece una estampa tranquila de quietud fluvial con sotos de galería muy bien conservados dominados por el ameneiro (Alnus glutinosa).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','espacio','Laguna de Cospeito (Feoga) y humedales de la Terra Chá','Excepcional complejo lagunar natural de origen endorreico asentado en mitad de la gran llanura sedimentaria chairega. Sus extensas láminas de agua dulce perenne, rodeadas por impenetrables cinturones de carrizales, juncos y sauces, constituyen un paisaje acuático interior de extraordinaria pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','espacio','Sierra del Caurel (Serra do Courel), devesas de Rogueira y A Rogueira, y pliegue geológico de Campodola','Santuario de la biodiversidad y la geología europea, con valles glaciares profundos esculpidos sobre pizarras y cuarcitas metamórficas replegadas. La Devesa de Rogueira alberga un bosque primario mixto de una densidad e importancia botánica colosal, flanqueado por crestas afiladas de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28004','espacio','Seimeira de Vilagocende, cascada del río Porteliña y cumbres del revés','El municipio más extenso de Galicia, caracterizado por un relieve aserrado de fuertes desniveles sobre materiales paleozoicos. Destaca por la monumental Seimeira de Vilagocende, una cascada con más de 50 metros de caída libre vertical de agua cristalina sobre roca umbría tapizada de musgos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','espacio','Ría de Foz, acantilados de Cangas de Foz y Punta do Bispo','Impresionante estuario donde las corrientes fluviales y las mareas cantábricas modelan amplias llanuras intermareales de fango y arena. Hacia el litoral abierto da paso a abruptos frentes acantilados esculpidos sobre esquistos replegados que muestran la fuerza de la abrasión marina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','espacio','Cabecera del río Narla, lomas de la Serra de Cova da Serpe y berrocales menores','Paisaje penillanurero de formas suaves interrumpido por elevaciones graníticas ecorrodadas en bloques redondeados. Ofrece amplios horizontes visuales limpios recubiertos por densas masas de matorral atlántico mediterráneo y pequeños sotos fluviales de montaña baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','espacio','Riberas del río Ferreira y cañón del Miño inferior','Tramo donde el río Ferreira labra una garganta sinuosa sobre esquistos paleozoicos antes de unirse al Miño. Destaca por la armonía visual de sus orillas empinadas y la pureza botánica de sus sotos de ribera autóctonos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27024','espacio','Valle de Trascastro, peñas calcáreas y embalse de Vilasouto','Paisaje quebrado de transición a la Sierra del Caurel, caracterizado por escarpes de roca caliza cristalina jurásica y pizarras. Ofrece una vista nítida de cuevas de disolución y laderas cubiertas de densos bosques de castaño centenario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','espacio','Valle aluvial del río Neira y lomas de Láncara','Espacio fluvial donde el río Neira erosiona de forma suave el terreno sobre pizarras y areniscas. Destaca por la contemplación de sus vegas húmedas y la regularidad geométrica de sus sotos ripícolas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','espacio','Val de Lourenzá y cañón del río Baos','Profunda cuenca erosiva flanqueada por lomas de fuertes pendientes compuestas por esquistos y granitos degradados. El fondo del valle ofrece una vista diáfana de un corredor perennemente verde con frondosos bosques de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','espacio','Miño lucense e Insuas do Miño (Insua de Abaixo)','Tramo aluvial protegido donde el río Miño ensancha su lecho y se fragmenta creando islas de sedimentación cuaternaria. Ofrece un paisaje de quietud hídrica con imponentes masas boscosas de alisos y sauces de gran nitidez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','espacio','Pedregal de Irimia (Nacimiento del río Miño) y Serra de Meira','Impresionante acumulación de colosales bloques cuarcíticos de origen periglacial (canchal) bajo los cuales se escucha fluir el agua primigenia del río Miño. La   cresta montañosa ofrece un horizonte diáfano de texturas pétreas descarnadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','espacio','Cova del Rei Cintolo y salto de agua de la Fervenza','El mayor complejo kárstico subterráneo de Galicia, excavado en calizas cámbricas con galerías monumentales repletas de estalactitas y estalagmitas. En el exterior destaca un espectacular encajonamiento fluvial con cascadas de agua hipertransparente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','espacio','Valle de Lemos, riberas del Cabe y terrazas fluviales','Amplia y absoluta depresión geológica cuaternaria de relieve llano y liso compuesta por depósitos arcillo-limosos. Ofrece extensas panorámicas diáfanas interrumpidas únicamente por el dosel verde de los sauces de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','espacio','Curso alto del río Ulla y dehesas de Sirgal','Tramo fluvial de montaña baja donde el río Ulla discurre sobre un sustrato de granitos degradados y esquistos. La composición visual destaca por la claridad de las aguas y la presencia de frondosas masas forestales mixtas de roble y castaño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','espacio','Serra do Xistral (vertiente norte) y cañón del río Eume','Paisaje atlántico extremo caracterizado por altas lomas redondeadas y romas batidas por el viento, donde se originan turberas de cobertura hiperhúmedas. El río Eume excava en su cabecera un cañón de laderas escarpadas de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','espacio','Reserva de la Biosfera de Os Ancares, cañón del río Navia y valle de Rao','Espectacular y abismal tajo fluvial excavado sobre pizarras hercínicas oscuras y cuarcitas en el límite asturiano. Las vertientes presentan pendientes vertiginosas de una fisonomía mineral agreste y salvaje, tapizadas de bosques primarios atlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27035','espacio','Embalse de Salime (río Navia) y umbrías de Negueira','El municipio menos poblado de Galicia, aislado por el encajonamiento absoluto del río Navia entre montañas de pizarras descarnadas. La inmensa lámina de agua se adapta de forma laberíntica al relieve, creando paisajes de una fuerza visual sobregogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90845','espacio','Gargantas del río Navia y devesas del monte Torubio','Entorno subalpino prepirenaico-cantábrico con fuertes desniveles topográficos y pasillos de piedra caliza y pizarra. Destaca por el aislamiento absoluto de sus valles boscosos cubiertos de densos melojares, acebedos y hayedos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','espacio','Serra de Gañidoira y valle de las turberas del Landro','Altiplano elevado caracterizado por colinas redondeadas sobre gneis sometidas a una alta pluviosidad estacional. Ofrece un tapiz verde perpetuo de brezales higrófilos y nacimientos de arroyos que bajan encajonados hacia el Cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','espacio','Insuas del Miño (Insua de San Roque) y campo kárstico de Penas de Rodas','Complejo aluvial y granítico singular donde el Miño genera islas interiores vírgenes de densos sotos inundables. Destaca el paraje de Penas de Rodas, dos colosales e inexplicables bloques de granito esférico que emergen exentos en el llano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','espacio','Torrentes de Mácara y dehesas de quejigo','Cabecera fluvial donde el río Ulla se encaja sobre un lecho de rocas metamórficas ultrabásicas (anfibolitas), creando rápidos y cascadas menores de gran interés geológico y rodeadas de un frondoso bosque gallego autóctono.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','espacio','Ribera Sacra, riberas del Sil y meandro de A Maiorga','Monumental desfiladero fluvial donde el río Sil penetra estrechamente cortando el zócalo granítico antes de su unión con el Miño. Sus imponentes paredes rocosas verticales caen a plomo sobre aguas oscuras y profundas de gran potencia estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','espacio','Cañón del río Miño y laderas de la Ribera Sacra occidental','Tramo donde el río Miño fluye confinado entre vertiginosas vertientes de rocas graníticas y esquistos replegados. El paisaje de umbría destaca por sus laderas cubiertas de densas masas estables de castaño y matorral atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','espacio','Sierra de Rañadoiro y fuentes del río Navia','Puerto de montaña alpino que marca el límite geográfico oriental de Galicia, asentado sobre pizarras desmanteladas y cuarcitas. Permite la contemplación de   horizontes infinitos de crestas aserradas y valles profundos cubiertos de nieblas atlánticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','espacio','Serra de Saa y gargantas del río Lor','Término quebrado caracterizado por el encajonamiento absoluto del río Lor entre montañas de pizarras metamórficas. Ofrece un paisaje mineral rudo con densos bosques de castaño y pequeñas oquedades en los estratos geológicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','espacio','Cañón del río Eo y barranco de Vilameá','Angosto desfiladero fluvial labrado sobre pizarras paleozoicas por las aguas del río Eo en el límite con Asturias. Las orillas rocosas son de una verticalidad colosal, tapizadas de maduros robledales de umbría y un dosel ripario impecable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','espacio','Pliegue geológico de Campodola-Leixazós y cañón del Sil','Santuario geológico de nivel internacional que expone un colosal pliegue acostado del Carbonífero visible a simple vista en una ladera descarnada de pizarras. El término comparte además los imponentes cortados verticales del cañón del Sil.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27056','espacio','Ribera del río Miño y terrazas aluviales de grava','Término de reducidas dimensiones asentado de forma horizontal sobre los depósitos de gravas y arenas del curso medio del Miño. Ofrece una vista diáfana de la corriente hídrica flanqueada por una franja fragmentada de sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','espacio','Playa de las Catedrales (Monumento Natural de As Catedrais) y ría de Ribadeo','Uno de los monumentos geológicos marinos más espectaculares de la Tierra. Los acantilados de pizarra y esquistos han sido esculpidos por la abrasión marina en forma de colosales arcos de piedra de más de 30 metros, grutas abovedadas y pasillos minerales de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','espacio','Cañón del río Sil, Peñas de Doade y meandros del Sil','Impresionante corte transversal sobre el batolito granítico labrado en vertical por las aguas profundas del río Sil. Ofrece una fisonomía geológica de enormes murallas de piedra gris desnudada de más de 300 metros de caída libre en una de las zonas más puras de la Ribera Sacra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27053','espacio','Estrechos del río Eo y dehesas de San Fiz','Valle fluvial angosto y profundamente encajonado de forma sinuosa sobre materiales de pizarras paleozoicas. Las laderas presentan pendientes vertiginosas cubiertas de una de las masas de robledal y castañar atlántico más compactas y vírgenes del norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','espacio','Valle del río Eo y lomas de la Serra de Meira (vertiente norte)','Relieve ondulado de media montaña caracterizado por terrenos de esquistos y pizarras expuestos a una intensa erosión hídrica. Ofrece una panorámica de laderas verdes perennes y pequeños arroyos de cabecera estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','espacio','Valle del río Oribio, Serra do Lóuzara y dehesas de castaños','Entorno de montaña atlántica de aislamiento absoluto flanqueado por los relieves de la Sierra del Caurel. Destaca por la pureza botánica de sus dehesas de castaños   centenarios y arroyos que discurren encajonados bajo selvas de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27057','espacio','Valle aluvial del río Sarria y lomas arcillo-esquistosas','Depresión erosiva suave donde el valle se ensancha sobre terrazas sedimentarias del terciario superior y cuaternarias. Permite la contemplación de un paisaje diáfano de formas redondeadas y pequeñas alamedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','espacio','Ribera Sacra, cañón del Miño y meandro de Cabo do Mundo (vertiente oriental)','Impresionante sector del cañón del Miño flanqueado por colosales e imponentes paredes verticales de roca granítica. La vista ofrece el majestuoso giro cóncavo del río abrazando la muela rocosa, rodeado de densos bosques de umbría de valor contemplativo colosal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','espacio','Cañón del Sil, Miradores de Cadeiras y Santiorxo (escarpes verticales)','Uno de los puntos cumbre de la Ribera Sacra, caracterizado por un colosal cañón dolomítico y granítico con paredes verticales de más de 400 metros de caída limpia sobre el río Sil. La magnitud de la fractura geológica y el silencio visual de sus aguas oscuras son sobregogedores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','espacio','Gargantas del río Miño y dehesas de Sobrecedo','Vertiente occidental del cañón del Miño con laderas de fuertes pendientes compuestas por pizarras y granitos. Ofrece amplios horizontes visuales limpios sobre el cauce encajonado del río y las masas forestales continuas de robledal atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27061','espacio','Serra de Cadeira y barrancos del río Eo inferior','Relieve de fuertes pendientes compuesto por potentes bancos de cuarcitas y esquistos que descen de forma monumental hacia la cuenca del Eo, cubierto de densas masas de matorral atlántico y bosquetes mixtos bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','espacio','Valle del río Oribio y cumbres calizas del monte Oribio','Espectacular paisaje calcáreo de alta montaña atlántica caracterizado por la presencia de grandes canchales de piedra, lapiaces profundos y oquedades kársticas aéreas que rompen la continuidad de las pizarras de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90846','espacio','Sierra del Xistral central y nacimiento del río Ouro','Relieve montañoso granítico axial cubierto por turberas de cobertura hiperhúmedas y brezales alpinos que se mantienen verdes a lo largo de todo el año, ofreciendo una panorámica limpia de alta montaña gallega en un entorno de constante niebla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','espacio','Parameras de la Terra Chá occidental y cuenca del río Magdalena','Altiplano calizo y arcilloso elevado que define la fisonomía de la comarca chairega alta. Ofrece horizontes abiertos y diáfanos de carácter estepario atlántico con sutiles escorrentías en los márgenes de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','espacio','Ría de Viveiro, acantilados de Monte Faro y eucaliptal monumental de Chavín (entorno natural)','Espectacular confluencia geológica costera donde los promontorios graníticos de Monte Faro funcionan como baluartes erosivos que protegen una ría encajonada. Los acantilados marinos exteriores muestran una fisonomía abrupta de gran potencia visual batida por el Cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90847','espacio','Serra de Lousamba y cabeceras del río Labrada','Paisaje de media montaña atlántica con relieves de suaves pendientes configurados por areniscas y pizarras hercínicas. Destaca por el aislamiento absoluto de sus valles boscosos cubiertos de robledales basales y brezales húmedos continuos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','espacio','Acantilados de Punta Roncadoira e Isla de Ansarón','Costa rocosa abrupta configurada por la erosión extrema del Cantábrico sobre bloques graníticos desmantelados. Destaca por sus plataformas de abrasión marina, arrecifes y una fisonomía de costa salvaje y mineral desprovista de playas de arena fina.   ¡Objetivo cumplido con rigor absoluto! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90065','espacio','Lomas de la Campiña del Henares y arroyo de las Monjas','Relieve suavemente ondulado de la meseta sedimentaria compuesto por arcillas y margas propensas a la erosión hídrica superficial. Ofrece una panorámica de horizontes limpios de carácter estepario y sutiles cárcavas agrícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','espacio','Alta Sierra de Guadarrama y riberas del río Lozoya','Entorno de alta montaña integrado en el Parque Nacional de la Sierra de Guadarrama, con un valle de origen glaciar y tectónico encajonado. Destaca por la contemplación de sus frondosos bosques de umbría compuestos por robles rebollos, fresnedas y el curso cristalino y frío del río Lozoya.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','espacio','Los Cerros de Alcalá y escarpes del río Henares','Impresionante frente de cerros testigo de morfología tabular con potentes farallones arcillosos y de yesos esculpidos por el río Henares. Ofrece un gran interés geomorfológico por sus cárcavas rojizas y la transición visual entre la llanura aluvial y los páramos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90067','espacio','Dehesa de Alcobendas y cuenca media del arroyo de la Vega','Paisaje ondulado suave asentado sobre arenas graníticas y arcos sedimentarios terciarios del piedemonte serrano. Presenta interés contemplativo limitado a sus pequeños encinares fragmentados y horizontes diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29002','espacio','Cuenca del arroyo de la Reguera y lomas arcillosas','Terreno horizontal con pendientes mínimas constituido por depósitos de arenas y arcillas miocénicas de la submeseta sur. Su valor se reduce a la inmensidad diáfana de su horizonte agrario sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90068','espacio','Confluencia de los ríos Alberche y Perales','Singular nudo hidrológico aluvial donde ambos cursos fluviales unifican sus cauces sobre amplias playas de arenas graníticas cuaternarias. Ofrece una composición visual de gran plasticidad con frondosos sotos de galería dominados por sauces, fresnos y álamos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90069','espacio','Las Terrazas de Algete y vega baja del río Jarama','Cornisa de arcillas de sedimentación y calizas que cae mediante taludes pronunciados hacia la gran llanura aluvial del río Jarama. Ofrece amplias panorámicas limpias de horizontes despejados desde los bordes de la plataforma alcarreña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90070','espacio','Berrocales de Alpedrete y dehesas graníticas','Paisaje de piedemonte caracterizado por colosales acumulaciones de bloques y bolos graníticos redondeados por la erosión físico-química. Las caprichosas formas de la roca viva gris se integran de forma armónica entre dehesas de encina y fresno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90071','espacio','Valle del río Tajuña y encinares de la Alcarria madrileña','Profundo corte erosivo donde el río Tajuña labra un valle encajonado flanqueado por las muelas calizas de cumbre plana. Ofrece una composición de gran belleza visual entre los escarpes de roca y la densa vegetación esclerófila de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90072','espacio','Valle de Anchuelo y muelas arcillosas del páramo','Relieve ondulado de la Alcarria madrileña caracterizado por vertientes de fuerte pendiente labradas sobre materiales margosos y yesíferos del Terciario. Destaca por sus perfiles geológicos y los sutiles fenómenos de escorrentía estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','espacio','Reserva Natural del Regajal-Mar de Ontígola, Confluencia Tajo-Jarama y Sotos Históricos (entorno natural)','Excepcional e histórico complejo geográfico aluvial donde se funden los dos ríos más importantes de la   cuenca sobre terrazas cuaternarias de gran fertilidad. Alberga el Mar de Ontígola, un humedal permanente rodeado de carrizales y cerros de yesos cristalinos de gran valor plástico y botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','espacio','Parque Regional del Sureste, Laguna de las Madres y Cortados de Casa Eulogio','Monumentales cortados calizos y de yesos con paredes totalmente verticales que caen sobre la llanura de inundación del río Jarama. El complejo cuenta con lagunas de origen freático de aguas calmas que reflejan la magnitud de los acantilados geológicos grises.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28015','espacio','Valle del arroyo de la Arroyada y cárcavas de arcilla','Tramo donde el arroyo excava los depósitos de arenas y arcillas sueltas miocénicas creando pequeñas cárcavas de tonalidades ocres. Permite observar los procesos de erosión remontante hídrica superficial sobre el relieve suave.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28016','espacio','Embalse de El Atazar, cañón del río Lozoya y riscos de pizarra','Paisaje extremo e imponente caracterizado por el encajonamiento absoluto del río Lozoya entre montañas verticales de pizarras paleozoicas oscuras. La inmensa lámina de agua perenne se adapta de forma laberíntica al relieve quebrado de la Sierra Norte, de una fuerza visual sobrecogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','espacio','Cárcavas del río Guadarrama y monte de Batres','Impresionantes escarpes de arcilla y arenas formados por la intensa erosión remontante de las escorrentías hacia el río Guadarrama. Ofrece una fisonomía de badlands de tonos dorados y ocres de gran impacto visual que contrasta con el encinar maduro superior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28018','espacio','Valle de la Maliciosa, La Pedriza (límite oeste) y dehesas del Berrocal','Relieve de alta montaña alpina situado en las faldas de la imponente masa granítica de La Maliciosa, en el Parque Nacional de Guadarrama. Destaca por sus canchales vertiginosos de piedra, sus bloques graníticos modelados y un dosel continuo de pino silvestre de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28019','espacio','Parameras del Tajo y arroyo de la Vega','Altiplano calizo horizontal interrumpido por sutiles depresiones erosivas rellenas de arcillas del Mioceno. Ofrece horizontes diáfanos limpios característicos de la Alcarria baja, donde destacan las formas de escorrentía superficial en las pendientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28020','espacio','Sierra de la Puebla y colas del embalse de El Atazar','Término quebrado de la Sierra Norte caracterizado por laderas de pendientes extremas compuestas por pizarras y esquistos paleozoicos desmantelados. Ofrece amplias panorámicas visuales limpias sobre las lenguas de agua encajadas en la montaña salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28021','espacio','Berrocal del monte de la Dehesa y riberas del embalse de El Atazar','Extraordinaria concentración de bloques y bolos graníticos de colosales dimensiones (como el imponente canchal del Berrueco) esculpidos por la meteorización química. La piedra gris emerge exenta de la tierra rodeada de encinas y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','espacio','Monte de Boadilla y cuenca del río Guadarrama','Relieve ondulado suave del piedemonte compuesto por arcillas y arcosas graníticas erosionadas.   Destaca por albergar una masa forestal continua y madura de encinar mediterráneo con horizontes limpios sin relieve abrupto notable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','espacio','Parque Nacional de la Sierra de Guadarrama, la Pedriza Posterior y Sierra de Hoyo','Impresionante transición geomorfológica al pie de los colosales riscos de granito de la Pedriza y la silueta alpina de la Maliciosa. Ofrece un paisaje mineral majestuoso de bolos graníticos, canchales y dehesas de encina con arroyos transparentes de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90073','espacio','Sierra de Guadarrama septentrional y dehesas del río de la Cigüeñuela','Vertiente de alta montaña en Somosierra caracterizada por laderas escarpadas de gneis y pizarras paleozoicas. Destaca por sus frondosos bosques de umbría dominados por el roble rebollo, sus pastizales alpinos y los arroyos de deshielo hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28025','espacio','Valles de la Alcarria meridional y arroyo de Santa María','Paisaje alcarreño caracterizado por muelas calizas erosionadas que dan paso a pequeños barrancos y vaguadas de arcilla. Ofrece una fisonomía esteparia austera de formas suaves marcadas por la escorrentía estacional y el matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28026','espacio','Llanuras de la cuenca media del Guadarrama y arroyo de la Albufera','Terreno de lomas muy suaves compuesto por arenas arcósicas cuaternarias depositadas por la erosión granítica de la sierra. Destaca únicamente por sus amplios horizontes despejados de campiña y sutiles cauces secos temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','espacio','Meandro encajonado del río Lozoya y cola del embalse de Puentes Viejas','Espectacular y perfecto meandro geológico donde el río Lozoya fluye confinado, excavando un foso natural sobre el zócalo de gneis y pizarras. La composición visual de la gran lámina de agua rodeada de densos pinares de pino silvestre es colosal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','espacio','Valle de Bustarviejo, el Pendón y faldas de la Sierra de la Cabrera','Singular cubeta geológica de origen tectónico rodeada de imponentes cumbres graníticas y canchales de gneis descarnados. Alberga un microclima de gran pluviosidad con un tapiz vegetal espeso de robledales rebollos, abedulares relictos y fuentes de agua pura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28029','espacio','Piedemonte granítico y dehesas de Cabanillas','Relieve ondulado de la transición a la sierra caracterizado por afloramientos menores de bloques graníticos redondeados (berrocales). Ofrece una panorámica de dehesas estables de encina y fresno perfectamente adaptadas a los suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','espacio','Lanchar de Cadalso, Peña Muñana y pinar de Tórtolas','Espectacular paisaje granítico caracterizado por colosales domos, lanchares de roca viva lisa y la imponente aguja exenta de Peña Muñana. El pinar de pino piñonero y resinero coloniza las fracturas de la piedra, creando un fuerte contraste cromático y visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28032','espacio','Campiña del Henares y arroyo Camarmilla','Espacio estrictamente plano con sutiles ondulaciones arcillo-margosas del Mioceno sometidas a   erosión laminar. Ofrece horizontes diáfanos limpios desprovistos de relieve abrupto o de formaciones arboladas nativas compactas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28033','espacio','Parameras de Campo Real y olivares calcícolas','Altiplano calizo tabular miocénico de la Alcarria de Alcalá, cortado de forma suave por pequeñas escorrentías. Destaca por la contemplación geológica de sus muelas de cumbre plana y las texturas blanquecinas de sus suelos calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','espacio','Puerto de Canencia, Chorrera de Mojonavalle y abedular de Canencia','Entorno de alta montaña caracterizado por un microclima de umbría húmeda en la Sierra de Guadarrama. Destaca por albergar un bosque relicto mixto de abedules, acebos y tejos, donde el arroyo vierte sus aguas en una cascada de más de treinta metros sobre rocas metamórficas de gneis.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28035','espacio','Hoz del río Tajuña y cerro de la Alcarria','Tramo fluvial encajonado donde el río Tajuña erosiona las plataformas de yesos y calizas miocénicas de la Alcarria meridional. Ofrece cortados rocosos y un soto de ribera con álamos y cañaverales que contrastan con los páramos áridos superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28036','espacio','Llanuras de la cuenca baja del Guadarrama','Terreno horizontal con pendientes mínimas constituido por depósitos de arenas arcósicas y limos en el límite con Toledo. Su valor contemplativo se reduce a la inmensidad diáfana de un horizonte completamente llano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28037','espacio','Peña de Cenicientos, lanchares de granito y encinares de la loma','Extremo suroccidental de la provincia con imponentes vertientes graníticas pertenecientes al Sistema Central. El relieve destaca por sus colosales domos de piedra viva desnudada y laderas cubiertas de una masa forestal continua de encina y pino piñonero de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','espacio','Valle de la Fuenfría, Siete Picos y nacimiento del río Guadarrama','Uno de los anfiteatros de alta montaña más majestuosos del Sistema Central, configurado por picos de gneis y granito que superan los 2.100 metros de altitud. Alberga un bosque continuo de pino silvestre de valor botánico nacional, canchales vertiginosos y cascadas de deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28039','espacio','Riberas del embalse de El Atazar y cerros de pizarra','Península geológica rodeada por la mayor lámina de agua de la provincia, adaptada al relieve quebrado de pizarras y esquistos paleozoicos. La panorámica ofrece   una vista limpia donde el azul del agua se inserta entre las áridas laderas de la Sierra Norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28040','espacio','Cortados de Ciempozuelos, río Jarama y salinas de interior','Monumental y abrupto frente vertical de yesos y arcillas del Mioceno que domina la llanura de inundación del Jarama. Ofrece una fisonomía desértica de badlands de tonos blanquecinos con abundancia de cavidades naturales y vegetación gipsófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28041','espacio','Barrancos del río Jarama oriental y lomas margosas','Relieve ondulado de la campiña de transición, labrado sobre materiales arcillo-arenosos expuestos a erosión hídrica superficial. Ofrece visuales diáfanas y despejadas desprovistas de relieve abrupto o de masas arbóreas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28046','espacio','Cerro del Castillo, Jaralón y berrocales graníticos','Relieve de piedemonte caracterizado por colinas graníticas y afloramientos de bloques redondeados por la erosión. El paisaje destaca por sus dehesas estables de encina que conviven de manera armoniosa con las caprichosas formas de la roca viva gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28047','espacio','Cuenca alta del río Guadarrama y dehesas aluviales','Fosa tectónica donde se acumulan sedimentos arenosos procedentes del desmantelamiento granítico de la sierra de Guadarrama. Ofrece horizontes abiertos y llanos interrumpidos por fresnedas maduras y el curso del río sobre cantos rodados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','espacio','Páramo de Colmenar y cañón del río Tajo','Altiplano calizo del Plioceno que se interrumpe de forma tajante hacia la vega aluvial del Tajo, modelando profundos escarpes y barrancos. Ofrece un paisaje estepario con una nítida estratificación geológica en sus canteras naturales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28042','espacio','Dehesas del río Perales y berrocales graníticos occidentales','Paisaje caracterizado por un relieve ondulado de arenas graníticas cubierto por una de las masas de encinar mediterráneo más estables de la zona central, flanqueando un curso de agua estacional con ricas alamedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','espacio','Cañón del río Manzanares, puente de la Marmota y alto de la dehesa','Impresionante desfiladero fluvial donde el río Manzanares corta en vertical el zócalo granítico del piedemonte de Guadarrama. Presenta imponentes farallones de piedra gris de formas angostas, marmitas de gigante en el lecho del río y encinares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28044','espacio','Riberas del río Aulencia y embalse de Valmayor (cola)','Espacio donde el río Aulencia discurre encajonado entre lomas de granito y gneis antes de remansarse en el embalse. Ofrece una vista contemplativa de láminas de agua rodeadas por un denso manto forestal de encinar y jarales mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28048','espacio','Paraderas de Corpa y fuentes del páramo','Altiplano calizo de la Alcarria madrileña con formas de relieve suaves labradas por la escorrentía difusa, donde la alta permeabilidad genera manantiales naturales de agua. Ofrece horizontes diáfanos y limpios de carácter estepario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28049','espacio','Terrazas fluviales del río Henares bajo','Espacio estrictamente plano compuesto por sedimentos cuaternarios de arenas, limos y gravas transportadas por el río. El interés natural es limitado debido a la horizontalidad uniforme del relieve.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28050','espacio','Llanuras de la Sagra alta y arroyo de la Guatén','Terreno horizontal de la submeseta sur compuesto por arcillas y arenas miocénicas estables dedicadas a la agricultura. Ofrece vistas abiertas de horizontes limpios sin accidentes geográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28053','espacio','Campiña del río Torote y lomas arcillosas','Relieve ondulado suave constituido por depósitos arcillo-margosos terciarios propensos a la erosión remontante de pequeños arroyos. Ofrece una fisonomía esteparia diáfana desprovista de masas forestales continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','espacio','Monte Abantos, Pinar de la Abantos (vertiente sur) y dehesa de la Herrería','Impresionante paisaje montañoso caracterizado por imponentes pendientes de granito y gneis cubiertas por densos bosques mixtos de robles, castaños relictos y pinos resineros. Las monumentales laderas dominan visualmente la transición hacia la meseta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28055','espacio','Meandros del río Tajo e islas fluviales de Estremera','Tramo donde el río Tajo discurre divagante describiendo curvas amplias sobre sedimentos cuaternarios en el límite con Cuenca. Ofrece un paisaje acuático con ricos sotos ripícolas estables compuestos por alisos, sauces y chopos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28056','espacio','Dehesas graníticas del Perales y dehesa de la Oliva','Relieve ondulado de arenas arcósicas con presencia de afloramientos menores de bloques graníticos redondeados. Ofrece una fisonomía de encinar y fresnedas de gran pureza visual con pequeños arroyos estacionales de montaña baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28057','espacio','Valle fluvial del río Torote y cárcavas marginales','Depresión erosiva donde el río Torote labra terrazas aluviales encajadas entre colinas de arcillas y margas. Ofrece una panorámica de la campiña baja con sutiles bandas de coloración ocre expuestas por la escorrentía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28058','espacio','Llanura aluvial del arroyo de Culebro','Terreno marcadamente horizontal constituido por limos, arcillas y depósitos aluviales cuaternarios finos. Su valor contemplativo se reduce a la inmensidad del horizonte llano mesetario sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28059','espacio','Terrazas aluviales del río Jarama medio y vegas bajas','Espacio plano de sedimentación cuaternaria compuesto por potentes depósitos de gravas, arenas y limos fluviales. Ofrece visuales diáfanas del cauce flanqueado por una franja fragmentada de sauces y cañaverales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','espacio','Cañón del río Tajo, escarpes yesíferos de Fuentidueña y humedales menores','Espectacular tramo donde el río Tajo corta de forma abrupta las estructuras yesíferas del Terciario, labrando farallones y cortados verticales de gran impacto geométrico. El   contraste entre el río y los taludes áridos blanquecinos es sobresaliente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28061','espacio','Parque Regional del Curso Medio del Río Guadarrama y cañón del río Aulencia','Desfiladero fluvial excavado sobre el zócalo granítico donde el río discurre confinado entre escarpes rocosos y grandes canchales de piedra gris. Alberga una masa forestal continua de encinar mediterráneo y jarales de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28062','espacio','Valle del Lozoya alto, riscos de la Sierra de la Cabrera y dehesas del río','Ubicación montañosa excepcional en la vertiente norte, caracterizada por un relieve de pendientes extremas labrado sobre gneis y pizarras hercínicas. Ofrece amplios horizontes visuales limpios sobre el cauce transparente y frío del río Lozoya.   Gargantilla del Lozoya y Pinilla de Buitrago - Puntuación: 84/100 • Paraje: Valle del río Lozoya y riberas del embalse de Riosequillo.     Descripción: Valle de modelado glaciar y tectónico profundo flanqueado por las imponentes cumbres de la Sierra de Guadarrama. La inmensa lámina de agua del embalse se integra de forma armónica entre pastizales alpinos altos y densos robledales rebollos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28064','espacio','Sierra de Somosierra occidental y arroyo de Gascones','Término quebrado de alta montaña integrado en la Sierra Norte, labrado sobre pizarras paleozoicas y gneis. Presenta valles colgados con arroyos de deshielo hipertransparentes y laderas umbrías tapizadas por densas masas de pino silvestre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28065','espacio','Parque Regional del Sureste, Cerro de los Ángeles y riberas del río Manzanares bajo','Promontorio testigo de origen sedimentario arcillo-calcáreo que emerge de forma exenta y cónica en mitad de la llanura del Jarama. Ofrece una panorámica geográfica de la submeseta sur y los cortados yesíferos marginales de la cuenca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28066','espacio','Llanos de la cuenca media baja del Guadarrama','Terreno horizontal con pendientes mínimas constituido por sedimentos miocénicos estables de arenas arcósicas. Presenta una fisonomía de campiña diáfana desprovista de accidentes geográficos notables o masas arbóreas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28067','espacio','Embalse de Pedrezuela y cañón del río Guadalix','Estrechamiento fluvial donde el río excava un desfiladero rocoso sobre calizas cretácicas y granitos antes de remansarse. Ofrece una panorámica de amplias láminas de agua encajonadas entre laderas de encinar mediterráneo y enebros de miera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28068','espacio','Puerto de Guadarrama, Alto del León y umbrías de la Cabeza Líjar','Relieve de alta montaña alpina configurado por potentes farallones y escarpes de granito del eje central de la cordillera. Destaca por sus pendientes vertiginosas, canales de avalanchas cubiertas de pino silvestre y canchales de piedra gris expuesta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28069','espacio','Reserva de la Biosfera de la Sierra del Rincón, cañón del río Jarama alto y dehesas de robles centenarios','Uno de los enclaves de montaña más aislados y espectaculares de la provincia, enclavado en un relieve de pizarras y gneis. El río Jarama da sus primeros pasos encajonado en un desfiladero de umbría absoluta, flanqueado por robles melojos y abedulares de valor planetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28070','espacio','Valle del río Madarquillos y cumbres de Somosierra','Término quebrado de alta montaña con fuertes pendientes rocosas compuestas por cuarcitas y pizarras oscuras. Destaca por la contemplación visual del río Madarquillos encajonado en un fértil dehesa de montaña con avellanos, fresnos y robles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28071','espacio','Valle de Horcajuelo y arroyos de la Sierra del Rincón','Paisaje caracterizado por un relieve montañoso liso y redondeado sobre materiales paleozoicos de gran antigüedad geológica. Ofrece un tapiz verde perenne de robledales rebollos de montaña alta, brezales húmedos y arroyos de deshielo hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28072','espacio','Sierra de Hoyo, berrocales de la Tortuga y encinares graníticos','Impresionante macizo granítico exento que se eleva de forma abrupta de la fosa de Madrid, caracterizado por un laberinto mineral de bloques y bolos redondeados. Ofrece una fisonomía rugosa donde los encinares maduros y jarales colonizan los pasillos de roca viva.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28073','espacio','Llanura aluvial del arroyo de Guatén medio','Espacio estrictamente plano de sedimentación terciaria fina, caracterizado por la ausencia absoluta de accidentes topográficos notables. El valor visual se limita a la limpieza geométrica del diáfano horizonte agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28074','espacio','Cuenca del arroyo de Butarque y lomas de arenas arcósicas','Terreno de colinas muy bajas compuesto por arenas y arcillas cuaternarias procedentes de la erosión de la sierra de Guadarrama. Ofrece horizontes abiertos y diáfanos característicos de la campiña baja del sur.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28075','espacio','Campiña del Jarama oriental y lomas arcillosas','Relieve de suaves colinas margosas y arcillas terciarias del Mioceno medio con formas redondeadas por la erosión hídrica superficial. Presenta un paisaje agrario diáfano desprovisto de accidentes topográficos severos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28076','espacio','Valle alto del Lozoya, Sabinar de Lozoya y embalse de Pinilla','Excepcional cubeta tectónica y glaciar que alberga una de las principales masas calcáreas de la Sierra Norte, con presencia de un raro sabinar albar de alta montaña. Ofrece una inmensa lámina de agua permanente que refleja las cumbres de Guadarrama.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28901','espacio','Berrocal de Sieteiglesias y dehesas graníticas del río Lozoya','Complejo de relieve ondulado caracterizado por potentes afloramientos de bloques graníticos redondeados de colosales dimensiones. Ofrece una estampa tranquila de rocas grises que emergen exentas de la tierra entre densas masas de encina y enebros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28078','espacio','Valle del río Madarquillos y laderas de pizarra de la Sierra Norte','El municipio menos poblado de la provincia, caracterizado por un relieve aserrado de fuertes desniveles sobre materiales paleozoicos. Destaca por el aislamiento   absoluto de sus paisajes boscosos cubiertos de densos melojares y arroyos cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','espacio','Monte de El Pardo y Casa de Campo (entornos naturales geográficos)','Excepcional e histórico complejo forestal de encinar mediterráneo de llanura asentado sobre arenas arcósicas y terrazas cuaternarias del río Manzanares. Ofrece una uniformidad visual y botánica de bosque continuo de encina madura único enclavado en una gran metrópolis.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28080','espacio','Monte de Majadahonda y cuenca media del río Guadarrama','Relieve ondulado de la rampa serrana compuesto por depósitos de arenas y arcillas graníticas del Mioceno. Ofrece horizontes despejados con encinares fragmentados y sutiles fenómenos de escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','espacio','La Pedriza del Manzanares, Embalse de Santillana, Yelmo y Ventana','Uno de los santuarios geomorfológicos y paisajísticos más espectaculares del planeta, compuesto por un laberinto colosal de riscos graníticos, domos de piedra lisa (El Yelmo), arcos naturales de roca y callejones minerales esculpidos por la erosión físico-química de forma sublime, que vierten sobre una gran balsa de agua perenne.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28083','espacio','Páramo de Meco y alcarrias del Henares norte','Plataforma calcárea tabular que define la fisonomía de la Alcarria Alta antes de descender mediante pendientes marcadas hacia el río Henares. Ofrece horizontes despejados de carácter estepario y texturas de suelo blanquecino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28084','espacio','Parque Regional del Sureste y confluencia de los ríos Henares y Jarama','Nudo hidrológico aluvial de la depresión del Tajo donde ambos ríos unifican sus cauces sobre amplias terrazas de gravas y limos cuaternarios. Ofrece imponentes escarpes de arcilla y yesos en los márgenes y sotos de galería estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28085','espacio','Puerto de la Morcuera, Hueco de San Blas y pico de la Najarra','Espectacular cabecera de valle de montaña alpina bajo los colosales paredones de calizas y gneis del macizo de la Cuerda Larga. Alberga majestuosos bosques continuos de pino silvestre y robledales rebollos de montaña alta, con cascadas de deshielo atronadoras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28086','espacio','Atalaya del Molar, cortados del río Guadalix y cuevas de yesos','Espacio de transición geológica donde las plataformas calizas de la Alcarria se cortan hacia la campiña, dejando al descubierto potentes taludes de margas y cuevas naturales de yeso cristalino. Ofrece interesantes contrastes de luz y relieve quebrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28087','espacio','Peñota, Siete Picos (vertiente sur) y dehesas de los Molinos','Entorno montañoso de la Sierra de Guadarrama con desniveles colosales sobre granitos y gneis del eje hercínico. Destaca por sus canchales de piedra, arroyos alpinos de deshielo hipertransparentes y un dosel continuo de pino silvestre y robles de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28088','espacio','Hayedo de Montejo (Patrimonio de la Humanidad) y río Jarama alto','Uno de los santuarios botánicos más colosales y perfectos de Europa, consistente en un bosque relicto de hayas (Fagus sylvatica) que se mantiene en un microclima de umbría húmeda extrema a orillas del Jarama primario, sobre pizarras y gneis paleozoicos de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28089','espacio','Llanuras de la cuenca baja del Guadarrama oriental','Terreno de colinas bajas arcillo-arenosas miocénicas sujetas a procesos de erosión laminar suave por las labores agrícolas, ofreciendo una fisonomía horizontal y diáfana sin accidentes geográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28090','espacio','Laderas de la Sierra de Hoyo norte y dehesas graníticas','Espacio de transición geológica caracterizado por un relieve ondulado de arenas arcósicas con presencia de afloramientos de bloques graníticos redondeados. Ofrece una de las fresnedas y dehesas de encina más extensas y estables del piedemonte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28091','espacio','Cortados de Morata y valle aluvial del río Tajuña','Profunda incisión fluvial donde el río Tajuña excava las plataformas calizas de la Alcarria meridional, dejando imponentes paredes verticales de roca caliza y yesos de gran valor estético, rodeadas por una fértil vega aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28092','espacio','Riberas del río Guadarrama y parque natural de El Soto (entorno fluvial)','Tramo aluvial donde el río Guadarrama ensancha su lecho de arenas arcósicas depositando limos cuaternarios. Ofrece una fisonomía de campiña baja con pequeños sotos de galería compuestos por sauces, chopos y cañaverales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28093','espacio','Puerto de Navacerrada, Bola del Mundo, Valle de la Barranca y embalse de Navacerrada','Uno de los epicentros paisajísticos de alta montaña alpina del Sistema Central. Presenta colosales riscos de gneis desnudados por la erosión crioclástica, lagunas de origen glaciar sepultadas, cascadas de deshielo atronadoras y bosques prístinos subalpinos de pino silvestre de un impacto visual colosal, que vierten sobre una gran balsa de agua perenne.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28094','espacio','Dehesas de Navalafuente y arroyo de Gargantilla','Paisaje de media montaña caracterizado por un relieve ondulado sobre gneis y pizarras hercínicas con presencia de pequeños arroyos de cabecera que corren bajo densos bosquetes mixtos de roble rebollo, encinas y sauces de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28095','espacio','Cañón del río Perales y riscos de la Degollada','Angosto y profundo desfiladero fluvial excavado de forma sinuosa sobre calizas y granitos paleozoicos por el río Perales. Las imponentes paredes verticales de roca gris albergan cuevas aéreas y están rodeadas de frondosos encinares y jarales de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28096','espacio','Cárcavas del arroyo de la dehesa y lomas de arenas','Relieve ondulado suave del sudoeste provincial constituido por arenas de matriz granítica terciarias propensas a la erosión hídrica. Ofrece horizontes abiertos y diáfanos de campiña con sutiles escorrentías en las pendientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28097','espacio','Chorrera de San Mamés y Sierra de Somosierra','Espectacular e imponente salto de agua de montaña con más de treinta metros de caída vertical libre sobre una pared descarnada de gneis en mitad de la   cordillera. El entorno de umbría ofrece un paisaje forestal de pino silvestre y robledales rebollos de enorme fuerza estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28099','espacio','Cañón del río Alberche y dehesas de Navas','Tramo donde el río Alberche corta las estructuras graníticas del extremo occidental de la provincia, modelando un cañón fluvial con pequeños farallones rocosos y dehesas estables de encina que caen hacia el agua cristalina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28100','espacio','Páramo de Nuevo Baztán y barranco de la Olmeda','Plataforma calcárea tabular de la Alcarria de Alcalá que define un horizonte de líneas limpias, interrumpido por la erosión remontante de pequeños arroyos que forman barrancos arcillosos suaves cubiertos de encinar de carácter arbustivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28101','espacio','Valle de la Olmeda y escarpes calizos alcarreños','Cuenca erosiva de gran armonía paisajística con laderas calizas y de margas cubiertas de densas masas forestales de encinar mediterráneo y quejigo. Ofrece una composición visual de cañones alcarreños de umbrías estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28102','espacio','Valle del río Tajuña y cortados de yesos orientales','Tramo donde el río Tajuña labra un valle encajonado de vertientes escarpadas y terrazas de calizas y margas del Mioceno. Destaca por el contraste geomorfológico entre las plataformas superiores desnudadas y las laderas cubiertas de encinar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28104','espacio','Mirador de Paracuellos (escarpe del páramo) y cortados del río Jarama','Imponente cornisa natural caliza y arcillosa que define el fin del páramo alcarreño, interrumpiéndose de forma abrupta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28106','espacio','Llanuras de la campiña baja del sur','Terreno estrictamente plano de la submeseta sur compuesto por sedimentos finos arcillo-limosos del Terciario central. Su valor estético se limita a la inmensidad diáfana de un horizonte completamente abierto y desprovisto de accidentes topográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','espacio','Cárcavas de Patones (Pontón de la Oliva), cañón del río Lozoya y Cancho de la Cabeza','Uno de los conjuntos geológicos más espectaculares de la provincia. Presenta imponentes cortados verticales de calizas cretácicas replegadas y las colosales Cárcavas de arcilla roja, un laberinto de afiladas agujas, pirámides de tierra y profundas hendiduras de una fuerza cromática y visual sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28108','espacio','Cañón del río Guadalix, embalse de Pedrezuela (vertiente sur) y cuevas calizas','Angosto desfiladero fluvial labrado por el río Guadalix sobre calizas cretácicas y granitos. Las orillas rocosas verticales de tonos grises y la fuerza de las corrientes ofrecen una estampa de gran potencia visual, rodeada de encinares mediterráneos estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28109','espacio','Embalse de San Juan, río Alberche y cerro de San Esteban','Paisaje granítico occidental caracterizado por el encajonamiento absoluto del río Alberche entre montañas verticales de bloques de piedra redondeados y grandes   domos calizos. Ofrece una inmensa lámina de agua turquesa rodeada de densos pinares de pino piñonero de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28110','espacio','Risco de las Cuevas, cañón del Tajuña y muelas calizas','Monumental murallón vertical de roca caliza jurásica eocénica que presenta una espectacular profusión de oquedades y cuevas naturales de disolución kárstica y erosión eólica, que se asoman de forma vertical sobre el lecho aluvial del río Tajuña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28111','espacio','Páramo de Pezuela y cabecera del río Tajuña (vertiente alcarreña)','Altiplano calizo elevado que define la fisonomía de la Alcarria Alta en el límite con Guadalajara. Ofrece horizontes abiertos y diáfanos de carácter estepario con sutiles escorrentías en los márgenes de la muela tabular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28112','espacio','Valle alto del Lozoya, yacimientos kársticos del Calvero de la Higuera y río Lozoya','Entorno de alta montaña prepirenaica caracterizado por un valle de modelado glaciar profundo flanqueado por imponentes macizos calcáreos. Ofrece interesantes complejos de cuevas kársticas aéreas, praderas húmedas y una panorámica limpia de las cumbres de Guadarrama.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28113','espacio','Parque Regional del Sureste (límite sur) y lomas yesíferas de Pinto','Espacio aluvial y de transición geológica caracterizado por terrazas sedimentarias cuaternarias estables y colinas bajas de yesos del Terciario superior. Ofrece horizontes   diáfanos con formas suaves modeladas por la escorrentía superficial difusa.   Madrid).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28115','espacio','Monte de Pozuelo y cuenca media del arroyo de Antequina','Relieve ondulado suave del piedemonte serrano constituido por arenas arcósicas y arcillas miocénicas. Destaca por albergar masas forestales fragmentadas de encinar mediterráneo que rompen de forma suave el horizonte horizontal de la submeseta norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28116','espacio','Parameras de la Alcarria de Alcalá y llanuras calcáreas','Altiplano calizo horizontal perfecto compuesto por calizas lacustres del Terciario superior. Ofrece horizontes diáfanos limpios de carácter marcadamente estepario, donde   se aprecian sutiles fenómenos de escorrentía en los márgenes de las muelas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28117','espacio','Reserva de la Biosfera de la Sierra del Rincón y dehesas del río de la Puebla','Entorno montañoso del Sistema Central caracterizado por laderas de pendientes extremas compuestas por pizarras paleozoicas y gneis. Alberga frondosos bosques de umbría con robles rebollos centenarios, acebedos y un lecho fluvial de aguas hipertransparentes de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28118','espacio','Sierra de la Puebla, valle del río de la Puebla y riscos de pizarra','Impresionante y aislado valle de montaña de la Sierra Ayllón madrileña, encajonado de forma vertiginosa entre murallones verticales de pizarras oscuras. Ofrece un paisaje mineral agreste y salvaje con inmensos canchales de piedra, arroyos torrenciales y una quietud visual sobrecogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','espacio','Embalse de Puentes Viejas, río Lozoya y dehesas de El Berrueco','Complejo hidrológico encajonado donde las aguas del río Lozoya discurren confinadas describiendo meandros sinuosos sobre el zócalo de gneis. La inmensa lámina de agua turquesa se integra de forma armónica entre densos pinares de pino silvestre y encinares de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28119','espacio','Llanos de Quijorna, arroyo de las Cavadas y encinares de transición','Espacio de transición geológica entre las rampas graníticas de la sierra y la cuenca sedimentaria del Tajo. Ofrece una fisonomía de colinas suaves cubiertas por   una masa continua de encinar maduro y monte bajo mediterráneo con pequeños barrancos arcillosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','espacio','Parque Nacional de la Sierra de Guadarrama, Macizo de Peñalara, Valle del Lozoya y Cascadas del Purgatorio','Uno de los santuarios de modelado glaciar y periglacial más colosales del Sistema Central, dominado por el pico de Peñalara y sus lagunas alpinas transparentes sobre granitos y gneis. Presenta cascadas monumentales en roca pura, canchales vertiginosos y el mayor bosque continuo de pino silvestre (Pinus sylvestris) de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28121','espacio','Dehesa de Redueña y cortados calizos del Cretácico','Singular estrechamiento geológico caracterizado por un frente de murallones de roca caliza vertical que marca la transición al piedemonte. Ofrece interés por el modelado kárstico superficial, pequeñas oquedades aéreas y la presencia de quejigares y encinares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28122','espacio','Valle del arroyo de Valdeatienza y rañas de la campiña','Paisaje quebrado caracterizado por plataformas elevadas de cantos de cuarcita englobados en matrices arcillosas rojizas (rañas). Ofrece un fuerte contraste cromático en sus laderas erosionadas y pequeños barrancos estacionales con encinar fragmentado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28123','espacio','Parque Regional del Sureste, Junta de los Ríos (Jarama y Manzanares) y Cortados de Rivas','Monumental e impresionante frente de acantilados yesíferos con paredes totalmente verticales de color blanquecino y gris que superan los 100 metros de caída limpia sobre el río Jarama. Las lagunas de origen freático a sus pies reflejan la magnitud geológica de esta falla del Terciario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28124','espacio','Umbrías del río Lozoya y colas del embalse de El Atazar','Término quebrado de la Sierra Norte con vertientes de fuertes pendientes compuestas por pizarras y esquistos paleozoicos desmantelados. Destaca por las panorámicas despejadas que permiten contemplar las lenguas de agua encajadas en el relieve mineral salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28125','espacio','Sierra de la Almenara, río Cofio y pinares de Robledo','Relieve montañoso caracterizado por imponentes crestas de granito y gneis que flanquean el cauce encajonado y tortuoso del río Cofio. Ofrece una composición visual de gran verdor con masas compactas de pino piñonero y encinares estables de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28126','espacio','Dehesa de Robregordo, acebeda de Robregordo y altos de Somosierra','Vertiente de alta montaña atlántica del Sistema Central labrada sobre gneis, que alberga un rarísimo e histórico reducto botánico de acebos (Ilex aquifolium) de porte arbóreo monumental en umbría absoluta, rodeado de arroyos cristalinos de deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28127','espacio','Curso medio del río Guadarrama y dehesa de Navalcarbón (entorno natural)','Espacio aluvial de piedemonte donde el río Guadarrama excava terrazas sedimentarias arcósicas. Ofrece una vista diáfana de lomas suaves cubiertas de encinar mediterráneo con pequeños sotos ripícolas que marcan los cauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28128','espacio','Castañar de Rozas de Puerto Real y embalse de Los Morales','Impresionante umbría forestal encajada entre relieves graníticos occidentales, que alberga el bosque de castaño (Castanea sativa) más extenso y monumental de la Comunidad de Madrid, ofreciendo un espectáculo cromático otoñal e invernal sobresaliente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28129','espacio','Cañón del río Guadalix y cascadas del Hervidero','Hermoso desfiladero fluvial donde el río Guadalix corta las estructuras graníticas y metamórficas del zócalo, labrando saltos de agua encajonados sobre pozas de piedra oscura. Las orillas verticales están rodeadas de frondosos bosques de galería y encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28130','espacio','Parque Regional del Sureste (tramo norte) y sotos del río Jarama','Amplia llanura aluvial cuaternaria de sedimentación limosa donde confluyen de forma majestuosa los ríos Henares y Jarama. Ofrece una estampa tranquila de quietud fluvial con sotos de galería bien conservados dominados por sauces y álamos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','espacio','Paraje Natural de la Sierra de Guadarrama, monte Abantos y bosque de la Herrería','Monumental ladera montañosa granítica que se eleva de forma abrupta configurando un balcón natural colosal sobre la submeseta. Destaca por sus canchales de grandes bloques de piedra gris meteorizada y por albergar maduros e impenetrables bosques de roble melojo, pino silvestre y castaños centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28132','espacio','Humedales de San Martín, río Jarama y cortados de yeso orientales','Espacio de la vega baja del Jarama caracterizado por una inmensa horizontalidad sedimentaria interrumpida hacia el este por los farallones blanquecinos de   la meseta caliza. Aloja pequeños complejos lagunares freáticos rodeados de carrizales estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','espacio','Embalse de San Juan, gargantas del río Alberche y cerro de Guisando (límite)','Espectacular composición donde una inmensa lámina de agua perenne se encaja de forma laberíntica entre colosales relieves graníticos y domos de roca viva lisa. Las laderas verticales están vestidas por una masa forestal continua de pino piñonero de gran potencia estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28134','espacio','Dehesa Boyal de San Sebastián y riberas del río Jarama','Relieve ondulado suave del piedemonte constituido por depósitos arcillo-arenosos miocénicos. Destaca por albergar un encinar maduro adehesado con horizontes despejados que miran hacia la llanura aluvial del Jarama.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28135','espacio','Cañón del río Aceña, río Cofio y peñas del Chivato','Espectacular paisaje de alta montaña occidental en el límite con Ávila, caracterizado por profundas gargantas excavadas por los ríos sobre gneis y pizarras hercínicas oscuras. Ofrece vertientes vertiginosas de fisonomía salvaje con saltos de agua y densos pinares alpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28136','espacio','Valle del arroyo de Anchuelo y muelas de la Alcarria','Altiplano ondulado de la meseta oriental madrileña modelado sobre arcillas y calizas del Mioceno. Ofrece una vista limpia de la estratificación sedimentaria en los cortes de las colinas y pequeños matorrales mediterráneos bajos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28137','espacio','Escarpe de la Humosa y páramo de la Alcarria','Imponente cornisa caliza natural que se corta de forma drástica y vertical elevándose casi 200 metros sobre la llanura aluvial del río Henares. Ofrece una panorámica geomorfológica colosal y limpia que abarca toda la campiña baja de Madrid y Guadalajara.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28140','espacio','Llanuras aluviales de la cuenca baja del Guadarrama','Terreno estrictamente horizontal compuesto por arcillas y sedimentos finos miocénicos de la submeseta meridional. Su valor contemplativo se limita a la inmensidad lineal del diáfano horizonte desprovisto de accidentes topográficos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28141','espacio','Dehesas de Sevilla la Nueva y arroyo del Sotillo','Relieve de colinas muy bajas y formas redondeadas constituido por arenas de erosión granítica (arcosas). Destaca por la uniformidad visual de sus dehesas estables de encina con horizontes limpios de campiña alta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28143','espacio','Puerto de Somosierra, dehesa de Somosierra y Chorrera de los Litueros','Espectacular cabecera de alta montaña alpina axial que marca la divisoria de aguas del Sistema Central. Alberga la Chorrera de los Litueros, un monumental e impresionante salto de agua cristalina sobre paredes de gneis y pizarras oscuras que da nacimiento al río Duratón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28144','espacio','Hoya de San Blas, dehesa de Soto y faldas de la Cuerda Larga','Impresionante cubeta de origen tectónico rodeada por los colosales contrafuertes de gneis y granito del Parque Nacional de Guadarrama. Ofrece un paisaje vegetal maduro de robledales rebollos, pastizales colgados de montaña alta y pinares de gran nitidez visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28145','espacio','Riberas del río Jarama e islas de sedimentación','Tramo fluvial protegido donde el río Jarama ensancha su lecho aluvial y se ramifica creando islas sedimentarias cuaternarias de cantos rodados y arenas. Aloja uno de los bosques de galería (alisedas y choperas) mejor conservados y más maduros de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28146','espacio','Riscos de Tielmes, río Tajuña y muelas calizas','Profundo cañón fluvial labrado por el río Tajuña sobre las calizas lacustres de la Alcarria Baja, con farallones rocosos verticales de color blanquecino. Destaca por el contraste estético entre la piedra desnudada de las cumbres y el lecho verde del soto ribereño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28147','espacio','Parque Regional del Sureste, Corte del río Tajuña y confluencia Jarama-Tajuña','Espectacular nudo hidrológico donde el río Tajuña vierte sus aguas al Jarama a los pies de imponentes y verticales cortados yesíferos del Terciario inferior. Ofrece una fisonomía de gran fuerza visual con estratos geológicos expuestos y amplias láminas de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28148','espacio','Llanura aluvial del río Henares y terrazas de grava','Espacio estrictamente plano de la campiña baja compuesto por potentes depósitos de gravas y limos del Cuaternario. Su interés visual se reduce a la dinámica hidrológica elemental del curso del río Henares en sus márgenes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28149','espacio','Llanuras de la submeseta sur y arroyo de las Cárcavas','Terreno horizontal constituido por sedimentos finos arcillo-limosos del Terciario central desprovisto de   relieves notables. Su valor estético se limita a la inmensidad diáfana de un horizonte completamente plano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28150','espacio','Secanos de Torrejón y formaciones arcillosas del sur','Paisaje llano característico de la meseta meridional interrumpido por sutiles ondulaciones margosas propensas a la erosión laminar, ofreciendo una fisonomía esteparia austera de horizontes limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28151','espacio','Cerro de la Maliciosa norte, canal de Cabarrús y escarpes calizos','Zona de contacto geológico entre el zócalo granítico-pizarroso de la sierra y las cubiertas calizas de la Alcarria. Presenta laderas escarpadas de roca caliza del Cretácico con interesantes formas de disolución y vegetación mediterránea mixta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28152','espacio','Parque Regional de la Cuenca Alta del Manzanares y berrocal de Torrelodones','Extraordinaria concentración de bloques y colosales bolos graníticos redondeados por la meteorización físico-química. Las caprichosas formas de la piedra gris emergen exentas de la tierra entre dehesas maduras de encina y enebros de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28153','espacio','Vega del río Jarama y escarpes alcarreños occidentales','Tramo donde el río Jarama discurre encajonado entre las primeras terrazas graníticas de la sierra y los taludes de arcilla y caliza de la meseta alcarreña. Ofrece visuales limpias de sotos ripícolas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28154','espacio','Valle del arroyo de Pantueña y muelas arcillosas','Depresión erosiva de formas suaves labrada sobre materiales arcillo-margosos de la Alcarria de Alcalá. Ofrece una estampa contemplativa marcada por la geometría de las vertientes onduladas cultivadas y pequeños coscojares marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28903','espacio','Parque Regional de la Cuenca Alta del Manzanares (limite este) y arroyo de Tejada','Relieve ondulado suave asentado sobre arenas graníticas y arcos sedimentarios del somontano de la sierra. Permite la contemplación de horizontes diáfanos limpios cubiertos por masas adehesadas de encina bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28155','espacio','Parameras de Valdaracete y barrancos arcillosos de la Alcarria baja','Altiplano calizo tabular interrumpido por la erosión remontante de pequeños arroyos que forman cárcavas arcillosas. Ofrece una fisonomía esteparia mediterránea con amplios horizontes visuales limpios sobre la cuenca del Tajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28156','espacio','Llanuras de la campiña alta de Alcalá y lomas margosas','Plataforma elevada compuesta por sedimentos terciarios arcillo-arenosos con pendientes mínimas. Ofrece un paisaje horizontal y austero de horizontes limpios desprovisto de accidentes geográficos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28157','espacio','Valle de la Vega y muelas calizas de la Alcarria meridional','Profundo corte erosivo que rompe la continuidad de la muela calcárea, dejando al descubierto perfiles de calizas lacustres y arcillas en las laderas. Ofrece una composición armónica entre los escarpes de roca y el matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28158','espacio','Sierra de La Cabrera, Cancho Gordo y berrocales de Valdemanco','Espectacular y colosal paisaje granítico presidido por la alineación de la Sierra de la Cabrera, con imponentes crestones de piedra, domos lisos y laberintos minerales de bolos redondeados de color grisáceo que emergen entre masas densas de pino silvestre y robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28159','espacio','Cañón del río Cofio, dehesa de Valdemaqueda y pinares resineros','Impresionante desfiladero fluvial donde el río Cofio se encaja de forma radical entre las montañas graníticas occidentales del Sistema Central. Ofrece una fisonomía de laderas de vertiginosas pendientes vestidas por un dosel continuo e impenetrable de pino piñonero y resinero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28160','espacio','Rampa granítica de la sierra, río Perales y dehesas de Valdemorillo','Espacio de transición geológica caracterizado por afloramientos graníticos desmantelados y el curso encajonado del río Perales sobre pizarras paleozoicas. Destaca por sus amplios horizontes visuales limpios cubiertos de encinares y monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','espacio','Lomas yesíferas de Valdemoro y llanuras de la submeseta','Terreno ondulado suave constituido por margas y arcillas con potentes estratos de yeso cristalino del terciario medio. Ofrece interés visual por los destellos de los minerales bajo la luz del sol en las pendientes desnudas de vegetación arbolada compacta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28162','espacio','Campiña alta del Jarama y arroyo de la dehesa','Plataforma de raña compuesta por acumulaciones antiguas de cantos rodados cuarcíticos estables sobre suelos arcillosos de tonalidades rojizas, que ofrece visuales limpias de horizontes agrarios despejados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28163','espacio','Valle del arroyo de Micheo y colinas de pizarras marginales','Espacio de transición hacia la sierra de Ayllón caracterizado por colinas suaves de pizarras paleozoicas degradadas alternadas con sedimentos aluviales. Ofrece una fisonomía quebrada y rural de gran armonía visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28164','espacio','Terrazas fluviales del río Jarama y sotos de galería','Llanura aluvial cuaternaria de inundación donde el río Jarama dibuja curvas suaves depositando arenas finas y gravas. Ofrece una estampa contemplativa de sotos ripícolas bien conservados compuestos por sauces, chopos y cañaverales estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28165','espacio','Páramo de Valdilecha y barranco del río Tajuña (cabecera)','Plataforma calcárea tabular perfecta alcarreña que define la fisonomía de la muela antes de descender hacia el valle encajonado. Destaca por la horizontalidad de su horizonte y los sutiles procesos de escorrentía remontante en las vertientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28166','espacio','Valle del arroyo de Pantueña y lomas margosas','Depresión erosiva suave de la Alcarria de Alcalá labrada sobre arcillas miocénicas propensas a la erosión laminar. Ofrece horizontes abiertos y despejados desprovistos de relieve abrupto o de formaciones arboladas nativas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28167','espacio','Parque Regional del Sureste, Lagunas de Velilla y cortados del Jarama','Complejo lagunar freático de aguas calmas y permanentes asentado al pie de monumentales e imponentes cortados yesíferos verticales esculpidos por el río Jarama. Ofrece una composición de gran fuerza visual con extensos carrizales y espadañales perilagunares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28168','espacio','Cañón del río Guadalix, embalse de Pedrezuela (cola) y escarpes calizos','Tramo donde el río Guadalix excava un desfiladero labrado sobre calizas cretácicas y pizarras del zócalo antes de remansarse. Ofrece una panorámica de laderas rocosas escarpadas cubiertas de vegetación mediterránea esclerófila de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28169','espacio','Atalaya natural de Venturada y piedemonte granítico','Cornisa de rocas graníticas desmanteladas y gneis que conforma un mirador geográfico natural con vistas panorámicas excepcionales sobre la cuenca del Guadalix y la campiña baja, rodeada de dehesas de encina y fresno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28170','espacio','Barranco de Villaconejos y parameras de yesos del Tajo','Relieve ondulado caracterizado por potentes estratos de yeso cristalino y arcillas miocénicas de la cuenca baja. Ofrece interés visual por las caprichosas formas de escorrentía hídrica en las pendientes áridas de tonalidades blanquecinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28172','espacio','Cerro de San Juan, muelas calizas de la Alcarria y barranco del Viso','Conjunto de plataformas calcáreas tabulares que emergen con fuerza interrumpiendo la campiña del   Henares. Ofrece una vista nítida de los taludes arcillosos de las vertientes y de los sutiles procesos de erosión remontante de las escorrentías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28173','espacio','Valle del río Tajo, escarpes calizos del sur y terrazas fluviales','Tramo final de la provincia donde el río Tajo discurre encajonado entre potentes farallones de calizas y margas oligocénicas del páramo. Ofrece una panorámica limpia de amplias láminas de agua que fluyen flanqueadas por ricas alamedas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28174','espacio','Valle del río Perales y lomas arcósicas','Cuenca aluvial de formas suaves labrada sobre arenas graníticas y arcillas pliocénicas por el curso bajo del río Perales. Ofrece horizontes despejados con sutiles meandros y pequeñas formaciones arbóreas ripícolas asociadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28175','espacio','Cañón bajo del río Perales y dehesas de encina','Pequeño encajonamiento fluvial donde el río Perales excava el terreno blando antes de su unión con el Alberche, flanqueado por colinas suaves cubiertas por una masa continua de encinar mediterráneo maduro bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28176','espacio','Curso medio del río Guadarrama y llanuras arenosas del Aulencia','Terreno de lomas muy suaves compuesto por arenas arcósicas depositadas por la erosión de la sierra. Destaca por sus amplios horizontes despejados de campiña y pequeños encinares fragmentados en las divisorias de aguas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28177','espacio','Valle del río Guadarrama y terrazas sedimentarias','Cuenca sedimentaria de piedemonte donde el río Guadarrama dibuja terrazas de gravas y arenas arcósicas. Ofrece una visual limpia dominada por la horizontalidad del terreno y las pequeñas hileras de sauces de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28178','espacio','Lomas arcósicas de la campiña del Alberche y arroyos temporales','Paisaje ondulado suave constituido por arenas arcósicas sueltas propensas a la erosión hídrica superficial difusa. Ofrece horizontes diáfanos limpios desprovistos de relieve abrupto severo o de masas forestales nativas compactas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28179','espacio','Valle del río Vega, muelas calizas de la Alcarria y dehesas forestales','Valle encajonado de la Alcarria Baja con laderas de pendientes pronunciadas cubiertas por masas estables de encinar y quejigar centenario. Ofrece una vista nítida del modelado erosivo de las plataformas calcáreas del Mioceno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','espacio','Páramo de Villarejo y barrancos de la Alcarria meridional','Altiplano calizo elevado tabular que define la divisoria de aguas entre las cuencas del Tajuña y el Tajo. Ofrece horizontes abiertos y diáfanos de carácter estepario con sutiles procesos de escorrentía remontante en las vertientes arcillosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28181','espacio','Parque Regional del Curso Medio del Río Guadarrama y El Forestal (entorno natural)','Tramo aluvial donde el río Guadarrama labra profundos taludes arenosos y arcillosos rodeados de dehesas estables de encina, conviviendo con un histórico y frondoso soto de galería naturalizado de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28182','espacio','Sierra de Guadarrama septentrional y dehesas del río Lozoya','Vertiente montañoso-silícea de la Sierra Norte caracterizada por laderas de pendientes acusadas compuestas por gneis y pizarras hercínicas. Destaca por sus dehesas estables de roble rebollo y fresnos, con horizontes limpios que miran al valle del Lozoya.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28183','espacio','Machotas (La Machota Alta y Baja) y lanchares graníticos de Zarzalejo','Espectacular alineación geomorfológica compuesta por dos colosales domos graníticos (Las Machotas) que emergen exentos en el límite con Ávila. Presenta impresionantes lanchares de roca viva lisa, laberintos minerales de bolos redondeados grises y castañares relictos de gran impacto estético.   ¡Objetivo cumplido con rigor absoluto! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90745','espacio','Reserva Natural de la Laguna de la Ratosa y lomas de la cuenca','Humedal endorreico de aguas temporales e hipersalinas asentado sobre un sustrato evaporítico triásico. Ofrece una fisonomía esteparia diáfana y una costra blanquecina de salinas interiores de gran nitidez geomorfológica durante el estío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90433','espacio','Parque Natural de las Sierras de Tejeda, Almijara y Alhama, Boquete de Zafarraya y pico La Maroma (vertiente norte)','Imponente brecha tectónica natural y vertical de roca caliza jurásica que fractura el relieve bético conectando con el altiplano granadino. Sus vertiginosas pendientes de mármoles dolomíticos grises albergan profundos barrancos y bosques subalpinos de pino laricio de gran fuerza visual.   Alfairate - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','espacio','Poljé de Alfarnate, Tajo de los Frailes y Sierra de Enmedio','Excepcional depresión kárstica de fondo plano (poljé) rodeada por un anfiteatro monumental de riscos calizos y farallones desnudados. Ofrece una composición visual de alta montaña bética única en la provincia, con texturas de piedra gris rugosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90435','espacio','Los Pirineos de la Axarquía, Tajo del Fraile, Tajo de Doña Ana y de Comares','Colosales e impresionantes pitones calizos exentos que emergen de forma dramática y vertical sobre el paisaje alomado de la Axarquía. Sus paredes de piedra viva caliza constituyen hitos geomorfológicos de extraordinario impacto contemplativo y visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','espacio','Valle bajo del río Algarrobo y escarpes prelitorales','Breve corredor fluvial encajonado sobre pizarras y esquistos meteorizados antes de su tramo costero deltaico. Ofrece horizontes diáfanos limpios con sutiles escorrentías y matorral mediterráneo xerófilo adaptado a las laderas expuestas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90437','espacio','Valle del río Genal, umbrías de Algatocín y crestones calizos','Impresionante paisaje forestal continuo de la Serranía de Ronda, caracterizado por vertientes escarpadas tapizadas de espesos castañares y alcornocales maduros. El relieve de pizarras contrasta vivamente con las agujas calizas grises calcáreas que coronan las cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90438','espacio','Vertiente norte de la Sierra de Mijas y barranco de la Zambrana','Macizo de mármoles dolomíticos blancos y calizas jurásicas que presenta fuertes pendientes y canchales basales. Destaca por la nitidez geológica de sus escarpes superiores cubiertos de pinar mediterráneo y matorral de romero y tomillo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','espacio','Sierra de Mijas (vertiente occidental) y barranco del Tejar','Relieve montañoso carbonatado caracterizado por profundos barrancos de erosión hídrica y surgencias kársticas menores en la base del mármol dolomítico. Ofrece panorámicas despejadas de gran potencia visual sobre el fértil valle del Guadalhorce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90440','espacio','Lomas arcillo-esquistoñas de la Axarquía y río Almáchar','Paisaje quebrado labrado sobre materiales del complejo alpujárride (pizarras y esquistos filadianos) intensamente erosionados en formas abarrancadas. Ofrece un laberinto visual de lomas romas de tonalidades oscuras y ocres.   Almedíjar - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90441','espacio','Nacimiento del río Almargen (Ojo de Almargen) y lomas salinas','Importante surgencia natural de aguas hipersalinas y sulfurosas ligada a los diapiros de yesos triásicos de la cuenca. Ofrece un paisaje austero y blanquecino de gran interés mineralógico con sutiles llanuras de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90442','espacio','Desfiladero del río Campanillas y relieves del flysch','Tramo donde el río Campanillas excava un valle encajonado sobre un sustrato de alternancias de areniscas y pizarras (flysch milonítico). Presenta una fisonomía quebrada y ruda de laderas de fuertes pendientes cubiertas de olivares silvestres y jarales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','espacio','Paraje Natural del Desfiladero de los Gaitanes (vertiente sur) y El Chorro','Uno de los cañones geológicos más monumentales y sobregogedores de Europa, donde el río Guadalhorce fractura en vertical murallones de calizas y conglomerados del Mioceno. Sus paredes verticales desnudas superan los 300 metros de caída libre limpia en pasillos minerales angostos de un impacto estético absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32001','espacio','Sierra de Prieta (faldas) y nacimiento del río Jorox','Espacio de transición geológica hacia las altas cumbres de la Sierra de las Nieves, caracterizado por farallones de caliza jurásica gris. El cañón de Jorox destaca por sus cascadas menores y formaciones de tobas calcáreas goteantes rodeadas de huertos tradicionales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90443','espacio','Los Riscos de Cartajima y Alpandeire y valle del río Audalázar','Impresionante e internacionalmente reconocido torcal y laberinto kárstico exterior compuesto por tormos, callejones de roca caliza erosionada en formas caprichosas y lapiaces profundos. Ofrece una estética mineral desolada de gran potencia visual rodeada de encinares montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','espacio','Paraje Natural del Torcal de Antequera y Peña de los Enamorados','Uno de los paisajes kársticos más colosales, perfectos e icónicos del planeta, declarado Patrimonio de la Humanidad. El modelado horizontal de estratos calizos del Jurásico mediante procesos de disolución y gelifracción ha esculpido un laberinto de piedras hongo, pasadizos minerales y esfinges rocosas de valor geomorfológico supremo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90746','espacio','Valle encajonado del río Turvilla','Pequeña cuenca fluvial prelitoral excavada de forma sinuosa sobre esquistos paleozoicos y pizarras. Ofrece una vista nítida de laderas de fuerte pendiente cubiertas de monte bajo mediterráneo y matorral xerófilo que flanquean el cauce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','espacio','Reserva Natural de las Lagunas de Archidona (Laguna Grande y Chica) y Hoz de Marín','Excepcional complejo de humedales cársticos de aguas permanentes sulfatadas, flanqueados por la Hoz de Marín, un desfiladero fluvial calizo de gran pureza. Ofrece una estampa contemplativa de aguas calmas rodeadas de carrizales y pinares estables de pino carrasco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','espacio','Desfiladero de los Gaitanes (vertiente norte) y embalses del Guadalhorce','Sector septentrional del colosal cañón fluvial calizo donde confluyen tres grandes ríos en un laberinto de láminas de agua perenne turquesa. Las imponentes   estructuras tectónicas replegadas y los paredones de conglomerados verticales componen un espectáculo geológico de primer orden.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','espacio','Cerro de Bentomiz y barrancos de la Axarquía oriental','Promontorio de materiales paleozoicos y pizarras oscuras que se eleva de forma abrupta configurando un balcón natural sobre el litoral malagueño. Ofrece amplios horizontes visuales limpios sobre relieves fuertemente abarrancados por la escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90444','espacio','Garganta del arroyo de la Ventilla','Profunda e inesperada incisión fluvial y cañón excavado sobre areniscas calcáreas (molasas) miocénicas en la Meseta de Ronda. El fondo del desfiladero alberga una ribera prístina en umbría absoluta con un frondoso bosque de galería maduro de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','espacio','Cañón de las Angosturas (Río Guadalmina)','Impresionante desfiladero fluvial esculpido sobre peridotitas (rocas ultramáficas de origen mantélico) y calizas tectónicas. El río fluye confinado en un pasillo mineral estrecho de paredes verticales pulidas por el agua, con pozas de color esmeralda hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29022','espacio','Tajo de Benadalid y peñas calcáreas del valle del Genal','Imponente murallón de roca caliza jurásica gris que emerge de forma exenta y tajante sobre las laderas boscosas de la Serranía de Ronda. Ofrece una fisonomía mineral rugosa con canchales basales y amplios horizontes visuales limpios hacia el valle.   Benahavís - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29024','espacio','Cañón de los Almendrales y umbrías de castañar del Genal','Relieve quebrado y forestal continuo caracterizado por un profundo barranco fluvial excavado en pizarras y esquistos paleozoicos. Las vertientes de umbría albergan majestuosos bosques de castaño de gran potencia cromática, coronados por crestones calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','espacio','Sierra de Mijas (frente oriental), Tajo del Quebradizo y acantilados marinos menores','Ladera montañosa carbonatada de fuertes pendientes compuesta por mármoles dolomíticos que caen de forma pronunciada hacia el mar de Alborán. Ofrece un paisaje mineral escarpado cubierto de pinar mediterráneo y matorral xerófilo adaptado a la salinidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29026','espacio','Valle aluvial del río Benamargosa y lomas de la Axarquía','Espacio donde el valle fluvial se ensancha sobre depósitos de limos y arenas cuaternarias, flanqueado por colinas de esquistos oscuros. Ofrece una estampa tranquila de campos esteparios interrumpidos por la franja vegetal del soto ribereño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29027','espacio','Cerros de la Axarquía baja y cuenca del río Vélez','Relieve ondulado de formas suaves labrado sobre materiales paleozoicos propensos a la erosión hídrica superficial difusa. Ofrece horizontes diáfanos limpios desprovistos de relieve abrupto severo o de masas arbóreas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','espacio','Cueva del Gato (Surgencia del Guadiaro), Cueva de la Pileta y cañón de Benaoján','Uno de los complejos hidrogeológicos y kársticos más monumentales de España, en el Parque Natural de Grazalema. Destaca la Cueva del Gato, una colosal boca   pétrea de donde resurge a la superficie un río subterráneo en forma de cascada cristalina sobre una poza pura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29029','espacio','Garganta de las Buitreras (límite oriental) y alcornocal de Benarrabá','Término que comparte un abismal e impresionante cañón fluvial calizo con paredes verticales estrechas que aprisionan el río Guadiaro. Las vertientes interiores del municipio albergan un frondoso bosque continuo de alcornoques y quejigos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29031','espacio','Nacimiento del río Turón, dique de El Burgo y Sierra de las Nieves norte','Cabecera fluvial prístina integrada en el Parque Nacional, flanqueada por los colosales murallones calizos y peridotitas del macizo bético. El río Turón fluye con aguas cristalinas color esmeralda entre sotos ripícolas de sauces y frondosos bosques de pino albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29032','espacio','Reserva Natural Lagunas de Campillos (Laguna Dulce, Salada y de Capacete)','Excepcional complejo lagunar endorreico de origen kárstico-tectónico asentado sobre materiales evaporíticos del Triásico. Sus extensas láminas de agua temporales y permanentes ofrecen una horizontalidad absoluta rodeada de cinturones de vegetación perilagunar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29033','espacio','Parque Natural de Sierra Tejeda, Saltillo del río Almanchares y pico La Maroma','Paisaje bético de alta montaña con vertiginosas pendientes calizas grises y de mármoles dolomíticos. Destaca el abismal desfiladero del río Almanchares, un cañón calizo de paredes totalmente verticales desnudas esculpido por la erosión de torrentes estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29034','espacio','Fábrica de la Luz, río Turvilla superior y umbrías de Sierra Tejeda','Término montañoso encajonado de forma longitudinal entre imponentes murallones calcáreos y mármoles cristalinos. Ofrece una vista nítida de arroyos de cabecera que brotan de la roca, rodeados de masas estables de pino resinero y quejigares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29035','espacio','Sierra de Cañete, Tajo del Padrastro y barrancos arcillosos','Colosal e icónica muela de piedra caliza jurásica con paredes totalmente verticales (El Padrastro) que emerge exenta sobre el relieve alomado del norte provincial. Ofrece un hito geomorfológico rudo de tonos grises rodeado de olivares y monte mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29036','espacio','Sierra de Alcaparaín, manantiales termófilos y escarpes calizos','Fractura tectónica profunda que permite el afloramiento directo de aguas minero-medicinales a los pies de murallones de roca caliza y peridotitas. Ofrece un paisaje quebrado de gran interés hidrogeológico y laderas cubiertas de pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29037','espacio','Los Riscos de Cartajima (Torcal del Alto Genal)','Espectacular y monumental torcal y laberinto kárstico exterior caracterizado por una colosal concentración de piedras hongo, callejones de roca caliza jurásica erosionada y lapiaces profundos, configurando un paisaje mineral desolado sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29038','espacio','Valle medio del río Guadalhorce y escarpes de arcilla','Amplia llanura aluvial cuaternaria de sedimentación limosa donde el río Guadalhorce ensancha su curso. Destaca por las panorámicas despejadas de la cuenca baja y las pequeñas hileras de sotos ripícolas fragmentados de sauces y cañaverales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29039','espacio','Cerros de Casabermeja y cuenca del río Guadalmedina','Relieve quebrado caracterizado por afloramientos de materiales flyschoides y arcillas rojas propensas a la erosión hídrica superficial. Ofrece una estampa de lomas redondeadas y pequeños barrancos con monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29040','espacio','Sierra de la Cruz, macizo de Alcaparaín y nacimiento de Coín (Albaía)','Impresionante vertiente caliza y dolomítica que marca el inicio del Parque Nacional de la Sierra de las Nieves, con paredes verticales de gran caída y canchales basales. Destaca por la pureza de sus fuentes y masas forestales de pino laricio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','espacio','Canuto de la Utrera (Torcal de Casares) y Sierra Crestellina','Espectacular desfiladero kárstico labrado sobre calizas jurásicas (Canuto de la Utrera) que conforma el torcal más meridional de Europa. El término destaca además por los afilados e imponentes crestones calizos de Sierra Crestellina colonizados por rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29042','espacio','Barranco Blanco (Río Alaminos) y dehesas de Albuqueria','Hermoso tramo fluvial excavado en el contacto de los mármoles dolomíticos de la sierra con las peridotitas del manto, labrando un lecho pedregoso de aguas cristalinas   hipertransparentes y pozas naturales rodeadas de densos pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29044','espacio','El Balcón de la Axarquía (Muela caliza de Comares)','Colosal plataforma y muela de piedra caliza que emerge de forma totalmente vertical y exenta, dominando de manera absoluta el laberinto de lomas arcillosas de la comarca. Ofrece una estructura geomorfológica limpia de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29045','espacio','Parque Natural de Sierra Tejeda, barranco del río Juanes y pico Lucero','Paisaje alpino bético caracterizado por imponentes farallones de dolomías cristalinas y mármoles blancos que desafían la gravedad en laderas de pendientes vertiginosas, cubiertas por un denso manto forestal de pino silvestre y resineros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','espacio','Monumental Garganta de las Buitreras (Río Guadiaro) y alcornocal de la Sauceda','Abismal cañón fluvial calizo declarado Monumento Natural, con grietas tectónicas y pasillos de roca totalmente verticales de más de 100 metros de caída libre que aprisionan el río. Alberga además el frondoso y húmedo bosque de alcornocales relictos de la Sauceda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29047','espacio','Riberas del río Genil y terrazas de grava de la Moheda','Tramo aluvial donde el río Genil ejerce de límite provincial fluyendo sobre una llanura de sedimentación cuaternaria. Ofrece una vista diáfana de amplias láminas de agua que corren custodiadas por un denso bosque de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29049','espacio','Falla de la Sierra de El Camorro y Cueva de Belda','Espectacular e imponente cresta caliza jurásica replegada que emerge exenta junto al curso remansado del embalse de Iznájar. Alberga la Cueva de Belda, una monumental cavidad kárstica con grandes salas de colapso geológico y lagunas interiores freáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29048','espacio','Nacimiento del río de las Cuevas y desfiladero del Carrizal','Importante y prístina surgencia kárstica de agua dulce que brota de los acuíferos calizos de la sierra alta, abriéndose paso a través de un estrecho pasillo rocoso calizo con formaciones de tobas y sauces de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','espacio','Paraje Natural de Los Reales de Sierra Bermeja','Uno de los afloramientos de peridotitas más extensos y colosales del planeta, caracterizado por montañas de rocas ricas en hierro y magnesio que adoptan un color rojizo granate intenso. Ofrece un paisaje mineral de pendientes extremas cubierto por el único bosque de pinsapos (Abies pinsapo) asentado sobre este sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29052','espacio','Chorreras de Balastar y valle del Genal','Espectaculares saltos de agua naturales escalonados con más de 20 metros de caída libre sobre impresionantes paredes de toba calcárea y travertinos activos, rodeados de huertos nativos tradicionales y densos encinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','espacio','Cañón del río Chíllar y Sierra de Almijara','Impresionante desfiladero fluvial kárstico (Los Cahorros) esculpido sobre dolomías y mármoles blancos, con pasillos minerales tan angostos que las paredes de piedra caliza se tocan con las manos sobre el flujo de agua hipertransparente y fría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29054','espacio','Desembocadura del río Fuengirola y litoral bajo','Espacio aluvial y deltaico modificado por la dinámica marina litoral sobre arenas finas. Su valor contemplativo natural es reducido, limitándose a la observación del curso final de sedimentación fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','espacio','Tajo de Gaucín, río Genal y asomaderos graníticos de la Serranía','Imponente fractura geológica coronada por un pitón calizo que domina visualmente la fosa del bajo Guadiaro. Ofrece un relieve abrupto y salvaje donde se cruzan las vertientes de pizarras paleozoicas con el monte mediterráneo perenne.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29057','espacio','Paraje Natural de Sierra Bermeja occidental, río Almárchar y dehesas del Genal','Entorno virgen de aislamiento absoluto caracterizado por colosales laderas de peridotitas rojizas y barrancos umbríos de pizarras. Alberga majestuosos bosques mixtos de alcornoque, castaño y pinsapos en relieves de pendientes vertiginosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29058','espacio','Arroyo de la Canasta y lomas de la Sierra de las Nieves','Espacio de piedemonte caracterizado por colinas suaves labradas sobre calizas y arcillas triásicas en la transición hacia la Hoya de Málaga. Destaca por el dosel regular de su monte mediterráneo arbustivo y encinares marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29059','espacio','Reserva Natural de la Laguna de Fuente de Piedra (límite sur) y Sierra de Humilladero','Término que comparte la inmensa cuenca endorreica palustre de la provincia, flanqueada por la Sierra de Humilladero, un relieve de calizas jurásicas cubierto de pinar de repoblación estable que rompe la horizontalidad de la llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29060','espacio','Nacimiento del río Genal y dehesas de castaños centenarios','Monumental surgencia natural clasificada como Monumento Natural, donde el río Genal brota con fuerza atronadora de las entrañas kársticas de una cueva caliza jurásica. El entorno ofrece una umbría de laderas escarpadas cubiertas de densos castañares de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29061','espacio','Nacimiento del río Molinos, Sierra Blanca y embalse de la Concepción','Espectacular manantial de origen kárstico donde el agua brota en un colosal borbollón de los acuíferos calizos y peridotitas de la sierra, vertiéndose de forma rápida hacia el embalse encajonado entre montañas desnudas de color rojizo y gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29062','espacio','Lomas de Iznate y barrancos de la Axarquía media','Relieve ondulado de formas romas labrado sobre esquistos y pizarras oscuras de la cuenca baja prelitoral. Ofrece un paisaje laberíntico de laderas erosionadas expuestas a la escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29063','espacio','Valle del río Guadiaro y murallón calizo de la Sierra de Líbar','Impresionante corte geográfico donde el río Guadiaro fluye encajonado flanqueando las monumentales e infranqueables paredes verticales calizas de la sierra de Líbar, cubiertas de densos encinares de montaña de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29064','espacio','Río Monardilla, dehesas forestales de castaños y vertiente de peridotitas','Término montañoso de la Serranía de Ronda asentado sobre la transición geológica de pizarras y rocas ultramáficas rojas de Sierra Bermeja. Ofrece profundos valles de umbría forestal continua de castañares y alcornocales maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29065','espacio','Torcal de los Riscos (compartido) y barranco del río de las Zúas','Entorno caracterizado por un relieve calizo kárstico muy quebrado con presencia de callejones de roca y monolitos, que da paso a profundos valles fluviales de umbría absoluta con sotos ripícolas estables e hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29066','espacio','Cerros de la Axarquía litoral y arroyo de Iberos','Relieve quebrado suave compuesto por materiales esquistosos paleozoicos expuestos a la escorrentía superficial. Ofrece amplios horizontes visuales que miran hacia la línea de costa con matorral bajo xerófilo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','espacio','Parque Natural Montes de Málaga, desembocadura del Guadalhorce y peñón del Cuervo','Extraordinaria confluencia de espacios que abarca desde el relieve abrupto e hiperfragmentado de flysch del Mioceno en los Montes hasta el humedal costero estuarino del Guadalhorce con sus lagunas arenosas y el promontorio calizo litoral del peñón del Cuervo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29068','espacio','Canuto de la Utrera occidental y lomas prelitorales','Frente de colinas calizas y arcillas triásicas en el extremo occidental provincial. Presenta un relieve   escarpado con sutiles pasillos minerales kársticos e interesantes vistas despejadas hacia el mar de Alborán.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29069','espacio','Sierra Blanca, pico de Juanar y dunas de Artola (entorno natural)','Imponente murallón montañoso de mármoles blancos calcáreos que se eleva de forma vertical a más de 1.200 metros junto a la costa mediterránea. En su fachada marítima conserva el Monumento Natural de las dunas de Artola, un sistema dunar costero de gran valor geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29070','espacio','Sierra de Mijas y cortados del Puerto de los Condes','Macizo carbonatado de relieves abruptos compuesto por mármoles dolomíticos grises y blancos desnudados por la erosión crioclástica. Ofrece amplias panorámicas sobre la costa y laderas cubiertas de matorral mediterráneo aromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29071','espacio','Lomas arcillo-esquistoñas de la Axarquía sur','Terreno de colinas bajas arcilloso-pizarrosas expuesto a una intensa erosión laminar. Ofrece horizontes diáfanos limpios de formas suaves desprovistos de relieve abrupto notables o de masas arboladas nativas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29072','espacio','Sierra de la Camorra y cueva de los Órganos','Relieve calizo jurásico aislado que emerge sobre la llanura de la depresión de Antequera, caracterizado por interesantes fenómenos de disolución kárstica exterior e interior con oquedades y salas subterráneas monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29073','espacio','Sierra de Canucha y nacimientos del arroyo de Alpujata','Espacio de transición geológica hacia la Sierra de las Nieves, caracterizado por murallones de calizas y mármoles que conviven con terrenos de peridotitas rojizas. Ofrece pendientes pronunciadas cubiertas de densos encinares y pinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29074','espacio','Llanos de Líbar, Sima de Gaucín y Hoz de Montejaque','Impresionante poljé y depresión kárstica de alta montaña bética rodeada por infranqueables y colosales murallones verticales de caliza grisácea desnudada. Aloja la Sima de Gaucín, un monumental sumidero natural donde se hunden las aguas torrenciales de la cuenca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29075','espacio','Paraje Natural de los Acantilados de Maro-Cerro Gordo y Cueva de Nerja (entorno geomorfológico)','Uno de los tramos costeros más espectaculares del mar Mediterráneo peninsular. Colosales acantilados calcáreos y de mármoles de más de 100 metros de caída vertical limpia sobre aguas turquesas cristalinas, que conviven con un imponente complejo kárstico de cuevas monumentales subterráneas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29076','espacio','Sierra de Alpujata, refugio de Juanar y cañón del río Real','Paisaje montañoso abrupto caracterizado por el drástico contacto de los mármoles blancos de Sierra Blanca con las peridotitas granates de Alpujata. Ofrece un relieve de fuertes desniveles con frondosos bosques de pino carrasco y alcornocales de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29077','espacio','Parque Nacional de la Sierra de las Nieves, pinsapar de Parauta y valle del Genal','Espectacular entorno que alberga una de las masas boscosas más puras, maduras y continuas de pinsapos   (Abies pinsapo), un abeto reliquia del Terciario que crece de forma majestuosa en laderas calcáreas de umbría absoluta y pendientes vertiginosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29079','espacio','Alta Axarquía, nacimiento del río Guaro y tajos de Marchamona','Impresionante anfiteatro natural kárstico flanqueado por colosales escarpes calizos y murallones desnudados grises. Destaca por el nacimiento del río Guaro, cuyas aguas cristalinas brotan con fuerza de la base de los bloques calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29080','espacio','Sierra de la Gibralgalia y escarpes del Guadalhorce','Relieve ondulado y quebrado compuesto por areniscas calcáreas (molasas) miocénicas que forman pequeños farallones tabulares sobre el valle del río Guadalhorce, ofreciendo panorámicas limpias de la cuenca media.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29081','espacio','Umbrías de castañar de Pujerra y cabecera del río Guadalmansa','Una de las mayores concentraciones continuas de bosque de castaño de Andalucía, asentada sobre laderas escarpadas de pizarras hercínicas de gran pluviosidad. Ofrece un espectáculo visual y cromático de primer orden estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29082','espacio','Acantilados de El Cantal y Cueva del Tesoro (entorno geológico)','Promontorios calcáreos litorales del Jurásico que interrumpen la línea de costa baja formando pequeños acantilados marinos de abrasión. Alberga cavidades kársticas de origen marino únicas en el continente europeo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29083','espacio','Tajos de Sabar y río Cueva','Conjunto de impresionantes pitones y farallones calizos que emergen de forma abrupta entre colinas arcillosas y olivares de la Axarquía norte. Ofrece un paisaje mineral fragmentado de gran interés plástico y contrastes de luz.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','espacio','Tajo de Ronda (Río Guadalevín), Hoya de Ronda y Sierra de Líbar (límite oriental)','Monumental, colosal e internacionalmente célebre desfiladero fluvial excavado por el río Guadalevín sobre una meseta tabular de areniscas calcáreas calcáreas. Sus paredes verticales desnudas superan los 100 metros de caída libre limpia en una geoforma de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29085','espacio','Parque Natural de Sierra Tejeda y río Salares','Término quebrado caracterizado por profundos barrancos y escarpes de dolomías y esquistos del complejo alpujárride. Ofrece un paisaje de media montaña aislado cubierto por un dosel regular de pino resinero y encinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29086','espacio','Valle del río Cájula y lomas esquistosas','Relieve ondulado de la Axarquía central constituido por depósitos de pizarras paleozoicas sujetas a intensa erosión laminar. Ofrece visuales diáfanas y limpias de lomas romas con matorral mediterráneo bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29087','espacio','Sierra Tejeda, pico de la Maroma (vertiente sur) y barranco de la dehesa','Paisaje bético de alta montaña con imponentes crestones calizos y canchales de piedra gris que definen las vertientes superiores de la serranía, cubiertas por un manto denso de pinares adaptados al frío y matorral saxícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29088','espacio','Llanos de Sierra de Yeguas y salinas temporales','Espacio marcadamente horizontal del extremo norte provincial constituido por arcillas y sedimentos limosos miocénicos. Ofrece horizontes diáfanos limpios de carácter estepario con sutiles escorrentías difusas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29089','espacio','Tajo del Molino (Hoz del río Venta) y Sierra de Teba','Espectacular y angosto desfiladero fluvial excavado de forma vertical sobre calizas jurásicas por el río de la Venta. Las impresionantes paredes de piedra gris forman una brecha geológica natural con oquedades aéreas y cuevas kársticas de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29090','espacio','Parque Nacional de la Sierra de las Nieves, Torrecilla y pinsapar de los Horcajuelos','El corazón orográfico del Parque Nacional, coronado por el pico Torrecilla sobre colosales murallones calcáreos grises. Alberga profundos cañones fluviales, lapiaces altos y el majestuoso e impenetrable pinsapar de los Horcajuelos de valor ecológico universal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29901','espacio','Sierra de Mijas (vertiente sur) y manantial de Inca (entorno natural)','Frente de colinas calizas y mármoles dolomíticos que caen hacia la llanura litoral baja, caracterizado por históricas surgencias de agua kárstica en la base de la sierra rodeadas de pinar mediterráneo fragmentado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','espacio','Valle bajo del río Torrox y lomas prelitorales','Relieve ondulado caracterizado por terrenos esquistosos paleozoicos expuestos a la escorrentía difusa, ofreciendo una fisonomía esteparia mediterránea de horizontes limpios que se abren hacia la línea de costa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29092','espacio','Arroyo de Totalán y lomas arcillosas','Terreno de colinas bajas arcillo-pizarrosas situado en el sector oriental malagueño, con formas suaves labradas por la escorrentía hídrica superficial difusa sin accidentes notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29093','espacio','Sierra de Abdalajís y canal de piedra caliza de la Hoz','Monumental, altivo e imponente murallón de roca caliza jurásica de color grisáceo que se eleva de forma vertical y limpia configurando un paisaje mineral descarnado de enorme fuerza visual y espectaculares lapiaces superficiales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','espacio','Delta del río Vélez y acantilados de Almayate','Espacio aluvial cuaternario horizontal donde el río Vélez vierte sus sedimentos limosos, flanqueado hacia el oeste por pequeños promontorios y escarpes calcáreos prelitorales que marcan antiguas líneas de costa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29095','espacio','Ribera del arroyo Burriana y lomas arcillosas','Relieve ondulado suave constituido por margas y arcillas de la cuenca subbética septentrional. Su atractivo radica en las formas de erosión de escorrentía superficial y en los pequeños sotos de ribera asociados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29902','espacio','Vertiente sur del Torcal de Antequera','Ubicación privilegiada a los pies de las monumentales e infranqueables paredes verticales calizas del laberinto kárstico del Torcal. Ofrece una panorámica colosal de estratos rocosos replegados y canchales de piedra gris expuesta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29098','espacio','Lomas del Entredicho y llanuras subbéticas','Paisaje de lomas y muelas erosionadas compuestas por arcillas y calizas arenosas en el límite con Córdoba y Granada. Ofrece horizontes abiertos de carácter netamente estepario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29096','espacio','Sierra de Camarolos, nacimiento del río Guadalhorce (El Chorro) y dehesas de Hondonero','Impresionante anfiteatro natural kárstico flanqueado por las verticales paredes de roca caliza jurásica de la Sierra de los Camarolos, rico en surgencias de agua perennes y grandes canchales de piedra de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29097','espacio','Fuente de los Cien Caños (Nacimiento del río Guadalhorce) y Sierra de San Jorge','Monumental e impresionante salto de agua y surgencia kárstica multifocal donde el agua brota cristalina de decenas de orificios de una pared de toba calcárea adosada a la roca vertical gris de la sierra, configurando un hito visual único.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29099','espacio','Embalse de La Viñuela y valle alto del río Guaro','Gran cubeta de agua interior perenne encajada entre colinas quebradas de pizarras de la Axarquía. Ofrece una amplia panorámica visual de quietud hídrica que contrasta   con las texturas desnudas de los relieves arcillo-esquistosos que delimitan su horizonte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29100','espacio','Parque Nacional de la Sierra de las Nieves, Alta Serranía y Pinsapar de Yunquera','Uno de los templos botánicos del sur de Europa, asentado sobre colosales relieves calizos y calizas dolomíticas jurásicas. Alberga la mayor y más densa masa forestal continua de pinsapo (Abies pinsapo), un abeto relicto de la era glaciar que tapiza laderas de pendientes vertiginosas.   ¡Objetivo cumplido con rigor absoluto! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90402','espacio','Paisaje Protegido del Canyón del Río Chícamo y badlands de Abanilla','Espectacular oasis subdesértico donde el río Chícamo esculpe una angosta garganta sobre margas y calizas paleógenas. Ofrece un paisaje visualmente impactante de aguas cantarinas que fluyen entre densos palmerales nativos y paredes verticales de tierras arcillosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30002','espacio','Hoya de Don García y meandros del río Segura','Tramo donde el río Segura describe sinuosos giros confinado entre los relieves de la Sierra del Oro y terrazas aluviales cuaternarias. Destaca por la contemplación del dosel verde de su frondoso bosque de ribera que contrasta con la aridez de las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','espacio','Paisaje Protegido de Cuatro Calas, Cabo Cope y escarpes marinos','Tramo costero virgen caracterizado por formaciones de dunas fósiles de color amarillento e intensas geoformas debidas a la erosión del oleaje. El monumental promontorio calcáreo de Cabo Cope se eleva de forma vertical sobre el mar ofreciendo una perspectiva mineral sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30004','espacio','Badlands del río Mula y cárcavas de arcilla','Paisaje marcadamente árido labrado sobre potentes depósitos de margas yesíferas del Mioceno superior expuestas a una intensa erosión hídrica. Ofrece una fisonomía desértica muy plástica con crestas afiladas y barrancos que cambian de color con la luz del atardecer.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30005','espacio','Vega Media del Segre y llanura de inundación aluvial','Espacio estrictamente horizontal compuesto por limos y arenas cuaternarias depositadas por la dinámica fluvial baja del río Segura. Su valor contemplativo se reduce a la inmensidad diáfana de la cuenca baja de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30902','espacio','Riberas del Mar Menor y humedal de la Hita','Frente litoral interior caracterizado por la inmensidad de la lámina de agua de la laguna salada sobre arenas cuaternarias. Aloja el humedal de la Hita, un cinturón perilagunar diáfano dominado por extensas formaciones de salicornias y carrizales halófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30006','espacio','Estrecho de la Arboleja (Rambla de Lébor) y faldas de Sierra Espuña','Impresionante desfiladero y pasillo mineral de apenas un metro de ancho esculpido por el agua sobre potentes estratos de areniscas calcáreas. Las paredes verticales umbrías gotean agua de origen freático, albergando musgos y helechos relictos de gran belleza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30007','espacio','Confluencia del río Mula con el río Segura','Nudo hidrológico aluvial de la depresión central murciana donde ambos cauces unifican sus flujos sobre terrazas de gravas y limos fluviales. Ofrece una visual limpia dominada por la horizontalidad de la cuenca y sutiles alamedas ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30008','espacio','Parque Natural de Sierra Espuña, Paisaje Protegido de los Barrancos de Gebas y badlands','Uno de los contrastes geomorfológicos más colosales del sureste español. Combina los imponentes murallones calcáreos y los frondosos pinares de Sierra Espuña con el espectacular desierto blanco de los Barrancos de Gebas, un laberinto de cárcavas arcillosas de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30009','espacio','Ojos de Archena, fallas térmicas y río Segura','Espacio donde el río Segura corta las estructuras calizas prelitorales, permitiendo el afloramiento directo de manantiales de aguas termales ligados a fracturas tectónicas profundas. Ofrece una estampa contemplativa de riberas encajonadas flanqueadas por cañaverales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30010','espacio','Vega Baja del Segura y sotos fronterizos','Término estrictamente plano asentado en la cuenca baja del Segura en el límite con Alicante. Presenta un   relieve estrictamente horizontal de interés limitado a la fisonomía lineal del río flanqueado por sauces ripícolas dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','espacio','Valle de Ricote, peñón de Blanca y embalse de Ojos','Espectacular garganta fluvial donde el río Segura discurre encajonado de forma sinuosa entre imponentes farallones de roca caliza jurásica y dolomías de la Sierra del Oro. La panorámica de la lámina de agua confinada por la montaña salvaje posee una gran fuerza estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30012','espacio','Salto del Usero (Río Mula) y cañón del Pasico Ucenda','Hermoso salto de agua natural donde el río Mula se desploma en una profunda poza de aguas de color turquesa hipertransparentes esculpida en una bóveda caliza arenosa del Mioceno. El entorno presenta formaciones de tobas calcáreas goteantes de enorme plasticidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30013','espacio','Reserva Natural del Cañón de Almadenes (Río Segre), Paraje de la Santa e islas fluviales','Monumental desfiladero de más de cuatro kilómetros de longitud con paredes verticales de roca caliza jurásica de más de 100 metros de caída limpia sobre el río Segura. Alberga el bosque de ribera (alamedas, sauces y fresnos) mejor conservado de la Región de Murcia en un entorno kárstico sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30014','espacio','Badlands de Campos del Río y escarpes del río Mula','Paisaje desértico extremo caracterizado por un laberinto de cárcavas, chimeneas de hadas y afiladas agujas de arcillas de tonalidades blanquecinas y ocres. Ofrece una panorámica limpia de intensa erosión remontante de un gran interés plástico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','espacio','Paraje Natural de las Fuentes del Marqués y Sierra de Mojantes','Extraordinaria y monumental surgencia kárstica multifocal (sartenes) donde el agua brota cristalina y con gran caudal de las entrañas calcáreas jurásicas. El entorno está rodeado de un frondoso bosque mixto y olivares tradicionales de montaña de gran armonía visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','espacio','Parque Natural de Calblanque, Monte de las Cenizas y Peña del Águila, e Islas del litoral (Hormigas)','Uno de los frentes costeros vírgenes más colosales del Mediterráneo peninsular, caracterizado por una geología extrema de pizarras esquistosas, dunas fósiles y arenas oscuras. Sus acantilados abruptos y calas de aguas puras forman un paisaje mineral y una costa salvaje única.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30017','espacio','Sierra de Quípar, cabecera del río Quípar y cabezos calizos','Entorno subbético quebrado caracterizado por el encajonamiento fluvial del río entre muelas calizas jurásicas grises. Ofrece un paisaje mineral agreste bien conservado, cubierto de densas masas estables de pino carrasco y encinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30018','espacio','Terrazas del río Guadentín inferior y llanuras','Relieve estrictamente horizontal constituido por arenas y arcillas aluviales cuaternarias de la depresión central murciana. Ofrece un horizonte lineal diáfano sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30019','espacio','Cañón de Almadenes (vertiente este), La Hoya de la Sima y el Almorchón','Sector copartícipe del colosal desfiladero calizo del río Segura, flanqueado por la imponente mole del Almorchón, un pitón calcáreo exento de perfil alpino que emerge de forma dramática sobre las parameras semiáridas y los extensos sotos fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30020','espacio','Paisaje Protegido del Humedal del Ajauque y Rambla Salada, y fallas del Baño','Extraordinaria cuenca endorreica semiárida con afloramientos yesíferos del Mioceno, donde las aguas hipersalinas crean costras minerales blanquecinas de gran interés visual. Destaca por el contraste plástico de sus badlands desérticos y las surgencias termales ligadas a fracturas profundas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30021','espacio','Rambla de Fuente Álamo y vertientes de la Sierra de Carrascoy','Amplia llanura sedimentaria de piedemonte constituida por depósitos aluviales y arenas finas del Plioceno. Ofrece horizontes diáfanos limpios interrumpidos hacia el norte por las laderas abruptas y matorrales mediterráneos esclerófilos de la sierra calcárea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','espacio','Sierra del Carche, Sierra de Santa Ana y Salero de Jumilla','Imponente alineación montañosa subbética caracterizada por colosales escarpes de roca caliza jurásica grises, lapiaces y profundos barrancos kársticos. En sus llanuras bajas destaca un monumental diapiro de yesos y sales triásicas de extraordinario valor cromático y geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30023','espacio','Estrecho de Librilla (Rambla de Algeciras) y cárcavas de arcilla','Impresionante corte geológico y cañón excavado por las avenidas de agua en una matriz de areniscas y arcillas del terciario medio. Sus imponentes   paredes rocosas verticales flanquean un pasillo mineral angosto de gran potencia visual y texturas rugosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30024','espacio','Cabecera del río Luchena, estrecho de la Quinta, Sierra de la Almenara y Rambla de Ramonete (litoral)','Extenso término de colosales contrastes geológicos que abarca desde los cañones fluviales kársticos del interior entre pinares puros, hasta su frente playero protegido. Sus acantilados costeros de esquistos y calas minerales puras ofrecen paisajes de costa salvaje inigualables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30026','espacio','Paisaje Protegido de la Sierra de las Moreras, erosiones de Bolnuevo y minas de Mazarrón (entorno geomorfológico)','Prodigio del modelado eólico y marino consistente en las Gredas de Bolnuevo, colosales estructuras de areniscas amarillentas esculpidas en formas caprichosas de setas. El entorno de la sierra y sus calas rocosas puras componen una de las estampas costeras minerales más impactantes del Mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30027','espacio','Badlands de la Alcayna y escarpes del río Segura','Paisaje marcadamente árido de colinas bajas compuesto por potentes depósitos de arcillas y margas miocénicas expuestas a erosión remontante hídrica. Ofrece una fisonomía desértica de cárcavas y afiladas agujas ocres de gran valor plástico visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30028','espacio','Reserva Natural del Macizo de Revolcadores, Estrecho de Bolvonegro y cañón del río Alhárabe','El techo de la Región de Murcia, caracterizado por un colosal e imponente relieve subbético calizo que supera los 2.000 metros de altitud. Destaca por el estrecho de Bolvonegro, un desfiladero fluvial donde el agua corta estratos   rocosos fosilíferos verticales en una umbría botánica pura y salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30029','espacio','Sierra de la Muela, escarpes del río Mula y cañón de la Puebla','Monumental muela caliza de paredes totalmente verticales de color gris que emerge exenta y de forma dramática sobre los campos semiáridos de la cuenca. Sus cortados rocosos y la presencia de cuevas naturales de disolución kárstica constituyen hitos visuales de primer orden.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','espacio','Parque Regional de El Valle y Carrascoy, y Cresta del Gallo','Impresionante murallón calcáreo y dolomítico que flanquea la gran vega aluvial, caracterizado por las caprichosas formas de la erosión en las crestas dentadas de la piedra gris (Cresta del Gallo). Sus laderas presentan fuertes pendientes vestidas por un denso pinar mediterráneo continuo de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30031','espacio','Valle de Ricote, Estrecho del Solvente y riberas del Segura','El sector más angosto y espectacular del Valle de Ricote. El río Segura fluye confinado, excavando un desfiladero absoluto de paredes verticales de calizas jurásicas que aprisionan el agua transparente, rodeado de un oasis botánico que besa las rocas de las vertientes de forma majestuosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30032','espacio','Sierra de Pliego y barranco de la Mota','Relieve quebrado subbético caracterizado por laderas de pendientes pronunciadas compuestas por calizas y margas replegadas. Ofrece amplios horizontes visuales limpios sobre pasillos de roca gris descarnada e incipientes campos de lapiaces superficiales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30033','espacio','Rambla de Nogalte y lomas del Cabezo de la Jara','Paisaje penillanurero semiárido configurado por el amplio lecho pedregoso de la rambla sobre arenas y sedimentos cuaternarios finos. Destaca por la austera contemplación de sus texturas minerales ocres y la vegetación xerófila arbustiva nativa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30034','espacio','Sierra de Ricote, laderas del Almeces y umbría de la Virgen','Macizo montañoso calizo y dolomítico de relieve muy abrupto que se eleva de forma monumental sobre el valle fluvial del Segura. Presenta escarpes verticales de roca desnuda, canchales de piedra crioclástica y densos pinares de pino carrasco adaptados a las pendientes vertiginosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30035','espacio','Riberas del Mar Menor e Islas de San Javier (Isla Mayor e Isla Perdiguera)','Espacio litoral interior caracterizado por la inmensidad de la lámina de agua de la laguna salada, donde emergen de forma monumental conos volcánicos relictos de andesitas oscuras. Ofrece horizontes marítimos limpios de gran interés geológico y nitidez estática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30036','espacio','Parque Regional de las Salinas y Arenales de San Pedro','Excepcional complejo costero que alberga un sistema de dunas móviles bien conservadas y lagunas salineras de origen marino y aluvial cuaternario. Ofrece una fisonomía acuática y costera limpia de extensas llanuras salinas, encañizadas tradicionales y comunidades vegetales halófilas sublíneas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30901','espacio','Embalse de Santomera y lomas arcilloso-calcáreas de la Sierra de la Cresta','Cuenca de agua remansada sobre un relieve suavemente ondulado de arcillas y yesos miocénicos en el sector nororiental murciano. Ofrece un paisaje tranquilo de aguas mansas que contrastan con los cabezos áridos y matorrales mediterráneos marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30037','espacio','Cabezo Gordo','El único promontorio de mármoles triásicos y calizas cristalinas que emerge de forma totalmente aislada (cerro testigo) como una isla mineral en mitad de la inmensa llanura aluvial del Campo de Cartagena, ofreciendo una fisonomía geológica exenta de gran valor contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30038','espacio','Terrazas fluviales del río Segura y rambla de Saladar','Espacio plano de llanura aluvial cuaternaria compuesto por depósitos arcillo-limosos estables de la depresión central. Destaca por la fisonomía horizontal de sus suelos de sedimentación y sutiles procesos de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30039','espacio','Parque Natural de Sierra Espuña (vertiente sur), barranco de la Hoz y Los Pilones','Espectacular y profundo cañón calizo y de areniscas labrado por las avenidas de agua de forma longitudinal en la falda de la sierra. Sus imponentes paredes de piedra vertical gris albergan espectaculares formaciones tectónicas replegadas en un entorno forestal continuo de pino carrasco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30040','espacio','Valle de Ricote oriental, el Salto de la Novia y riberas del Segura','Impresionante estrechamiento fluvial donde el río Segre quiebra en vertical un murallón de calizas jurásicas. Ofrece una panorámica de laderas rocosas escarpadas que   caen a plomo sobre un soto de galería bien conservado de gran valor estético y armonía visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30042','espacio','Valle de Ricote, escarpes de la Asomada y meandros del Segura','Cornisa de arcillas de sedimentación y calizas que cae mediante taludes pronunciados hacia la llanura aluvial del río Segura. Ofrece amplias panorámicas limpias de horizontes despejados sobre las curvas fluviales de la verde vega del valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30043','espacio','Espacio Natural de la Sierra de Castellar, Monte Arabí y barranco de la Fuente','Extraordinario bloque calizo jurásico exento que emerge en el altiplano murciano, caracterizado por el espectacular modelado alveolar en nido de abeja (taffoni) esculpido por la erosión eólica en sus paredes rocosas de tonos dorados. Un paisaje mineral abstracto de enorme fuerza visual.   Navarra).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90705','espacio','Cueva de Zatoia / Robledal de Garralda','Entorno subalpino asentado sobre una meseta kárstica a gran altitud, caracterizado por profundas grietas e importantes yacimientos prehistóricos en sus oquedades naturales. El relieve abrupto se combina con formaciones   vegetales boreoalpinas singulares perfectamente adaptadas al clima riguroso del Pirineo navarro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90708','espacio','Laguna de Lor / Lagunas de Ablitas','Humedal de origen endorréico situado en la llanura de la Ribera Baja, que destaca por sus láminas de agua estables rodeadas de densos carrizales. Es un enclave visual de gran contraste geográfico, rompiendo la aridez esteparia meridional mediante un ecosistema lacustre de alta relevancia ecológica. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90710','espacio','Sierra de Codés / Peña Lapoblación','Gran muralla de roca caliza crestada que emerge de forma vertical en el extremo occidental navarro. Sus perfiles afilados y escarpes calcáreos albergan vegetación eurosiberiana relicta en sus umbrías, ofreciendo una imponente barrera orográfica visible desde toda la comarca. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90711','espacio','Bizkaia de Aibar / Barranco de Valdecomuna','Relieve prepirenaico modelado en margas y areniscas con marcadas crestas y barrancos sinuosos. Alberga formaciones boscosas autóctonas de quejigos y encinas mediterráneas bien conservadas, con una interesante morfología de erosión fluvial en sus cauces estacionales. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90712','espacio','Desfiladero del río Ega / Sierra de Lóquiz','Valle angosto flanqueado por las imponentes paredes rocosas de la sierra calcárea de Lóquiz. El cauce del río Ega modela una foz interior con densos bosques de ribera y encinares que se aferran a los bloques de piedra coluviales. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90714','espacio','Reserva Natural del Nacedero del Urederra','Espectacular anfiteatro kárstico donde el agua subterránea de la sierra de Urbasa surge verticalmente en una pared rocosa. El curso alto del río genera cascadas sucesivas y pozas de aguas de un intenso azul turquesa, rodeadas por un frondoso hayedo clasificado como uno de los entornos fluviales más puros de España. [1, 2, 3, 4].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90715','espacio','Nacedero de Aguas Belzas / Río Ega','Surgencia hídrica de llanura alimentada por los acuíferos subterráneos de la sierra de Lóquiz. El agua brota de forma tranquila creando un pozo profundo y constante rodeado de vegetación hidrófila y viejos sauces. [1, 2, 3].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90718','espacio','Regata de Mediano / Valle de Odieta','Paisaje fluvial encajonado de carácter atlántico, donde el relieve suave pirenaico permite el desarrollo de praderas húmedas y bosques densos de frondosas. La pureza de sus aguas calcáreas y los perfiles de la cuenca alta del Arga definen su alto interés paisajístico. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31020','espacio','Malloak / Sierra de Aralar','Impresionante alineación de moles calizas piramidales que caen de forma casi vertical e interrumpida con desniveles de más de 700 metros sobre el fondo del valle. Este relieve abrupto y alpino presenta canales de   desprendimiento y praderías colgadas de gran potencia escénica. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31023','espacio','Balsa de Ezkoriz / Cortados de Badostáin','Humedal interior de origen endorréico recuperado sobre arcillas ecorregionales, flanqueado por pequeños escarpes erosionados. Es un reducto de agua y vegetación de enea que contrasta cromáticamente con las lomas cerealistas colindantes de la cuenca. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31024','espacio','Cabecera del río Urumea / Peñas de Arano','Entorno encajonado de valles de fuerte pendiente sobre materiales silíceos, dominado por riachuelos torrenciales estacionales. La alta pluviosidad de la zona permite la existencia de robledales atlánticos puros y espectaculares formaciones de helechos gigantes en sus vaguadas oscuras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90720','espacio','Cascada de Iera / Macizo de Cinco Villas','Salto de agua encajado en una garganta granítica profunda, rodeado por uno de los bosques mixtos atlánticos mejor conservados del norte peninsular. El relieve destaca por sus acusadas pendientes y la presencia de ejemplares monumentales de castaños y robles pedunculados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31026','espacio','Barranco de San Juan / Yeseras de Aras','Paisaje semiárido modelado sobre margas yesíferas, donde la erosión hídrica ha creado cárcavas y pequeños barrancos de tonos blanquecinos. Cuenta con vegetación gipsícola altamente especializada y adaptada a la falta de humedad del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31027','espacio','Bosque de Larrañeta / Río Leziza','Llanura aluvial pirenaica dominada por un majestuoso e histórico robledal de fondo de valle. El curso de agua del río Leziza cruza la zona de forma serpenteante, dejando depósitos de gravas y terrazas fluviales de gran valor geomorfológico. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31030','espacio','Umbría de Montejurra / Barranco de San Adrián','Ladera escarpada caliza tapizada por un denso encinar carrascal de gran valor botánico debido a su densidad y madurez. El relieve presenta canchales de piedra y crestas rocosas que definen el perfil meridional de esta emblemática montaña navarra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31031','espacio','Alto de Gorriti / Cabecera del río Leizarán','Relieve de montaña atlántica con divisorias de aguas muy marcadas y lomas cubiertas de helechales verdes y pastizales húmedos. Los pequeños arroyos que bajan hacia el río Leizarán tallan laderas empinadas bajo la sombra de hayedos trasmochos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31032','espacio','Parque Natural de las Bardenas Reales (Bardena Blanca)','Paisaje pseudo-desértico de belleza sobrecogedora, modelado por la erosión extrema sobre arcillas, yesos y areniscas. Destacan los imponentes cabezos aislados como Castildetierra y las profundas redes de barrancos laberínticos, que configuran un relieve único en Europa de aspecto lunar. [1, 2, 3].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31033','espacio','Monte Aribe / Cabecera del Irati','Entorno prepirenaico cubierto por densas masas de bosque mixto de haya y abeto blanco integradas en la influencia de la Selva de Irati. El relieve es abrupto, quebrado por riachuelos de montaña de aguas sumamente frías y lechos rocosos cubiertos de briófitos. [1, 2, 3].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90722','espacio','Garganta del río Irati / Baños de Aribe','Desfiladero estrecho donde el río Irati corta transversalmente las estructuras calizas pirenaicas. La fuerza erosiva del agua ha creado marmitas de gigante y angosturas de roca desnuda flanqueadas por una vegetación de ribera atlántica de excepcional frondosidad. [1, 2, 3].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31035','espacio','Barranco del Toll / Lomas de Codés','Pequeña cuenca de erosión de carácter estepario y arcilloso, donde las escasas corrientes fluviales temporales esculpen regueros y cárcavas. Presenta   comunidades de matorral mediterráneo xerófilo de gran interés por su resistencia a la sequía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31036','espacio','Sierra de Mendía / Barranco de la Santa Cruz','Alineación caliza de baja altitud que destaca sobre la llanura agrícola de la Navarra Media. Sus laderas están cubiertas por un denso matorral de coscoja y encinas dispersas, mostrando curiosas formas de erosión alveolar en los afloramientos rocosos de la cumbre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31037','espacio','Sotos del río Arakil / Llanura de Sakana','Tramo fluvial maduro donde el río Arakil ensancha su cauce y genera meandros bien definidos rodeados de sotos de sauces y alisos. El fondo de valle ofrece una perspectiva visual limpia de las grandes moles calizas de las sierras vecinas. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31038','espacio','Monte de la Chola / Barranco de las Canteras','Formación de cerros testigo arcillosos con costras calcáreas superiores que protegen el relieve de la erosión. Las laderas muestran el desarrollo de encinares aclarados mediterráneos adaptados a suelos pobres y un modelado de lomas suaves típico de la Navarra Central.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31039','espacio','Meandro del río Arga / Encinar de Sarria','Gran curva fluvial excavada por el río Arga en su entrada a la Navarra Media, encajonada entre laderas rocosas. La margen cóncava presenta escarpes calizos verticales cubiertos por un encinar mediterráneo termoatlántico de gran valor biogeográfico. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31042','espacio','Peña de Azagra / Sotos del río Ebro','Imponente muela de yesos y arcillas compactas que se levanta de manera vertical directamente sobre el margen izquierdo del río Ebro. Ofrece una espectacular sección geológica de estratos sedimentarios expuestos y domina un soto de ribera con importantes saucedas y alamedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31043','espacio','Santuario de Codés (Entorno) / Peña de los Cencerros','Paisaje alpino de alta montaña caliza en el sector occidental de la sierra de Codés. El relieve se caracteriza por impresionantes agujas de roca caliza y profundas canales erosionadas por el hielo, rodeadas de hayedos que colonizan las pedrizas calcáreas fijas.   Si estás listo para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90723','espacio','Bosque de Bakaiku / Sierra de Urbasa (Vertiente Norte)','Impresionante ladera de fuerte pendiente cubierta por un hayedo subatlántico continuo y denso. El relieve está configurado por el colapso de bloques calizos de la cornisa de Urbasa, creando un caos de rocas cubiertas de musgo de gran belleza umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31045','espacio','Monte de la Valdorba / Regata de Leoz','Paisaje de lomas suaves y colinas modeladas sobre margas, característico de la Navarra Media. Destaca por la alternancia de encinares mediterráneos bien conservados y pequeños barrancos con vegetación de transición de quejigos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31048','espacio','Embalse de El Ferial / Estepa de la Ribera','Lámina de agua artificial integrada en un entorno semiárido arcilloso de la cuenca de Cascante. Sirve como refugio biológico rodeado de vegetación halófila y carrizales, rompiendo la uniformidad del paisaje de llanuras y cerros erosionados meridionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90724','espacio','Bosque de Orgi / Valle de Basaburúa','Excepcional robledal húmedo de llanura, testigo relicto de los antiguos bosques que cubrían los valles encharcadizos del norte navarro. El relieve de fondo de saco favorece la acumulación de agua, sustentando robles pedunculados centenarios y una rica flora hidrófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31050','espacio','Cascada de Xorroxin / Turberas de Belate','Espectacular salto de agua encajonado donde nace el río Bidasoa, rodeado de un frondoso bosque de alisos, avellanos y castaños. El valle presenta un relieve de modelado kárstico y criptokárstico con laderas de fuerte   pendiente, praderas siempre verdes y singulares ecosistemas de turbera en altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31137','espacio','Embalses de Leurtza','Dos lagos de montaña encajonados en un circo kárstico rodeado de hayedos maduros en un ambiente de alta pluviosidad. El agua cristalina refleja el verde intenso de la vegetación subatlántica y los relieves calizos suavizados por la erosión química.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31053','espacio','Sotos del río Arga / Meandro de las Norias','Amplio meandro fluvial excavado en la llanura aluvial de la Navarra Media, donde el río Arga deposita gravas y limos. Alberga una franja bien conservada de soto mediterráneo con álamos, sauces y densas comunidades de helófitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31054','espacio','Parque Natural del Señorío de Bértiz','Impresionante masa forestal atlántica continua que tapiza un relieve abrupto de valles encajonados y fuertes pendientes a orillas del Bidasoa. Su microclima templado y húmedo permite el desarrollo de hayedos y robledales maduros con una extraordinaria biodiversidad de helechos y briófitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31055','espacio','Nacedero del río Araxes / Monte Balerdi','Surgencia kárstica a los pies de las imponentes moles calizas de las Malloas de Aralar. El río Araxes brota con fuerza entre bloques de piedra calcárea, flanqueado por un desfiladero umbrío cubierto de castaños, avellanos y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31061','espacio','Barranco de la Pradera / Lomas de Melgar','Relieve de lomas suaves y llanuras arcillosas arcillocostrosas con escasa cobertura vegetal arbórea. Destaca el modelado de pequeños barrancos estacionales donde se desarrollan matorrales gipsícolas y mediterráneos adaptados a la aridez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31062','espacio','Sotos del río Ebro / Bardena Negra (Límite)','Tramo aluvial donde el río Ebro ensancha su cauce originando islas fluviales y densos sotos de ribera. Hacia el norte, el relieve asciende suavemente hacia los escarpes arcillosos y los cabezos característicos del entorno bardenero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31064','espacio','Soto de la Resma / Río Ebro','Espacio fluvial mediterráneo dominado por la dinámica del río Ebro, con depósitos sedimentarios recientes y terrazas aluviales. La vegetación de ribera muestra una notable zonificación con alamedas, tamarizales y saucedas adaptadas a las crecidas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31065','espacio','Cortados del río Aragón / Soto Artica','Impresionantes paredes verticales de arcillas y yesos estratificados que el río Aragón ha erosionado a lo largo del tiempo. Los escarpes contrastan cromáticamente con el verde intenso del soto de ribera que se extiende a sus pies.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31066','espacio','Los Cortados de Cárcar / Río Ega','Majestuoso frente escarpado de yesos y margas que se desploma de forma vertical sobre el cauce terminal del río Ega. El relieve muestra las secciones geológicas sedimentarias y la intensa acción erosiva fluvial en un entorno semiárido.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31067','espacio','Laguna de Pitillas (Entorno) / El Paso (Bardenas)','Zona de transición entre los humedales esteparios y los llanos arcillosos de la Bardena Blanca. Destaca por el relieve plano roto por cabezos y el barranco de la Estruendosa, con comunidades vegetales esteparias de gran singularidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31068','espacio','Laguna de Lor (Franja Sur) / Balsa de Pulguer (Entorno)','Cubeta lagunar natural recrecida asentada sobre los materiales yesíferos y arcillosos de la cuenca del Queiles. El contraste visual del agua azul con las tierras rojizas y la vegetación de carrizal define este enclave de la Ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31070','espacio','Meandro de la Nava / Confluencia Ebro-Aragón','Gran espacio de confluencia fluvial donde el río Aragón vierte sus aguas en el Ebro, generando un complejo sistema de islas, brazos muertos y meandros. Posee un soto maduro de chopos negros, sauces y álamos blancos de gran valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31071','espacio','Sierra de Leyre (Extremo Este) / Barranco de las Almadías','Relieve de fuertes pendientes prepirenaicas modelado en calizas y margas finas. El barranco presenta un curso de agua torrencial encajonado entre laderas cubiertas de quejigales y pinares de pino silvestre en régimen de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31072','espacio','Riberas del río Alhama / Sotos de la Vega','Corredor verde fluvial que rompe la aridez de la llanura esteparia de la Ribera Alta. El río Alhama discurre entre terrazas cuaternarias de gravas, sustentando un modesto pero denso cinturón de sauces, cañaverales y tamarices.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31077','espacio','Estancas de Corella / La Torrecilla','Conjunto de balsas y humedales de origen endorréico situados en una llanura aluvial cuaternaria. El relieve es llano, destacando la presencia de avifauna acuática sobre las láminas de agua protegidas por cinturones de eneas y carrizos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31078','espacio','Soto de la Mejana / Río Ebro (Límite Regional)','Último tramo del río Ebro en territorio navarro, caracterizado por una llanura de inundación muy amplia y   fértil. El soto conserva retazos de la vegetación riparia original con grandes ejemplares de álamo blanco y sauces mimbreros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31079','espacio','Barranco de Valdeasens / Lomas de Codés','Pequeña cuenca de recepción torrencial con cárcavas labradas sobre margas yesíferas, situada en las estribaciones meridionales de la sierra de Codés. Presenta una vegetación arbustiva mediterránea rala y discontinua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31080','espacio','Vertiente Sur de Montejurra / Barranco de San Pedro','Paisaje quebrado calizo donde los escarpes de Montejurra entran en contacto con los terrenos arcillosos de la solana. Destacan los densos encinares carrascales que colonizan las laderas pedregosas y los pequeños afloramientos rocosos singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31081','espacio','Valle de Malerreka / Bosque de Artze','Entorno de montaña atlántica con una densa red de regatas y arroyos que descienden hacia el río Ezcurra. El relieve es abrupto, cubierto casi en su totalidad por un hayedo-robledal continuo de gran frondosidad y tapices verdes de briófitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31087','espacio','Manantial de Aguas Salinas / Río Ezcurra','Surgencia de aguas minero-medicinales con una altísima concentración de sal debido al lavado de los materiales triásicos subterráneos (keuper). El río Ezcurra discurre paralelo, encajonado en un relieve atlántico de laderas empinadas y verdes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31090','espacio','Cascada de Iiana / Cabecera del Ezcurra','Pequeño salto de agua de montaña situado en una regata encajonada entre perfiles abruptos silíceos. El entorno destaca por la alta densidad de helechales y hayedos trasmochos envueltos en brumas frecuentes debido a la influencia oceánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31091','espacio','Valle de Ergoiena / Faldas de San Donato (Beriáin)','Valle colgado prepirenaico flanqueado por las imponentes e impresionantes paredes verticales de la sierra de Urbasa y el imponente escarpe calizo del monte Beriáin. Destacan los densos hayedos calcícolas y los gigantescos caos de rocas desprendidas de las cornisas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31092','espacio','Sorogain / Bosque de Mezquíriz','Valle de origen glaciar y fluvial caracterizado por un amplio fondo de praderas alpinas rodeado por hayedos atlánticos puros de enorme extensión. El río Erro modela el relieve con pequeños saltos y pozas cristalinas sobre pizarras y areniscas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31094','espacio','Sierra de Gallipienzo / Barranco de la Sarda','Formación de crestas de areniscas y margas con una densa cobertura de encinar mediterráneo y quejigal. El relieve muestra procesos de erosión diferencial que crean pequeños escarpes y lomas de gran valor paisajístico en la comarca de Sangüesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31096','espacio','Sierra de Codés (Vertiente Sur) / Peña de la Población','Relieve calizo escarpado que forma parte del imponente frente meridional de la sierra de Codés. Destacan las laderas cubiertas de canchales de piedra y la presencia de encinares mediterráneos adaptados a la fuerte insolación de la vertiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45065','espacio','Parque de Los Llanos / Desfiladero del río Ega','El río Ega cruza la localidad abriendo un espectacular pasadizo natural entre paredes calizas y formaciones kársticas de yesos del Keuper. Destacan las pozas de agua salobre conocidas como "Agua Salada", surgencias termales de alta pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31098','espacio','Valle de Esteríbar / Hayedo de Eugi','Extenso valle pirenaico modelado por el curso alto del río Arga sobre materiales paleozoicos. El relieve quebrado está dominado por el imponente hayedo de Eugi, un bosque continuo que se extiende por laderas umbrías aportando una gran calidad paisajística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31099','espacio','Sierra de Lóquiz (Estribaciones) / Barranco de San Andrés','Lomas arcillosas y calcáreas de transición en la base de la sierra de Lóquiz. Presenta un relieve suave cubierto de matorrales xerófilos mediterráneos y bosquetes dispersos de encina carrasca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31100','espacio','Cueva de Basaura / Raso de Urbasa (Límite)','Gran surgencia kárstica temporal que drena las aguas de la plataforma de Urbasa a través de una impresionante boca de cueva. El relieve está repleto de dolinas, lapiaces y simas profundas ocultas bajo el espeso hayedo calcícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31108','espacio','Bardena Negra / Cabezo de Aguilar','Relieve de mesetas tabulares y cerros coronados por calizas que protegen los estratos inferiores de arcillas de la erosión. A diferencia de la Bardena Blanca, este paisaje presenta una cobertura vegetal notable de pino carrasco y coscojales de gran valor ambiental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31109','espacio','Sierra de Erreniega (El Perdón) / Balsa de Galar','Vertiente septentrional de la sierra del Perdón, caracterizada por laderas arcillo-areniscosas cubiertas de encinares aclarados. La pequeña balsa de Galar destaca como un modesto punto de agua que rompe la aridez de las lomas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31114','espacio','Valle de la Valdorba / Regata de Cidacos','Paisaje de transición mediterránea-atlántica compuesto por colinas suaves margosas. Los fondos de barranco albergan masas mixtas de quejigos y encinas con un sotobosque denso de enebros y matorral calcícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31115','espacio','Robledal de Garralda / Valle de Aézcoa','Magnífica masa forestal de roble albar asentada sobre un relieve quebrado de naturaleza caliza en el Pirineo navarro. El entorno presenta pequeñas dolinas y lapiaces cubiertos por el tapiz verde del bosque y surcados por regatas limpias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31116','espacio','Crestas de Codés / Barranco de San Lorenzo','Enclave noroccidental situado en la vertiente umbría de la sierra de Codés. El relieve presenta un fuerte desnivel con farallones calizos verticales que dan paso a hayedos y quejigales bien conservados debido a la alta humedad ambiental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31117','espacio','Cuenca del río Urumea / Macizo de Artikutza (Límite)','Uno de los relieves más abruptos y lluviosos de la Península, modelado sobre materiales silíceos (pizarras y granitos). El paisaje destaca por sus interminables bosques atlánticos de hayas y robles, sus profundos valles encajonados y ríos de aguas puras y torrenciales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31118','espacio','Manantial de Arteta (Cabecera) / Sierra de Andía','Altiplanicie kárstica de alta montaña caracterizada por lapiaces, dolinas y depresiones donde se infiltra el agua de lluvia hacia el acuífero de Arteta. El relieve presenta escarpes verticales imponentes orientados hacia el valle de Ollo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31121','espacio','Sierra de Guirguillano / Alto de Echauri (Vertiente Sur)','Macizo calizo-margoso con un relieve quebrado y expuesto a la insolación mediterránea. La vegetación está dominada por carrascales arbustivos y coscojas adaptadas a suelos pedregosos y pendientes pronunciadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31124','espacio','Sierra de Izco / Peña de Izaga (Vertiente Sur)','Ladera escarpada que desciende desde la mole caliza de la peña Izaga, caracterizada por canchales de piedra y perfiles afilados. Alberga masas densas de pino silvestre y encinares de montaña bien estructurados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31134','espacio','Puerto de Remendía / Bosque de Jaurrieta','Altiplanicie prepirenaica caracterizada por un relieve suave pero elevado, donde se desarrollan extensos hayedos e importantes masas de pino silvestre. Las regatas que cruzan el término vierten sus frías aguas hacia el río Salazar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31135','espacio','Riberas del río Aragón / Sierra de Peña','El río Aragón modela un paisaje fluvial de llanura aluvial con islas de grava y sotos bien formados. Hacia el sur, el relieve se rompe abruptamente con las crestas calizas e inclinadas de la sierra de Peña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31140','espacio','Cabecera del río Anue / Bosque de Lanz','Paisaje pirenaico atlántico con un relieve de valles suaves cubiertos de praderas e imponentes masas de hayedos. Las fuentes del río Anue brotan en este entorno de alta pluviosidad, configurando regatas cristalinas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31141','espacio','Peña Lapoblación (El León Dormido)','Impresionante mole caliza de perfil aserrado y silueta antropomorfa que emerge verticalmente de forma aislada sobre el paisaje. Sus paredes rocosas presentan escarpes verticales de gran interés geológico y albergan vegetación rupícola relicta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31142','espacio','Cortados del río Arga / El Castillo (Relieve)','Frente de erosión fluvial donde el río Arga ha excavado las terrazas arcillosas cuaternarias, creando   pequeños acantilados terrosos. Ofrece una amplia panorámica visual de la vega fluvial y los sotos mediterráneos asociados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31143','espacio','Puerto de Larraona / Hayedo de Urbasa','Escalón tectónico escarpado que da acceso directo a la plataforma superior de la sierra de Urbasa. El relieve se caracteriza por impresionantes farallones de roca caliza y un hayedo denso de suelo kárstico repleto de musgos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31152','espacio','Los Cortados de Lerín / Río Ega','Espectacular y kilométrico frente de yesos blanquecinos y arcillas que el río Ega ha cortado a pico en la Navarra Media. Este relieve escarpado semiárido muestra una erosión en cárcavas muy desarrollada y comunidades vegetales gipsícolas especializadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31154','espacio','Raso de Lezaun / Sierra de Andía','Altiplanicie kárstica elevada donde el relieve es predominantemente llano pero salpicado de dolinas, depresiones de colapso y lapiaces. Carece de cursos de agua superficiales debido a la intensa filtración, presentando pastizales alpinos xerófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31155','espacio','Foz de Lumbier','Impresionante e imponente garganta excavada por el río Irati al atravesar la sierra de Leyre, con paredes calizas verticales que alcanzan los 150 metros de altura. El relieve muestra espectaculares formas de erosión fluvial y alberga una de las mayores colonias de buitres de la península.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31157','espacio','Peñaguda / Sotos del río Ebro','Alineación de cerros y escarpes de yesos y arcillas erosionados que flanquean la margen izquierda del río Ebro. El fondo de valle está dominado por la dinámica aluvial y los sotos mediterráneos de sauces y álamos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31159','espacio','Foz de Arbayún (Extremo Sur) / Río Salazar','Punto de confluencia orográfica donde el río Salazar excava impresionantes gargantas en las calizas de la sierra de Leyre. El relieve presenta imponentes acantilados verticales con vegetación eurosiberiana relicta en los repliegues más sombríos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31161','espacio','Sierra de Guirguillano (Laderas) / Regata de Salado','Paisaje de colinas margosas de transición mediterránea, con pendientes moderadas cubiertas por matorrales xerófilos de romero y coscoja. El relieve muestra pequeñas cárcavas erosivas en los materiales arcillosos expuestos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31165','espacio','Soto de Imas / Río Ebro','Amplia llanura de inundación del río Ebro que alberga uno de los sotos de ribera más extensos de la zona, compuesto por saucedas y alamedas maduras. El relieve es plano, conformado por terrazas aluviales cuaternarias de gravas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31166','espacio','Encina de Tres Patas / Sierra de Lóquiz (Vertiente Sur)','El relieve destaca por las abruptas paredes calizas de la sierra de Lóquiz que limitan el valle. En sus faldas se asienta un encinar mediterráneo milenario calcícola donde destaca un ejemplar monumental de encina de morfología caprichosa única.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31169','espacio','Confluencia de los ríos Aragón y Ebro','Enclave geográfico de alta dinámica fluvial donde el río Aragón entrega su gran caudal al Ebro. El paisaje se configura mediante islas de grava, madrejones y sotos de ribera mediterráneos de sauces y chopos negros bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31171','espacio','Sotos del río Arga / Cortados de las Navas','El río Arga serpentea por una llanura arcillosa labrando escarpes y terrazas fluviales de baja altura. Los sotos albergan una densa vegetación hidrófila de carrizales y sauces que contrastan con las áridas lomas circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31173','espacio','Riberas del río Queiles / Balsa de la Dehesa','Relieve llano aluvial interrumpido por pequeñas terrazas cuaternarias en la Ribera Baja. El curso de agua del río Queiles aporta un corredor de vegetación palustre verde que rompe la monotonía del paisaje estepario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31174','espacio','Barranco de San Andrés / Lomas de Tierra Estella','Paisaje de colinas suaves modeladas sobre materiales arcillosos y margosos, con pequeñas masas de encinar mediterráneo residual adaptado a la xericidad estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31175','espacio','Desfiladero de Congosto / Embalse de Laguna de Mues','Angosto paso natural excavado por el río Odrón entre las peñas calizas de la sierra de Codés. Aguas abajo se abre una pequeña cubeta lagunar encajada entre relieves abruptos cubiertos de encinares arbustivos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31176','espacio','Barranco de la Cardelina / Balsas de la Estanca','Entorno semiárido de la Ribera Alta modelado sobre arcillas y terrazas fluviales cuaternarias. Presenta pequeñas depresiones endorreicas estacionales y una vegetación gipsícola dispersa adaptada a la salinidad del suelo xerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31178','espacio','Sotos del río Aragón / Bardenas Altas','Amplio corredor fluvial donde el río Aragón dibuja meandros encajados entre terrazas aluviales y depósitos de gravas. Destaca por sus densas alamedas y por limitar con el relieve quebrado de arcillas erosionadas del norte bardenero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31179','espacio','Peñas de Murillo / Río Aragón','Escarpes yesíferos verticales que flanquean el cauce del río, sirviendo de refugio para avifauna rocosa. El contraste geomorfológico es muy marcado entre la llanura de inundación verde del soto y los cerros desnudos de tonalidades blanquecinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31180','espacio','Encinar de Uterga / Lomas de Valdizarbe','Paisaje de transición compuesto por colinas suaves calcáreas cubiertas por manchas dispersas de encinar mediterráneo. El relieve presenta pequeñas vaguadas modeladas por escorrentías temporales que vierten sus aguas hacia la cuenca del río Robo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31182','espacio','Costalera / Sierra de Codés','Cresta caliza sumamente afilada que corona el horizonte del valle de Berrueza con sus perfiles de dientes de sierra. Las laderas septentrionales muestran grandes canchales y un espeso sotobosque de boj y hayas adaptado a la umbría rocosa de altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31183','espacio','Confluencia de los ríos Arga y Robo','Enclave fluvial estratégico donde se unen los dos cauces principales de la Valdizarbe, generando un soto de llanura fértil. La vegetación está dominada por sauces y chopos que tapizan las terrazas bajas y los depósitos de limos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31184','espacio','Encinar de San Tirso / Río Ega','Pequeñas lomas calizas y margosas cubiertas por un bosque aclarado de encinas de carácter mediterráneo-   continental. El relieve es suave y conecta las llanuras cerealistas con los primeros contrafuertes de la sierra de Lóquiz.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31186','espacio','Robledal de Ostiz / Regata de Mediano','Valle de relieve suave atlántico donde los suelos profundos permiten el desarrollo de un majestuoso bosque de robles pubescentes. Pequeños arroyos sinuosos modelan el fondo de la cuenca calcárea con perfiles aterrazados de gran verdor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31187','espacio','Valle de San Esteban / Regata de Oiz','Entorno atlántico profundo encajonado en el macizo paleozoico de Cinco Villas, caracterizado por sus fuertes pendientes y suelos silíceos. El relieve quebrado genera cascadas menores estacionales bajo la sombra de castañares viejos y helechales gigantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31188','espacio','Desfiladero de Sorauren / Río Ultzama','Brecha fluvial abierta por el río Ultzama en las estructuras calcáreas prepirenaicas, creando un paso estrecho y sombrío. La vegetación de ribera se funde con hayas y robles que colonizan los desprendimientos de las laderas verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31190','espacio','Barranco de San Juan / Lomas de Sorlada','Relieve de suaves colinas margosas en el sector suroccidental navarro, erosionadas por pequeños cursos fluviales de régimen torrencial. Cuenta con matorral mediterráneo xerófilo disperso y pequeños afloramientos de areniscas rojizas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','espacio','Laguna de Pitillas (Límite) / Ribera del Cidacos','Llanura aluvial mediterránea definida por las terrazas del río Cidacos y la proximidad de cuencas endorreicas. El terreno es llano con ligeras ondulaciones arcillosas que albergan carrizales y comunidades vegetales adaptadas al clima semiárido.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31195','espacio','Selva de Irati (Nacedero del Irati) / Cueva de Arpea','Corazón del Pirineo navarro que alberga un relieve kárstico de alta montaña con el espectacular pliegue anticlinal sinclinal de Arpea. El paisaje forestal lo domina el hayedo-abetal de Irati, que rodea el embalse de Irabia y los nacimientos fluviales entre praderas alpinas de Larraun.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31196','espacio','Garganta del río Irati / Monte Alba','Estrecho pasaje fluvial encajado entre moles calizas prepirenaicas cubiertas de hayedos densos. La fuerza erosiva del agua ha labrado pequeñas marmitas y resaltes rocosos en el cauce, configurando un paisaje de agua y bosque de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31197','espacio','Encinar de la Valdorba / Barranco de Mairaga','Paisaje submediterráneo de la Navarra Media caracterizado por colinas modeladas en margas y areniscas. Alberga masas forestales mixtas de encina y quejigo perfectamente adaptadas a la continentalidad climática y suelos arcillosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31200','espacio','Cortados de San Marcos / Río Ega','Escarpes de yesos y arcillas que dominan las terrazas fluviales inferiores de la comarca de Estella. La erosión hídrica ha esculpido pequeñas cárcavas en las vertientes desnudas, que contrastan con los sotos de ribera del río Ega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33014','espacio','Sotos de la Magdalena / Meandro de Aranzadi','Tramo aluvial donde el río Arga dibuja meandros completos sobre una llanura de inundación de limos cuaternarios. Conserva zonas de vegetación hidrófila madura con sauces y alisos que aíslan visualmente el curso del agua del entorno urbano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31203','espacio','Sierra de Selva / Barranco de la Rinconada','Enclave montañoso rodeado de tierras aragonesas, caracterizado por un relieve Prepirenaico de crestas de arenisca y pinedas silvestres. Los barrancos son profundos y estrechos, mostrando formas de erosión torrencial muy marcadas en las vertientes umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31204','espacio','Peña de San Gregorio / Sierra de Codés (Borde)','Muela caliza aislada de paredes verticales que emerge sobre el paisaje agrícola de la Berrueza. Sus laderas calizas presentan un encinar denso con madroñeras y formas kársticas menores como lapiaces y pequeñas oquedades de disolución.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31205','espacio','Reserva Natural de la Laguna de Pitillas','Extenso humedal de origen endorreico considerado uno de los ecosistemas lacustres más importantes del norte peninsular. La lámina de agua somera está rodeada por un cinturón masivo de carrizo y enea, asentada sobre una cubeta arcillosa que alberga una biodiversidad acuática excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','espacio','Sotos del río Arga / Monte Redondo','Amplio valle fluvial donde el río Arga recibe las aguas del río Robo, ensanchando sus terrazas aluviales. El relieve circundante está formado por colinas arcillosas cubiertas de matorral mediterráneo y pequeños retazos de encinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31207','espacio','Alto de la Cruz / Barranco de Mairaga','Relieve de la Navarra Media compuesto por lomas arcilloso-margosas cubiertas de encinares aclarados. Presenta una red de barrancos temporales donde la erosión deja al descubierto estratos sedimentarios de areniscas finas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31208','espacio','Soto del Murillo / Meandros del río Ebro','Gran corredor aluvial de la Ribera Baja donde el río Ebro despliega meandros amplios abandonados y sotos maduros. Destaca por la densidad de sus alamedas y saucedas que colonizan las islas de gravas y los depósitos de limos fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31209','espacio','Foz de Arbayún / Río Salazar','Uno de los cañones más espectaculares de España, labrado por el río Salazar al cortar la sierra de Leyre. Sus paredes verticales calizas alcanzan los 300 metros de altura, albergando un frondoso bosque mixto en el fondo y la mayor colonia de buitres leonados de Navarra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31212','espacio','Sierra de Peña / Barranco de la Vizcaya','Crestas Prepirenaicas de areniscas que definen el relieve septentrional de la comarca de Sangüesa. Las laderas expuestas al norte albergan densos quejigales, mientras que los valles muestran una intensa erosión hídrica en suelos margosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31213','espacio','Cabecera del río Ezcurra / Monte Erasun','Paisaje típico de la Navarra húmeda cantábrica, con valles encajonados sobre rocas silíceas. La alta pluviosidad mantiene un relieve siempre verde dominado por helechales, praderas atlánticas y manchas tupidas de hayedos trasmochos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31215','espacio','Confluencia de los ríos Ebro y Ega','Gran llanura aluvial donde el río Ega entrega sus aguas al Ebro, generando un espacio de inundación de gran dinamismo fluvial. Los sotos albergan formaciones densas de álamos negros y sauces sobre terrazas de gravas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31217','espacio','Sierra de Guerinda / Barranco de la Tejería','Relieve montañoso de la Navarra Media caracterizado por alineaciones de areniscas que albergan encinares bien conservados. La erosión ha labrado pequeños desfiladeros y formaciones rocosas singulares en las crestas superiores del macizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31219','espacio','Barranco de San José / Río Linares','Relieve suave de lomas arcillosas rota por la incisión del río Linares, que genera un pequeño corredor verde en una comarca de marcada aridez estival. Presenta vegetación palustre dispersa en el fondo del cauce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31220','espacio','Balsa de la Sarda / Desembocadura del Cidacos','Humedal estacional situado sobre una meseta arcillosa que sirve de refugio a comunidades botánicas halófilas. El relieve conecta la vega del río Aragón con los páramos desérticos del norte de las Bardenas Reales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31223','espacio','Meandro de Sartaguda / Río Ebro','Gran curva aluvial del río Ebro que delimita el término municipal, caracterizada por playas de cantos rodados y sotos maduros. La vegetación riparia está muy bien desarrollada con especies hidrófilas como sauces y álamos blancos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31224','espacio','Los Cabezos de Sesma / Barranco del Pozo','Paisaje estepario modelado sobre potentes estratos de yesos terciarios que forman cerros testigo de cimas planas. Las vertientes presentan un relieve de cárcavas y barrancos secos con comunidades botánicas gipsícolas especializadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31225','espacio','Basílica de San Gregorio Ostiense (Entorno) / Peña de la Concepción','Elevación caliza prominente que ofrece una excelente sección de estratos calcáreos fallados sobre el valle de la Berrueza. La umbría está tapizada por un encinar carrascal maduro con abundante sotobosque mediterráneo de boj.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31226','espacio','Desfiladero del Bidasoa / Monte Mendaur (Faldas)','Estrecho valle atlántico tallado por el río Bidasoa sobre pizarras y areniscas paleozoicas del macizo de Cinco Villas. Las laderas presentan pendientes muy acusadas cubiertas de pinos, robles y un sotobosque exuberante de helechos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31227','espacio','Monte Plano / Barranco de San Martin','Extensa plataforma elevada o somontano cubierto por una costra calcárea que protege las arcillas inferiores de la erosión. Conserva retazos de un encinar mediterráneo continental adaptado a la escasez de agua superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31228','espacio','Sierra de Aláiz / Canteras de Tiebas','Imponente frente calizo fallado que delimita por el sur la cuenca de Pamplona. El relieve destaca por sus escarpes verticales de roca desnuda y canchales, colonizados en sus zonas menos abruptas por encinares calcícolas y bojedales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31229','espacio','Barranco de San Sebastián / Lomas de Valdizarbe','Suaves ondulaciones del terreno modeladas sobre margas grises de la Navarra Media. Pequeños cursos de agua estacionales generan vaguadas donde se desarrolla vegetación arbustiva mediterránea y quejigos dispersos.   Toledo (Valle de Yerri).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31230','espacio','Santuario de Codés / Peña de los Cencerros','Vertiente meridional de la sierra de Codés, caracterizada por un relieve abrupto de agujas calcáreas y farallones rocosos. La umbría alberga densos hayedos calcícolas, mientras que las zonas bajas presentan encinares mediterráneos de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31231','espacio','Valle del río Linares / Lomas de Sansol','Relieve erosionado sobre arcillas y yesos donde el río Linares excava un pequeño cauce encajonado. El paisaje visual está dominado por colinas de perfiles suaves y sotos fluviales de carácter submediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','espacio','Bárdena Negra (Límite) / Sotos del río Ebro (Soto del Queiles)','Punto de transición donde la llanura aluvial del Ebro contacta con los relieves tabulares de la Bardena Negra, caracterizados por cabezos arcillosos coronados por calizas. Los sotos fluviales albergan una densa vegetación palustre de gran valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31233','espacio','Ribera del río Queiles','Pequeña llanura aluvial de inundación cuaternaria modelada por el río Queiles en la Ribera Baja. El relieve es prácticamente llano con sotos aclarados de sauces y chopos adaptados a la fuerte estacionalidad hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31234','espacio','Sierra de Perdón (Vertiente Sur) / Barranco de las Eras','Laderas margosas que descienden de la sierra del Perdón hacia la Valdizarbe, cubiertas por matorrales de degradación y encinares dispersos. Presenta un relieve de lomas suaves expuestas a una fuerte insolación mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31235','espacio','Sierra de Ujué / Barranco de l''Andandía','Macizo montañoso aislado de la Navarra Media constituido por potentes bancos de areniscas que forman crestas y relieves tabulares. Las laderas están profundamente abarrancadas y cubiertas por densos encinares carrascales de gran valor biogeográfico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31236','espacio','Bosque de Orgi / Cabecera del río Ultzama','Valle de relieve suave de origen kárstico-aluvial que alberga el robledal de Orgi, un bosque milenario de roble pedunculado único en Navarra adaptado a suelos encharcados. El paisaje destaca por sus praderas siempre verdes y regatas serpenteantes de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31241','espacio','Foz de Iñigalzu / Sierra de Areta','Valle prepirenaico profundamente quebrado por el río Areta, que talla gargantas calcáreas estrechas y de difícil acceso. Las laderas montañosas están cubiertas por densas masas de pino silvestre, hayas y grandes extensiones de bosque virgen subalpino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31242','espacio','Garganta del río Irati (Sector San Vicente) / Cerros de Ripodas','Tramo donde el río Irati se encajona entre colinas margosas y calizas antes de unirse al Aragón. El   relieve muestra escarpes fluviales moderados cubiertos por encinares mediterráneos de transición y quejigales ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31243','espacio','Cuenca del río Erro / Lomas de Esteríbar','Paisaje de transición Prepirenaica caracterizado por colinas suaves labradas en margas grises. El río Erro define un pequeño corredor aluvial con sotos de sauces y pequeños humedales estacionales en las vaguadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90937','espacio','Embalses de Leurtza (Compartido) / Monte Mendaur','Espectacular entorno de montaña atlántica donde dos lagunas de montaña se asientan en una cubeta kárstico-silícea rodeada de hayedos densísimos. El relieve es abrupto, con fuertes pendientes y arroyos de aguas sumamente puras y frías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31246','espacio','Sierra del Perdón (Crestas) / Barranco de la Tejería','Vertiente meridional de la alineación montañosa del Perdón, caracterizada por fallas geológicas y afloramientos de areniscas. Las laderas están colonizadas por matorrales xerófilos y encinares degradados por la erosión hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31249','espacio','Cueva de los Montes / Bardenas Reales (Plataforma de El Plano)','Impresionante relieve de cabezos arcillosos erosionados y acantilados de yeso que limitan con la gran llanura aluvial del Ebro. La erosión hídrica y eólica ha labrado un paisaje laberíntico de barrancos secos y formaciones geológicas pseudo-desérticas de gran contraste visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','espacio','Laguna de las Cañas / Barranco de Longar','Gran humedal de origen endorreico y tectónico catalogado como Reserva Natural, situado en la muga con La Rioja. La lámina de agua permanente está rodeada por un denso cinturón de carrizal que destaca sobre los relieves llanos y secos de arcillas de la Ribera Alta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31254','espacio','Sotos del río Aragón / Badinas de Villafranca','Tramo final del río Aragón caracterizado por una llanura de inundación muy dinámica con meandros abandonados y maduros ("badinas"). Alberga una vegetación hidrófila de soto mediterráneo excepcionalmente densa, con álamos, sauces y carrizales profundos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31255','espacio','Monte Monjardín / Carrascal de Villamayor','Prominente cerro testigo de naturaleza caliza que emerge de manera cónica y aislada sobre la llanura de la Navarra Media. Sus vertientes pedregosas están cubiertas por un espeso carrascal mediterráneo maduro que resalta en el relieve agrícola circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31257','espacio','Ribera del río Iranzu / Lomas de Mauriain','Paisaje de colinas suaves arcilloso-margosas modelado por el tramo bajo del río Iranzu antes de su entrega al Ega. El cauce presenta pequeños sotos de sauces y chopos en un relieve de transición agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31261','espacio','Mar de Pirineo (Embalse de Yesa) / Sierra de Leyre','Gran masa de agua de tonos turquesas encajada al pie de los paredones calizos verticales de la sierra de Leyre. El contraste visual entre las aguas y las laderas cubiertas de quejigos y pinos silvestres define un paisaje prepirenaico de gran magnitud.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90938','espacio','Crestas de la Sierra de Altzania','Relieve de alta montaña caliza que marca el límite occidental del corredor de la Sakana. Destaca por sus paredones grises, lapiaces escarpados y un frondoso hayedo atlántico que coloniza las laderas de fuertes pendientes calcáreas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31263','espacio','Río Ezkurra / Bosque de Bidasoa','Valle de modelado silíceo con un curso fluvial de aguas sumamente puras y rápidas. El relieve quebrado está completamente cubierto por un tapiz verde de helechales, robledales atlánticos y castaños centenarios que prosperan bajo la alta pluviosidad de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31264','espacio','Cueva de las Brujas / Túnel del riachuelo Olabidea','Impresionante complejo kárstico superficial cuya cavidad principal consiste en un túnel natural de más de 120 metros de longitud excavado por la erosión continua del agua. El entorno combina este relieve subterráneo colapsado con praderas húmedas y masas boscosas de castaños y robles pedunculados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31265','espacio','Valle de Lana / Desfiladero de Arquijas','Angosto cañón calizo labrado por el río Ega al romper las estructuras rocosas que separan Navarra de Álava.   Las paredes verticales albergan una densa masa forestal de encinas y quejigos que se agarran a las repisas de piedra.   Ourense).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','espacio','Canón del río Arnoia / Penedos de Pascoais','Valle fluvial encajonado sobre un relieve granítico donde el río Arnoia discurre entre grandes bolos de piedra y rápidos. Destacan las formaciones de bosque de ribera autóctono combinadas con sotos de castaños centenarios que crecen entre caprichosas formas rocosas erosionadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90507','espacio','Fervenza do Formigueiro / Senda do Barbantiño','Salto de agua encajado en una fractura tectónica granítica de la comarca de Ourense. El entorno destaca por la densa vegetación de ribera que cubre las márgenes del riachuelo, con abundancia de helechos gigantes y musgos de umbría húmeda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90508','espacio','Confluencia de los ríos Miño y Arnoia / Penedo do Viso','Espectacular llanura aluvial y encuentro de caudales fluviales encajados entre escarpadas laderas graníticas. El microclima local permite la existencia de formaciones vegetales mixtas donde el bosque atlántico se entremezcla de forma natural con especies de afinidad mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90509','espacio','Serra do Suído / Fervenzas de Abelenda','Paisaje de alta montaña gallega caracterizado por altiplanicies graníticas azotadas por el viento, turberas de gran valor ecológico y profundos valles de erosión glaciar.   Sucesivos saltos de agua cristalina salpican las laderas rocosas cubiertas de matorral atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90510','espacio','Serra do Larouco / Valle del río Salas','Imponente relieve montañoso de perfil alomado y naturaleza granítica que hace frontera con Portugal. Destaca por sus canchales de piedra, laderas desnudas azotadas por el viento y zonas de turbera de alta montaña que alimentan el curso alto del río Salas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90511','espacio','Parque Natural Baixa Limia-Serra do Xurés / Encoro das Conchas','Frontera natural kárstica y granítica que destaca por sus cañones encajonados y picos escarpados de perfil abrupto. El entorno combina las aguas calmas del embalse con laderas densamente pobladas por formaciones boreoatlánticas e importantes manchas de madroños.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90512','espacio','Valle del río Arnoia / Os Milagres (Laderas boscosas)','Depresión tectónica donde el río Arnoia ensancha su cauce generando un paisaje fluvial maduro y de aguas templadas. Las laderas circundantes están cubiertas por un mosaico vegetal caducifolio dominado por robles melojos y castaños centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90513','espacio','Desfiladero del río Barbaña / Desembocadura del regato de Piñeiral','Pequeña incisión fluvial sobre roca granítica degradada que rompe la monotonía del relieve de la periferia ourensana. Presenta sotos de ribera bien estructurados con alisos, sauces y un denso sotobosque de helechos que colonizan las umbrías húmedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90514','espacio','Serra do Eixe / Meandros del río Sil','Gran fosa tectónica flanqueada por las cumbres de la sierra del Eixe, donde el río Sil dibuja amplias curvas sobre depósitos aluviales. El fondo del valle muestra terrazas fluviales y laderas de pizarra con una vegetación de fuerte influencia mediterránea y encinares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90676','espacio','Valle del río Avia','Relieve suave de ladera granítica que desciende de manera escalonada hacia el lecho del río Avia. Cuenta con pequeños arroyos estacionales que salpican la cuenca baja, flanqueados por corredores estrechos de vegetación aluvial y matorral atlántico termófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42036','espacio','Fuentes del río Abión y dehesa caliza','Pequeña cuenca de recepción kárstica donde el río Abión inicia su curso mediante afloramientos limpios de agua subterránea. El entorno combina lomas calizas suaves cubiertas de sabina albar y praderas húmedas estacionales que aprovechan la alta presencia de humedad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90516','espacio','Cañón del río Viñao / Sotos de Astureses','Profundo encajonamiento fluvial excavado sobre granito donde el agua genera pequeños rápidos y pozas cristalinas. La umbría del cañón atesora formaciones forestales densas de castaños, robles y laureles silvestres que forman túneles vegetales cerrados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90517','espacio','Penedos de Podentes / Río Ourille','Paisaje granítico colinado caracterizado por la presencia de bolos de piedra redondeados debido a la erosión química de la roca. El río Ourille cruza el término formando pequeños saltos de agua y canales estrechos de alta densidad de vegetación hidrófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90518','espacio','Cañón del río Bibei / Estribaciones de Peña Trevinca','Impresionante corte geológico vertical donde el río Bibei hiende las estructuras de pizarra y granito a gran profundidad. El paisaje visual es sobrecogedor debido a la   verticalidad de los escarpes calcáreos y la vegetación mediterránea relicta que resiste en los abrigos rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90520','espacio','Serra del Faro de Avión / Regato de Maquiáns','Vertiente montañosa abrupta caracterizada por fuentes pendientes y un relieve modelado por la escorrentía superficial. Las laderas están cubiertas por extensas áreas de matorral atlántico, carballeiras jóvenes y afloramientos de roca granítica gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90521','espacio','Macizo de Peña Trevinca / Teixedal de Casaio','Alta montaña alpina que alberga la cumbre más alta de Galicia y el Teixedal de Casaio, un bosque relicto de tejos centenarios único en Europa. El relieve muestra circos y valles de origen glaciar con lagunas de montaña de aguas heladas y crestas de pizarra desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34007','espacio','Parque del río Arenteiro / Penedo da Moura','Tramo de corredor fluvial encajado donde el río Arenteiro discurre entre bloques graníticos formando rápidos y pequeñas cascadas. La ribera conserva una excelente representación de bosque atlántico gallego con alisos monumentales y masas de helechos reales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90522','espacio','Cañón del río Miño (Tramo bajo) / Desembocadura del Arnoia','Grandes laderas escarpadas que caen directamente sobre el cauce del río Miño, configurando un paisaje de desfiladero encajonado. La vegetación destaca por el fuerte contraste entre el bosque caducifolio de las cumbres y los encinares termo-atlánticos de las zonas bajas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90523','espacio','Ladera del río Miño / Encoro de Castrelo','Amplia cubeta fluvial flanqueada por laderas graníticas de pendientes moderadas que caen hacia el río Miño. Destaca por el contraste de las aguas mansas embalsadas con los afloramientos rocosos y pequeños reductos de bosque mixto atlántico-mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90524','espacio','Cabezo de Manzaneda / Valle del río Támega','Relieve de transición hacia la alta montaña con laderas pizarrosas cubiertas de brezales y matorral atlántico. El tramo alto del río Támega discurre encajonado entre valles secundarios que albergan magníficas masas de castaños centenarios aislados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','espacio','Cañón del río Sil (Ribeira Sacra) / Souto de Poboeiros','Impresionante garganta tectónica con paredes verticales de granito que se desploman cientos de metros sobre el curso del río Sil. Las umbrías verticales albergan un majestuoso sotobosque calcícola de madroños y densos bosques de robles que contrastan con los escarpes desnudos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','espacio','Valle del río Arnoia / Souto de Castromao','Depresión orográfica caracterizada por suaves colinas graníticas y llanuras aluviales bien drenadas. El paisaje visual destaca por sus formaciones maduras de carballeiras y sotos de castaños densos que colonizan las vaguadas húmedas de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90525','espacio','Confluencia de los ríos Miño y Avia / Regato de Barbantiño','Paisaje geomorfológico de valles encajados y laderas escarpadas sobre materiales graníticos erosionados. La confluencia fluvial genera una densa llanura de inundación protegida por sotos maduros de alisos, sauces y laureles silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32029','espacio','Serra de Queixa / Valle del río Navea','Macizo de alta montaña con un relieve fuertemente modelado por antiguos procesos glaciares y periglaciares. Cuenta con altiplanicies desnudas y profundos valles encajonados donde el río Navea esculpe gargantas bajo la sombra de abedulares y acebedas relictas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','espacio','Sotos del río Miño / Barra (Afloramientos rocosos)','Tramo de corredor fluvial donde el río Miño se ensancha ligeramente mostrando islas fluviales y depósitos de gravas. Las laderas circundantes presentan una topografía suave de colinas graníticas cubiertas por pinos y robles melojos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32027','espacio','Cañón del río Miño / Termas de Cortegada (Entorno natural)','Estrecho desfiladero granítico donde el Miño discurre fuertemente encajonado entre escarpadas laderas de fuertes pendientes. La elevada humedad y el abrigo orográfico permiten la proliferación de laurisilva relicta, alcornoques y densas masas de helechos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32028','espacio','Serra de Larouco / Nacimiento del río Búbal','Relieve montañoso de cumbres aplanadas y fuertes escarpes laterales labrados sobre granito y esquistos. La vegetación predominante es el matorral alpino y brezales secos que ofrecen un aspecto cromático cambiante a lo largo de las estaciones.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32030','espacio','Parque Natural Baixa Limia-Serra do Xurés / Río Pacín','Paisaje granítico de alta montaña caracterizado por circos glaciares, espectaculares bolos graníticos y agujas rocosas desgastadas. El río Pacín forma pozas naturales de aguas cristalinas e intensos tonos verdes enmarcadas en un denso bosque atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32031','espacio','Rocas de San Pedro / Serra de Cabeza de Vaca','Singular paisaje de lomas graníticas donde la erosión ha esculpido caprichosas formas rocosas y penedos   aislados. La vegetación está dominada por brezales densos y carballeiras bajas que se abren paso entre las grietas de la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32033','espacio','Valle del río Arnoia / Devesa de Poulo','Relieve quebrado de media montaña con valles estrechos orientados hacia la cuenca del Arnoia. Alberga pequeñas manchas de robledal maduro y vegetación de ribera que se refugia en los profundos cortes del terreno arcillogranítico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34001','espacio','Serra de San Mamede / Encoro de Pías','Altiplanicie de alta montaña penillanura con afloramientos rocosos y turberas subalpinas dispersas. El paisaje es austero y de horizontes abiertos, dominado por brezales y formaciones arbustivas adaptadas a los rigores del clima continental de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90526','espacio','Serra de Testeiro / Nacimiento del río Viñao','Dorsal montañosa que sirve de barrera climática, caracterizada por un relieve abrupto de fuertes pendientes sobre materiales esquistosos. Presenta una alta pluviosidad que sustenta extensas praderas húmedas y densas masas forestales de frondosas caducifolias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32038','espacio','Cañón del río Sil / Codos de Larouco (Escarpes)','Vertiente de pendientes extremas tallada sobre pizarras y areniscas en la zona de transición hacia el cañón del Sil. El relieve es marcadamente abrupto, ofreciendo una imponente visual de la fractura geológica de la comarca con vegetación xerófila mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32039','espacio','Valle del río Támega / Serra de San Mamede (Ladera Este)','Amplio anfiteatro montañoso que da origen a la cuenca alta del Támega, rodeado de cumbres redondeadas. Las laderas albergan devesas de robles y grandes extensiones de castaños bien conservadas, con pequeños arroyos que caen en cascada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','espacio','Riberas del río Avia / Salto de Pena Corneira (Entorno)','Valle de modelado aluvial rodeado por colinas graníticas cubiertas de densa vegetación forestal. El curso del río Avia discurre de forma sinuosa flanqueado por alisos y sauces centenarios que configuran un corredor verde continuo de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32041','espacio','Parque Natural Baixa Limia-Serra do Xurés / Pico do Viso','Vertiente noroccidental del macizo del Xurés caracterizada por enormes canchales y bloques graníticos de formas caprichosas. El paisaje muestra un fuerte gradiente altitudinal dominado por densos brezales, robledales termófilos y madroñales de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32042','espacio','Parque Natural Baixa Limia-Serra do Xurés / Cañón del río Fecha','Espectacular y abrupto desfiladero granítico donde el río Fecha se desploma creando una sucesión ininterrumpida de cascadas y pozas gigantescas. Es uno de los relieves más puros y agrestes del noroeste peninsular, rodeado de vegetación endémica subatlántica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32043','espacio','Serra de San Mamede / Sotos de Maceda','Laderas montañosas de pendientes suaves que sirven de piedemonte al macizo de San Mamede. Están densamente cubiertas por masas forestales de robles y   castaños caducifolios que dan paso a pastizales húmedos en los fondos de los valles fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32044','espacio','Macizo de Central Ourensán / Souto de Rozabales','Alta montaña caracterizada por el imponente domo granítico de Cabeza de Manzaneda y el Monumento Natural del Souto de Rozabales, que alberga castaños milenarios de perímetros gigantescos. El relieve muestra valles glaciares y extensas laderas cubiertas de piornales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32046','espacio','Fervenzas del río Cerves / Serra del Faro de Avión','Impresionante sucesión de saltos de agua y marmitas de gigante excavadas por el río Cerves sobre una ladera granítica vertical de fractura tectónica. El entorno está rodeado de un denso bosque húmedo de ribera con una altísima densidad de musgos y helechos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32047','espacio','Valle del río Arnoia / Lomas de Olás','Relieve alomado y suave sobre materiales graníticos meteorizados de la meseta ourensana. Los pequeños valles albergan arroyos modestos rodeados de vegetación riparia común y masas aclaradas de robles melojos y pinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32048','espacio','Serra da Gralheira / Nacimiento del río Tuela','Entorno montañoso de carácter rústico y fronterizo con predominio de rocas metamórficas y perfiles redondeados por la erosión antigua. Los cursos altos de los ríos excavan valles estrechos poblados por abedulares, brezales y matorral de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32049','espacio','Bidueiral de Montederramo / Serra de San Mamede','Alberga uno de los bosques de abedules más importantes y meridionales de Europa, asentado sobre laderas de fuerte pendiente e influencia atlántica. El relieve montañoso presenta suelos húmedos e higrófilos que generan un paisaje forestal de gran misticismo visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32050','espacio','Valle de Verín / Río Támega','Fosa tectónica rellenada por sedimentos cuaternarios que genera una amplia y fértil llanura aluvial. El río Támega vertebra el territorio con meandros abandonados y sotos de ribera bien estructurados que rompen con las elevaciones montañosas perimetrales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32051','espacio','Parque Natural Baixa Limia-Serra do Xurés / Encoro de Salas','Paisaje granítico de alta montaña integrado en la reserva de la biosfera, con grandes bloques de roca desnudas y valles inundados. Cuenta con corredores ecológicos fluviales de aguas puras y una vegetación dominada por robledales y matorral de cumbre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','espacio','Cañón del río Sil / Peares (Confluencia Sil-Miño)','Espectacular y escarpado tramo final del cañón del Sil en su encuentro con el río Miño, formando un imponente nudo de gargantas graníticas verticales. Las laderas están cubiertas por una densa masa forestal mixta con especies mediterráneas relictas de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32053','espacio','Riberas del río Támega / Lomas de San Cibrao','Terreno de suaves colinas y valles de sedimentación arenosa en la frontera meridional con Portugal. El río Támega aporta una franja de sotos húmedos con sauces y chopos que contrastan con los relieves secos y erosionados del entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34008','espacio','Surgencias termales del río Miño / Canón de Outariz (Margen natural)','Fosa tectónica donde confluyen varios ríos y emergen fracturas corticales con aguas termales. Los márgenes del Miño conservan zonas de afloramiento granítico escarpado y densos sotos aluviales bien integrados en la dinámica fluvial natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32055','espacio','Lomas de San Vitoiro / Río Arnoia','Paisaje mesetario suavemente ondulado sobre granito degradado con presencia de pequeños boscajes de robles y pinos de repoblación. El relieve interior es de valles ciegos y pequeñas dehesas que drenan de forma natural hacia la cuenca del Arnoia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32056','espacio','Cañón del río Miño (Frontera) / Río Crespos','Relieve abrupto que desciende de manera vertiginosa hacia el cauce internacional del río Miño. Las laderas están fuertemente hendidas por barrancos sombríos donde la vegetación atlántica alcanza su máxima densidad con robles, laureles y alcornoques.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32057','espacio','Cañón del río Sil / Balcones de Madrid (Cortados rocosos)','Uno de los puntos más sobrecogedores de la Ribeira Sacra, con paredes verticales de granito que caen a plomo más de 300 metros sobre el río Sil. El relieve es una gigantesca fractura geológica tapizada de castaños y encinas de roca aferradas a los cantiles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32058','espacio','Encoro de Cachamuíña / Laderas del río Loña','Relieve colinado de naturaleza granítica que suaviza la transición hacia la capital ourensana. Presenta   pequeños cañones fluviales excavados por el río Loña, cubiertos por masas forestales caducifolias mixtas y abundante sotobosque de helechales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90527','espacio','Garganta del río Miño / Desembocadura del río Búbal','Paisaje quebrado de fuertes pendientes donde el río Búbal se encajona antes de verter sus aguas en el Miño. Destaca por sus formaciones rocosas graníticas erosionadas y por la presencia de densas carballeiras que tapizan las laderas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','espacio','Encoro de Santa Eulalia / Sierra de Mones','Entorno encajonado de valles de pizarra donde las aguas tranquilas del embalse reflejan los perfiles escarpados de la sierra de Mones. Cuenta con una vegetación mixta con notables colonias de encinas mediterráneas adaptadas a los suelos secos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32061','espacio','Cabecera del río Arenteiro / Sotos de Corna','Altiplanicie granítica de transición con un relieve suavemente quebrado por regatos estacionales. Alberga devesas bien conservadas de roble melojo y castaños dispersos que se asientan sobre suelos higrófilos típicos de la alta Galicia interior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32062','espacio','Fervenza de Parada / Valle de A Limia','Pequeño salto de agua encajado en una falla granítica que rompe hacia la llanura de A Limia. El entorno fluvial está sumamente protegido por densas masas de bosque de ribera y helechos monumentales que prosperan en la humedad constante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90528','espacio','Cañón del río Bibei / Navea (Desfiladeros)','Impresionante relieve quebrado donde los ríos Bibei y Navea labran profundas gargantas en la roca metamórfica. Las escarpadas laderas albergan sotos de castaños centenarios y comunidades mediterráneas de madroños y encinas de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90529','espacio','Riberas del río Deva / Regato de Trado','Estrecho valle fluvial encajonado sobre granito en el límite sudoccidental de la provincia. El curso del río Deva es rápido y limpio, rodeado por un soto aluvial maduro con alisos, sauces y densas formaciones de matorral atlántico húmedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32066','espacio','Serra de Penagache / Barranco de Leirado','Macizo granítico fronterizo de formas redondeadas con vertientes abruptas cubiertas de densos brezales y piornales de montaña. Los valles interiores albergan pequeños arroyos de aguas sumamente limpias y carballeiras protegidas en las vaguadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32067','espacio','Carballeira del río Limia / Humedales de Congostro','Paisaje de llanura aluvial integrado en la reserva de la biosfera, caracterizado por extensas praderas húmedas y charcas estacionales. Destacan sus históricas masas forestales de robles pedunculados asentadas sobre los antiguos sedimentos de la cuenca lacustre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32082','espacio','Llanura aluvial de A Limia / Río Faramontaos','Extensa llanura sedimentaria de topografía horizontal asentada sobre la antigua cuenca lacustre de Antela. El paisaje visual es abierto y homogéneo, roto únicamente por los canales de drenaje naturalizados y pequeños bosquetes de sauces y abedules.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','espacio','Confluencia del río Miño y el río Avia / Penedos de Rego','Gran cubeta tectónica de modelado granítico donde confluyen los caudales más importantes de la zona sudoccidental. El relieve muestra terrazas fluviales bien definidas y escarpes rocosos cubiertos de matorral termófilo y reductos de soto aluvial maduro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','espacio','Valle del río Mente / Sotos de Castrelo de Abajo','Paisaje quebrado prepirenaico de transición con valles profundos y laderas cubiertas de brezales secos. El cañón del río Mente destaca por su aislamiento geográfico y por albergar magníficos sotos de castaños centenarios bien estructurados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32072','espacio','Encoro de San Martiño / Estrecho de San Miguel','Valle de origen tectónico donde el río Sil se ensancha formando un humedal fluvial de gran interés ornitológico y paisajístico. Aguas abajo, el relieve se cierra bruscamente en escarpes pizarrosos con vegetación xerófila mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32074','espacio','Lomas de Las / Río Barbantiño','Topografía suavemente ondulada caracterizada por la presencia de colinas graníticas erosionadas de baja altitud. Cuenta con arroyos menores que drenan la cuenca   central, flanqueados por matorrales atlánticos y robledales jóvenes dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90531','espacio','Valle del río Barbaña / Desfiladero de Soutopenedo','Depresión erosiva que rompe hacia la fosa de Ourense, encajonando levemente el curso del río Barbaña. Las laderas presentan afloramientos de granito meteorizado con pinos y parches aislados de vegetación riparia adaptada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32076','espacio','Serra de Martñá / Riberas del río Oseira','Macizo montañoso de perfil alomado que domina el norte de la comarca, con vertientes cubiertas de densos brezales. El curso alto del río Oseira modela un valle angosto poblado por un frondoso robledal atlántico bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32077','espacio','Areales de Sandiás / Antigua Laguna de Antela (Restos)','Llanura sedimentaria donde la extracción minera histórica ha generado un complejo de lagunas artificiales naturalizadas de alta relevancia ecológica. Sirve de refugio para la flora palustre en mitad de la árida llanura agrícola desecada de A Limia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90532','espacio','Cañón del río Navea / Pena Folgoso','Profunda incisión fluvial con laderas de pendientes extremas que caen de forma vertical hacia el lecho del río Navea. El entorno destaca por su espectacularidad visual, con sotos de castaños colgados de las rocas y masas de matorral subalpino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32078','espacio','Serra de San Mamede (Cumbres) / Nacimiento del río Limia','Altiplanicie de alta montaña granítica donde se sitúan las fuentes del río Limia en forma de pequeñas turberas y regatos. El paisaje es desarbolado, dominado por praderas de montaña y piornales azotados por el viento continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32079','espacio','Bosque de Torán / Río Benito','Relieve mesetario de lomas arcillo-graníticas suaves con pequeñas cuencas endorreicas estacionales. Cuenta con pequeñas manchas de carballeira mixta y corredores estrechos de sauces que acompañan los cursos de agua menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32080','espacio','Cañón del río Mao / Cortados del Sil','Espectacular confluencia donde el río Mao rasga la meseta granítica en un cañón de verticalidad absoluta antes de unirse al Sil. El relieve presenta saltos de agua encajados y una umbría perenne poblada por robles, castaños y madroños relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32081','espacio','Margen izquierdo del río Miño / Penedos de Mugares','Escarpadas laderas graníticas orientadas al norte que caen directamente sobre el cauce del río Miño. La umbría orográfica permite el desarrollo de un denso encinar mediterráneo mixto con alcornoques y robles que colonizan los canchales de piedra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32083','espacio','Macizo de Peña Trevinca / Lagunas Glaciares de Carrizais y Ocelo','Paisaje alpino de la cumbre de Galicia, caracterizado por un modelado glaciar perfecto con circos, morrenas e impresionantes lagunas de alta montaña de aguas heladas. Alberga laderas de pizarra desnudas, cascadas estacionales y los ecosistemas más puros y vírgenes del noroeste peninsular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32084','espacio','Serra de Penagache / Nacimiento del río Ourille','Relieve montañoso granítico de cumbres redondeadas e importantes canchales que marcan la divisoria de aguas de la comarca. Las vaguadas albergan carballeiras compactas bien conservadas y turberas de alta montaña de gran interés biogeográfico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32085','espacio','Aguas minero-medicinales del río Támega / Desfiladero de Mairos','Fosa tectónica flanqueada por fallas corticales donde el río Támega ensancha su cauce tras superar pequeños estrechos rocosos. Los márgenes conservan una excelente muestra de vegetación ripícola con alamedas y saucedas maduras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34012','espacio','Encoro de Bao / Cañón del río Bibei','Impresionante paisaje fluvial donde el embalse inunda un laberinto de valles pizarrosos profundamente encajonados. El relieve es marcadamente abrupto, con vertientes escarpadas cubiertas de brezales, robledales melojos y pinos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32087','espacio','Penedos de Tamallancos / Río Barbantiño','Paisaje granítico colinado dominado por grandes bolos de piedra redondeados debido a la   meteorización química. Los cursos de agua menores excavan pequeñas canales sombrías cubiertas por densas masas de matorral atlántico húmedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32088','espacio','Sotos de Córgomo / Cascadas del río Baos','Valles de fuertes pendientes labrados sobre pizarras y esquistos en la cuenca del Sil. El río Baos genera pequeños saltos de agua encajados en gargantas umbrías rodeadas por magníficos sotos de castaños y encinares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32089','espacio','Serra de San Mamede / Arribas del río Arnoia','Vertiente suroccidental del macizo montañoso, caracterizada por un relieve abrupto de alta montaña que desciende hacia la llanura. Las laderas están cubiertas por extensos piornales, brezales húmedos y densas devesas de robles melojos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32090','espacio','Humedal de A Limia / Regato de Saa','Zona de llanura aluvial integrada en el entorno protegido de la antigua laguna de Antela. Cuenta con canales naturalizados, praderas inundables estacionales y sotos de ribera bien conservados que albergan una flora palustre especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32091','espacio','Fervenza da Cerveira / Serra de Mairos','Espectacular salto de agua que salva el desnivel geológico de la frontera luso-gallega, encajonado en una fractura de rocas metamórficas. El entorno es muy agreste, dominado por matorrales secos mediterráneos y robledales de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32092','espacio','Parque Natural do Invernadeiro / Cañón del río Cenza','Paisaje de aislamiento geográfico absoluto en un cañón pizarroso de proporciones colosales, con una de las cascadas más altas de Galicia en el río Cenza. El relieve es totalmente abrupto y salvaje, cubierto por acebedas, abedulares y bosques relictos de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32036','espacio','Valle del río Arnoia / Sotos de Armeá','Relieve de suaves colinas graníticas que escoltan el curso medio del río Arnoia. Las márgenes del río presentan una franja bien conservada de bosque aluvial caducifolio que contrasta con los afloramientos rocosos cubiertos de brezales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32037','espacio','Serra de Cabeza de Meda','Elevación montañosa granítica que define el perfil meridional de la Ribeira Sacra, con cumbres aplanadas y fuertes escarpes laterales. El paisaje visual es diáfano y está cubierto por densas formaciones de matorral alpino y brezales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90803','espacio','Riberas del río Valdavia / Oteros de Abia','Tramo fluvial moduro donde el río Valdavia genera una estrecha llanura de inundación flanqueada por sotos de chopos y sauces. El relieve se caracteriza por suaves oteros arcillosos que delimitan el horizonte cerealista de la comarca de la Vega-Valdavia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35001','espacio','Cañón de la Horadada / Embalse de Aguilar / Peña Longa','Impresionante garganta excavada por el río Pisuerga sobre las estructuras calizas de las Loras, mostrando paredes verticales de gran potencia geomorfológica. El entorno combina este relieve abrupto con masas de agua estables rodeadas de pinares y quejigares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90238','espacio','Nacimiento del Canal de Castilla / Estrechuras del Pisuerga','Punto geográfico donde el río Pisuerga aporta su caudal al histórico canal, discurriendo entre pequeños cortados calizos y terrazas aluviales bien definidas. El paisaje visual destaca por la madurez de su bosque de ribera y la pureza de sus aguas corrientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90239','espacio','Valle de San Pedro / Páramo de Alba','Relieve típico de la plataforma caliza del Cerrato, caracterizado por profundos valles de erosión y páramos descarnados. Las laderas presentan lapiaces incipientes y pequeños rodales de encinas y tomillares xerófilos adaptados a la sequía extrema.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90804','espacio','Humedal de la Balsa / Lomas arcillosas','Pequeña cubeta endorreica naturalizada en mitad de la llanura de Tierra de Campos, que sirve de refugio estacional para la avifauna y flora palustre. El relieve es de lomas suaves arcillosas con un perfil liso y homogéneo de tonos rojizos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','espacio','Cuesta de Valoria / Páramo de San Torcaz','Prominente escarpe calizo que rompe de forma abrupta hacia la llanura cerealista, mostrando el perfil clásico de un cerro testigo. Las vertientes albergan un estrato   geológico expuesto con vegetación gipsícola, esparteras y encinas achaparradas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90241','espacio','Sotos del río Ucieza / Praderas de la Ermita de las Fuentes','Valle de sedimentación cuaternaria donde el río Ucieza dibuja meandros suaves rodeado de saucedas y alamedas. El entorno presenta pequeñas surgencias de agua subterránea estables que saturan el suelo, generando praderas húmedas permanentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90805','espacio','Valle del Cerrato / Monte de la Dehesa','Paisaje quebrado del páramo palentino con profundos barrancos de erosión hídrica sobre calizas y margas. La umbría conserva un encinar denso y maduro con quejigos subatlánticos relictos de gran valor forestal y botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','espacio','Meandros del río Pisuerga / Páramo de San Pedro','Amplio corredor fluvial donde el río Pisuerga erosiona las bases del páramo calcáreo, generando escarpes ribereños de fuerte impacto visual. El fondo del valle muestra depósitos de gravas y sotos de ribera bien estructurados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34018','espacio','El Mirador de Campos / Escarpe del Páramo de Autilla','Imponente fractura orográfica donde la meseta caliza superior colapsa verticalmente hacia la gran llanura arcillosa de Tierra de Campos. El relieve muestra desniveles acusados y una sección estratigráfica perfecta visible desde decenas de kilómetros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','espacio','Valle de San Antón / Monte de San Gregorio','Corazón geográfico del Cerrato, definido por un laberinto de valles ciegos y cerros coronados por calizas tabulares. Las laderas albergan dehesas maduras de encina carrasca y un denso matorral de aromáticas adaptado a suelos calizos rústicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','espacio','Valle de Santullán / Hayedo de Brañosera (Límite) / Minas de caliza','Entorno subalpino de la Montaña Palentina caracterizado por fallas carboníferas y relieves calizos abruptos. Cuenta con profundas canales cubiertas por masas compactas de hayedo puro, tejos aislados y acebedas que colonizan las pedrizas calcáreas.   Basardilla (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','espacio','Laguna de la Nava (Límite) / Ramal de Campos del Canal de Castilla','Llanura horizontal arcillosa caracterizada por un relieve liso propio de la cuenca sedimentaria del Duero. La presencia de agua se limita a los canales y pequeñas lagunas estacionales rodeadas de carrizales y juncos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34031','espacio','Riberas del río Cueza / Llanura esteparia','Paisaje monótono de Tierra de Campos roto sutilmente por el curso encajonado del río Cueza. Las márgenes albergan vegetación ripícola dispersa y carrizales que rompen la sequedad de los campos agrícolas circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34032','espacio','Valle del río Ebro / Escarpes de la Lorilla','Enclave palentino rodeado por Cantabria y Burgos, asentado sobre los impresionantes farallones calizos   que caen hacia el cañón del Ebro. El relieve es quebrado y agreste, dominado por quejigares de roca y matorral atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34036','espacio','Nacimiento del río Camesa / Hayedo de la Pedrosa / Sestil de la Choza','Alta montaña alpina en las estribaciones de la cordillera Cantábrica, con un relieve modelado por el hielo y la nieve. El hayedo de la Pedrosa forma un dosel boscoso continuo e impresionante sobre laderas de pendientes extremas y lechos rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34037','espacio','Cuenca alta del río Valdavia / Monte de quejigos','Zona de transición entre la llanura y la montaña, con un relieve de lomas suaves y valles disimétricos. Las zonas forestales conservan quejigares bien estructurados asentados sobre depósitos de rañas y cantos rodados cuarcíticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34038','espacio','Vega del río Carrión / Llanura aluvial','Amplia terraza fluvial cuaternaria donde el río Carrión ensancha su lecho y genera un soto maduro de chopos negros, sauces y alisos. El relieve es plano, destacando por el contraste de color verde con el entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34041','espacio','Valle del río Boedo','Pequeña depresión erosiva donde el río Boedo discurre de forma tranquila sobre materiales arcillosos y arcenes de cantos rodados. Cuenta con sotos fluviales bien conservados e islas de carrizal estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34042','espacio','Río Carrión (Tramo medio) / Arroyos del Camino','Terreno horizontal aluvial caracterizado por la presencia de una densa red de riego naturalizada y acequias   antiguas. Las márgenes del Carrión aportan una franja continua de vegetación hidrófila de alto valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34045','espacio','Charcas de Capillas / Tierra de Campos','Paisaje plano arcilloso con pequeñas depresiones donde aflora el agua freática en invierno, generando charcas temporales. Presenta una vegetación esteparia especializada y adaptada a la alta salinidad del suelo seco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34046','espacio','Barranco de la Volpejera','Pequeño surco de erosión excavado por corrientes efímeras sobre arcillas de la meseta norte. El paisaje es árido y abierto, con matorrales ralos y pastizales estacionales xerófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','espacio','Riberas del río Carrión / Isla de los Monjes','Amplio pasaje fluvial donde el río Carrión se divide en varios brazos generando islas naturales cubiertas de un frondoso bosque de galería. El relieve es suave y aluvial, con alisos centenarios y sauces de gran porte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34049','espacio','Peña Redonda (Estribaciones) / Brezales de la Peña','Imponente relieve de transición montañosa dominado por la mole caliza de Peña Redonda. El paisaje visual es severo, con grandes escarpes de roca gris desnudas y laderas cubiertas de brezales y encinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34050','espacio','Valle del río Esgueva / Páramo de Castrillo','Extremidad meridional palentina definida por el valle del río Esgueva, encajonado entre páramos calizos tabulares. Destaca por el contraste entre los cultivos de fondo de valle y los taludes descarnados de margas blanquecinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34051','espacio','Valle de Cerrato / Arroyo de San Miguel','Complejo laberinto de lomas y barrancos esculpidos sobre calizas del Mioceno. El relieve presenta escarpes rocosos donde se refugian encinas carrascas y una densa vegetación arbustiva de tomillo, espliego y salvia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34052','espacio','Riberas del río Valdavia / Vega de Villavega','Tramo medio del río Valdavia caracterizado por un relieve de llanura aluvial con terrazas escalonadas de cantos rodados. El río conserva sotos maduros de chopos autóctonos y sauces que estabilizan las márgenes erosionadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34056','espacio','Parque Natural Montaña Palentina / Paraje de Fuente de Cobre / Desfiladero de la Requejada','Espectacular relieve de alta montaña donde el río Pisuerga brota de una gran cavidad kárstica en la Fuente de Cobre. El entorno combina impresionantes desfiladeros calizos con la mayor masa forestal mixta de la provincia, incluyendo hayedos, robledales y acebedas relictas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34057','espacio','Páramo de Cevico / Valle de Valdecañas','Relieve tabular del Cerrato con imponentes mesetas calcáreas cortadas a pico por la erosión fluvial. Las vertientes de las cuestas muestran cárcavas arcillosas y densos encinares que cubren las zonas de umbría mejor conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34058','espacio','Valle del arroyo de Navas / Monte de la Dehesa','Profunda incisión erosiva en el páramo calcáreo que genera un valle estrecho rodeado de escarpes de roca caliza bien definidos. Alberga uno de los encinares más   extensos y densos del Cerrato, con un sotobosque rico en sabinas y enebros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','espacio','Humedal de San Facundo / Tierra de Campos','Cubeta endorreica recuperada sobre arcillas cuaternarias, que retiene agua de escorrentía superficial durante el invierno. Presenta densas masas de enea y carrizales que rompen la homogeneidad visual de la meseta cerealista palentina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34060','espacio','Valle del río Franco / Monte de Cobos','Relieve ondulado de media montaña caliza delimitado por el cauce limpio del río Franco. Las laderas están cubiertas por encinares aclarados mediterráneos y quejigos que marcan la transición hacia las tierras burgalesas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34062','espacio','Congosto del río Valdavia / Monte de la Abadía','Pequeño desfiladero donde el río Valdavia corta las primeras estribaciones montañosas cuarcíticas. El cauce se estrecha bruscamente entre bloques de roca erosionados, rodeado por masas boscosas de quejigos y pinos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34063','espacio','Ribera del río Pisuerga / Confluencia del Arlanza','Enclave geográfico marcado por el encuentro de los cursos fluviales del Pisuerga y el Arlanza sobre una llanura aluvial madura. Destaca por la anchura de sus sotos de ribera, con abundantes saucedas y alamedas bien estructuradas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34066','espacio','Valle del río Pisuerga (Límite) / Páramo de Cubillas','Declive calizo septentrional del Cerrato que desciende hacia la cuenca del Pisuerga mediante una sucesión de cuestas y cárcavas arcillosas. Conserva   encinares ralos adaptados a una extrema insolación y suelos pobres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34068','espacio','Loma de la Dehesa / Arroyos del Boedo','Relieve alomado sobre materiales arcillosos y cuarcíticos que sirve de cabecera a pequeños arroyos tributarios del Boedo. Alberga parches boscosos de robles melojos y quejigos adaptados al clima continental severo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','espacio','Confluencia de los ríos Pisuerga y Carrión / Monte de la Santa Espina','Estratégico nudo fluvial donde se unen los dos grandes ríos de la provincia, generando una inmensa dehesa y llanura de inundación. El relieve montañoso perimetral cuenta con el denso encinar del monte de Dueñas, un pulmón verde de gran valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34070','espacio','Valle del río Franco / Páramo de San Carlos','Relieve escarpado del Cerrato oriental donde el río Franco excava un valle sinuoso. Las paredes del páramo muestran afloramientos calcáreos y taludes cubiertos por un denso matorral mediterráneo de tomillares y encinas aisladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34071','espacio','Valle del río Valdavia / Lomas de Villagonzalo','Paisaje llano de la comarca del Boedo-Valdavia interrumpido por pequeñas elevaciones cuarcíticas erosionadas. El río Valdavia aporta un soto húmedo lineal estable compuesto por chopos y densos matorrales de mimbreras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34072','espacio','Río de la Cueza / Llanura cerealista','Topografía horizontal extrema de Tierra de Campos, donde el río de la Cueza traza un cauce pálido y   somero. Presenta un relieve uniforme y desprovisto de vegetación arbórea, de alto interés para la observación de horizontes limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34073','espacio','Riberas del río Carrión / Estribaciones de la Montaña Palentina','Tramo alto del río Carrión en su salida de los macizos montañosos, discurriendo sobre un lecho pedregoso de cantos cuarcíticos. El relieve empieza a ondularse, albergando sotos de alisos bien conservados y robledales jóvenes en las cuestas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','espacio','Cuádruple Esclusa del Canal de Castilla / Río Ucieza','Hito de la ingeniería hidráulica integrado en un entorno natural aluvial donde el Canal de Castilla cruza el término de forma rectilínea. El paisaje visual destaca por las hileras kilométricas de chopos que escoltan el cauce artificial sobre la llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','espacio','Humedal de la Laguna de la Nava de Fuentes / Praderas del Hoyo','Extraordinario humedal estepario de origen endorreico, recuperado sobre una inmensa llanura arcillosa horizontal. Sus someras láminas de agua dulce están rodeadas por inmensos carrizales, juncales y praderas inundables, constituyendo un ecosistema acuático único de gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34077','espacio','Arroyo de Valdepero / Lomas de la Vega','Relieve de lomas arcillosas suaves que marcan la transición entre la cuenca de Palencia y Tierra de Campos. El arroyo aporta un humedal modesto estacional con espadañas y matorral rústico mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','espacio','Entorno del río Carrión / Sierra de la Peña (Límite)','Macizo de media montaña que marca el flanco occidental de la cuenca minera palentina, donde el río Carrión discurre encajonado sobre un lecho de bloques cuarcíticos. Las laderas albergan densas masas de roble melojo y pinos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','espacio','Confluencia del río Burejo y el río Pisuerga / Presa de San Andrés','Amplio valle aluvial donde el río Burejo entrega sus aguas al Pisuerga, generando un entramado de meandros, islas y brazos fluviales. La vegetación de ribera es madura y densa, destacando grandes ejemplares de sauces, alisos y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34082','espacio','Valle del arroyo de San Juan / Monte de la Dehesa','Relieve quebrado y áspero del sur del Cerrato, caracterizado por escarpes margosos erosionados en cárcavas. La umbría conserva un encinar carrascal compacto de gran valor para la fijación de suelos pobres sobre calizas tectónicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34088','espacio','Riberas del río Carrión / Soto de Husillos','Tramo aluvial del río Carrión en la comarca de la Vega, donde el cauce se ensancha y estabiliza sobre sedimentos cuaternarios. El soto de ribera forma un túnel   vegetal continuo de chopos, sauces y fresnos de gran espesura visual. Iciar (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34089','espacio','Ribera del río Pisuerga / Puente de Itero (Entorno)','Límite oriental de la provincia marcado por el curso amplio del río Pisuerga sobre una llanura de inundación horizontal. Presenta un bosque de galería muy maduro con alamedas blancas que contrastan cromáticamente con el páramo burgalés fronterizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34091','espacio','Valle del río Valderaduey','Relieve alomado arcilloso de la comarca de la Vega-Valdavia donde el río Valderaduey da sus primeros pasos. El cauce está flanqueado por praderas estacionales húmedas y rodales dispersos de chopos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34092','espacio','Azud del Pisuerga / Vega de Lantadilla','Tramo aluvial donde el río Pisuerga ensancha su cauce generando llanuras de sedimentación fértiles. El soto fluvial conserva manchas boscosas de fresnos y sauces que protegen las márgenes de las crecidas invernales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34094','espacio','Valle del río Cueza / Lomas del Camino','Topografía horizontal de suaves ondulaciones arcillosas propia del norte de Tierra de Campos. El arroyo de la Cueza define una vaguada verde estacional de carrizales que rompe la monotonía del paisaje de secano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34903','espacio','Cabecera del río Ucieza / Lomas de la Loma','Terreno ondulado cuarcítico y arcilloso que marca la divisoria de aguas de pequeños arroyos de la comarca. Alberga dehesas aclaradas de encina y quejigos adaptados a los crudos inviernos de la meseta norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90242','espacio','Alto de San Cristóbal / Valle de Ucieza','Pequeño cerro testigo arcilloso que destaca sobre la planicie horizontal de la comarca del Boedo. Las vertientes muestran un modelado por erosión laminar con matorral mediterráneo xerófilo ralo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34098','espacio','Escarpados del Castillo / Ribera del río Pisuerga','Prominente cerro testigo calizo que domina estratégicamente el valle del Pisuerga. El relieve presenta taludes descarnados de yesos y arcillas combinados con un soto aluvial maduro en el fondo de la fosa tectónica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34099','espacio','Riberas del río Carrión / Canal de Castilla','Corredor fluvial aluvial donde el río Carrión discurre paralelo al trazado artificial del Canal de Castilla. El paisaje visual está fuertemente marcado por la densidad del bosque de galería que une ambos cursos de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34100','espacio','Riberas del río Carrión / Vega de Mantinos','Salida del río Carrión de la Montaña Palentina, discurriendo sobre terrazas cuarcíticas escalonadas de cantos rodados. El agua es sumamente limpia y rápida, rodeada de alisos monumentales y saucedas de carácter atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34101','espacio','Arroyo de las Presas / Tierra de Campos','Topografía horizontal extrema arcillosa donde la escorrentía superficial genera pequeños regueros   estacionales. Presenta pastizales secos y un paisaje despejado de horizontes limpios típico de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34102','espacio','Canal de Castilla (Ramal de Campos) / Praderas de Mazariegos','Paisaje llano de Tierra de Campos cruzado por la línea verde del canal artificial. Cuenta con pequeñas cubetas arcillosas inundables en invierno que sustentan comunidades de juncos y plantas palustres especializadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34103','espacio','Río Valdeginate / Lomas de Mazuecos','Cauce fluvial somero y encajonado que discurre sobre arcillas compactas en la llanura cerealista. El relieve es suavemente alomado, desprovisto de masas arbóreas nativas con un perfil estepario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34104','espacio','Ribera del río Pisuerga / Canal de la Margen Izquierda','Llanura de inundación del Pisuerga en el límite con la provincia de Burgos, caracterizada por depósitos de gravas y limos fértiles. El soto de ribera es continuo y denso, compuesto por alamos blancos y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34106','espacio','Arroyo de Anguijón / Llanura esteparia','Extrema llanura arcillosa horizontal de Tierra de Campos meridional. El pequeño arroyo aporta un corredor verde modesto estacional de eneas y juncos que rompe temporalmente el paisaje xerófilo dominante.   Mingo de la Vega (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34108','espacio','Ribera del río Carrión / Cerro de la Cruz','Punto de inflexión geográfica donde el río Carrión abandona la vega alta y se encaja levemente entre cerros testigos calizos. Las vertientes del cerro muestran erosión en cárcavas arcillosas combinadas con un frondoso bosque de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34109','espacio','Valle del río Templarios / Lomas de Moratinos','Relieve suave de lomas arcillosas que define el límite occidental de la provincia con León. El pequeño valle del riachuelo alberga praderas secas y matorrales mediterráneos de resistencia extrema al frío continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34110','espacio','Peña de Mudá / Valle de Mudá / Hayedo secundario','Espectacular mole caliza gris que emerge verticalmente sobre un valle pirenaico de la Montaña Palentina. El relieve presenta lapiaces, simas kársticas y laderas umbrías densamente pobladas por hayas, quejigos y avellanos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34112','espacio','Riberas del río Carrión / Soto del Monasterio (Entorno)','Tramo medio-alto del río Carrión donde el cauce discurre ramificado en una llanura aluvial fértil. El soto de ribera destaca por la madurez y porte de sus alisos, chopos negros y fresnos que forman densas masas de sombra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34113','espacio','Río Boedo / Lomas cuarcíticas de Olea','Valle suave labrado por el río Boedo sobre materiales arcillosos y depósitos de rañas superiores. Las elevaciones circundantes presentan un matorral denso de brezo rubio y quejigos achaparradas adaptados al clima severo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34114','espacio','Valle del río Burejo / Dehesa de Moarves','Hermosa comarca de transición de la Ojeda, caracterizada por valles encajonados sobre calizas y areniscas. Alberga dehesas de robles melojos y quejigares bien conservados, con pequeños arroyos de aguas sumamente limpias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34116','espacio','Riberas del río Pisuerga / Vega de Osornillo','Tramo aluvial donde el río Pisuerga hace frontera con Burgos, discurriendo de forma sinuosa sobre depósitos de gravas. El soto fluvial conserva saucedas maduras y alamedas que estabilizan las terrazas fluviales cuaternarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34901','espacio','Confluencia de los ríos Vallarna y Pisuerga / Páramo de Osorno','Amplia cubeta de sedimentación erosionada donde el modesto río Vallarna entrega sus aguas al Pisuerga al pie de los páramos calizos. Destaca por la anchura de la llanura de inundación y los taludes calcáreos expuestos de la meseta norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','espacio','Monte el Viejo / Riberas del río Carrión / Sotillo de los Canónigos','Gran meseta tabular caliza (Monte el Viejo) que emerge al sur de la capital, mostrando escarpes calcáreos y un denso encinar carrascal autóctono. El río Carrión cruza el término dividiéndose en varios brazos con un bosque de galería muy maduro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34121','espacio','Valle del río Arlanza / Páramo de San Lazaro','Espectacular desfiladero aluvial donde el río Arlanza corta las estructuras calizas del Cerrato palentino antes de unirse al Pisuerga. El relieve presenta farallones de roca caliza grises y un soto de ribera frondoso con sauces monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34123','espacio','Laguna de la Nava (Sector Norte) / Casas del Rey','Extensa llanura arcillosa horizontal de Tierra de Campos que alberga una parte importante del recuperado humedal estepario de la Nava. El paisaje visual es de una horizontalidad absoluta rota por las someras láminas de agua y grandes masas de carrizales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34124','espacio','Valle del arroyo de Payo / Lomas de quejigos','Relieve alomado de la comarca de la Ojeda esculpido sobre areniscas y arcillas. Las vertientes conservan pequeñas manchas boscosas de quejigos y melojos mezcladas con brezales que muestran un marcado carácter de transición montañosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34125','espacio','Arroyo de Pedraza / Llanura esteparia','Paisaje plano arcilloso de Tierra de Campos meridional, caracterizado por una aridez estival extrema. El pequeño riachuelo estacional aporta un modesto corredor de juncos y espadañas sin presencia de arboledas nativas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34904','espacio','Parque Natural Montaña Palentina / Nacedero del río Pisuerga (Cueva del Cobre) / Valle de Redondo','Impresionante circo alpino de alta montaña donde el río Pisuerga surge de una inmensa y profunda cavidad kárstica calcárea. El relieve es totalmente abrupto y salvaje, flanqueado por los mayores hayedos, abedulares y acebedas vírgenes del norte provincial.   Pino de Viduerna (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34132','espacio','Riberas del río Ucieza / Praderas del arroyo de San Juan','Paisaje geomorfológico horizontal caracterizado por terrazas fluviales cuaternarias y depósitos aluviales donde el río Ucieza ensancha su cauce. Ofrece un marcado   contraste cromático estacional gracias a la vegetación palustre que rompe la llanura cerealista de Tierra de Campos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34135','espacio','Monumento Natural de Las Tuerces / Covalagua / Cueva de los Franceses','Espectacular meseta caliza (lora) donde la disolución kárstica y la erosión del viento han esculpido un laberinto de callejones y formas gigantescas de aspecto ruiniforme. Cuenta con profundos cañones donde brotan surgencias cársticas rodeadas de hayedos relictos y vegetación rupícola especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34136','espacio','Vega del río Carrión / Páramo de la Cueza','Relieve de transición entre la llanura de inundación aluvial del Carrión y los escarpes arcillosos de los páramos colindantes. Cuenta con una estrecha banda de sotos de ribera bien conservados y pequeños bosquetes mixtos de quejigo adaptados al suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34137','espacio','Barranco del arroyo de la Cueza','Suave valle de erosión labrado sobre margas y arcillas compactas en el sector centro-occidental de la provincia. La hidrografía estacional genera un relieve de cárcavas y pequeñas lomas coronadas por matorrales xerófilos de baja altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34139','espacio','Valle de la Ojeda / Lomas de San Pedro','Depresión erosiva flanqueada por relieves calizos y areniscas que marcan la entrada a la cuenca prepirenaica. Las laderas de umbría atesoran masas compactas y bien estructuradas de quejigares y encinares mediterráneos que colonizan el suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34140','espacio','Cabecera del río Valdavia / Monte de la Horca','Relieve ondulado sobre depósitos de rañas y cantos rodados que configuran un paisaje de transición montañosa. El curso fluvial está escoltado por un corredor continuo de alisos, sauces y un denso robledal de melojo que tapiza las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34141','espacio','Ribera del río Arlanza / Monte de Valdeladrón','Tramo final del río Arlanza donde se encajona levemente entre terrazas de gravas y terrazas aluviales profundas. Los márgenes fluviales conservan sotos maduros de chopos y álamos blancos, limitando con un denso encinar calcícola de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34143','espacio','Ribera del río Carrión / Vega de Portillejo','Amplia llanura de inundación cuaternaria modelada por la dinámica divagante del río Carrión. Muestra un mosaico visual compuesto por madrejones abandonados, carrizales permanentes y sotos de saucedas que rompen el relieve llano de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34146','espacio','Valle del río Pisuerga / Cuestas de Reinoso','Paisaje típico del Cerrato palentino con lomas y cerros testigo coronados por calizas eocenas sobre bases arcillosas. Las laderas escarpadas presentan una interesante vegetación gipsícola y matorrales mediterráneos que resisten la acusada insolación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34147','espacio','Vega del río Carrión / Dehesa de Renedo','Valle aluvial maduro donde el río Carrión se bifurca en pequeños ramales y canales naturales estacionales. El entorno conserva manchas aisladas de bosque de ribera y pastizales húmedos con alta presencia de avifauna ligada al medio acuático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34149','espacio','Ribera del río Ucieza / Cruce del Canal de Castilla','Llanura sedimentaria donde confluyen las dinámicas fluviales del Ucieza con la infraestructura hidráulica histórica. Destaca por el contraste de las láminas de agua estables y sus densos cinturones de eneas y carrizos frente al paisaje desarbolado circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34151','espacio','Estribaciones de la Sierra de la Peña / Valle de Riosmenudos','Relieve prepirenaico de gran interés geomorfológico, caracterizado por la transición entre los páramos de raña y las grandes moles calizas alpinas. Las umbrías albergan densas masas forestales de robles melojos, quejigos y tejos aislados de gran porte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34155','espacio','Confluencia del río Carrión y río Ucieza / Canal de Castilla (Caldas)','Complejo nudo hidrográfico de llanura aluvial donde el río Carrión recibe aportes fluviales en un entorno de riberas muy anchas. Destaca por la frondosidad de sus alamedas, saucedas maduras y grandes masas de carrizal que sirven de refugio faunístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34156','espacio','Barrancos de la Cueza / Lomas de San Martín','Paisaje erosionado sobre arcillas y areniscas con un relieve modelado por el arroyo de la Cueza en forma de suaves cárcavas. Las laderas expuestas al sur muestran   matorrales xerófilos y tomillares mediterráneos adaptados a la escasez de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','espacio','Ribera del río Carrión / Monte de la Morterona','Gran corredor fluvial donde el Carrión abandona la montaña y deposita grandes masas de gravas, creando islas y meandros. Las vertientes orientadas al norte están densamente pobladas por un robledal de melojo maduro que se extiende por el páramo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34158','espacio','Desfiladero del río Pisuerga / Coto Redondo / Sierra de la Peña','Angosto cañón fluvial labrado por el río Pisuerga al romper las estructuras calizas mesozoicas de la Montaña Palentina. Las escarpadas laderas albergan una frondosa vegetación mixta con robles, quejigos y una densa vegetación de ribera de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34159','espacio','Sotos del río Carrión / Canal de la Margen Izquierda','Tramo bajo de llanura fluvial aluvial caracterizado por meandros abandonados y depósitos de sedimentos finos. Las márgenes del cauce albergan franjas continuas de saucedas y alamedas que configuran un corredor ecológico de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34160','espacio','Valle de Mudá / Senda del Bisonte (Entorno Natural) / Peñas de San Cebrián','Paisaje alpino integrado en la Montaña Palentina, caracterizado por moles calizas escarpadas que emergen entre densos valles forestales. Las umbrías y laderas contienen magníficos bosques mixtos de hayas, robles y acebedas de carácter totalmente salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34161','espacio','Valle del río Boedo','Pequeña cubeta de erosión modelada sobre arcillas cuaternarias donde el río Boedo discurre de forma sinuosa. Presenta un corredor verde estrecho y bien estructurado compuesto por sauces, chopos y abundantes praderas húmedas de fondo de valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34163','espacio','Arroyo de Valdeginate (Curso superior)','Paisaje horizontal de Tierra de Campos con una topografía dominada por suaves ondulaciones arcillosas. La presencia de pequeñas corrientes de agua estacionales permite el crecimiento de espadañas y carrizos aislados en mitad del entorno cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34165','espacio','Ribera del río Cueza / Lomas del Pozo','Depresión aluvial labrada por el río Cueza sobre materiales terciarios degradados de la comarca. Ofrece una perspectiva diáfana de lomas suaves donde la vegetación ripícola se reduce a pequeños núcleos de sauces y chopos negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34167','espacio','Páramo de Torozos / Barranco de Valdecastro','Escarpada fractura orográfica que corta el páramo calizo calcáreo del sur provincial, generando un profundo barranco de vertientes abruptas. Las zonas protegidas de la insolación conservan encinares aclarados mediterráneos y quejigares de gran rusticidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34168','espacio','Riberas del río Boedo / Monte de las Trazas','Relieve alomado que delimita el valle fluvial del Boedo, caracterizado por suelos mixtos de arcilla y cantos rodados. Las laderas albergan brezales secos y pequeñas   manchas boscosas de rebollo que sirven de transición hacia el norte montañoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34171','espacio','Sierra de la Peña / Pico Fraile / Castro de la Peña','Imponente muralla caliza carbonífera que se levanta de forma casi vertical, mostrando impresionantes farallones rocosos y canchales de piedra desnuda. Las faldas montañosas están cubiertas por densos sabinares relictos, hayedos sombríos y acebedas de gran pureza geomorfológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34170','espacio','Cañón del río Bricia / San Andrés de Arroyo (Entorno)','Estrecha hoz fluvial excavada por el río Bricia sobre estratos de piedra caliza mesozoica. El desfiladero presenta paredes verticales con formas de erosión alveolar, albergando en su fondo umbrío una frondosa vegetación de ribera con sauces y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34174','espacio','Ribera del arroyo de la Canal / Cuestas de Santoyo','Topografía de suaves lomas y cerros margosos que limitan con las vegas bajas del río Pisuerga. El relieve presenta pequeñas cárcavas debido a la erosión hídrica, salpicadas por tomillares y matorral mediterráneo adaptado a la aridez esteparia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34175','espacio','Ribera del río Carrión / Vega de Quintanilla','Sector medio del valle del Carrión caracterizado por una llanura aluvial llana con depósitos de gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y álamos forman un denso cinturón vegetal continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34177','espacio','Meandro del río Pisuerga / Soto de la Reva','Gran curva fluvial descrita por el río Pisuerga sobre la llanura aluvial del Cerrato. La margen cóncava presenta pequeños escarpes erosionados, mientras que la llanura de inundación alberga un magnífico bosque de ribera con alamedas y saucedas maduras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34178','espacio','Valle del río San Martín / Robledal de Tabanera','Paisaje quebrado de media montaña en el Cerrato, con profundos valles excavados entre páramos calcáreos. Destaca por albergar una de las manchas forestales de encina y quejigo más densas y mejor conservadas del extremo meridional palentino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34179','espacio','Valle del río Valdavia / Alto de la Varga','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas que drenan hacia la cuenca del Valdavia. El entorno forestal está dominado por extensas masas de roble rebollo adaptadas a suelos ácidos y clima continentalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34181','espacio','Cortados de Tariego / Pico de la Viña / Ribera del Pisuerga','Espectaculares farallones y costras calizas que caen de forma abrupta sobre la vega del río Pisuerga, ofreciendo una sección geológica perfecta del neógeno. Las paredes rocosas sirven de nido a grandes rapaces y presentan comunidades de flora rupícola y yesícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34184','espacio','Cerro de Torremormojón / Páramo de los Torozos','Imponente cerro testigo calizo que emerge de forma aislada en el límite meridional de Tierra de Campos. El relieve presenta una fuerte pendiente erosionada con cárcavas en la base margosa, coronado por una plataforma caliza calcárea de horizontes diáfanos.   Torres de Berandilla • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34185','espacio','Parque Natural Montaña Palentina / Valle de Miranda / Pico Curavacas (Vertiente Sur)','Alta montaña alpina modelada por la erosión glaciar sobre conglomerados oscuros y pizarras carboníferas. Presenta circos glaciares impresionantes, canchales de piedra verticales y lagunas de montaña heladas, rodeadas de pastizales subalpinos y brezales de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34186','espacio','Riberas del río Pisuerga / Monte de San Carlos','Tramo donde el río Pisuerga discurre encajonado entre suaves colinas calizas y terrazas fluviales cuaternarias. Cuenta con un soto de ribera continuo dominado por alisos y sauces negros que aporta un alto valor cromático al entorno forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34192','espacio','Valle del río Ucieza / Robledal de Robladillo','Cuenca fluvial de relieve suave labrada sobre sedimentos terciarios de la zona central palentina. El fondo del valle está ocupado por praderas húmedas estacionales y pequeñas manchas dispersas de robles quejigos y melojos en las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34189','espacio','Valle de Hornillos / Cuestas del Cerrato','Paisaje típico de páramo fragmentado con escarpes calcáreos y profundas vaguadas de erosión hídrica. Las laderas de umbría conservan restos de encinares mediterráneos arbustivos y una notable variedad de plantas aromáticas de alta resistencia a la sequía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34190','espacio','Valle del río Valdavia / Monte de Valderrábano','Relieve ondulado característico de la comarca de la Valdavia, asentado sobre sedimentos sueltos de raña y cantos rodados. Las laderas boscosas albergan un denso rebollar de roble melojo que configura un tapiz vegetal continuo de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34196','espacio','Valle del río Valle / Páramo de las Bodegas','Profundo tajo erosivo labrado sobre la plataforma caliza del Cerrato, dando lugar a un valle encajonado de vertientes empinadas. El relieve muestra canchales de ladera y escarpes rocosos donde proliferan encinas carrascas y matorrales mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34902','espacio','Riberas del río de los Retortillos / Laguna de Carrión (Entorno)','Llanura sedimentaria con suaves depresiones arcillosas que acumulan agua de forma estacional de carácter endorréico. Los cursos fluviales modestos están acompañados por espadañares, juncales y carrizales que rompen la aridez de la meseta cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34199','espacio','Parque Natural Montaña Palentina / Fuentes Tamáricas / Espigüete / Cascada de Mazobre','Impresionante relieve calizo de alta montaña donde destaca la majestuosa pirámide calcárea del pico Espigüete. Alberga la mítica surgencia kárstica intermitente de las Fuentes Tamáricas, profundas gargantas, gargantas de roca y cascadas de aguas de deshielo rodeadas de hayedos puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34023','espacio','Confluencia del río Pisuerga y río Carrión / Soto de la Reva','Amplia llanura aluvial cuaternaria donde confluyen los dos principales ejes fluviales de la provincia. A pesar de la antropización, las márgenes conservan un soto de ribera maduro de gran anchura poblado por álamos blancos, chopos y sauces negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34201','espacio','Páramo de Vertavillo / Valle del arroyo de San Pedro','Relieve de páramos tabulares cortados por valles sinuosos de fuertes pendientes de origen torrencial. Las plataformas calizas superiores muestran un paisaje diáfano que da paso en las laderas a manchas compactas de encinar carrascal y quejigar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34234','espacio','Valle del río Valdavia / Monte de Villasila','Relieve ondulado y suave compuesto por depósitos de rañas arcillo-arenosas con presencia de cantos rodados cuarcíticos. Alberga masas forestales densas de roble rebollo adaptadas al clima continental y pequeños riachuelos estacionales de aguas limpias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34204','espacio','Vereda del arroyo de la Vega','Paisaje completamente horizontal de Tierra de Campos asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales cubiertas de juncos y gramíneas que rompen la llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34205','espacio','Valle de Cerrato / Monte de San Mamés','Paisaje fragmentado de páramos calcáreos con laderas de fuertes pendientes que caen hacia el fondo del valle. Atesora una de las masas forestales más densas de encina carrasca de la comarca, asentada sobre lapiaces y afloramientos calizos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34206','espacio','Riberas del río Sequillo / Balsa de Villada','Llanura aluvial de inundación en el extremo occidental de Tierra de Campos modelada por el río Sequillo. Presenta una pequeña cubeta lagunar naturalizada que sirve de oasis vegetal para eneas, juncos y aves acuáticas en mitad de la estepa cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34208','espacio','Ribera del río Valdavia / Vega de San Martín','Tramo medio del río Valdavia caracterizado por un relieve llano de terrazas fluviales de gravas y arenas. Los márgenes del río cuentan con un corredor continuo de sauces y alisos que contrasta cromáticamente con los campos agrícolas colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34210','espacio','Valle del río Pisuerga / Lomas de Villahán','Topografía de lomas suaves y cerros testigo margosos situados en la margen derecha del valle del Pisuerga. El relieve presenta pequeñas cárcavas de erosión hídrica cubiertas por tomillares, esparteras y matorral mediterráneo adaptado a suelos secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34211','espacio','Arroyo de la Madre / Monte Bajo de Villaherreros','Relieve suave de la meseta central palentina caracterizado por sedimentos arcillosos cuaternarios. Presenta pequeños arroyos temporales acompañados de carrizales aislados y matorral de quejigo muy aclarado debido al secular aprovechamiento agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34213','espacio','Ribera del río Pisuerga / Cuestas de Villalaco','Imponentes escarpes calizos y cuestas que caen de forma directa sobre la llanura de inundación del río Pisuerga. Las laderas de fuerte pendiente muestran estratos sedimentarios expuestos y albergan manchas dispersas de encinar mediterráneo termo-atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34214','espacio','Riberas del río Carrión / Monte de la Dehesa','Zona de transición de la Montaña Palentina donde el río Carrión discurre encajonado entre terrazas fluviales pedregosas. Las faldas montañosas están cubiertas por densos bosques mixtos de roble rebollo y pinos silvestres que tapizan el relieve quebrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34215','espacio','Arroyo de Villamil / Páramo de Sirga','Topografía monótona y horizontal sobre arcillas cuaternarias rota únicamente por la incisión de arroyos estacionales. Estos pequeños cauces acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34218','espacio','Vega del río Carrión / Sotos de Villaluenga','Amplio valle aluvial maduro labrado por la dinámica fluvial del río Carrión sobre gravas y limos. El cauce mantiene un corredor forestal denso de alisos, chopos y sauces que forma un cinturón vegetal continuo de alto valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34220','espacio','Laguna de la Nava (Sector Occidental) / Autillo','Gran llanura endorreica arcillosa que alberga los restos recuperados del histórico "Mar de Campos". El humedal estacional genera una inmensa lámina de agua rodeada de kilométricos carrizares y comunidades palustres de excepcional valor ecológico y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34221','espacio','Páramo de Villamediana / Barranco de Valdebeón','Relieve quebrado del Cerrato caracterizado por una extensa plataforma caliza cortada por barrancos de vertientes abruptas. Las umbrías protegidas albergan   encinares carrascales densos y formaciones arbustivas de quejigo adaptadas al suelo calcáreo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34222','espacio','Valle del río Boedo / Monte de Villameriel','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas cuarcíticas que drenan hacia la cuenca del Boedo. La cubierta forestal está dominada por masas densas de roble rebollo adaptadas al riguroso clima continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34225','espacio','Ribera del río Carrión / Soto de la Central / Canal de Castilla','Tramo final del río Carrión antes de su desembocadura, donde se ensancha generando una amplia llanura aluvial. Los márgenes conservan sotos maduros de álamos y sauces que interactúan visualmente con el ramal sur del Canal de Castilla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34224','espacio','Curso del arroyo de la Cueza','Paisaje completamente horizontal de Tierra de Campos asentado sobre arcillas y limos terciarios. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales cubiertas de juncos que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34227','espacio','Arroyo de la Madre / Lomas de Rebollar','Topografía de lomas suaves arcillosas degradadas situadas en la comarca de Tierra de Campos. Presenta pequeños riachuelos estacionales acompañados de carrizales aislados y restos de matorral de quejigo muy aclarado debido a la secular explotación agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34228','espacio','Ribera del río Valdavia / Alto de la Horca','Relieve ondulado característico de la comarca de la Valdavia, asentado sobre sedimentos sueltos de raña y cantos rodados. Las laderas boscosas albergan un denso rebollar de roble melojo que configura un tapiz vegetal continuo de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34229','espacio','Valle del río Boedo / Cuestas de Villaprovedo','Pequeña cubeta de erosión modelada sobre arcillas cuaternarias donde el río Boedo discurre de forma sinuosa. Presenta un corredor verde estrecho y bien estructurado compuesto por sauces, chopos y abundantes praderas húmedas de fondo de valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34232','espacio','Humedal de la Dehesa / Arroyo de la Vega','Llanura sedimentaria con suaves depresiones arcillosas que acumulan agua de forma estacional de carácter endorréico. Los cursos fluviales modestos están acompañados por espadañares, juncales y carrizales que rompen la aridez de la meseta cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34233','espacio','Ribera del río Ucieza / Páramo de Villasarracino','Valle aluvial de relieve suave labrada sobre sedimentos terciarios de la zona central palentina. El fondo del valle está ocupado por praderas húmedas estacionales y pequeñas manchas dispersas de robles quejigos y melojos en las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34236','espacio','Arroyo de la Gañinas / Lomas de Villaturde','Topografía monótona y horizontal sobre arcillas cuaternarias rota únicamente por la incisión de arroyos estacionales. Estos pequeños cauces acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34238','espacio','Páramo de Villaviudas / Valle del arroyo de San Pedro','Relieve de páramos tabulares cortados por valles sinuosos de fuertes pendientes de origen torrencial. Las plataformas calizas superiores muestran un paisaje diáfano que da paso en las laderas a manchas compactas de encinar carrascal y quejigar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34243','espacio','Riberas del río Carrión / Soto de la Isla','Tramo medio del río Carrión caracterizado por una llanura aluvial llana con depósitos de gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y álamos forman un denso cinturón vegetal continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34245','espacio','Páramo de Guardo / Nacimiento del río Ucieza','Altiplanicie pedregosa formada por grandes depósitos de rañas cuarcíticas procedentes de la Cordillera Cantábrica. El relieve es marcadamente horizontal, albergando el origen de modestas redes fluviales que nacen en pequeñas vaguadas cubiertas de brezo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34246','espacio','Ribera del río Ucieza','Cuenca fluvial de relieve suave labrada sobre sedimentos terciarios de la zona central palentina. El fondo del valle está ocupado por praderas húmedas estacionales y pequeñas manchas dispersas de robles quejigos en las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90626','espacio','Parque Natural de Tamadaba / Risco Faneque / Valle de Agaete','Impresionante macizo basáltico costero que alberga uno de los pinares canarios nativos más puros de Gran Canaria. El relieve se desploma verticalmente hacia el océano Atlántico en el Risco Faneque, considerado uno de los acantilados marinos más altos del mundo con más de mil metros de caída casi absoluta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90627','espacio','Monumento Natural del Barranco de Guayadeque','Colosal incisión lítica de origen erosivo y volcánico que separa los municipios de Agüimes e Ingenio. Sus escarpadas vertientes caleras albergan una altísima concentración de flora endémica macaronésica rupícola y   espectaculares oquedades naturales colgadas en paredes verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25001','espacio','Monumento Natural de la Caldera de Gairía / Malpaís de Chico','Cono volcánico de emisión reciente que emerge de forma simétrica en la llanura central de Fuerteventura. El relieve destaca por su perfecta morfología cratérica y las coladas de lava basáltica rugosa (malpaís) que lo circundan, colonizadas de forma exclusiva por líquenes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90628','espacio','Marina de Arrecife / Islote de Fermina','Formación arrecifal y lenguas de lava basáltica que interactúan directamente con las corrientes del océano en Lanzarote. Configura un relieve costero bajo de arrecifes, canales someros de agua cristalina y entrantes intermareales de alto valor geológico marino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25002','espacio','Paisaje Protegido de las Cumbres / Caldera de Tejeda / Pinar de Tamadaba','Escenografía geológica colosal caracterizada por una inmensa caldera de colapso volcánico con paredes que superan los ochocientos metros de desnivel. El relieve muestra agujas monolíticas desnudas y profundas gargantas labradas por el agua bajo la umbría de pinos canarios ancestrales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25003','espacio','Montaña de Arucas / Laderas lávicas de San Andrés','Domo volcánico de tipo fonolítico perfectamente individualizado que domina la rampa norte de Gran Canaria. Sus laderas muestran el flujo de coladas antiguas fuertemente meteorizadas que mueren en una costa rocosa batida por el mar de forma constante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25004','espacio','Parque Rural de Betancuria / Macizo de Betancuria','Relieve correspondiente al Complejo Basal de Fuerteventura, material geológico más antiguo del archipiélago expuesto por la erosión extrema. Presenta un paisaje de lomas desnudas, crestas afiladas y barrancos profundos de tonalidades cromáticas ocres y verdosas únicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90643','espacio','Parque Rural de Doramas / Barranco de Azuaje','Profunda y angosta garganta excavada por la erosión fluvial en el norte de Gran Canaria. El relieve destaca por sus paredes verticales cubiertas de una exuberante vegetación relicta de laurisilva macaronésica, alimentada por constantes surgencias de agua subterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25005','espacio','Monumento Natural de Amagro / Caldera de los Pinos de Gáldar','Imponente macizo basáltico aislado que emerge de forma abrupta junto a la costa norteña, mostrando crestas   afiladas de gran fuerza visual. En las cumbres destaca una alineación de cráteres volcánicos cubiertos de pino canario que contrastan con la aridez del relieve circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90629','espacio','Monumento Natural del Volcán de la Corona / Acantilado de Famara','Colosal cono volcánico cuyo colapso dio origen a un espectacular tubo lávico subterráneo de varios kilómetros de longitud. El relieve culmina en el imponente risco de Famara, una pared vertical caliza y basáltica que se desploma seiscientos metros sobre el océano Atlántico en Lanzarote.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35011','espacio','Barranco de Guayadeque (Vertiente Norte) / Caldera de los Marteles','Margen septentrional de una de las mayores incisiones erosivas del archipiélago, caracterizada por imponentes farallones rocosos. La cabecera limita con una gran caldera de colapso de morfología circular perfecta con paredes cubiertas de matorral endémico canario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35012','espacio','Monumento Natural de los Azulejos de Veneguera / Barranco de Mogán','Formación geológica espectacular donde las alternancias de coladas volcánicas y procesos hidrotermales han teñido las laderas de llamativos tonos verdes, azules y ocres. El relieve se prolonga en barrancos rectilíneos encajonados que vierten hacia un litoral de acantilados abruptos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35013','espacio','Reserva Natural Especial de Los Tilos de Moya / Barranco de Moya','Uno de los últimos reductos puros de laurisilva canaria, asentado sobre el fondo y los escarpes de una profunda incisión fluvial. El entorno presenta un relieve   quebrado y sombrío con una altísima densidad de humedad botánica y grandes formaciones de helechos gigantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35015','espacio','Parque Natural de Jandía / Monumento Natural de Ajuy','Impresionante macizo montañoso que conforma una península de crestas afiladas y escarpes salvajes azotados por el mar. En Ajuy destaca el afloramiento de las coladas más antiguas del archipiélago y cuevas marinas colosales labradas directamente sobre calizas oceánicas y sedimentos fósiles del cretácico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35017','espacio','Parque Rural de Betancuria (Sector Norte) / Barranco de los Molinos','Cauce fluvial encajonado de carácter desértico que rasga la penillanura basáltica de Fuerteventura, albergando una pequeña corriente de agua permanente. El relieve costero destaca por la erosión de coladas lávicas negras que contrastan con los tonos ocres del interior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35018','espacio','Paisaje Protegido de La Geria (Sector Oriental)','Paisaje geomorfológico único condicionado por la acumulación masiva de piroclastos negros (lapilli) procedentes de erupciones históricas. El relieve está modelado por dunas de arena negra que recubren los flancos de conos volcánicos perfectamente suavizados por la erosión del viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','espacio','Reserva Natural Especial de las Dunas de Maspalomas / Caldera de Tirajana / Risco Blanco','Impresionante campo de dunas de arena orgánica viva en constante movimiento que interactúa directamente con el litoral marino. Hacia el interior, el municipio se quiebra en la inmensa caldera tectónica de   Tirajana, dominada por el imponente pitón fonolítico de Risco Blanco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','espacio','Monumento Natural de la Bandama (Caldera y Pico de Bandama)','Impresionante caldera volcánica de explosión freatomagmática con un diámetro de un kilómetro y más de doscientos metros de profundidad perfecta. El fondo de la cubeta alberga un frondoso bosque termófilo canario aislado que conforma un ecosistema visualmente sobrecogedor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35022','espacio','Caldera de Tirajana / Guriete / Palmeral de Sorrueda','Paisaje abrupto caracterizado por imponentes crestas basálticas y gargantas rocosas donde la erosión ha esculpido formas caprichosas. El fondo del cauce alberga una gran masa de agua embalsada rodeada por uno de los palmerales de Phoenix canariensis más densos y puros de la isla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35023','espacio','Paisaje Protegido de las Cumbres (Guía) / Barranco de Moya (Vertiente Occidental)','Laderas septentrionales de fuerte gradiente orográfico modeladas sobre materiales volcánicos antiguos fuertemente meteorizados. Las umbrías altas conservan brezales y restos de monteverde que tapizan un relieve quebrado por pequeñas cascadas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','espacio','Parque Natural del Archipiélago Chinijo / Risco de Famara / Isla de La Graciosa','Impresionante alineación de acantilados costeros que se desploman verticalmente más de seiscientos metros sobre el brazo de mar del Río en Lanzarote. Frente al risco emerge el paisaje llano y desértico de La Graciosa, salpicado por conos volcánicos de tonos rojizos puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35025','espacio','Monumento Natural del Roque Nublo / Roque Bentayga / Caldera de Tejeda','Uno de los paisajes geológicos más sobrecogedores del mundo, formado por el colapso de un gran estratovolcán. El relieve está presidido por gigantescos pitones monolíticos de erosión de naturaleza fonolítica que emergen de forma vertical sobre un laberinto de barrancos colosales desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35026','espacio','Paisaje Protegido de Lomo Magullo / Barranco de los Cernícalos','Estrecho desfiladero basáltico que alberga una de las pocas corrientes fluviales continuas de Gran Canaria durante todo el año. El relieve presenta saltos de agua sucesivos encajados en la roca, flanqueados por una densa sauceda y palmerales nativos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','espacio','Espacio Protegido de Pino Santo / Barranco de Teror','Relieve de medianías caracterizado por una compleja red de lomas verdes y barrancos sinuosos de origen erosivo. Las laderas de umbría albergan excelentes representaciones de bosque termófilo y grandes ejemplares de acebuches asentados sobre suelos volcánicos fértiles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35028','espacio','Paisaje Protegido de La Geria / Montaña de Gaida','Vertiente sur del gran manto de cenizas volcánicas negras de Lanzarote, flanqueada por las elevaciones de conos de piroclastos. El relieve muestra la rugosidad extrema de las coladas de lava basáltica que descienden de manera suave hacia el litoral meridional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35029','espacio','Parque Nacional de Timanfaya / Parque Natural de Los Volcanes / Caldera Blanca','Espectacular y dantesco campo de lavas basálticas inalteradas surgidas durante las erupciones históricas, que configuran un paisaje de aspecto puramente lunar. Destaca Caldera Blanca, un cráter prehistórico gigante de proporciones perfectas que emerge indemne entre el malpaís negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35030','espacio','Paisaje Protegido de Malpaís Grande / Cuchillos de Vigán','Relieve desértico caracterizado por "cuchillos", que son imponentes alineaciones montañosas alargadas y afiladas separadas por amplios valles planos de erosión. A sus pies se extiende un inmenso campo de lavas basálticas negras y rugosas de gran pureza estructural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35031','espacio','Reserva Natural Especial de Los Marteles / Caldera de Tenteniguada','Impresionante anfiteatro semicircular de origen erosivo flanqueado por imponentes roques y pitones fonolíticos verticales. El relieve muestra escarpes abruptos donde la humedad de las cumbres permite el desarrollo de una densa flora arbustiva endémica de gran vistosidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35032','espacio','Parque Rural de Doramas (Valleseco) / Barranco de la Virgen','Cuenca alta de un valle profundamente encajonado que destaca por su orientación norteña y alta captación de nieblas. El relieve alomado está completamente cubierto de un tapiz verde húmedo compuesto por helechales, restos de laurisilva y centenarios castañares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','espacio','Parque Nacional de Timanfaya (Sector Sur) / Monumento Natural de Los Ajaches / Charco de los Clicos','Paisaje de vulcanismo extremo con campos de lava cordada y conos de escorias multicolores. En el litoral   destaca el Charco de los Clicos, una espectacular laguna costera de aguas de color verde esmeralda intenso debido a algas endémicas, encajada en un cráter parcialmente colapsado por el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36020','espacio','Sobreiral do Arnego / Cañón del río Ulla','Impresionante bosque relicto de alcornoques de carácter mediterráneo-atlántico que coloniza las laderas escarpadas del río Arnego. El relieve es quebrado, labrado sobre materiales esquistosos que caen de manera abrupta hacia el encuentro con el gran cauce del río Ulla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90533','espacio','Pesqueiras del río Miño / Desembocadura del río Deva','Tramo fronterizo donde el río Miño fluye encajonado entre grandes afloramientos graníticos y bloques de piedra erosionados. El relieve fluvial está marcado por canales rocosos estrechos y rápidos de agua, flanqueados por sotos aluviales y densas masas de helechales subatlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','espacio','Costa de Silleiro / Acantilados del faro','Litoral rocoso y agreste expuesto al oleaje directo del océano Atlántico, caracterizado por una plataforma de abrasión marina. Destaca por sus escarpes graníticos oscuros de perfiles afilados y la total ausencia de playas de   arena, configurando un paisaje costero puramente contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','espacio','Fervenzas del río Barosa / Parque de la Naturaleza de Segade','Espectacular sucesión de saltos de agua y cascadas que salvan un desnivel geológico abrupto sobre un lecho de roca granítica pulida. El entorno conforma una garganta sombría con una elevada humedad constante, tapizada por musgos, helechos reales y alisos centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36003','espacio','Parque Nacional de las Islas Atlánticas (Isla de Ons) / Cabo Udra','Relieve insular granítico con una vertiente occidental extremadamente abrupta que se desploma en acantilados verticales calados por cuevas marinas (furnas). En el continente, Cabo Udra ofrece un paisaje de penedos graníticos gigantescos moldeados por la erosión eólica e hidrodinámica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90534','espacio','Fervenza de Segade / Riberas del río Umia','Tramo donde el río Umia se encajona en un lecho pedregoso generando rápidos, pozas profundas y un salto de agua sobre fractura tectónica. La densa vegetación de ribera gallega forma un túnel forestal cerrado de alisos y robles de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','espacio','Complejo Intermareal Umia-Grove (Sector Oriental) / Marismas de Tragove','Extensa llanura fangosa de carácter estuarino modelada por las oscilaciones de las mareas en la desembocadura del río Umia. El paisaje visual destaca por la horizontalidad de sus canales someros, juncales halófilos y bancos de arena que cambian de fisonomía por horas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90535','espacio','Valle del río Lérez / Penedos de Praderrei','Relieve colinado de naturaleza granítica que encajona el curso medio del río Lérez, formando pequeños cañones sombríos. Las laderas expuestas muestran imponentes bloques rocosos redondeados por la meteorización, rodeados de brezales y robledales jóvenes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','espacio','Costa de la Vela / Acantilados de Donón / Cabo Home','Impresionante fachada litoral que se levanta de forma vertical más de ciento cincuenta metros sobre el océano Atlántico, marcando la entrada a la ría de Vigo. Las paredes de roca desnuda sufren la erosión marina extrema, flanqueadas por dunas colgadas de alto valor geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90536','espacio','Desembocadura del río Ulla / Marismas de Catoira','Punto estratégico de transición geomorfológica donde el río Ulla se funde con la ría de Arousa creando un laberinto de islas fluviales arcillosas. El relieve está dominado por llanuras de inundación cubiertas de extensos carrizales y espadañares de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','espacio','Serra do Cando / Fervenzas de Antas / Baños de San Xusto','Territorio montañoso quebrado por la fractura del bloque granítico gallego, dando lugar a profundas   gargantas y saltos de agua cristalina. Alberga magníficas manchas de bosque atlántico mixto con robles, castaños e importantes masas de helechos en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90537','espacio','Serra do Suído / Nacimiento del río Tea / Turberas de Fonte Uceira','Altiplanicie alpina caracterizada por un paisaje desarbolado de horizontes diáfanos, grandes canchales y turberas húmedas higrófilas de excepcional valor ecológico. Los riachuelos torrenciales descienden por las laderas graníticas formando cascadas encajonadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90538','espacio','Encoro de Frieira / Cañón del río Miño (Sector Oriental)','Grandes vertientes escarpadas y laderas de fuertes pendientes que caen directamente sobre el cauce embalsado del río Miño. La orientación orográfica permite la coexistencia de robledales atlánticos con alcornoques y madroños de afinidad mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90539','espacio','Valle del río Gallo / Castro de Castrolandín (Entorno forestal)','Depresión tectónica rodeada de colinas graníticas cubiertas por masas forestales caducifolias bien conservadas. El río Gallo fluye de forma sinuosa por el fondo aluvial, dejando terrazas de sedimentos y franjas continuas de saucedas y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90540','espacio','Monte de San Domingos / Nacimiento del río Asneiro','Paisaje de media montaña dominado por una penillanura granítica con cumbres redondeadas y lomas cubiertas de brezales y matorral atlántico húmedo. Las pequeñas vaguadas albergan el nacimiento de arroyos que dan lugar a praderas higrófilas y zonas de turbera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36017','espacio','Sobreiral de Valiñas / Riberas del río Ulla','Alberga una de las formaciones de alcornoques más septentrionales y mejor conservadas de Galicia, adaptada a un microclima particular en las laderas del río Ulla. El cauce fluvial presenta tramos encajonados de gran fuerza escénica con sotos de alisos y rápidos rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36018','espacio','Serra do Candán / Nacimiento del río Lérez','Espacio natural protegido caracterizado por crestas graníticas, grandes canchales y una red de riachuelos torrenciales de aguas extremadamente puras. La vegetación está compuesta por extensos brezales húmedos, abedulares y carballeiras maduras en las laderas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36019','espacio','Serra do Suído / Fervenza de Casariños','Entorno abrupto de alta pluviosidad donde el relieve granítico se fractura en cañones profundos y paredones desnudas. Destaca el doble salto de agua de Casariños, encajonado entre una vegetación exhuberante de ribera con helechos gigantes y musgos permanentes.   Agolada • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36021','espacio','Serra da Groba / Cuenca del río Miñor','Macizo granítico costero que ofrece perfiles alomados y una red de barrancos interiores donde nacen numerosos arroyos. Las laderas están cubiertas por matorrales xerófilos y dehesas de robles que dan paso a sotos fluviales bien estructurados en las zonas bajas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36009','espacio','Complejo Intermareal Umia-Grove / Con Negro','Antigua isla unida al continente por un istmo arenoso, cuyo extremo occidental (Con Negro) presenta un litoral de bloques graníticos caóticos esculpidos por la erosión   marina. La zona intermareal conforma una inmensa llanura de fangos y algas de alta productividad biológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36901','espacio','Parque Natural de Carreirón','Espacio insular granítico caracterizado por un relieve costero bajo fuertemente erosionado por las mareas. Destaca por sus complejos dunares fósiles, marismas interiores y formaciones de penedos rocosos redondeados que emergen directamente de las aguas de la ría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36024','espacio','Fraga de Catasós / Valle del río Deza','Monumento natural que alberga un bosque mixto de robles y castaños con algunos de los ejemplares más altos de Europa. El relieve alomado del interior pontevedrés está surcado por el río Deza, que labra valles fluviales de gran frondosidad botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36007','espacio','Cabo Udra (Sector Oriental) / Lago de Castiñeiras (Entorno natural)','Litoral escarpado de la ría de Pontevedra que da paso hacia el interior a una elevación montañosa donde se asienta una laguna naturalizada. El entorno forestal combina arroyos encajonados entre laderas graníticas con vegetación arbustiva atlántica húmeda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36027','espacio','Valle de Salnés / Riberas del río Da Chanca','Topografía de lomas suaves y llanuras aluviales de sedimentación fina en el corazón de las Rías Baixas. El curso del río Da Chanca aporta una franja estrecha pero continua de vegetación ripícola con sauces y alisos que rompe el mosaico agrícola de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','espacio','Monte da Escusa / Nacimiento del río Armenteira','Elevación granítica que constituye el techo de la comarca del Salnés, ofreciendo laderas de fuerte pendiente cubiertas de brezales. En sus laderas nace el río Armenteira, que excava un pequeño cañón sombrío poblado por un denso bosque de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','espacio','Fraga de Moaña / Monte Faro Domaio','Vertiente montañosa granítica de fuertes desniveles que cae directamente sobre la ría de Vigo. La umbría del monte Faro alberga un denso bosque atlántico autóctono (fraga) surcado por riachuelos rápidos que forman pequeñas cascadas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','espacio','Riberas del río Tea / Pasos de Totó','Corredor fluvial encajonado de gran pureza geomorfológica sobre el sustrato granítico del sur de la provincia. El río Tea discurre entre grandes bolos de roca y playas fluviales de gravas, rodeado de un denso bosque de alisos y robles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36031','espacio','Surgencias del río Tea','Pequeño enclave geográfico asentado en una fractura tectónica profunda por donde emergen aguas mineromedicinales. El relieve está definido por el cauce encajonado del río Tea y una densa vegetación de ribera que aporta una alta frescura visual al entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36032','espacio','Valle del río Gato / Dehesas de Amil','Relieve colinado de transición caracterizado por pequeños valles de erosión labrados sobre materiales graníticos meteorizados. Las zonas de ladera conservan manchas de carballeiras jóvenes y sotos de castaños integrados en la dinámica húmeda regional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36033','espacio','Valle del río Louro / Lomas de Guizán','Depresión tectónica alargada por donde discurre el río Louro entre depósitos cuaternarios de arenas y arcillas. Las elevaciones laterales presentan una topografía suave de colinas cubiertas por pinos y parches aislados de vegetación atlántica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','espacio','Cañón del río Miño / Riberas del río Termes','Vertiente escarpada que desciende de manera abrupta hacia el curso internacional del río Miño. Las laderas presentan afloramientos de roca desnuda y pequeñas canales erosionadas donde se refugian alcornoques mediterráneos y robles atlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','espacio','Estuario del río Miñor / Monte de Monteferro','Impresionante península granítica que se adentra en el océano protegiendo la desembocadura del río Miñor. El relieve costero de Monteferro muestra acantilados bajos batidos por el mar, contrastando con las marismas fangosas del estuario interior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36010','espacio','Costa de Oia / Pozas de Mougás','Litoral rocoso rectilíneo de una enorme crudeza visual, donde la sierra de la Groba se desploma casi directamente en el océano. En los valles transversales, los arroyos de montaña excavan pozas naturales y cascadas en la roca granítica desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','espacio','Serra do Galleiro / Barranco del río Moscoso','Relieve quebrado dominado por la imponente presencia granítica de la sierra del Galleiro, con laderas desnudas azotadas por el viento. Las vaguadas sombrías albergan arroyos torrenciales rodeados por carballeiras bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','espacio','Monte Castrove / Litorales rocosos de Raxó','Ladera granítica de gran pendiente que domina la margen norte de la ría de Pontevedra. El relieve asciende rápidamente hacia el macizo de Castrove, mostrando una alternancia de escarpes de roca y pequeños barrancos con vegetación arbustiva húmeda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90848','espacio','Cañón del río Verdugo / Pasos de Mirón','Tramo fluvial encajonado de gran belleza plástica, donde el río Verdugo discurre encajado entre escarpes graníticos y grandes bloques de piedra. El entorno conserva una excelente representación de bosque atlántico gallego hiperhúmedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90849','espacio','Río Tea / Coto da Bouza','Amplio valle fluvial modelado por la dinámica del río Tea en su tramo medio, caracterizado por islas fluviales y depósitos de gravas. Las elevaciones circundantes presentan lapiaces y penedos graníticos cubiertos de matorral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','espacio','Marismas del Alba / Ensenada de San Simón (Sector Norte)','Extenso humedal intermareal situado en la desembocadura del río Lérez, constituido por llanuras salinas y canales de marea. Ofrece un paisaje horizontal dominado por vegetación halófila de juncos y eneas de un alto interés contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','espacio','Gándaras de Budiño','Zona de llanura aluvial y humedal interior originada por una fosa tectónica donde el río Louro remansa sus aguas. El espacio presenta un complejo sistema de   lagunas, turberas y densos sotos de ribera que albergan una flora palustre relicta única en la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','espacio','Confluencia del río Umia y río Chaín','Paisaje llano de modelado aluvial correspondiente al tramo bajo de la cuenca del Umia. Destaca por el desarrollo de amplias llanuras de inundación protegidas por un cinturón boscoso de sauces, alisos y chopos de gran densidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','espacio','Ensenada de San Simón / Estrecho de Rande','Espacio costero semicerrado de aguas tranquilas que conforma el fondo de la ría de Vigo, delimitado por el angosto estrecho de Rande. El relieve combina ensenadas fangosas intermareales con laderas graníticas que caen abruptamente al mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','espacio','Riberas del río Umia / Sotos de Barrantes','Tramo aluvial maduro donde el río Umia dibuja meandros suaves sobre la llanura de sedimentación de la comarca. El cauce mantiene un corredor forestal denso e ininterrumpido de alisos que aporta frescura y contraste visual al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','espacio','Serra do Faro (Vertiente Occidental) / Río Arnego','Alineación montañosa que marca el límite geográfico oriental de la provincia, con cumbres aplanadas cubiertas de brezales alpinos. El curso alto del río Arnego fluye por valles estrechos rodeados de pastizales húmedos y pequeños robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','espacio','Desembocadura del río Miño / Monte Santa Trega (Ladera Norte)','Espectacular estuario fluvial donde el río Miño se ensancha hasta alcanzar varios kilómetros de anchura antes de verter sus aguas al océano. El paisaje muestra un mosaico de islas de arena (esteiros), cañaverales y sotos de ribera bajo imponentes relieves graníticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36049','espacio','Valle del río Caselas / Lomas de San Jorge','Topografía de colinas suaves y pequeños valles aluviales de naturaleza granítica y arcillosa. El río Caselas vertebra el territorio con una franja modesta de vegetación riparia común rodeada de paisajes forestales antropizados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36050','espacio','Riberas del río Miño / Desembocadura del río Mendo','Amplio corredor fluvial fronterizo caracterizado por playas de cantos rodados, islas fluviales y llanuras de inundación periódica. La vegetación de ribera está muy desarrollada con alisos, sauces negros y abundantes cañaverales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','espacio','Complejo Intermareal Umia-Grove (Sector Sur) / Punta Faxilda','Tramo costero donde destaca Punta Faxilda, un saliente rocoso granítico de formas afiladas expuesto a la dinámica del mar abierto de la ría de Pontevedra. El relieve costero es abrupto y contrasta con las zonas de marisma baja del sector intermareal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','espacio','Fervenza do Toxa / Cañón del río Deza','Impresionante salto de agua que, con más de treinta metros de caída vertical sobre una fractura granítica, está considerado uno de los más altos de Galicia. La cascada está encajada en una garganta profunda y umbría cubierta por una densa fraga atlántica virgen.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90541','espacio','Confluencia del río Verdugo y río Oitavén','Espectacular encuentro de caudales fluviales encajados en un profundo tajo granítico rodeado de laderas de fuertes pendientes. El paisaje visual es de una gran potencia gracias a los rápidos de agua, grandes bloques rocosos y un bosque caducifolio muy cerrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36054','espacio','Espacio Natural del Baixo Miño / Goian (Riberas)','Llanura aluvial baja situada en el margen derecho del tramo final del río Miño. El relieve es marcadamente horizontal con depósitos sedimentarios finos, destacando visualmente por sus extensos carrizales, islas fluviales de arenas y sotos de ribera maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36014','espacio','Parque Natural del Monte Aloia','Imponente atalaya granítica aislada que emerge en el bajo Miño, caracterizada por un relieve abrupto de canchales, grandes rocas moldeadas y barrancos profundos. Presenta una frondosa cubierta forestal con una rica biodiversidad de helechales de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36056','espacio','Fervenzas de Parafita / Riberas del río Valga','Pequeña incisión fluvial sobre roca granítica donde el río Valga salva varios desniveles tectónicos formando cascadas sucesivas y pozas de aguas cristalinas. El entorno está cubierto por un espeso dosel forestal de alisos y robles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36015','espacio','Parque Nacional de las Islas Atlánticas (Islas Cíes)','Archipiélago granítico de valor paisajístico excepcional, cuya fachada occidental atlántica está constituida por impresionantes acantilados verticales de más de cien metros esculpidos por furnas marinas. Un relieve abrupto, salvaje y puramente contemplativo que cierra la ría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36059','espacio','Cañón del río Ulla / Islas de Gres','Tramo donde el río Ulla discurre fuertemente encajonado entre paredes de roca esquistosa y granítica, formando rápidos y un conjunto singular de islas fluviales interiores unidas de forma natural por un denso dosel de alisos centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36058','espacio','Salinas de Ulló / Ensenada de San Simón (Sector Sur)','Humedal costero de origen intermareal donde las antiguas estructuras salineras abandonadas han creado un complejo lagunar naturalizado. El relieve es de llanuras de fango y canales someros que albergan densas praderas de vegetación halófila palustre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','espacio','Monte Xiabre / Riberas del río Con','Macizo granítico que domina la entrada a la ría de Arousa, caracterizado por cumbres elevadas azotadas por el viento y laderas cubiertas de brezales. Sus estribaciones bajas albergan valles de erosión fluvial con sotos de ribera bien estructurados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36061','espacio','Litoral de As Sinas / Marismas de Fianteira','Costa baja de carácter arenoso y fangoso orientada hacia el interior de la ría de Arousa, modelada por la dinámica de las mareas. Cuenta con pequeñas lagunas costeras estacionales y zonas de juncales halófilos de gran valor estético natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90673','espacio','Sierra de Cantabria (Faldas meridionales) / Barranco de San Juan','Imponente transición orográfica donde los escarpes calizos de la sierra de Cantabria dominan el relieve de suaves terrazas areniscas del valle del Ebro. Las vaguadas albergan pequeñas masas de encinar mediterráneo y quejigar que colonizan los suelos pedregosos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90265','espacio','Confluencia de los ríos Leza y Ebro','Amplia llanura aluvial y de inundación donde el río Leza vierte sus aguas arcillosas en el cauce maduro del Ebro. Los márgenes conservan sotos ripícolas bien estructurados con álamos blancos, chopos negros y grandes extensiones de carrizales estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90266','espacio','Cañón del río Alhama / Las Inviernas','Profunda garganta esculpida por la acción erosiva del río Alhama sobre calizas y yesos mesozoicos, generando farallones verticales de tonos rojizos y grises. Las paredes rocosas sirven de asentamiento a importantes colonias de aves rapaces y flora rupícola adaptada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90267','espacio','Peña de Albelda / Sotos del río Iregua','Espectacular muralla natural de conglomerados oligocenos fracturados que se levanta de forma vertical sobre   la cuenca del Iregua. El pie de monte conecta con una llanura fluvial protegida por densos cinturones de sauces y alisedas maduras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90268','espacio','Valle bajo del río Iregua / Terrazas fluviales de Lardero','Topografía horizontal de terrazas aluviales cuaternarias compuestas por gravas y cantos rodados finos. Ofrece un paisaje abierto donde el curso del río Iregua aporta una franja estrecha pero continua de vegetación de ribera y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90924','espacio','Valle del río Tuerto / Lomas de San Lorenzo','Relieve ondulado sobre arcillas terciarias degradadas de la Rioja Alta, esculpido por arroyos modestos. Los fondos de valle acumulan humedad suficiente para albergar pequeñas saucedas y carrizales que rompen la homogeneidad del paisaje agrario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90925','espacio','Riberas del río Yalde','Suave llanura sedimentaria donde el río Yalde suaviza su curso sobre depósitos aluviales finos. Presenta un corredor verde estrecho compuesto por sauces y chopos dispersos, con lomas marginales de margas y areniscas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90269','espacio','Reserva Natural de los Sotos de Alfaro','Uno de los ecosistemas de ribera más importantes de la cuenca del Ebro, caracterizado por una densa red de meandros, islas fluviales (mugas) y madrejones. Alberga un espectacular y frondoso bosque aluvial de sauces, chopos blancos, fresnos y extensos cañaverales salvajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90926','espacio','Sierra de Cameros / Barranco de San Juan / Monte de Santiago','Relieve de media montaña con vertientes abruptas y barrancos sinuosos que drenan hacia la cuenca del Iregua. Las laderas orientadas a la umbría atesoran masas compactas de robledal de melojo y rebollos, combinadas con afloramientos calizos desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90927','espacio','Riberas del río Tirón / Sotos de Oreca','Tramo aluvial maduro donde el río Tirón ensancha su lecho dejando depósitos de gravas cuaternarias. Cuenta con sotos ripícolas continuos y bien conservados, formados por álamos blancos y sauces que aportan una alta frescura visual al entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','espacio','Cañón del río Najerilla / Pancrudo / Bosque de Cobezón','Impresionante tajo geológico con paredes calizas verticales de varios cientos de metros de altura esculpido por el río Najerilla. Alberga un relieve totalmente   abrupto tapizado por hayedos puros, encinares de roca calcárea y espectaculares formaciones kársticas superficiales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90928','espacio','Vega del río Najerilla / Lomas de Santa Coloma','Transición entre la llanura de inundación aluvial del Najerilla y las lomas arcillo-areniscas que enmarcan el valle. Presenta pequeños tramos de soto de ribera bien estructurados con sauces, chopos negros y pastizales húmedos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90929','espacio','Altos de Arenzana / Arroyo de Carraquinea','Topografía ondulada dominada por cerros testigos arcillosos con costras superiores de areniscas. Las vaguadas albergan pequeñas dehesas muy aclaradas de quejigo mediterráneo y matorral arbustivo de tomillo y romero adaptado a la sequía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90930','espacio','Desfiladero del río Cidacos / Peñas de Arnedillo','Majestuoso cañón de conglomerados y calizas triásicas caracterizado por espectaculares agujas y crestas verticales de tonos rojizos. El relieve cuenta con importantes fracturas corticales que dan origen a pozas termales naturales en el mismo cauce del río Cidacos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90271','espacio','Peña de Arnedo / Cañón del Cidacos / Llanos de la Dehesa','Impresionante conjunto de farallones y cerros arcillo-areniscos de color rojizo encendido que flanquean el valle del Cidacos, moldeados por la erosión eólica. Las paredes verticales albergan cuevas naturales y están circundadas por matorrales mediterráneos xerófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90931','espacio','Meandro del Ebro / Soto de Arrúbal','Paisaje completamente horizontal sobre la llanura aluvial baja del Ebro. Presenta un pequeño meandro abandonado ocupado por vegetación palustre hidrófila y una franja modesta de sauces que rompe la monotonía del entorno industrial periférico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26020','espacio','Campo Charro / Riberas del arroyo de la Valmuza','Paisaje penillanura horizontal sobre materiales graníticos y de pizarra del neógeno. Destaca por albergar un bosque adehesado de encinas centenarias bien estructurado, donde el suelo arcillo-pedregoso da paso a pequeñas charcas estacionales y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26021','espacio','Picuezo y Picueza / Cañón del río Cidacos','Singulares e imponentes monolitos de arenisca y conglomerados moldeados por la erosión diferencial del viento y el agua, que se elevan verticalmente más de cuarenta metros en la entrada del desfiladero del Cidacos, conformando una estampa geológica única.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26022','espacio','Valle del río Tuerto / Lomas de Azofra','Suave relieve colinado de la Rioja Alta compuesto por sedimentos arcillosos del neógeno. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las lomas presentan tomillares y restos dispersos de quejigales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26023','espacio','Valle del río Cárdenas / Monte de San Lorenzo (Estribaciones)','Depresión aluvial labrada por el río Cárdenas sobre materiales rojizos de arcilla y cantos rodados. El relieve asciende suavemente hacia la sierra, mostrando un corredor verde continuo de sauces y alisos flanqueado por dehesas de rebollo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26024','espacio','Llanura de Santo Domingo / Arroyo de Bañares','Topografía monótona y horizontal sobre depósitos aluviales y glacis cuaternarios de la Rioja Alta. La presencia de pequeñas corrientes de agua estacionales genera áreas húmedas aisladas con juncos que rompen la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26025','espacio','Cerro de El Campo / Riberas del río Oja','Escarpada cuesta de areniscas que domina la amplia vega de inundación pedregosa del río Oja. Las vertientes protegidas de la insolación conservan encinares aclarados mediterráneos que contrastan con los sotos de ribera del fondo aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26026','espacio','Desfiladero del río Najerilla / Peñas de Baños','Zona de transición de la sierra donde el río Najerilla corta transversalmente los estratos de conglomerados rojizos. Las laderas presentan fuertes pendientes cubiertas por quejigares, encinares maduros y un soto fluvial de gran densidad vegetal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26027','espacio','Valle del río Cárdenas / Estribaciones de la Demanda','Relieve quebrado prepirenaico de transición con valles profundos y laderas cubiertas de brezales y robledales melojos. El curso alto del río Cárdenas destaca por sus aguas cristalinas y limpias flanqueadas por una frondosa vegetación de ribera de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26028','espacio','Sierra de la Hez / Barranco de San Pedro','Alineación montañosos caliza de perfil alomado con vertientes erosionadas que caen hacia el valle. Las umbrías y barrancos conservan manchas boscosas de encina   carrasca y un notable matorral aromático de romero y tomillo adaptado al suelo calcáreo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26030','espacio','Lomas de Bezares / Barranco de Valdega','Topografía de lomas suaves arcillosas degradadas situadas en la zona de transición a la sierra. Presenta pequeños riachuelos estacionales acompañados de carrizales aislados y matorral de quejigo muy aclarado debido al secular aprovechamiento ganadero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26031','espacio','Ribera del río Najerilla / Canal de Bobadilla','Sector medio del valle del Najerilla caracterizado por una llanura aluvial con grandes depósitos de cantos rodados cuarcíticos. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y chopos forman un cinturón vegetal de alto valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26032','espacio','Sierra de Urbión / Valle del río Brieva / Cabeza Parda','Alta montaña alpina modelada por procesos periglaciares sobre areniscas y conglomerados paleógenos. Cuenta con circos glaciares impresionantes, canchales de piedra verticales y riachuelos torrenciales de aguas heladas rodeados de hayedos y pastizales subalpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26033','espacio','Meandro de Briñas / Conchas de Haro / Río Ebro','Espectacular y angosto paso natural donde el río Ebro corta de forma transversal las estructuras calizas de la sierra de Cantabria. El río dibuja un gran meandro encajonado flanqueado por escarpes rocosos verticales cubiertos de vegetación mediterránea termófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','espacio','Meandro del Ebro en Briones / Cortados de San Llorente','Imponente cerro testigo calizo que se levanta directamente sobre una de las curvas más monumentales del curso medio del río Ebro. Ofrece un perfil de escarpes y terrazas fluviales de gran potencia visual con sotos maduros de alamedas al pie de la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26035','espacio','Cañón del río Leza / Cueva del Tesoro','Tramo alto del valle del río Leza caracterizado por un relieve de fuertes pendientes calizas esculpidas por la erosión hídrica. Las umbrías y laderas albergan densos encinares y quejigares calcícolas bien conservados, flanqueados por impresionantes farallones rocosos donde anidan aves rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26036','espacio','Sotos del río Ebro y río Cidacos / Humedal de la Degollada','Amplia llanura aluvial y de inundación donde confluyen las cuencas del Cidacos y el Ebro, rodeada de lagunas naturalizadas sobre arcillas. Los márgenes conservan sotos maduros de chopos, sauces y fresnos que contrastan cromáticamente con el relieve árido de las terrazas superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26037','espacio','Estribaciones de la Sierra de la Demanda / Peña del León','Relieve prepirenaico abrupto constituido por conglomerados y areniscas con un marcado gradiente altitudinal. Las laderas orientadas al norte están tupidas por frondosas masas forestales de quejigos y rebollos que dominan visualmente todo el valle del Najerilla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26038','espacio','Sierra de la Demanda / Nacimiento del río Najerilla (río Canales) / Gatón','Paisaje alpino de alta montaña modelado sobre pizarras y areniscas, caracterizado por circos de origen glaciar y picos que rozan los dos mil metros. El curso alto del río Canales discurre encajonado de forma torrencial entre hayedos puros, acebedas y pastizales subalpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26039','espacio','Valle del río Tuerto / Vega de Canillas','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en la Rioja Alta. Ofrece una perspectiva diáfana   donde el curso del río Tuerto aporta una franja estrecha de sauces negros y carrizales dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26042','espacio','Riberas del río Oja-Tirón','Tramo aluvial maduro donde confluyen las dinámicas hidrográficas de los ríos Oja y Tirón sobre glacis cuaternarios. Los márgenes fluviales conservan sotos ripícolas bien estructurados con álamos blancos y sauces que rompen la horizontalidad cerealista de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26043','espacio','Valle del río Oja / Canal de la Margen Derecha','Amplia llanura de inundación aluvial caracterizada por depósitos masivos de cantos rodados y gravas cuarcíticas. Presenta un corredor verde continuo de sauces que escolta el cauce del río Oja, ofreciendo un marcado contraste cromático a lo largo del año.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26044','espacio','Serranía de Moncalvillo / Cañón del río Yalde / Barranco de San Antón','Relieve de media montaña con vertientes abruptas y barrancos sinuosos cubiertos por densas masas de hayedo y pino silvestre. La cabecera del río Yalde se caracteriza por un relieve de fuertes desniveles, bloques de piedra sueltos y riachuelos cristalinos de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26046','espacio','Meandros del río Ebro / Soto de la Ermita','Gran terraza fluvial neógena situada en el margen derecho del río Ebro, donde el cauce dibuja curvas amplias sobre sedimentos finos. Las márgenes albergan un soto de ribera continuo poblado por alamedas y saucedas maduras que sirven de corredor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26047','espacio','Barranco de Valdelalosa / Cañón del río Alhama / Las Ruescas','Espectacular y profundo corte geológico donde el río Alhama corta transversalmente los estratos de yesos y margas de la Rioja Baja. Las paredes verticales rojizas y blanquecinas albergan vegetación gipsícola altamente especializada y comunidades rupícolas de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26048','espacio','Lomas de Cidamón / Arroyo de San Torcuato','Topografía de lomas suaves arcillosas degradadas en la meseta central de la Rioja Alta. Presenta pequeñas corrientes de agua estacionales acompañadas de juncos y gramíneas aisladas que rompen la homogeneidad del paisaje agrario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26049','espacio','Confluencia de los ríos Tirón y Oja / Cortados de Cihuri','Relieve singular donde el río Tirón excava un pequeño desfiladero sobre areniscas y conglomerados paleógenos antes de recibir las aguas del Oja. Las repisas rocosas albergan vegetación mediterránea termófila que se asoma sobre pozas profundas de aguas tranquilas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26050','espacio','Dehesa de Cirueña / Altos de San Lorenzo','Altiplanicie de transición hacia la sierra caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas orientadas a la umbría conservan pequeñas manchas boscosas de roble quejigo bien adaptadas al riguroso clima continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26051','espacio','Peñas de Clavijo / Cañón del río Leza (Sector Occidental)','Imponente muralla natural de conglomerados oligocenos fracturados que se levanta de forma vertical marcando el límite entre el valle del Ebro y el Camero Viejo.   Ofrece un relieve escarpado con farallones rocosos donde anidan grandes rapaces y crece flora rupícola especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26052','espacio','Barranco de Valdecañas / Lomas de Cordovín','Suave relieve colinado labrado sobre arcillas y margas de tonalidades rojizas típicas de la Rioja Alta. Las pequeñas vaguadas acumulan la humedad de arroyos estacionales, permitiendo el crecimiento de eneas y carrizos aislados en mitad del entorno vitícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26053','espacio','Valle de Ocón / Arroyo de la Madre','Relieve alomado que desciende de forma escalonada desde la sierra de la Hez hacia el valle de la Rioja Media. Cuenta con arroyos modestos flanqueados por corredores estrechos de vegetación aluvial y matorral mediterráneo termo-atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26054','espacio','Sierra de Alcarama / Cañón del río Linares','Paisaje montañoso agreste constituido por areniscas y calizas con una fuerte erosión hídrica que ha esculpido el desfiladero del río Linares. Las laderas desnudas y los escarpes albergan comunidades matorrales mediterráneos xerófilos y encinares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26055','espacio','Llanura de Santo Domingo / Arroyo de Corporales','Topografía monótona y horizontal sobre depósitos de glacis cuaternarios en el extremo occidental riojano. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26056','espacio','Riberas del río Tirón / Monte El Bolo','Sector medio del valle del río Tirón caracterizado por un relieve de terrazas de gravas y arenas aluviales. El cauce mantiene un corredor forestal denso e ininterrumpido de sauces y chopos que aporta frescura y contraste visual al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26057','espacio','Serranía de Moncalvillo (Vertiente Norte) / Barranco de las Neveras','Laderas montañosas de pendientes extremas talladas sobre materiales silíceos y areniscas. La elevada humedad de las cumbres permite la proliferación de frondosas masas de hayedos, robledales de melojo y densas masas de helechos en las vaguadas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26058','espacio','Cañón del río Cidacos / Desfiladero de Navalsaz / Valle Alto del Cidacos','Impresionante relieve quebrado labrado sobre areniscas y calizas con una gran riqueza en estratificaciones del cretácico. Las laderas escarpadas, salpicadas de matorral xerófilo mediterráneo, se hunden de forma abrupta hacia el lecho de un río Cidacos joven de aguas muy batidas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26059','espacio','Lomas de Santa Ana / Barranco de Ruatelo','Paisaje colinado sobre arcillas y cascajos que sirve de piedemonte septentrional a la sierra de Moncalvillo. Las pequeñas vaguadas acumulan humedad estacional, permitiendo la existencia de matorral de quejigo aclarado y cinturones modestos de carrizal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26060','espacio','Sierra de la Demanda (Estribaciones) / Barranco de San Millán','Relieve prepirenaico de fuerte pendiente constituido por pizarras y areniscas en la cuenca del río Cárdenas. La ladera umbría atesora manchas densas de roble rebollo y brezales húmedos que trepan hacia las cumbres de la cordillera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','espacio','Sierra de la Demanda / Picos de San Lorenzo y Cabeza Parda / Dehesa de Ezcaray','Majestuoso paisaje de alta montaña alpina con circos y valles de origen glaciar perfectamente definidos sobre areniscas y pizarras. Alberga inmensos hayedos puros, pinares silvestres y acebedas relictas de carácter totalmente salvaje, surcados por el río Oja de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26063','espacio','Montes Obarenes (Faldas orientales) / Barranco de Valdecastro','Relieve de transición entre los escarpes calizos montañosos y las llanuras cerealistas de la Rioja Alta. Presenta pequeñas formaciones de encinar mediterráneo arbustivo adaptadas a suelos calcáreos pobres y pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26064','espacio','Meandros del río Ebro / Soto de Buicio','Gran terraza fluvial neógena donde el río Ebro ensancha su cauce y dibuja amplias curvas sobre depósitos de sedimentos finos. Las márgenes albergan un soto de ribera continuo muy frondoso poblado por álamos blancos y sauces negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26065','espacio','Montes Obarenes / Peña Lengua','Escarpada fractura orográfica caracterizada por impresionantes agujas y crestas calcáreas verticales de tonos grisáceos. El relieve de umbría está densamente poblado por hayedos y quejigares que se aferran a las repisas de la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26066','espacio','Valle de Ocón (Bajo) / Arroyo de San Martín','Topografía de lomas suaves arcillosas degradadas orientadas hacia la fosa de la Rioja Media. Cuenta con arroyos estacionales acompañados de   cañaverales aislados y matorral mediterráneo de romero y tomillo resistente a la sequía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26068','espacio','Meandro de Gimileo / Cortados del río Ebro','Imponente cerro testigo que cae de forma directa sobre una de las curvas más cerradas del río Ebro en la Rioja Alta. Ofrece una sección geológica perfecta de arcillas y areniscas con un soto de ribera estrecho al pie de los escarpes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26069','espacio','Dehesa de Grañón / Altos de la Tejera','Altiplanicie horizontal en el extremo occidental riojano caracterizada por suelos arcillosos con cantos rodados cuarcíticos. Las vaguadas sombrías conservan pequeñas manchas boscosas de rebollo adaptadas al clima continentalizado de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26070','espacio','Sierra de Yerga / Barranco de la Cueva','Paisaje quebrado de media montaña con laderas de fuertes pendientes calizas y una densa red de escorrentía torrencial. Las zonas protegidas albergan encinares carrascales densos y un notable matorral aromático adaptado al sustrato calcáreo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','espacio','Conchas de Haro / Riberas del río Ebro y Tirón','Espectacular desfiladero natural donde el río Ebro corta de forma transversal las calizas de la sierra de Cantabria. El entorno fluvial presenta una imponente visual de peñas verticales combinada con amplios sotos de álamos en las confluencias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26073','espacio','Vega del río Tirón / Lomas de Velasco','Valle aluvial maduro donde el río Tirón discurre sobre depósitos cuaternarios de arenas y gravas finas. Ofrece una perspectiva diáfana con una franja estrecha pero continua de saucedas y alisos de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26074','espacio','Laguna de Hervías','Humedal de origen endorreico recuperado sobre arcillas ecorregionales en mitad de la llanura de la Rioja Alta. Destaca por su lámina de agua estable y un espeso cinturón de eneas y carrizos que sirve de oasis en el entorno agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26075','espacio','Valle del río Hormilla / Altos de la Redonda','Topografía ondulada labrada sobre arcillas terciarias rojizas por arroyos modestos. Los fondos de valle acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26076','espacio','Confluencia del río Hormilla y río Najerilla','Relieve aluvial de llanura baja donde la dinámica divagante de los dos cauces genera terrazas fluviales de gravas. Los márgenes conservan sotos de ribera bien estructurados con chopos negros y sauces que aportan frescura visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26077','espacio','Sierra de Cameros / Barranco de la Canaleja','Relieve montañoso abrupto en el Camero Viejo con valles estrechos esculpidos sobre calizas por arroyos temporales. Las vertientes de umbría conservan manchas densas de encina carrasca y quejigares mezclados con canchales de piedra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26078','espacio','Serranía de Moncalvillo / Arroyo de la Dehesa','Vertiente de pendientes moderadas constituida por materiales silíceos y areniscas que desciende hacia el valle. Las zonas altas albergan melojares jóvenes y brezales húmedos que tapizan un relieve quebrado por pequeñas escorrentías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26079','espacio','Vega del río Yalde / Lomas de Huércanos','Suave relieve colinado de transición caracterizado por sedimentos arcillosos del neógeno. El río Yalde aporta una franja estrecha de vegetación ripícola con sauces negros y eneas aisladas en mitad del entorno vitícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26080','espacio','Cañón del río Linares / Yacimiento de la Era del Peladillo (Entorno geológico) / Barranco de las Carboneras','Paisaje quebrado de la Rioja Baja donde el río Linares excava escarpes calcáreos y areniscas del Cretácico. El relieve destaca por sus espectaculares formaciones de estratos expuestos, cárcavas arcillosas y un entorno semidesértico colonizado por matorral mediterráneo xerófilo muy especializado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26081','espacio','Cañón del río Leza (Sector Medio) / Dehesa de Jalón','Valle de fuertes pendientes labrado sobre calizas jurásicas por el encajonamiento del río Leza. Las vertientes de umbría atesoran masas compactas de quejigos y encinares de roca, con profundos barrancos secundarios de gran fuerza visual y geomorfológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26082','espacio','Sierra de Cameros / Nacimiento del río Leza / Hoyo de las Brujas','Paisaje de alta montaña alpina con un relieve abrupto modelado por procesos periglaciares sobre areniscas y calizas. El curso alto del río Leza nace entre inmensos hayedos, abedulares relictos y pastizales subalpinos salpicados por dolinas y lapiaces kársticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26083','espacio','Cañón del río Jubera / Peñas de Zenzano','Impresionante tajo geológico con farallones calizos verticales esculpido por las aguas torrenciales del río Jubera. Las paredes rocosas sirven de asentamiento a importantes colonias de buitre leonado y presentan comunidades de flora rupícola calcícola de gran interés.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26084','espacio','Barranco de la Garganta / Terrazas del Iregua','Topografía horizontal de glacis y terrazas aluviales cuaternarias compuestas por gravas y cantos rodados finos. Ofrece una perspectiva abierta y diáfana rota únicamente por pequeñas incisiones torrenciales donde prolifera el matorral mediterráneo de romero y tomillo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26086','espacio','Sierra de la Demanda (Faldas orientales) / Barranco de las Cortes','Relieve de media montaña con vertientes abruptas constituidas por pizarras y areniscas. Las laderas orientadas a la umbría conservan masas densas de robledal de melojo y rebollos que se entremezclan con brezales húmedos de gran colorido estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26087','espacio','Riberas del río Tirón / Encoro de Leiva (Márgenes naturales)','Tramo aluvial donde el río Tirón remansa sus aguas en una cubeta sedimentaria flanqueada por lomas arcillosas. Los márgenes conservan un soto ripícola bien estructurado con sauces y chopos que conviven con cinturones de vegetación palustre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26088','espacio','Cañón del río Leza / Mirador del Torrejón (Escarpes naturales)','Espectacular e imponente desfiladero calizo de paredes totalmente verticales que superan los doscientos metros de caída a pico. El relieve muestra un modelado kárstico perfecto con cuevas colgadas y una umbría perenne   donde encinas y quejigos se agarran a los cantiles de roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','espacio','Humedal de la Grajera / Sotos del río Ebro (Soto Inundable de Alfaro)','Amplia llanura de inundación aluvial donde el Ebro dibuja meandros estables sobre sedimentos finos. Cuenta con una cubeta endorreica naturalizada (La Grajera) rodeada de un cinturón espeso de eneas, carrizos y alamedas maduras de gran interés paisajístico y contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90932','espacio','Parque Natural Sierra de Cebollera / Cascadas de Puente Rá / Laguna de la Horcajada','Majestuoso entorno alpino de alta montaña caracterizado por circos y valles de origen glaciar sobre areniscas y pizarras de la cordillera Ibérica. Alberga inmensos pinares silvestres, hayedos puros y cascadas sucesivas de aguas heladas encajadas en gargantas de roca salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26094','espacio','Valle de San Lorenzo / Arroyo de Manzanares','Relieve alomado que sirve de transición entre las altas cumbres de la Demanda y la llanura de Santo Domingo. Las laderas de suelo arcillo-pedregoso albergan pequeñas dehesas de quejigo y matorrales de transición atlántico-mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26093','espacio','Sierra de la Demanda / Cañón del río Gatón / Cambrones','Impresionante paisaje de montaña donde confluyen profundos valles fluviales encajonados sobre pizarras y areniscas. Las escarpadas vertientes están tapizadas por hayedos puros, robledales melojos y piornales de cumbre que rodean las aguas del embalse de Mansilla.   Manzanares de Rioja       (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26095','espacio','Angosto de Matute / Peñas de Tobía','Espectacular y angosta garganta excavada por el arroyo de Rigüelo sobre conglomerados calizos de un intenso color rojizo. Las paredes verticales del desfiladero son de una gran potencia visual, albergando flora rupícola especializada y grandes colonias de rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26096','espacio','Serranía de Moncalvillo (Piedemonte) / Arroyo de la Madre','Topografía de lomas suaves arcillosas que descienden desde la sierra hacia la cuenca del Ebro. Las pequeñas canales acumulan humedad estacional, permitiendo la presencia de matorral de quejigo aclarado y cinturones modestos de carrizal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26098','espacio','Sierra de la Hez / Valle del río Manzanares / Barranco de las Umbrías','Relieve montañoso abrupto caracterizado por fuertes desniveles, peñascos y barrancos esculpidos sobre calizas y caleras. La cubierta vegetal destaca por sus encinares carrascales y quejigares de ladera, que conviven con canchales de piedra erosionados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26099','espacio','Confluencia del río Leza y río Jubera / Cortados de Murillo','Relieve de llanura baja donde la dinámica divagante de los dos cauces genera terrazas fluviales de gravas y margas. Los márgenes conservan pequeños escarpes y sotos de ribera bien estructurados con chopos negros y sauces que aportan frescura visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26100','espacio','Sierra de Ausejo / Peña Isasa (Vertiente Occidental) / Nacimiento del río Cidacos (Estribaciones)','Paisaje montañoso de carácter rústico e inhóspito dominado por la imponente mole caliza de Peña Isasa. El relieve presenta vertientes de pendientes extremas cubiertas de brezales, matorrales xerófilos y encinares de roca adaptados a la sequedad continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26101','espacio','Sierra de Cameros / Barranco del Moro','Relieve de media montaña en el Camero Viejo con valles estrechos esculpidos sobre calizas por arroyos temporales. Las vertientes de umbría conservan manchas densas de encina carrasca y quejigares mezclados con canchales de piedra calcárea.   Si estás listo para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26102','espacio','Cortados de Peña Escalera / Malpica / Riberas del río Najerilla','Impresionantes paredes verticales de conglomerados arcillosos de un color rojo intenso que se elevan directamente sobre el curso medio del río Najerilla. El relieve ofrece una impactante fractura geológica de erosión fluvial combinada con un soto de ribera maduro de álamos y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26103','espacio','Peñas de Leza y Pagayos / Riberas del río Iregua','Imponente transición orográfica donde el valle del Ebro choca contra los primeros macizos de conglomerados oligocenos de Cameros. El terreno se quiebra en abruptos farallones rocosos y agujas que escoltan un corredor fluvial hiperhúmedo cubierto de densas choperas y saucedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26104','espacio','Barranco de Valdelalosa / Sierra de Alcarama','Paisaje agreste de la Rioja Baja modelado sobre margas y calizas del cretácico, famoso a nivel mundial por sus formaciones geológicas ricas en cristales de pirita perfectos. El relieve es quebrado, desértico y erosionado, cubierto por un matorral mediterráneo de tomillo y romero altamente adaptado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26106','espacio','Serranía de Moncalvillo / Barranco de San Miguel','Laderas montañosas de pendientes acusadas labradas sobre areniscas y materiales silíceos en el Camero Nuevo. La alta humedad ambiental favorece el desarrollo de dehesas maduras de roble rebollo y pastizales húmedos de montaña salpicados de pequeños afloramientos rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26107','espacio','Torcas de Nieva / Peña de El Castejón / Encinar de Montemediano','Espectacular relieve kárstico que presenta dolinas (torcas) y sumideros naturales excavados sobre la caliza mesozoica. El paisaje visual es de una gran dureza y magnificencia, alternando paredones grises desnudas donde anidan rapaces con densos encinares de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26109','espacio','Riberas del río Tirón / Vega de Ochánduri','Valle aluvial maduro donde el río Tirón suaviza su curso depositando gravas finas y limos. Presenta un corredor verde estrecho pero continuo compuesto por sauces negros y álamos que rompe la horizontalidad de las lomas agrícolas de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26108','espacio','Sierra de la Hez / Dehesa de Ocón / Barranco de San Julián','Macizo montañoso de perfil alomado que marca el límite de la Rioja Media, con vertientes umbrías cubiertas por un majestuoso e histórico carballeira de quejigos y robles. El relieve desciende en profundas barrancadas que ofrecen extensas panorámicas de la cuenca del Ebro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26110','espacio','Valle del río Oja / Barranco de Amunartia / Monte de San Lorenzo (Laderas)','Relieve de alta montaña alpina integrado en las estribaciones norteñas de la sierra de la Demanda, modelado sobre pizarras y areniscas. Las laderas de fuerte pendiente están completamente tapizadas por densos hayedos, robledales y pequeños arroyos de aguas bravas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26111','espacio','Cerros de Ollauri / Riberas del río Zamaca','Topografía de lomas suaves arcillosas y terrazas de arenisca labradas por la erosión diferencial en la Rioja Alta. Los arroyos estacionales acumulan eneas y juncos en sus cauces, mientras que las vertientes expuestas muestran tomillares mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26112','espacio','Cuevas de Ortigosa (La Paz y La Viña) / Cañón del río Alberco / Embalse de González Lacasa','Impresionante complejo kárstico subterráneo con cavidades repletas de espectaculares formaciones de estalactitas y estalagmitas. En la superficie, el relieve se quiebra en un estrecho desfiladero calizo de paredes caleras verticales cubiertas por densos encinares y quejigares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26113','espacio','Sierra de la Demanda / Cabecera del río Oja / Riberas del arroyo de San Llorente','Altiplanicie y valles de alta montaña subalpina caracterizados por un relieve de lomas redondeadas y fuertes desniveles erosionados. Alberga extensos pastizales de altura   y densas manchas forestales de hayas y acebedas relictas adaptadas al clima riguroso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26114','espacio','Serranía de Moncalvillo / Barranco de las Ruedas / Río Najerilla','Relieve quebrado de media montaña con vertientes escarpadas orientadas hacia la cuenca del Najerilla. Las umbrías del término municipal atesoran masas compactas de robledal de melojo y castañares dispersos que colonizan el suelo silíceo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26115','espacio','Sierra de Cameros / Barranco de San Andrés','Valle de pendientes extremas labrado sobre calizas por el encajonamiento de arroyos temporales en el Camero Nuevo. Las vertientes conservan manchas densas de encina carrasca y matorrales aromáticos de romero y tomillo que se asientan sobre canchales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26117','espacio','Páramo de la Plana / Llanos del Ebro','Altiplanicie árida de relieve marcadamente horizontal constituida por arcillas y costras yesíferas en la Rioja Baja. Cuenta con pequeñas barrancadas temporales donde prolifera de forma exclusiva el esparto, la retama y el matorral mediterráneo xerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26118','espacio','Sotos del río Iregua / Barranco de San Salvador','Tramo donde el río Iregua se encajona entre las primeras estribaciones montañosas calcáreas de Cameros, labrando rápidos de agua y pozas. La ribera mantiene una excelente y frondosa representación de bosque aluvial mezclado con quejigares de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26119','espacio','Sierra de Alcarama / Peña Isasa (Ladera Norte) / Barranco de la Canal','Imponente relieve de montaña calcárea caracterizado por el perfil afilado de las peñas caleras que dominan el valle del Rregatillo. Las paredes rocosas sirven de nido a grandes rapaces y presentan comunidades de flora rupícola adaptada a la sequedad continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26120','espacio','Peña de Quel / Cañón del río Cidacos','Espectacular y majestuoso farallón vertical de areniscas y conglomerados rojizos que se eleva de forma casi absoluta más de cien metros sobre la vega del río Cidacos. Ofrece una sección geológica perfecta modelada por la erosión eólica, coronada por matorral xerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26121','espacio','Sierra de Cameros / Barranco de Valdecuenca','Relieve de media montaña en el Camero Viejo con valles estrechos esculpidos sobre calizas jurásicas por torrentes estacionales. Las umbrías conservan manchas densas de encina carrasca mezcladas con canchales de piedra caliza erosionada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26122','espacio','Monte de San Cristóbal / Riberas del Embalse de González Lacasa','Entorno montañoso caracterizado por laderas de fuerte pendiente cubiertas por frondosos bosques de pino silvestre, hayas y robles que descienden hacia las aguas mansas del embalse. El relieve presenta pequeños barrancos sombríos con abundante presencia de helechales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26123','espacio','Valle de Ocón / Arroyo de la Madre','Topografía de lomas suaves arcillosas degradadas orientadas hacia la fosa de la Rioja Media. Cuenta con arroyos estacionales acompañados de cañaverales aislados y matorral mediterráneo resistente a la sequía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26124','espacio','Cañón del río Leza (Entrada) / Peñas de Ribafrecha','Impresionante puerta de entrada al cañón del Leza, donde el río corta de forma transversal las estructuras calizas de la sierra de Cameros. Las paredes verticales del desfiladero albergan una notable flora rupícola calcícola y grandes colonias de buitre leonado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26125','espacio','Sotos del río Ebro / Meandro de la Nava','Amplia llanura aluvial y de inundación baja donde el río Ebro dibuja amplios meandros sobre sedimentos finos arcillosos. Las márgenes albergan un soto de ribera continuo poblado por alamedas y saucedas maduras que sirven de corredor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26126','espacio','Valle del río Jubera / Barranco de San Vicente / Sierra de la Hez','Paisaje montañoso agreste constituido por areniscas y calizas con una fuerte erosión hídrica que ha esculpido el desfiladero del río Jubera. Las laderas desnudas y los escarpes albergan comunidades de quejigos, encinares de roca y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26127','espacio','Cerros de Rodezno / Lomas de San Cristóbal','Suave relieve colinado de la Rioja Alta compuesto por sedimentos arcillosos del neógeno. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las lomas presentan tomillares y restos dispersos de matorral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26128','espacio','Riberas del río Ea / Sotos de Sajazarra','Tramo aluvial maduro donde el río Ea discurre sobre depósitos cuaternarios de arenas y gravas finas en el extremo occidental. Ofrece un corredor verde estrecho   compuesto por sauces y chopos que rompe la horizontalidad cerealista de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','espacio','Cortados del río Ebro / Davalillo (Sotos y Escarpes)','Imponentes farallones de arcillas y areniscas esculpidos por el río Ebro en su curso medio, que dibuja curvas encajonadas a los pies de las peñas. Las repisas rocosas albergan vegetación mediterránea termófila que se asoma sobre sotos fluviales maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','espacio','Sierra de la Demanda / Valle del río Cárdenas / Cabeza Parda','Majestuoso paisaje de alta montaña con circos y valles de origen glaciar sobre areniscas y pizarras de la cordillera. Alberga inmensos hayedos puros, pinares silvestres y acebedas relictas de carácter totalmente salvaje, surcados por el río Cárdenas de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26131','espacio','Valle del río San Millán / Lomas de Yécora','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en el límite con Burgos. Ofrece una perspectiva diáfana donde el curso del arroyo aporta una franja estrecha de sauces negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26139','espacio','Lomas de San Torcuato / Arroyo de la Presa','Topografía de lomas suaves arcillosas degradadas en la meseta central de la Rioja Alta. Presenta pequeñas corrientes de agua estacionales acompañadas de juncos y gramíneas aisladas que rompen la homogeneidad del paisaje agrario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','espacio','Meandros del río Ebro / Sierra de Cantabria (Faldas)','Gran terraza fluvial neógena situada en el margen izquierdo del río Ebro, flanqueada por las estribaciones calizas de la sierra de Cantabria. El río dibuja curvas amplias rodeadas de un soto de ribera continuo muy frondoso poblado por álamos blancos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26134','espacio','Estribaciones de la Sierra de la Demanda / Barranco de Santa Coloma','Relieve prepirenaico abrupto constituido por conglomerados y areniscas con un marcado gradiente altitudinal. Las laderas orientadas al norte están tupidas por frondosas masas forestales de quejigos y rebollos que dominan el paisaje visual de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26135','espacio','Cañón del río Jubera / Cascadas de Santa Engracia / Peñas de San Martín','Impresionante tajo geológico con farallones calizos verticales esculpido por las aguas torrenciales del río Jubera, que genera saltos de agua sucesivos en la roca. Las paredes rocosas albergan comunidades de flora rupícola calcícola de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26136','espacio','Valle del río Cidacos / Lomas de Santa Eulalia','Transición entre la llanura de inundación aluvial del Cidacos y las lomas arcillo-areniscas que enmarcan el valle de la Rioja Baja. Presenta pequeños tramos de soto de ribera bien estructurados con sauces, chopos negros y carrizales estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','espacio','Vega del río Oja / Sotos de Santo Domingo','Amplia llanura de inundación aluvial caracterizada por depósitos masivos de cantos rodados y gravas cuarcíticas de la Rioja Alta. Presenta un corredor verde continuo de sauces que escolta el cauce del río Oja, ofreciendo frescura visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26140','espacio','Sierra de la Demanda (Piedemonte) / Arroyo de Santurde','Relieve alomado que sirve de transición entre las altas cumbres de la sierra de la Demanda y el valle del Oja. Las laderas de suelo arcillo-pedregoso albergan excelentes masas forestales de quejigo y robledales de melojo bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26141','espacio','Valle de Santurdejo / Estribaciones de la Demanda','Relieve quebrado prepirenaico de transición con valles profundos y laderas cubiertas de brezales secos. El curso de agua destaca por su aislamiento geográfico y por albergar pequeños sotos de sauces y rebollares en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26143','espacio','Serranía de Moncalvillo / Barranco de la Hermedaña','Laderas montañosas de pendientes extremas talladas sobre materiales silíceos y areniscas. La elevada humedad de las cumbres permite la proliferación de frondosas masas de hayedos, robledales de melojo y densas masas de helechos en las vaguadas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26144','espacio','Serranía de Moncalvillo (Vertiente Oriental) / Barranco de San Juan','Laderas que sirven de piedemonte al macizo de Moncalvillo, caracterizadas por pendientes moderadas. Están densamente cubiertas por masas forestales de robles melojos y quejigos que dan paso a pastizales húmedos en los fondos fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26145','espacio','Piedemonte de Moncalvillo / Arroyo de Sotés','Topografía de lomas suaves arcillosas que descienden desde la sierra hacia la cuenca del Ebro. Las   pequeñas canales acumulan humedad estacional, permitir el desarrollo de matorral de quejigo aclarado y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26146','espacio','Cañón del río Leza / Cueva de los Caserones / Huellas de Dinosaurio (Entorno Geológico)','Espectacular desfiladero calizo de paredes totalmente verticales que superan los doscientos metros de caída a pico en el Camero Viejo. El relieve muestra un modelado kárstico perfecto con oquedades y una umbría perenne donde encinas y quejigos se agarran a los cantiles de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26147','espacio','Cañón del río Leza (Sector Alto) / Sotos de Terroba','Tramo alto del valle del río Leza caracterizado por un relieve de fuertes pendientes calizas esculpidas por la erosión hídrica. Las umbrías y laderas albergan dehesas de quejigo calcícola bien conservadas, flanqueadas por farallones rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26148','espacio','Riberas del río Tirón / Sotos de Tirgo','Sector medio del valle del río Tirón caracterizado por un relieve de terrazas de gravas y arenas aluviales. El cauce mantiene un corredor forestal denso e ininterrumpido de sauces y chopos que aporta frescura y contraste visual al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26149','espacio','Peñas de Tobía / Conglomerados del río Tobía / Bosque de Cobezón','Uno de los paisajes geológicos más espectaculares de la provincia, caracterizado por gigantescos y majestuosos farallones de conglomerados rojizos que se elevan verticalmente cientos de metros. La base del relieve y sus umbrías albergan hayedos puros de gran belleza plástica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26150','espacio','Valle del río Tirón / Lomas de Tormantos','Paisaje geomorfológico horizontal de la Rioja Alta compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en el límite con Burgos. Ofrece una perspectiva diáfana donde el curso del río Tirón aporta un cinturón modesto de saucedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','espacio','Desfiladero de las Peñas / Riberas del río Iregua / Cueva de Ágreda','Impresionante tajo geológico con paredes calizas verticales tallado por el río Iregua en el corazón del Camero Nuevo. El relieve es totalmente abrupto y salvaje, mostrando grandes bloques de roca desprendidos y laderas tapizadas por hayedos y quejigares de gran madurez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26152','espacio','Valle del río Tuerto / Lomas de Torrecilla','Suave relieve colinado labrado sobre arcillas y margas de la Rioja Alta por arroyos modestos. Los fondos de valle acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26154','espacio','Confluencia del río Najerilla y río Ebro / Soto de Torremontalbo','Relieve aluvial de llanura baja donde el río Najerilla vierte sus aguas en el cauce maduro del Ebro. Los márgenes conservan sotos de ribera bien estructurados con chopos negros, álamos blancos y sauces que aportan una alta frescura visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26155','espacio','Riberas del río Ea / Cerros de Treviana','Paisaje de erosión labrado sobre margas, arcillas y costras de areniscas en el extremo noroccidental   riojano, dando lugar a un relieve quebrado de cárcavas. Las laderas presentan pequeñas formaciones de matorral mediterráneo adaptado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','espacio','Vega del río Najerilla / Lomas de Tricio','Transición entre la llanura de inundación aluvial del Najerilla y las lomas arcillo-areniscas que enmarcan el valle de la Rioja Alta. Presenta pequeños tramos de soto de ribera bien estructurados con sauces, chopos negros y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26160','espacio','Vega del río Najerilla / Meandros de Uruñuela','Corredor fluvial donde el río Najerilla se ensancha depositando grandes masas de cantos rodados y gravas cuarcíticas. El cauce mantiene un corredor forestal denso e ininterrumpido de alisos y sauces que forma un cinturón vegetal continuo de alto valor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26161','espacio','Sierra de Alcarama / Barranco de Valdemadera','Paisaje montañoso agreste de carácter inhóspito constituido por areniscas y calizas con una fuerte erosión hídrica en la Rioja Baja. Las vertientes de pendientes extremas están cubiertas de brezales, matorrales xerófilos y encinares de roca adaptados a la sequedad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','espacio','Sierra de la Demanda / Dehesa de Valgañón / Barranco de Iguareña','Relieve prepirenaico de alta montaña caracterizado por un relieve abrupto de fuertes desniveles, peñascos y barrancos profundos sobre materiales silíceos. Las faldas montañosas albergan un majestuoso e histórico acebedal y hayedos puros de gran interés.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26164','espacio','Sierra de Urbión / Valle del río Urbión / Cuenca del Najerilla','Alta montaña alpina modelada por procesos glaciares y periglaciares sobre areniscas y conglomerados paleógenos. Cuenta con circos glaciares, canchales de piedra verticales y riachuelos torrenciales de aguas heladas rodeados de hayedos y pastizales subalpinos.   Ventas de Baños • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26163','espacio','Lomas de Ventosa / Barranco de San Juan','Topografía de lomas suaves arcillosas que descienden desde la serranía hacia la cuenca central. Las pequeñas canales acumulan humedad estacional, permitiendo la presencia de matorral de quejigo aclarado y matorral mediterráneo aromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','espacio','Peñas de Viguera / Hoz del río Iregua / Cueva de San Esteban','Uno de los paisajes geológicos más monumentales de la cordillera, caracterizado por colosales e imponentes murallas de conglomerados rojizos que se desploman verticalmente cientos de metros sobre el río Iregua. Las umbrías y repisas rocosas albergan encinares de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26168','espacio','Valle bajo del río Iregua / Cortados de Villamediana','Topografía horizontal de terrazas aluviales cuaternarias compuestas por gravas, que presenta pequeños escarpes erosionados sobre margas en la margen derecha del río Iregua. Ofrece una franja de sotos ripícolas continuos compuestos por sauces negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26166','espacio','Sierra de Cantabria (Faldas) / Barranco de Esperamalo','Relieve de transición entre los escarpes calizos montañosos de la sierra de Cantabria y las llanuras de la Rioja Alta. Presenta pequeñas formaciones de encinar mediterráneo arbustivo y quejigar adaptadas a suelos calcáreos pedregosos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26167','espacio','Valle del río Oja / Lomas de Villalobar','Paisaje geomorfológico horizontal caracterizado por terrazas fluviales cuaternarias y depósitos aluviales de cantos rodados finos. El curso del río Oja aporta una franja estrecha pero continua de vegetación de ribera y carrizales dispersos.   Villalonso • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26169','espacio','Cañón del río Iregua / Riberas del riachuelo Vadillos','Relieve montañoso abrupto en el Camero Nuevo con valles estrechos esculpidos sobre calizas jurásicas por el encajonamiento del río Iregua. Las vertientes de umbría atesoran masas compactas de quejigos, hayedos y encinares de roca de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26170','espacio','Llanos del Cidacos / Barranco de la Fuente','Topografía de lomas suaves arcillosas degradadas orientadas hacia la cuenca baja de la Rioja Baja.   Cuenta con arroyos estacionales acompañados de cañaverales aislados y matorral mediterráneo de romero resistente a la sequía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26171','espacio','Valle del río Tuerto / Lomas de Villar','Suave relieve colinado de la Rioja Alta compuesto por sedimentos arcillosos del neógeno. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las lomas presentan tomillares y restos dispersos de matorral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26172','espacio','Sierra de la Demanda (Estribaciones) / Arroyo de Villarejo','Relieve alomado que sirve de transición hacia las altas cumbres de la cordillera, caracterizado por suelos mixtos de arcilla y cantos rodados. Las laderas albergan brezales secos y pequeñas manchas boscosas de rebollo que aportan valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26173','espacio','Sierra de Yerga / Depresión de Villarroya','Singular cuenca sedimentaria interior flanqueada por relieves calizos, caracterizada por un paisaje de lomas arcillosas fuertemente erosionadas. Presenta restos de dehesas aclaradas de encina mediterránea y matorral adaptado a la oscilación térmica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26174','espacio','Dehesa de Villarta / Altos de la Tejera','Altiplanicie horizontal en el extremo occidental riojano caracterizada por suelos arcillosos con cantos rodados cuarcíticos. Las vaguadas sombrías conservan pequeñas manchas boscosas de rebollo adaptadas al clima continentalizado de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26175','espacio','Sierra de la Demanda / Cañón del río Neila / Pico San Lorenzo','Paisaje alpino de alta montaña modelado sobre pizarras y areniscas, caracterizado por circos de origen glaciar y profundos valles encajonados. El curso alto del río Neila discurre encajonado de forma torrencial entre hayedos puros, acebedas y pastizales subalpinos salvajes.   嶄llamediana • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','espacio','Parque Natural Sierra de Cebollera / Hoyos de Iregua / Achichuelo','Espectacular entorno alpino de alta montaña caracterizado por circos, morrenas y valles de un perfecto modelado glaciar cuaternario. Alberga los mayores y más puros pinares silvestres de la provincia, colosales hayedos y riachuelos torrenciales de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','espacio','Cañón del río Urbión / Sierra de Urbión / Peñas de Viniegra','Impresionante tajo geológico con paredes de cuarcitas y areniscas verticales de varios cientos de metros de altura esculpido por el río Urbión. El relieve es totalmente abrupto y salvaje, flanqueado por hayedos puros y pastizales subalpinos de una gran potencia escénica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26179','espacio','Sierra de Urbión / Nacimiento del río Ormazal / Hoyo Mayor','Paisaje de alta montaña alpina caracterizado por un relieve abrupto modelado por procesos periglaciares sobre areniscas y conglomerados. Las faldas montañosas están cubiertas por extensos piornales, sabinares rastreros de altura y brezales de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','espacio','Llanura de la Rioja Alta / Arroyo de San Martín','Topografía monótona y horizontal sobre glacis cuaternarios y depósitos aluviales finos de la comarca. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales con juncos que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26181','espacio','Sierra de Cameros / Barranco de Zarzosa / Valle del Manzanares','Relieve montañoso abrupto en el Camero Viejo con valles estrechos esculpidos sobre calizas por arroyos temporales. Las vertientes de umbría conservan manchas de encina carrasca y un notable matorral aromático de romero adaptado al sustrato calcáreo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26183','espacio','Sierra de la Demanda / Valle del río Ciloria / Monte de San Lorenzo','Relieve alomado y quebrado que sirve de piedemonte a las altas cumbres de la Demanda, surcado por el río Ciloria de aguas cristalinas. Las laderas de fuerte pendiente están densamente cubiertas por hayedos puros y robledales de melojo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90485','espacio','Sierra de Gata / Valle del río Agueda / Barranco del Payo','Relieve abrupto de media montaña integrado en la vertiente norte del macizo de Gata, caracterizado por fuertes pendientes sobre pizarras. Las laderas de umbría atesoran masas forestales compactas de robles melojos y pinos silvestres, surcados por arroyos de montaña de aguas sumamente puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90486','espacio','Parque Natural de Arribes del Duero / Cañón del río Agueda','Espectacular e imponente encajonamiento fluvial donde el río Águeda corta transversalmente la penillanura granítica en un profundo desfiladero de paredes   verticales de pizarra. La umbría orográfica y el microclima permiten la proliferación de enclaves relictos de alcornoques, enebros y almendros silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90487','espacio','Riberas del río Tormes / Cañón del río Uces (Estribaciones)','Relieve colinado de transición caracterizado por la presencia de grandes bloques graníticos y penedos redondeados por la meteorización química. Los valles interiores albergan arroyos encajonados poblados por densas masas de matorral mediterráneo de escoba y encinas de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90498','espacio','Ribera del arroyo de la Alamedilla / Frontera lusa','Topografía ondulada modelada sobre pizarras y areniscas en el extremo occidental de la provincia, caracterizada por pequeños valles de erosión. El cauce mantiene un corredor forestal estrecho pero continuo de sauces y fresnos que destaca visualmente sobre las lomas desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90488','espacio','Riberas del río Tormes / Isla de Garcilaso / Meandro de Alba','Amplia vega de inundación aluvial donde el río Tormes ensancha su lecho dejando depósitos masivos de gravas y arenas cuaternarias. Cuenta con sotos ripícolas continuos muy frondosos poblados por álamos blancos, chopos negros y grandes extensiones de carrizal estable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90489','espacio','Riberas del río Yeltes / Dehesa de Alba','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas cuarcíticas que drenan hacia la cuenca del Yeltes. El entorno forestal está dominado por un denso rebollar de roble melojo que se integra con las encinas en un paisaje adehesado continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle de las Batuecas / Peña de Francia','Majestuoso entorno alpino de alta montaña caracterizado por un relieve totalmente abrupto y escarpado de cuarcitas que se desploman en profundos valles recónditos. Alberga espectaculares bosques mixtos de castaños, robles melojos y madroñales relictos, surcados por ríos torrenciales de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90490','espacio','Dehesa del Campo de Argañán / Arroyo de la Alberguería','Altiplanicie de transición hacia la sierra caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas orientadas a la umbría conservan masas compactas y bien estructuadas de quejigares y encinares mediterráneos arbustivos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90491','espacio','Riberas del río Almar','Paisaje completamente horizontal sobre la llanura aluvial de Tierra de Peñaranda, con suelos arcillosos expuestos a una intensa insolación. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales con eneas que rompen la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37015','espacio','Valle del río Turones / Ribera de Dos Casas','Relieve suave de ladera pizarrosa que desciende de manera escalonada hacia el lecho de la frontera fluvial. Presenta sotos de ribera bien estructurados con alisos, sauces y un denso sotobosque de helechos que colonizan las umbrías húmedas de los barrancos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90492','espacio','Sierra de Candelario / Valle del río Cuerpo de Hombre','Vertiente de pendientes moderadas constituida por materiales graníticos que desciende hacia la cuenca del Alagón. Las faldas montañosas albergan excelentes masas forestales de roble melojo, castañares maduros y pequeños riachuelos de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37014','espacio','Parque Natural de Arribes del Duero / Pozo de los Humos / Cañón del Duero','Uno de los paisajes geológicos más sobrecogedores y colosales de la península, donde el Duero hiende la penillanura en un cañón granítico con paredes verticales de más de cuatrocientos metros de caída a plomo. Destaca el Pozo de los Humos, un imponente salto de agua vertical del río Uces de cincuenta metros de altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37016','espacio','Riberas del río Tormes / Vega de Aldealengua','Tramo aluvial maduro donde el río Tormes discurre sobre depósitos cuaternarios de arenas y gravas finas cerca de la capital. Ofrece una franja de sotos ripícolas continuos compuestos por sauces negros, chopos y abundantes praderas húmedas de fondo de valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37017','espacio','Llanura de La Guareña / Arroyo de la Encina','Topografía monótona y horizontal sobre glacis cuaternarios en el extremo nororiental salmantino. La presencia de pequeñas corrientes de agua estacionales   genera pequeñas áreas higrófilas estacionales cubiertas de juncos que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37018','espacio','Sierra de Francia (Faldas norteñas) / Pico del Cervero','Relieve prepirenaico de fuerte pendiente constituido por cuarcitas y pizarras, que marca el inicio de la serranía. Las laderas orientadas a la umbría atesoran masas forestales densas de roble melojo y brezales húmedos de gran colorido estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37019','espacio','Campo de Ledesma / Arroyo de la Valmuza','Suave relieve colinado labrado sobre arcillas y margas por arroyos modestos. Los fondos de valle acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37020','espacio','Vega del río Tormes / Sotos de Aldearrubia','Sector medio de la llanura de inundación del Tormes caracterizado por depósitos de gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y álamos forman un cinturón vegetal continuo de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37021','espacio','Vega de Alba / Arroyo de Mazarros','Topografía de lomas suaves arcillosas degradadas orientadas hacia la cuenca del Tormes. Presenta pequeñas corrientes de agua estacionales acompañadas de juncos y gramíneas aisladas que rompen la homogeneidad del paisaje agrario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37022','espacio','Llanura cerealista de Peñaranda','Paisaje completamente horizontal asentado sobre arcillas y limos terciarios en la llanura oriental. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales cubiertas de juncos que rompen la llanura uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37023','espacio','Riberas del río Zurguén','Cuenca fluvial de relieve suave labrada sobre sedimentos terciarios de la zona central salmantina. El fondo del valle está ocupado por praderas húmedas estacionales y pequeñas franjas de sauces que escoltan el curso del arroyo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37024','espacio','Riberas del río Tormes / Cola del Embalse de Santa Teresa','Tramo donde el río Tormes se remansa en una amplia cubeta sedimentaria flanqueada por suaves colinas graníticas. Las márgenes albergan un mosaico visual compuesto por madrejones abandonados, carrizales permanentes y sotos de saucedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37025','espacio','Campo Charro / Arroyo de la Bóveda','Topografía de lomas suaves arcillosas que descienden hacia la cuenca central salmantina. Las pequeñas canales acumulan humedad estacional, permitiendo la presencia de matorral de encina y quejigo aclarado en régimen de dehesa tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37026','espacio','Espacio Natural Protegido de las Lagunas de El Bodón y Aldehuela / Río Yeltes','Excepcional complejo lagunar de origen endorreico sobre llanuras arcillo-arenosas con costras de raña. Destaca por albergar espectaculares láminas de agua de carácter estacional rodeadas de densos cinturones de juncos, eneas y un majestuoso melojar de fondo de valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37027','espacio','Riberas del río Tormes / Sotos de Almenara / Islas fluviales','Tramo de corredor fluvial trenzado donde el río Tormes se divide en multitud de brazos secundarios generando islas sedimentarias de gran valor ecológico. Los márgenes y las islas albergan un frondoso bosque de ribera con alnos, fresnos y álamos de gran plasticidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37029','espacio','Dehesas de Anaya / Arroyo de Alconada','Suave relieve colinado de transición caracterizado por sedimentos arcillosos del neógeno. El arroyo aporta una franja estrecha de vegetación ripícola con sauces negros y eneas aisladas en mitad de un paisaje de dehesas ganaderas de encina y quejigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37030','espacio','Cortados del río Tormes / Monte de Añover','Tramo donde el río Tormes se encajona en la penillanura labrando pequeños escarpes y cortados rocosos sobre gneis y granitos. Las laderas orientadas al norte conservan manchas dispersas de encinar mediterráneo termoatlántico con sotos fluviales al pie.   Arabiay • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37033','espacio','Llanura de La Armuña / Arroyo de la Encina','Paisaje completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37034','espacio','Lomas de El Arco / Campo de Ledesma','Topografía de lomas suaves arcillo-arenosas con presencia de cantos rodados cuarcíticos. Las laderas albergan brezales secos, escobas y pequeñas manchas boscosas de encina que sirven de transición hacia las penillanuras del Tormes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37035','espacio','Dehesa de Armenteros / Riberas del río Revilla','Relieve ondulado sobre depósitos de rañas y cantos rodados que configuran un paisaje de transición adehesada. El curso fluvial está escoltado por un corredor estrecho de sauces y un encinar mediterráneo aclarado adaptado al suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37038','espacio','Riberas del río Almar / Manantiales de aguas minerales','Llanura aluvial de modelado horizontal donde destaca la presencia de fracturas del terreno por las que brotan aguas de fuerte mineralización. El cauce del río Almar aporta una franja húmeda con sauces y juncos que contrasta cromáticamente con las lomas arcillosas del entorno.   Bárcila de la Abadía • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37040','espacio','Campo Charro / Arroyo de la Valmuza','Relieve horizontal propio de la penillanura salmantina sobre sustratos compactos de pizarra y arcilla. Conserva masas dispersas de encinar en régimen de dehesa que se intercalan con pequeñas charcas ganaderas y praderas de inundación estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37041','espacio','Campo Charro / Dehesa de Barbalos / Río Alagón (Cabecera)','Paisaje adehesado maduro caracterizado por un relieve de lomas muy suaves y onduladas con suelos pedregosos. El término municipal alberga las primeras vaguadas de escorrentía que dan origen a la red hidrográfica del Alagón, escoltadas por encinas centenarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37042','espacio','Riberas del río Huebra / Arribes menores','Tramo de penillanura que empieza a resquebrajarse en pequeños escarpes de roca granítica conforme se aproxima a la cuenca del Huebra. Presenta barrancos estrechos cubiertos por matorrales mediterráneos densos de escoba, tomillo y encinas adaptadas a las grietas de la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37044','espacio','Arribes del río Huebra / Cueva de la Mora / Filas de penedos graníticos','Paisaje kárstico-granítico caracterizado por un relieve caótico de grandes bolos de piedra moldeados por la erosión química y fracturas tectónicas. Las laderas descienden con fuerte pendiente hacia el encajonamiento del río Huebra, albergando una densa vegetación arbustiva mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37047','espacio','Riberas del río Tormes','Valle fluvial aluvial maduro donde el río Tormes discurre entre terrazas cuaternarias de gravas y limos finos. Las márgenes mantienen una franja bien conservada de bosque de ribera con chopos negros y sauces que aportan frescura visual en la penillanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37049','espacio','Parque Natural de Arribes del Duero / Cañón del río Camaces y río Huebra','Espectacular confluencia fluvial donde los ríos Huebra y Camaces excavan profundas y grandiosas gargantas sobre el sustrato granítico de la penillanura. El relieve muestra escarpes verticales de roca desnuda e imponentes farallones rocosos tapizados por enebros, alcornoques y jarales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37050','espacio','Riberas del río Huebra / Berrocal granítico de la dehesa','Relieve colinado de fuerte personalidad geológica debido a la abundancia de bloques de granito redondeados y amontonados por la erosión. El río Huebra discurre encajonado entre el lecho de piedra, escoltado por un denso encinar mixto con sotos de fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37051','espacio','Sierra de las Quilamas (Estribaciones) / Berrocal del caño','Paisaje de transición montañosa caracterizado por una elevada densidad de penedos graníticos y bolos de piedra exentos. Las laderas umbrías conservan manchas forestales jóvenes de roble melojo que colonizan los suelos pedregosos de la serranía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37052','espacio','Campo del Yeltes / Arroyo de la Nava','Topografía de lomas suaves arcillosas degradadas orientadas hacia la cuenca hidrográfica del río Yeltes. Presenta pequeñas cubetas endorreicas estacionales que acumulan eneas y juncos, rompiendo la horizontalidad de las dehesas aclaradas de encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37054','espacio','Espacio Natural Protegido de las Lagunas de El Bodón / Riberas del río Águeda','Excepcional complejo lagunar intermitente asentado sobre una llanura de raña con suelos arcillosos impermeables. La cubeta principal genera una espectacular lámina de agua rodeada por cinturones concéntricos de juncos y un denso bosque de roble melojo maduro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37055','espacio','Campo de Yeltes / Riberas del río Yeltes','Tramo aluvial donde el río Yeltes discurre de manera sinuosa sobre depósitos de cantos rodados cuarcíticos. Las márgenes albergan sotos ripícolas continuos compuestos por sauces negros y fresnos que destacan en mitad del relieve llano adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37056','espacio','Parque Natural de Arribes del Duero / Barranco del río Turones / Frontera lusa','Relieve quebrado en el extremo occidental de la provincia, caracterizado por una profunda incisión fluvial excavada sobre pizarras y areniscas. Las vertientes de fuerte pendiente albergan comunidades arbustivas mediterráneas y densos matorrales de jara adaptados a la escasez hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37058','espacio','Campo de Ledesma / Riberas del arroyo de la Valmuza','Paisaje típico de la penillanura central salmantina con lomas y cerros testigo sobre bases graníticas meteorizadas. Las vaguadas conservan dehesas bien estructuradas de encina y pequeños núcleos de sauces que acompañan las corrientes de agua temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37059','espacio','Campo Charro / Dehesa de Buenamadre / Arroyo de la dehesa','Topografía monótona y horizontal sobre sedimentos arcillosos neógenos caracterizados por una intensa explotación ganadera. Las pequeñas canales   acumulan humedad estacional permitiendo la presencia de matorral de encina y pastizales húmedos bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37060','espacio','Cuenca alta del río Tormes / Lomas de Cuatro Calzadas','Elevación orográfica de perfil redondeado que actúa como divisoria de aguas, ofreciendo un relieve expuesto a una intensa insolación. Las vertientes protegidas albergan masas compactas de quejigares y encinares mediterráneos que colonizan el suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37061','espacio','Sierra de Francia / Las Cavenes (Entorno Geológico) / Arroyo de la Gabia','Espacio de media montaña sobre calizas y pizarras donde destaca un paleorrelieve modificado por antiguas explotaciones mineras romanas. Las profundas zanjas y montículos de cantos rodados están completamente cubiertos por un denso bosque de roble melojo, castaños y brezales de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37065','espacio','Parque Natural de Arribes del Duero / Cañón del río Uces / Cascadas de la Fuente Santa','Espectacular e imponente desfiladero granítico donde el río Uces hiende la penillanura antes de su desembocadura. El relieve es totalmente abrupto, caracterizado por canchales caóticos de bolos de piedra, pequeñas cascadas encajonadas en la roca y una exuberante vegetación de enebros y encinas rupícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37062','espacio','Llanura de La Armuña / Arroyo de la Encina','Topografía completamente horizontal asentada sobre limos y arcillas cuaternarias del neógeno. La escorrentía superficial es de carácter estrictamente temporal, generando   pequeñas zonas de humedad estacional cubiertas de gramíneas que rompen la homogeneidad cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37067','espacio','Escarpes del río Tormes / Vega de Cabrerizos','Imponentes taludes y cortados de areniscas rojizas que caen con fuerte pendiente sobre el margen derecho de la cuenca baja del Tormes. Ofrece una sección geológica perfecta de terrazas aluviales combinada con sotos maduros de sauces y chopos negros en el fondo de la vega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37068','espacio','Campo de Yeltes / Arroyo de la Gavilana','Relieve horizontal propio de la penillanura salmantina central con suelos arcillo-pedregosos cuarcíticos. Las pequeñas vaguadas acumulan la humedad invernal y permiten la existencia de encinares aclarados en régimen de dehesa ganadera tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37069','espacio','Riberas del río Tormes / Soto de la Isla / Acequias de regadío naturalizadas','Valle aluvial maduro caracterizado por depósitos masivos de arenas y gravas finas cuaternarias. Cuenta con un soto de ribera continuo poblado por álamos blancos, chopos y densos cinturones de eneas que aprovechan los antiguos madrejones del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37070','espacio','Cerros de la Peña de Arias / Páramo de Calvarrasa','Elevación orográfica en forma de cerro testigo que destaca de manera aislada sobre la penillanura aluvial de Salamanca. Presenta laderas erosionadas con pequeños canchales que albergan un encinar mediterráneo arbustivo adaptado a la sequedad y los suelos pobres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37072','espacio','Campo Charro / Arroyo de la Valmuza','Paisaje penillanura horizontal sobre materiales arcillosos del terciario eoceno. Destaca por albergar un bosque adehesado de encinas centenarias bien estructurado, donde el suelo llano da paso a pequeñas dehesas y pastizales ganaderos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37073','espacio','Riberas del arroyo de la Encina / Lomas de Valdunciel','Topografía de lomas suaves arcillo-arenosas degradadas que marcan la transición hacia el norte de la provincia. Los arroyos temporales mantienen estrechas franjas de juncos y espadañas que aportan variedad cromática al entorno cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37074','espacio','Campo de Azaba / Riberas del río Azaba','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas cuarcíticas que drenan hacia la cuenca del Águeda. El entorno forestal está dominado por masas muy compactas de dehesas mixtas de encina y roble rebollo de gran madurez botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37077','espacio','Llanura de Peñaranda / Arroyo de la Vega','Paisaje completamente horizontal asentado sobre arcillas y sedimentos terciarios en la llanura oriental salmantina. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','espacio','Sierra de Candelario / Espacio Natural Protegido de Candelario / Nacimiento del río Cuerpo de Hombre / Hoya Moros','Espectacular y majestuoso paisaje alpino de alta montaña dominado por un relieve quebrado de origen glaciar con circos, morrenas e imponentes agujas graníticas desnudas. Alberga inmensos hayedos relictos, pinares   silvestres y cascadas de aguas de deshielo que descienden de forma torrencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37079','espacio','Campo Charro / Lomas de Canillas','Topografía de lomas suaves arcillosas que descienden hacia la cuenca central de la provincia. Las pequeñas canales acumulan la humedad estacional y permiten el desarrollo de encinares arbustivos mediterráneos aclarados en régimen de dehesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37080','espacio','Sierra de Béjar / Barranco del regato de Cantagallo','Relieve abrupto de media montaña con vertientes graníticas de fuertes pendientes y densas vaguadas umbrías. Las faldas montañosas están cubiertas por majestuosas masas de bosque atlántico caducifolio dominadas por robles melojos y castaños centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37081','espacio','Humedales de Cantalapiedra / Riberas del río Trabancos','Llanura sedimentaria con suaves depresiones arcillosas que acumulan agua de forma estacional de carácter endorreico. El modesto cauce del Trabancos aporta un estrecho cinturón de vegetación ripícola con sauces y carrizales que rompe la aridez cerealista.   Cantamayor • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37083','espacio','Cuenca del río Regamón / Lomas de Cantaracillo','Suave relieve colinado labrado sobre arcillas y margas de la comarca oriental por arroyos modestos. Los fondos de valle acumulan humedad estacional suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37085','espacio','Lomas de la Sagrada / Arroyo de la Valmuza (Cabecera)','Topografía ondulada sobre arcillas cuaternarias rota únicamente por la incisión de arroyos estacionales periurbanos. Estos pequeños cauces acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37086','espacio','Campo de Azaba / Dehesa de Carpio / Arroyo de la Carpa','Altiplanicie de transición caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas orientadas a la umbría conservan masas compactas y bien estructuradas de quejigares y encinares mediterráneos en dehesas tradicionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37087','espacio','Campo Charro / Dehesas de Carrascal / Arroyo de Barregas','Paisaje típico de la penillanura con lomas y cerros de erosión sobre bases graníticas meteorizadas. Las vaguadas conservan dehesas bien estructuradas de encina y pequeños núcleos de sauces que acompañan las corrientes de agua temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37088','espacio','Dehesa de Carrascal del Obispo / Arroyo del Obispo','Topografía monótona y horizontal sobre sedimentos arcillosos neógenos del Campo Charro. Las pequeñas canales acumulan humedad estacional permitiendo la presencia de matorral de encina y quejigo aclarado con pastizales ganaderos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37089','espacio','Sierra de las Quilamas (Faldas orientales) / Arroyo de la dehesa','Relieve de transición montañosa caracterizado por una topografía de suaves cerros y dehesas asentadas sobre sustratos de pizarras y granitos. Conserva masas forestales de roble melojo bien estructuradas que se entrelazan con brezales y escobares de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37090','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Riberas del río Francia','Profundo encajonamiento fluvial excavado sobre pizarras y cuarcitas donde el río Francia discurre de forma torrencial con aguas sumamente cristalinas. El relieve destaca por su fuerte pendiente escarpada y umbría, tapizada por densos bosques de castaños, robles y madroñales relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37091','espacio','Sierra de Gata / Cabecera del río Agueda / Frontera lusa','Relieve de media montaña caracterizado por picos redondeados de pizarra y vertientes abruptas cubiertas de piornales de montaña. Los cursos fluviales altos excavan profundas y estrechas canales cubiertas de robledales de melojo de influencia atlántica pura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37092','espacio','Llanura de La Armuña / Arroyo de Moriscos','Paisaje completamente horizontal asentado sobre arcillas y limos en la llanura cerealista septentrional. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la homogeneidad del paisaje agrario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37185','espacio','Valle del arroyo de la Encina / Lomas de Villiquera','Suave relieve de lomas areniscas labradas por la erosión diferencial en la comarca de la Armuña. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las vertientes expuestas muestran tomillares y pastos secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37096','espacio','Cañón del río Agueda / Yacimiento de Siega Verde (Entorno Natural)','Espectacular y profundo desfiladero fluvial donde el río Águeda corta transversalmente la penillanura caliza y de pizarras, generando farallones verticales de roca grisácea y canchales de ladera. El fondo sombrío alberga una frondosa vegetación mediterránea de ribera con sauces y fresnos negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37097','espacio','Campo de Yeltes / Riberas del río Morasverdes','Tramo medio del río Morasverdes caracterizado por una llanura aluvial con depósitos de gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados de sauces y chopos, integrados en un relieve llano de densas dehesas de encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37002','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle de Cepeda / Arroyo de San Pedro','Impresionante anfiteatro montañoso constituido por pizarras y cuarcitas en la Sierra de Francia, caracterizado por vertientes de fuertes pendientes de perfil escarpado. El relieve alberga las dehesas y frágiles masas de madroñales, castaños milenarios y acebedas más puras del entorno serrano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37099','espacio','Sierra de Francia (Límite Norte) / Cabecera del río Yeltes','Relieve montañoso de transición con vertientes escarpadas y barrancos sinuosos que dan origen a los   primeros aportes fluviales del río Yeltes. Las laderas orientadas a la umbría atesoran masas compactas de robledal de melojo y castañares dispersos sobre suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37100','espacio','Parque Natural de Arribes del Duero / Desfiladero del río Uces / Peñas de la Horcada','Relieve quebrado en las proximidades del cañón del Duero, caracterizado por una profunda incisión fluvial esculpida sobre rocas graníticas. Presenta un relieve de imponentes bloques de piedra redondeados e hilos de agua encajonados cubiertos por matorral mediterráneo denso de escobas y enebros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37101','espacio','Riberas del río Huebra / Dehesa de Cerralbo','Tramo donde el río Huebra empieza a encajonarse levemente entre terrazas de gravas y afloramientos de pizarras en la penillanura occidental. Los márgenes conservan sotos ripícolas bien estructurados con fresnos, alisos y un encinar calcícola perimetral.   Cheles • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37104','espacio','Sierra de Francia / Pico de la Bastida / Arroyo de la dehesa','Relieve de media montaña con vertientes abruptas de cuarcitas que superan los mil metros de altitud, configurando un paisaje quebrado de gran potencia visual. Las umbrías y barrancos secundarios conservan masas muy densas de roble melojo y brezales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37106','espacio','Campo de Ledesma / Riberas del río Cabeza de Diego Gómez / Berrocal granítico','Paisaje característico de la penillanura granítica salmantina con abundancia de bloques de piedra redondeados debido a la meteorización química de la roca. Las vaguadas albergan arroyos menores rodeados de dehesas maduras de encina y fresnos ripícolas dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37003','espacio','Riberas del río Águeda / Meandro de Ciudad Rodrigo / Charco de la Colada','Amplio corredor fluvial aluvial donde el río Águeda ensancha su cauce y genera una rica llanura de inundación cuaternaria con playas de cantos rodados e islas fluviales. Las márgenes albergan sotos ripícolas continuos muy desarrollados con alisos, chopos negros y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37108','espacio','Tierra de Peñaranda / Arroyo de Mazarros','Topografía de lomas suaves arcillosas degradadas situadas en la zona oriental de la provincia. Presenta pequeños riachuelos estacionales de carácter temporal acompañados de espadañas aisladas que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37109','espacio','Sierra de Béjar (Piedemonte) / Cañón del río Alagón','Paisaje quebrado de media montaña donde el río Alagón empieza a encajonarse en profundas gargantas esculpidas sobre materiales de pizarra. Las laderas escarpadas presentan una interesante vegetación mediterránea mixta con alcornoques, enebros y encinas de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37110','espacio','Riberas del río Almar / Lomas de Cordovilla','Paisaje geomorfológico horizontal de la Tierra de Peñaranda compuesto por terrazas fluviales cuaternarias y depósitos aluviales finos. Ofrece un corredor verde estrecho compuesto por sauces y chopos negros dispersos que aporta variedad al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37121','espacio','Riberas del río Tormes / Vega de Encinas','Sector bajo de la llanura de inundación del Tormes caracterizado por extensos depósitos aluviales de arenas y gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados donde los sauces y álamos forman un denso cinturón vegetal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37122','espacio','Riberas del río Tormes / Dehesa de Encinas','Tramo fluvial de la cuenca media del Tormes asentado sobre terrazas aluviales de gravas cuaternarias. Las laderas marginales del valle presentan suaves ondulaciones cubiertas por encinares adehesados maduros que se asoman al soto continuo de sauces y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37123','espacio','Arribes del río Huebra / Arroyo de las Fuentes','Relieve granítico penillanante que se deprime con suavidad hacia el encajonamiento occidental de la provincia. Muestra penedos y bolos rocosos redondeados rodeados de pastizales y matorral mediterráneo de jara y escoba que coloniza las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37124','espacio','Las Quilamas (Piedemonte) / Riberas del río Alagón / Barranco de las Palomas','Paisaje de transición montañosa con un relieve ondulado modelado sobre pizarras y areniscas. El curso alto del río Alagón discurre encajonado de forma sinuosa por el término, flanqueado por dehesas de encina, robledales de quejigo y fresnedas ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37125','espacio','Sierra de Francia (Vertiente Norte) / Pico de Caramocho / Arroyo de San Benito','Relieve de media montaña con vertientes abruptas de cuarcitas y pizarras que marcan el perfil septentrional de la sierra. Las umbrías atesoran frondosos bosques de castaños y robles melojos intercalados con extensos brezales y piornales de gran valor cromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37126','espacio','Campo de Ledesma / Arroyo de Espadaña','Relieve de penillanura horizontal sobre materiales graníticos con abundantes afloramientos de piedra exenta. Las pequeñas vaguadas acumulan la humedad estacional y dan origen a juncales y espadañares densos que contrastan con el encinar aclarado de la dehesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37128','espacio','Llanura de La Guareña / Arroyo de la Mina','Paisaje completamente horizontal situado en el extremo nororiental de la provincia, constituido por arcillas y limos miocenos. La escorrentía superficial es de carácter temporal y genera pequeñas franjas higrófilas estacionales que rompen la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37129','espacio','Cortados del río Tormes / Sotos de Florida','Imponentes taludes erosionados de areniscas de color rojizo que caen sobre la margen derecha de la llanura aluvial del Tormes. Ofrece una sección geológica nítida combinada en su base con un soto maduro y continuo de sauces negros, chopos y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37130','espacio','Valle del río Cañedo / Lomas de Forfoleda','Suave relieve colinado labrado sobre margas y arcillas compactas por arroyos de régimen estacional. Los fondos aluviales acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37131','espacio','Sierra de las Quilamas (Faldas orientales) / Arroyo de Frades','Relieve ondulado de piedemonte caracterizado por suelos pedregosos cuarcíticos y de pizarra que drenan hacia la cuenca del Alagón. La cubierta vegetal está dominada por masas densas de encina carrasca y robledales jóvenes de quejigo bien estructurados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37132','espacio','Parque Natural de Arribes del Duero / Muelle de Vega Terrón / Desembocadura del río Agueda / Cañón del Duero','Espectacular confluencia fluvial fronteriza donde el río Águeda entrega sus aguas al Duero en un relieve encajonado de proporciones colosales tallado sobre pizarras. Las paredes verticales del cañón albergan enebros silvestres, alcornoques relictos y una de las mayores colonias de aves rupícolas de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37133','espacio','Sierra de Béjar (Estribaciones) / Barranco del río Sangusín','Vertiente montañosa granítica de pendientes moderadas que sirve de transición hacia el macizo de Béjar. El curso del río Sangusín esculpe un valle estrecho poblado por un soto aluvial maduro y laderas cubiertas de melojares y robledales de quejigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37134','espacio','Valle del río Alhándiga / Vega de Fresno','Cuenca aluvial baja modelada por la dinámica del río Alhándiga sobre sedimentos arcilloso-arenosos finos. Muestra un corredor continuo de vegetación ripícola con sauces y juncos que destaca visualmente sobre las lomas suaves y secas de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37135','espacio','Campo Charro / Cuenca del río Huebra / Arroyo de San Esteban','Topografía horizontal de la penillanura central salmantina constituida por arcillas terciarias y dehesas ganaderas tradicionales. El término alberga pequeñas canales de escorrentía estacional que alimentan charcas ganaderas y praderas húmedas rodeadas de encinas centenarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37136','espacio','Espacio Natural Protegido de la Sierra de Gata / Riberas del río Agueda / Dehesa de Fuenteguinaldo','Extenso relieve de transición montañosa hacia el macizo de Gata, caracterizado por un suelo adehesado sobre rañas arcillo-pedregosas. El río Águeda cruza la zona de forma encajonada, flanqueado por inmensas masas boscosas mixtas de encina y roble rebollo de gran pureza botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37137','espacio','Campo de Yeltes / Arroyo de Fuenteliante / Dehesa del Rebollar','Relieve alomado y suave formado por terrazas de rañas arcillosas cuarcíticas que drenan hacia la cuenca del Yeltes. Las laderas orientadas a la umbría conservan masas de melojo y encinares mediterráneos que configuran un tapiz arbolado continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37138','espacio','Sierra de las Quilamas / Pico del Duende / Dehesas de Salvatierra','Elevación orográfica de perfiles redondeados sobre materiales de pizarra que da paso a la comarca serrana. Presenta una topografía de suaves cerros cubiertos de carballeiras y encinares densos alternados con grandes canchales de piedra erosionada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37139','espacio','Sierra de Béjar (Piedemonte) / Nacimiento del río Alagón / Lomas de la Calera','Entorno de media montaña granítica caracterizado por lomas suaves y lapiaces calcáreos donde surgen los primeros arroyos de la cabecera del Alagón. Las vertientes de umbría albergan manchas de roble melojo bien conservadas y pastizales húmedos permanentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37140','espacio','Campo de Argañán / Arroyo de Dos Casas / Frontera lusa','Altiplanicie horizontal en el extremo occidental de la provincia, caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las vaguadas conservan dehesas bien estructuradas de encina y pequeños núcleos de sauces que acompañan los arroyos fronterizos.   Si estás listo para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37141','espacio','Valle del río Gamo / Lomas de Gajates','Paisaje sedimentario horizontal de la Tierra de Alba compuesto por depósitos de arcillas y limos cuaternarios. El cauce modesto del río Gamo aporta una banda estrecha pero continua de carrizales, eneas y pequeños sauces que rompe la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37142','espacio','Campo Charro / Arroyo de la Valmuza','Relieve horizontal representativo de la penillanura salmantina central con suelos arcillo-pedregosos. El término municipal atesora magníficas masas boscosas de encinas centenarias en régimen de dehesa tradicional, salpicadas de pequeñas charcas estacionales para el ganado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37144','espacio','Riberas del río Tormes / Isla de Galisancho','Amplia llanura aluvial de inundación donde el río Tormes ensancha su cauce, ramificándose y generando pequeñas islas sedimentarias de gran valor ecológico. Los márgenes conservan un frondoso soto ripícola compuesto por alnos, fresnos y álamos blancos de gran plasticidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37145','espacio','Campo de Argañán / Riberas del río Azaba','Altiplanicie de transición caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas orientadas a la umbría de la cuenca del Azaba conservan excelentes masas forestales de dehesas mixtas de encina y quejigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37146','espacio','Estribaciones de la Sierra de Gredos / Riberas del río Corneja','Relieve de transición montañosa en el extremo oriental de la provincia, caracterizado por una elevada presencia de bloques graníticos y canchales. El tramo final del río Corneja aporta un soto aluvial maduro con sauces negros y alisos antes de unirse al Tormes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37147','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Garganta del río Alagón / Estanque de la Palla','Impresionante paisaje de media montaña constituido por pizarras y cuarcitas, donde el río Alagón labra profundas hoces encajonadas. Las vertientes escarpadas y umbrías están tapizadas por densos bosques de castaños, robles melojos y madroñales relictos de carácter salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37148','espacio','Vega del río Tormes / Arroyo de la Encina','Topografía horizontal de la llanura de inundación del Tormes compuesta por arenas y gravas finas cuaternarias. Ofrece una perspectiva diáfana con una franja estrecha de saucedas y alamedas que aporta variedad cromática al entorno agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37149','espacio','Campo de Ledesma / Dehesa de Garcirrey / Arroyo de la dehesa','Relieve de penillanura ondulada labrado sobre materiales graníticos con afloramientos dispersos de bolos rocosos. Las vaguadas acumulan la humedad estacional y   dan origen a pequeños juncales rodeados por un bosque adehesado de encina maduro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37150','espacio','Campo de Ledesma / Riberas del río Izcala / Berrocal granítico','Paisaje de fuerte personalidad geológica debido a la abundancia de bloques graníticos redondeados por la meteorización química de la roca. El río Izcala discurre entre el lecho de piedra, escoltado por un denso encinar mixto con sotos de fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37151','espacio','Campo de Ledesma / Arroyo de Golpejas','Topografía de lomas suaves arcillo-arenosas degradadas que marcan la transición hacia las penillanuras del Tormes. Los arroyos de régimen estacional mantienen estrechas franjas de juncos y espadañas que aportan variedad visual al entorno adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37152','espacio','Llanura de La Armuña / Lomas de Gomecello','Paisaje completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37154','espacio','Vitigudino (Comarca) / Riberas del río Huebra / Berrocal de Guadramiro','Relieve granítico penillanante caracterizado por la presencia de grandes penedos y bolos de piedra redondeados por la erosión. Las laderas descienden suavemente hacia la cuenca del Huebra, rodeadas de pastizales y matorral mediterráneo de escoba.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37155','espacio','Cañón del río Tormes / Cortados de Guijo / Cola del Embalse de Guijo','Espectacular desfiladero natural donde el río Tormes corta de forma transversal las estructuras graníticas de la penillanura. El entorno fluvial presenta una imponente visual de peñas verticales y canchales de piedra desnuda, coronados por vegetación mediterránea termófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37156','espacio','Sierra de las Quilamas (Estribaciones) / Lomas de Guijuelo','Elevación orográfica de perfiles redondeados sobre materiales de pizarra que actúa como divisoria de aguas en la comarca de Salvatierra. Las vertientes expuestas muestran matorrales mediterráneos y encinares aclarados adaptados a suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37157','espacio','Sierra de Gata / Valle del río Agueda','Relieve prepirenaico modelado sobre pizarras y areniscas con un marcado perfil de montaña media. Las laderas expuestas a la umbría atesoran masas forestales compactas de melojo, mientras que el curso alto del río Águeda aporta un corredor aluvial puro de aguas frías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37158','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Haya de Herguijuela / Valle del río Alagón','Impresionante relieve alpino caracterizado por profundas gargantas cuarcíticas que cobijan el ejemplar milenario del Haya de Herguijuela, una rareza botánica relicta a baja altitud. Las escarpas verticales albergan madroñales colosales y bosques mixtos de castaño de gran belleza contemplativa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37159','espacio','Campo de Salvatierra / Riberas del río Alagón','Topografía alomada asentada sobre materiales de transición pizarrosos y graníticos. Las dehesas de encina se entremezclan con quejigares jóvenes en las umbrías, mientras el relieve desciende suavemente hacia los primeros encajonamientos fluviales del Alagón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37004','espacio','Parque Natural de Arribes del Duero / Cachón de Camaces / Confluencia del Duero y Huebra','Uno de los paisajes geomorfológicos más salvajes y sobrecogedores de la cuenca, donde los ríos Duero, Huebra y Camaces hienden el granito en desfiladeros verticales de más de trescientos metros de caída. Cuenta con imponentes coladas de canchales y el espectacular salto estacional del Cachón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37161','espacio','Sierra de Béjar (Estribaciones) / Cañón del río Alagón','Profunda incisión fluvial esculpida por el río Alagón sobre materiales esquistosos y pizarras duras. El relieve presenta una fuerte pendiente escarpada con farallones rocosos donde proliferan encinares de roca calcícola, alcornoques relictos y matorral mediterráneo.   Hoyos (Los) • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37172','espacio','Espacio Natural Protegido de las Quilamas / El Bosque de la Honfría','Majestuoso anfiteatro montañoso de la sierra caliza y cuarcítica tapizado por uno de los bosques mixtos más ricos de Salamanca. Alberga ejemplares monumentales de castaños, acebos relictos y robles melojos alimentados por constantes surgencias de agua cristalina de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37007','espacio','Abadengo / Berrocal del río Camaces / Las Cavenes','Paisaje granítico penillanante caracterizado por la presencia de grandes "penedos" y bolos de piedra redondeados por la meteorización química. El relieve se deprime hacia la cuenca del Camaces, flanqueado por dehesas de encina madura y matorrales de escoba.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37174','espacio','Tierra de Peñaranda / Arroyo de la Manta','Paisaje monótono y horizontal asentado sobre arcillas terciarias en la estepa cerealista oriental. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales cubiertas de juncos que rompen la homogeneidad del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37176','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle del río Francia','Paisaje montañoso abrupto caracterizado por laderas de pendientes extremas esculpidas sobre pizarras y cuarcitas. El entorno hace honor a su nombre con una altísima densidad de madroños relictos que conviven de forma salvaje con espesos castañares y robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37178','espacio','Valle del río Gamo / Lomas de Malpartida','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en la Tierra de Peñaranda. Ofrece una perspectiva diáfana donde el curso del río Gamo aporta una franja modesta de vegetación ripícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37179','espacio','Riberas del río Zamayón / Lomas de Mancera','Paisaje geomorfológico horizontal de la Tierra de Peñaranda compuesto por terrazas fluviales cuaternarias y depósitos aluviales finos. Ofrece una perspectiva diáfana donde el curso del arroyo aporta una franja estrecha de sauces negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37180','espacio','Riberas del río Uces / Lomas del Manzano','Relieve de penillanura que empieza a resquebrajarse en pequeños escarpes de roca granítica conforme se aproxima al cañón de Arribes. Presenta barrancos estrechos cubiertos por matorrales mediterráneos densos de escoba, tomillo y encinas adaptadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37181','espacio','Sierra de Gata / Riberas del río Agueda / Barranco de Martiago','Relieve abrupto de media montaña integrado en la vertiente norte del macizo de Gata, caracterizado por fuertes pendientes sobre pizarras. Las laderas de umbría atesoran masas forestales compactas de robles melojos y pinos, surcados por arroyos de aguas sumamente puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37184','espacio','Parque Natural de Arribes del Duero / Pozo de los Humos (Vertiente Oriental) / Cola de Caballo / Cañón del Duero y Uces','Uno de los enclaves geológicos más sobrecogedores del noroeste peninsular. El relieve de la penillanura se rompe abruptamente en colosales farallones graníticos donde el río Uces se desploma en el Pozo de los Humos, un salto vertical de cincuenta metros rodeado de encinares rupícolas de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37186','espacio','Campo de Ledesma / Dehesas de La Mata / Arroyo de la Valmuza','Paisaje penillanura horizontal sobre sustratos de granito degradado con abundantes afloramientos de piedra exenta. Las dehesas de encinas centenarias dominan el relieve, combinadas con praderas ganaderas e incisiones fluviales menores estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37187','espacio','Campo Charro / Valle del río Valmuza','Topografía de lomas suaves arcillosas que descienden hacia la cuenca central de la provincia. Las pequeñas canales acumulan la humedad estacional y permiten el desarrollo de encinares arbustivos mediterráneos aclarados en régimen de dehesa ganadera tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37188','espacio','Riberas del río Tormes / Cola del Embalse de Santa Teresa / Peñas de La Maya','Relieve alomado que asoma al cauce del Tormes, caracterizado por escarpes de roca granítica y sedimentos arenosos finos. El embalse genera amplias láminas de agua rodeadas por un denso cinturón vegetal de carrizales y encinares aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37189','espacio','Sierra de las Quilamas (Faldas septentrionales) / Arroyo de Membribe','Relieve ondulado de piedemonte que marca el inicio de las primeras elevaciones paleozoicas de la comarca serrana. Las vaguadas y umbrías conservan manchas boscosas de quejigos y robles melojos mezcladas con encinares mediterráneos rústicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37190','espacio','Parque Natural de Arribes del Duero / Mirador de la Code (Escarpes naturales) / Cañón del Duero','Espectacular y colosal fractura tectónica donde el río Duero discurre fuertemente encajonado entre paredes graníticas verticales de más de trescientos metros de caída. La umbría orográfica y el microclima propician el desarrollo de densos bosques de alcornoque, enebro y encinas de roca de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37191','espacio','Arribes menores / Riberas del río Huebra','Tramo donde el río Huebra empieza a encajonarse levemente entre terrazas de gravas y afloramientos de pizarras en la penillanura occidental. Los márgenes conservan sotos ripícolas bien estructurados con fresnos, alisos y un encinar calcícola perimetral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37192','espacio','Cuenca del río Zurguén / Lomas de Miranda','Suave relieve colinado de la comarca de la Sagrada labrado sobre arcillas compactas por arroyos estacionales. Presenta pequeñas franjas de sauces y praderas húmedas de fondo de valle que rompen la aridez de las dehesas aclaradas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37008','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Confluencia del río Francia y San Benito','Imponente atalaya rocosa rodeada por los valles encajonados de los ríos Francia y San Benito, tallados sobre pizarras cambrianas. El relieve presenta vertientes escarpadas de gran frondosidad botánica cubiertas por frágiles masas de castaños, robles melojos y madroñales relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37009','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle del río Milano / Bosque de los castaños','Entorno montañoso quebrado de la Sierra de Francia, con profundas vaguadas de humedad constante labradas por corrientes torrenciales. Alberga masas forestales sumamente densas y maduras de castaños centenarios y robledales atlánticos puros de enorme valor contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37195','espacio','Sierra de Francia (Extremo Oriental) / Valle del río Sangusín / Cañón del Alagón','Paisaje quebrado de media montaña donde el río Sangusín entrega sus aguas al Alagón en un desfiladero esculpido sobre pizarras. Las laderas escarpadas presentan una densa cubierta forestal mixta con encinas de roca y madroños de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37196','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Cabecera del río Francia','Profundo encajonamiento fluvial excavado sobre pizarras y cuarcitas donde el río Francia discurre de forma torrencial con aguas sumamente cristalinas. El relieve destaca por su fuerte pendiente escarpada y umbría, tapizada por densos bosques de castaños y acebedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37197','espacio','Cañón del río Alagón / Sotos de Monleón','Estrecho tajo geológico excavado por el río Alagón al romper las estructuras graníticas de la penillanura salmantina. Las paredes del desfiladero presentan formas de erosión alveolar y albergan en su fondo un soto de ribera frondoso con alisos y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37198','espacio','Riberas del río Tormes / Cola del Embalse de Almendra / Berrocal granítico','Relieve de penillanura que desciende de manera escalonada hacia las aguas mansas embalsadas del Tormes. Destaca por sus amplios afloramientos de bloques graníticos redondeados (penedos) y matorrales de escoba mezclados con encinares.   Monumento • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37199','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Agujas de Monsagro / Fósiles de las Cuarcitas (Entorno Geológico)','Relieve alpino de alta montaña caracterizado por impresionantes farallones de cuarcita armoricana que conservan icnofósiles marinos expuestos por la erosión. El paisaje muestra canales pedregosas desnudas flanqueadas por densos melojares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37200','espacio','Riberas del río Tormes / Embalse de Santa Teresa (Margen Occidental)','Relieve colinado de naturaleza granítica que suaviza la transición hacia la comarca de Salvatierra. Presenta pequeños cañones fluviales excavados por el río Tormes, cubiertos por masas forestales caducifolias mixtas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37201','espacio','Valle del río Cuerpo de Hombre / Sierra de Béjar (Faldas)','Profunda incisión fluvial tallada por el río Cuerpo de Hombre sobre calizas y granitos, generando paredes verticales cubiertas de vegetación arbustiva. El cauce se caracteriza por rápidos de agua y pozas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37202','espacio','Llanura de La Armuña / Lomas de Monterrubio','Topografía completamente horizontal asentada sobre limos y arcillas cuaternarias del neógeno. La escorrentía superficial es de carácter estrictamente temporal, generando pequeñas zonas de humedad estacional cubiertas de gramíneas que rompen la homogeneidad cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37203','espacio','Campo Charro / Dehesas de Monterrubio / Arroyo de la Cortina','Topografía de lomas suaves arcillosas que descienden hacia la cuenca central de la provincia. Las pequeñas canales acumulan la humedad estacional y permiten el desarrollo de encinares arbustivos mediterráneos aclarados en régimen de dehesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37204','espacio','Sierra de Francia (Vertiente Norte) / Riberas del río Morasverdes','Relieve de media montaña con vertientes abruptas de cuarcitas y pizarras que marcan el perfil septentrional de la sierra. Las umbrías atesoran frondosos bosques de castaños y robles melojos intercalados con extensos brezales y piornales de gran valor cromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37205','espacio','Campo Charro / Lomas de Morille / Arroyo de la Vega','Topografía de lomas suaves de pizarra degradadas que marcan la transición hacia las penillanuras centrales. Los arroyos de régimen estacional mantienen estrechas franjas de juncos y espadañas que aportan variedad visual al entorno adehesado de encinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37207','espacio','Llanura de La Armuña / Lomas de Moriscos','Paisaje completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37208','espacio','Campo de Ledesma / Riberas del río Huebra','Tramo donde el río Huebra discurre de forma sinuosa sobre la penillanura granítica occidental de la provincia. El cauce mantiene un corredor forestal estrecho pero continuo de fresnos y sauces que aporta contraste al relieve llano adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37209','espacio','Campo Charro / Lomas de Mozárbez / Arroyo del Zurguén','Topografía de lomas suaves arcillosas que descienden hacia la cuenca central de la provincia. Las pequeñas canales acumulan la humedad estacional y permiten el desarrollo de encinares arbustivos mediterráneos aclarados en régimen de dehesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37211','espacio','Campo Charro / Cortados del río Huebra','Tramo donde el río Huebra empieza a encajonarse levemente entre terrazas de gravas y afloramientos de pizarras en la penillanura occidental. Los márgenes conservan sotos ripícolas bien estructurados con fresnos, alisos y un encinar calcícola perimetral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37212','espacio','Sierra de Béjar / Valle del río Cuerpo de Hombre / Garganta de Navacarros','Espectacular y majestuoso paisaje alpino de alta montaña dominado por un relieve quebrado de origen   glaciar con circos, morrenas e imponentes agujas graníticas desnudas. Alberga inmensos hayedos relictos, pinares silvestres y cascadas de aguas de deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37214','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Cascada de la Malena / Arroyo de la Nava','Relieve prepirenaico de fuerte pendiente constituido por cuarcitas y pizarras, que marca el inicio de la serranía de Francia. Las laderas orientadas a la umbría atesoran masas forestales densas de roble melojo y castañares dispersos sobre suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37215','espacio','Tierra de Peñaranda / Arroyo de Sotrobal','Paisaje completamente horizontal asentado sobre arcillas y limos en la llanura cerealista oriental. La   escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales con juncos que rompen la llanura uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37216','espacio','Valle del río Gamo / Lomas de Navales','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en la Tierra de Alba. Ofrece una perspectiva diáfana donde el curso del río Gamo aporta una franja modesta de vegetación ripícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37217','espacio','Sierra de Béjar (Piedemonte) / Arroyo de Navalmoral','Laderas montañosas graníticas de pendientes moderadas orientadas hacia la cuenca del Alagón. Las faldas de la sierra conservan carballeiras jóvenes, pastizales húmedos permanentes y formaciones de bolos graníticos de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37218','espacio','Riberas del río Tormes / Berrocal de Navamorales / Límite con Ávila','Paisaje de fuerte personalidad geológica debido a la abundancia de bloques graníticos redondeados por la meteorización química de la roca junto al cauce alto del Tormes. El lecho del río discurre entre el de piedra, escoltado por un denso encinar mixto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37219','espacio','Sierra de las Quilamas / Pico de la Rinconada / Nacimiento del río Quilamas','Elevación orográfica abrupta constituida por cuarcitas y pizarras que definen las cumbres septentrionales del macizo serrano. El relieve se quiebra en escarpes y profundos barrancos sombríos donde nace el río Quilamas entre melojares densos y acebedas.   Navasfrías • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37221','espacio','Sierra de Gata / Espacio Natural Protegido de El Rebollar / Nacimiento del río Agueda / Frontera lusa','Paisaje alpino de alta montaña modelado sobre pizarras y areniscas, caracterizado por el inmenso bosque de roble melojo (Rebollar), uno de los más extensos y puros de la península. El curso alto del río Águeda discurre encajonado de forma torrencial entre hayedos y acebedas relictas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37222','espacio','Llanura de La Armuña / Arroyo de la Encina','Topografía completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37223','espacio','Abadengo / Riberas del río Camaces','Relieve granítico penillanante caracterizado por la presencia de grandes penedos y bolos de piedra redondeados por la erosión. Las laderas descienden suavemente hacia la cuenca del Camaces, rodeadas de pastizales y matorral mediterráneo de escoba.   Orbañanos • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37224','espacio','Llanura de La Guareña / Arroyo de la Mina','Topografía monótona y horizontal sobre glacis cuaternarios en el extremo nororiental salmantino. La presencia de pequeñas corrientes de agua estacionales genera pequeñas áreas higrófilas estacionales cubiertas de juncos que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37225','espacio','Llanura de La Armuña / Arroyo de la Laguna','Topografía completamente horizontal asentada sobre limos y arcillas cuaternarias del neógeno. La escorrentía   superficial es de carácter estrictamente temporal, generando pequeñas zonas de humedad estacional cubiertas de gramíneas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37226','espacio','Riberas del río Tormes / Cañón del río Ledesma (Sector Norte)','Tramo de penillanura granítica que empieza a fracturarse en pequeños escarpes de roca conforme se aproxima al cauce del Tormes. Presenta barrancos estrechos cubiertos por matorrales mediterráneos densos de escoba y encinas adaptadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37228','espacio','Llanura de Peñaranda / Arroyo de la Vega','Paisaje completamente horizontal asentado sobre arcillas y sedimentos terciarios en la llanura oriental salmantina. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37229','espacio','Llanura de La Armuña / Arroyo de la Encina','Topografía completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37230','espacio','Campo Charro / Lomas de Parada / Arroyo de la Valmuza','Relieve horizontal representativo de la penillanura salmantina central con suelos arcillo-pedregosos. El término municipal atesora masas de encinas centenarias en régimen de dehesa tradicional, salpicadas de pequeñas charcas estacionales para el ganado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37231','espacio','Llanura de La Guareña / Arroyo de Rubiales','Topografía monótona y horizontal sobre glacis cuaternarios en el extremo nororiental salmantino. La presencia de pequeñas corrientes de agua estacionales genera pequeñas áreas higrófilas estacionales cubiertas de juncos que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37232','espacio','Llanura oriental / Arroyo de Paradinas','Paisaje de horizontes infinitos asentado sobre arcillas miocenas de la comarca oriental. Presenta pequeños riachuelos estacionales de carácter temporal acompañados de espadañas aisladas que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37233','espacio','Riberas del río Águeda / Dehesas de Pastores','Tramo fluvial donde el río Águeda discurre de forma encajonada entre suaves colinas calizas y pizarras de la comarca de Ciudad Rodrigo. Cuenta con un soto de ribera continuo dominado por alisos y sauces negros que aporta valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37234','espacio','Sierra de Gata / Pico Jálama (Vertiente Norte) / Espacio Natural Protegido de El Rebollar','Relieve abrupto de alta montaña integrado en la vertiente norte del macizo de Gata, caracterizado por fuertes pendientes sobre pizarras y granitos. Las laderas de umbría atesoran masas forestales compactas de robles melojos (rebollos) de valor botánico excepcional, surcados por arroyos puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37235','espacio','Tierra de Alba / Lomas de Pedraza / Arroyo de Mazarros','Topografía de lomas suaves arcillosas degradadas orientadas hacia la cuenca del Tormes. Presenta pequeñas corrientes de agua estacionales acompañadas de juncos y gramíneas aisladas que rompen la homogeneidad del paisaje agrario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37237','espacio','Campo Charro / Dehesas del río Alagón (Cabecera)','Topografía de lomas suaves arcillosas que descienden hacia la cuenca central salmantina. Las pequeñas canales acumulan humedad estacional, permitiendo la existencia de matorral de encina y quejigo aclarado en régimen de dehesa ganadera tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37236','espacio','Valle del río Gamo / Lomas de Pedrosillo','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en la Tierra de Alba. Ofrece una perspectiva diáfana donde el curso del río Gamo aporta una franja modesta de vegetación ripícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37238','espacio','Llanura de La Armuña / Arroyo de la Encina','Topografía completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37240','espacio','Vega del río Tormes / Sotos de Pelabravo','Sector medio de la llanura de inundación del Tormes caracterizado por depósitos de gravas cuaternarias periurbanas. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y álamos forman un cinturón vegetal de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37241','espacio','Campo Charro / Dehesa de Pelarrodríguez','Paisaje penillanura horizontal sobre materiales graníticos y de pizarra del neógeno. Destaca por albergar un bosque adehesado de encinas centenarias bien estructurado, donde el suelo arcillo-pedregoso da paso a pequeñas charcas ganaderas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37242','espacio','Riberas del río Tormes / Embalse de Santa Teresa (Sector Oriental)','Tramo donde el río Tormes se remansa en una amplia cubeta sedimentaria flanqueada por suaves colinas   graníticas. Las márgenes albergan un mosaico de carrizales permanentes, sotos de saucedas y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37243','espacio','Parque Natural de Arribes del Duero / Peña de La Peña / Riberas del río Uces','Imponente mole granítica aislada que emerge de forma espectacular en la penillanura occidental de la provincia. El relieve presenta vertientes de pendientes extremas cubiertas de brezales, matorrales xerófilos y encinares de roca adaptados a la sequedad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37244','espacio','Sierra de Béjar / Puerto de Béjar (Entorno) / Arroyo de la Pizarral','Relieve abrupto de media montaña con vertientes graníticas de fuertes pendientes y densas vaguadas umbrías. Las faldas montañosas están cubiertas por majestuosas masas de bosque atlántico caducifolio dominadas por robles melojos y castaños.   Peñando de Bracamonte • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37246','espacio','Llanura aluvial del río Regamón / Humedal de Peñaranda','Llanura sedimentaria con suaves depresiones arcillosas que acumulan agua de forma estacional de carácter endorreico. Ofrece una pequeña cubeta lagunar naturalizada que sirve de oasis vegetal para eneas y juncos que destacan visualmente en el paisaje plano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37247','espacio','Valle del río Almar / Lomas de Peñarandilla','Paisaje geomorfológico horizontal de la Tierra de Peñaranda compuesto por terrazas fluviales cuaternarias y depósitos aluviales finos. Ofrece un corredor verde estrecho compuesto por sauces y chopos negros dispersos que aporta variedad al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37248','espacio','Campo de Ledesma / Riberas del río Huebra / Berrocal granítico','Paisaje de fuerte personalidad geológica debido a la abundancia de bloques graníticos redondeados por la meteorización química de la roca. El río Huebra discurre entre el lecho de piedra, escoltado por un denso encinar mixto con sotos de fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37249','espacio','Campo de Ledesma / Arroyo de los Peralejos','Topografía de la penillanura granítica occidental caracterizada por la presencia de penedos y bolos rocosos redondeados aislados. Las vaguadas acumulan la humedad estacional y dan origen a pequeños juncales rodeados por un bosque adehesado de encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37250','espacio','Parque Natural de Arribes del Duero / Pozo de los Humos (Vertiente Norte) / Amansa el Duero / Cañón del Duero','Colosal anfiteatro granítico de la penillanura zamorano-salmantina, donde el relieve se quiebra en escarpes verticales de más de trescientos metros. Comparte el majestuoso salto de agua del Pozo de los Humos en el río Uces, un enclave de valor contemplativo e interés geológico excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37251','espacio','Sierra de Béjar (Piedemonte) / Riberas del río Alagón','Paisaje quebrado de media montaña donde el río Alagón empieza a encajonarse en profundas gargantas esculpidas sobre materiales graníticos. Las laderas escarpadas presentan una interesante vegetación mediterránea mixta con alcornoques y encinas de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37252','espacio','Cañón del río Alagón / Sotos de Pinedas / Sierra de Béjar (Faldas)','Espectacular desfiladero natural donde el río Alagón corta de forma transversal las estructuras graníticas de la penillanura. El entorno presenta una imponente visual de   peñas verticales y canchales de piedra desnuda, cubiertos por madroñales y alcornoques relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37253','espacio','Cortados del río Tormes / Sotos del Pino','Imponentes taludes erosionados de areniscas de color rojizo que caen sobre la margen derecha de la llanura aluvial del Tormes. Ofrece una sección geológica nítida combinada en su base con un soto maduro y continuo de sauces negros, chopos y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37254','espacio','Llanura de La Armuña / Arroyo de Pitiegua','Topografía completamente horizontal asentada sobre limos y arcillas cuaternarias del neógeno. La escorrentía superficial es de carácter estrictamente temporal, generando pequeñas zonas de humedad estacional cubiertas de gramíneas que rompen la homogeneidad cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37255','espacio','Campo Charro / Dehesas de Pizarral / Riberas del río Alagón (Cabecera)','Paisaje penillanante horizontal sobre materiales de pizarra del neógeno caracterizado por sus encinares centenarios. Las canales de escorrentía estacional alimentan pequeñas charcas ganaderas rodeadas por un denso bosque de encina maduro bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37256','espacio','Llanura de la Tierra de Peñaranda / Arroyo de las Cintas','Paisaje completamente horizontal asentado sobre sedimentos arcilloso-limosos terciarios en el extremo nororiental de la provincia. Ofrece una perspectiva diáfana rota únicamente por un corredor modesto de vegetación palustre que acompaña las avenidas estacionales del arroyo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37163','espacio','Sierra de Béjar / Macizo de Candelario / Collado de la Hoya','Paisaje de alta montaña alpina modelado por la erosión glaciar, caracterizado por circos, canchales graníticos gigantescos y fuertes pendientes subalpinas. Las laderas están cubiertas de piornales y pastizales húmedos de altura que sufren un riguroso clima invernal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37164','espacio','Meandros del río Tormes / Isla de Huerta','Amplia llanura aluvial cuaternaria donde el río Tormes ensancha su cauce, divagando en meandros estables y brazos secundarios. Las márgenes albergan un soto de ribera continuo y maduro poblado por álamos blancos, chopos negros y extensos carrizales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37165','espacio','Campo de Ledesma / Riberas del río Huebra / Berrocal granítico','Paisaje característico de la penillanura granítica con abundancia de bloques de piedra redondeados debido a la meteorización química de la roca. Las vaguadas albergan arroyos menores rodeados de dehesas maduras de encina y fresnos ripícolas dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37166','espacio','Espacio Natural Protegido de la Sierra de Gata / Riberas del río Azaba','Paisaje de piedemonte adehesado sobre suelos arcillo-pedregosos de raña con una alta densidad arbórea. El corredor fluvial del río Azaba destaca por la pureza de sus aguas y la frondosidad de sus sotos mixtos de roble rebollo y encinas centenarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37167','espacio','Peñas de Juzbado / Escarpes del río Tormes','Imponentes crestas y afloramientos de fallas graníticas que se levantan verticalmente en la margen derecha del río Tormes. El relieve ofrece una sección geomorfológica muy nítida donde las encinas de roca se asoman sobre el frondoso bosque aluvial de la vega baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37175','espacio','Vega de inundación del río Tormes','Topografía completamente horizontal de la comarca de la Tierra de Alba constituida por depósitos aluviales finos. El paisaje visual es diáfano, roto únicamente por el cinturón vegetal de sauces y carrizales asociados al eje fluvial principal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37183','espacio','Campo del Yeltes / Riberas del río Yeltes','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas cuarcíticas que drenan hacia la cuenca del Yeltes. El entorno forestal está dominado por un denso rebollar de roble melojo que se integra con las encinas en un paisaje adehesado continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49115','espacio','Campo Charro / Lomas de Mayalde / Arroyo de San Juan','Topografía de lomas suaves arcillosas que drenan hacia la cuenca central. Las pequeñas vaguadas acumulan la humedad estacional, permitiendo el desarrollo de matorral de encina aclarado y pastizales ganaderos bien conservados.   Melardos • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37245','espacio','Sierra de Gata / Espacio Natural Protegido de El Rebollar / Pico de El Payo','Espectacular paisaje de montaña caracterizado por un relieve de pizarras en el extremo sudoccidental, frontera con Portugal y Cáceres. Alberga inmensas masas   boscosas de roble melojo (rebollares) de influencia atlántica pura y riachuelos torrenciales cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37168','espacio','Sierra de Béjar / Valle del río Alagón / Monte de la Dehesa','Vertiente de pendientes extremas constituida por pizarras y granitos que descienden desde las cumbres hacia tierras extremeñas. El microclima serrano sustenta inmensas masas de bosque caducifolio dominadas por castañares centenarios y robles melojos en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37169','espacio','Tierra de Alba / Riberas del río Gamo','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos arcillosos. Ofrece una perspectiva diáfana donde el curso del río Gamo aporta un estrecho corredor verde continuo de sauces y espadañas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','espacio','Cañón del río Tormes / Carniceras / Berrocal de Ledesma','Impresionante garganta fluvial labrada por el río Tormes al tajar la penillanura granítica occidentalsalmantina. El lecho muestra meandros encajonados, gigantescos bloques   de piedra pulidos y una dehesa madura que se asoma de forma vertical sobre el cauce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37171','espacio','Sierra de Béjar / Valle del río Sangusín / Lomas de Ledrada','Relieve colinado de transición montañosa sobre el zócalo granítico del sureste provincial. El río Sangusín aporta una rica franja de sotos húmedos con sauces y alisos que contrasta con las vertientes pedregosas cubiertas de melojo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37213','espacio','Sierra de Béjar (Piedemonte septentrional) / Altiplanicie de la Nava / Arroyo de la Nava','Entorno de media montaña granítica caracterizado por una penillanura elevada con abundantes   bloques de piedra exentos y canchales. Las faldas montañosas albergan excelentes masas forestales de roble melojo y pastizales húmedos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37177','espacio','Sierra de Francia (Vertiente Norte) / Piedemonte de la Peña de Francia','Relieve quebrado prepirenaico constituido por cuarcitas y pizarras de fuertes pendientes. Las laderas umbrías están totalmente cubiertas por un majestuoso y frondoso dosel de robles melojos y pinares silvestres surcados por arroyos cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37258','espacio','Campo de Azaba / Riberas del río Azaba / Dehesa de la Puebla','Altiplanicie de transición hacia la vertiente norte de la sierra de Gata, caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas boscosas albergan masas compactas de roble rebollo y encinares mediterráneos que configuran un paisaje adehesado continuo de gran madurez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37259','espacio','Sierra de Béjar (Piedemonte) / Lomas de San Medel / Arroyo de la Calera','Elevación orográfica de perfiles redondeados que actúa como barrera climática menor en la comarca de Guijuelo. Presenta vertientes cubiertas de matorrales mediterráneos, escobares y dehesas aclaradas de encina y quejigo adaptadas al suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37263','espacio','Sierra de Béjar / Valle del río Cuerpo de Hombre / Garganta de Oso','Relieve de alta montaña que marca el límite meridional con Extremadura, caracterizado por fuertes pendientes graníticas y escarpes labrados por la escorrentía superficial. Las laderas de umbría están densamente tapizadas por majestuosos bosques de castaños centenarios y robledales de melojo de gran pureza botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37262','espacio','Riberas del río Huebra / Cañón del Uces (Estribaciones)','Zona donde la penillanura granítica empieza a fracturarse debido a la cercanía de los grandes encajonamientos fluviales del oeste de la provincia. El paisaje visual destaca por sus afloramientos de canchales de piedra, matorral mediterráneo de escoba y sotos mixtos de fresno que acompañan las corrientes de agua menores. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37264','espacio','Parque Natural de Arribes del Duero / Cañón del río Águeda / Puente de los Franceses (Escarpes)','Espectacular e imponente encajonamiento fluvial donde el río Águeda corta transversalmente la penillanura en un profundo desfiladero de paredes verticales de pizarra. El microclima permite la proliferación de enclaves relictos de alcornoques y enebros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37265','espacio','Riberas del río Regamón / Humedales temporales de la dehesa','Paisaje completamente horizontal asentado sobre arcillas y limos en la llanura de Tierra de Peñaranda. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales y charcas de carácter endorreico cubiertas de juncos y gramíneas.   Regumiel de la Sierra • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37266','espacio','Parque Natural de Arribes del Duero / Arribes del río Morgáez','Relieve quebrado caracterizado por el profundo encajonamiento del riachuelo Morgáez al romper la penillanura granítica en dirección al Duero. Las empinadas vertientes rocosas albergan un microclima donde prosperan enebros, alcornoques y matorral xerófilo de gran interés biogeográfico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37267','espacio','Riberas del río Yeltes / Dehesas de Retortillo','Sector medio de la cuenca fluvial caracterizado por un relieve suave de rañas arcillo-pedregosas cuarcíticas. El cauce mantiene un corredor forestal denso e ininterrumpido de sauces negros y fresnos ripícolas, perfectamente integrados con las encinas de la dehesa.   Robleda, La       (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37269','espacio','Espacio Natural Protegido de El Rebollar / Río Agueda','Extensa llanura pedregosa constituida por depósitos de rañas arcillo-arenosas cuarcíticas a los pies de la sierra de Gata. Alberga una de las masas forestales más compactas y puras de roble rebollo (Quercus pyrenaica) del suroeste peninsular, adaptada al clima subatlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37270','espacio','Campo Charro / Lomas de Robliza','Topografía monótona y horizontal sobre sedimentos arcillosos paleógenos, característica de la penillanura ganadera central. Las pequeñas canales de escorrentía estacional permiten el desarrollo de encinares aclarados en régimen de dehesa y pastizales secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37271','espacio','Campo de Ledesma / Arroyo de Rollán','Topografía de lomas suaves arcillo-arenosas degradadas que marcan la transición hacia las penillanuras del Tormes. Los arroyos de régimen estacional mantienen estrechas franjas de juncos y espadañas que aportan variedad visual al entorno adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37272','espacio','Valle del río Águeda / Lomas de Saelices','Relieve quebrado de media montaña caracterizado por la incisión del río Águeda sobre pizarras y conglomerados erosionados. Cuenta con sotos de ribera bien estructurados con alisos, sauces y dehesas mixtas de encina de gran valor estético y forestal.   Salas de los Infantes • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37275','espacio','Parque Natural de Arribes del Duero / Cañón del río Huebra / El Castillo (Escarpes)','Espectacular y grandioso desfiladero fluvial donde el río Huebra corta transversalmente la penillanura en un abismo granítico de más de trescientos metros de caída vertical. Las colosales paredes de roca desnuda albergan enebros silvestres, alcornoques relictos y una de las mayores comunidades de buitre leonado.   Salinas de Anaya • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37277','espacio','Embalse de Santa Teresa / Riberas graníticas del Tormes','Paisaje fluvial donde las aguas tranquilas del embalse inundan un relieve ondulado de pizarras y afloramientos graníticos. Destaca por el fuerte contraste visual   entre las láminas de agua estables y los encinares mediterráneos que colonizan las laderas pedregosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37278','espacio','Llanura de La Armuña / Lomas de San Cristóbal','Suave relieve de lomas areniscas labradas por la erosión diferencial en la comarca cerealista del norte de la capital. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las vertientes expuestas muestran tomillares secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37284','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle del río Alagón','Profundo encajonamiento fluvial excavado sobre pizarras y cuarcitas donde el río Alagón discurre de forma sinuosa con aguas cristalinas. El relieve destaca por su fuerte pendiente escarpada y umbría, tapizada por densos bosques de castaños, robles melojos y madroñales relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37285','espacio','Parque Natural de Arribes del Duero / Cañón del río Águeda / Puente de los de los Franceses','Espectacular e imponente encajonamiento fluvial donde el río Águeda corta la penillanura granítica en un profundo desfiladero de paredes verticales de pizarra. La umbría orográfica y el microclima permiten la proliferación de enclaves relictos de alcornoques, enebros y almendros silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37012','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle del río Francia','Majestuoso entorno alpino de alta montaña caracterizado por un relieve totalmente abrupto y escarpado de cuarcitas que se desploman en profundos valles recónditos. Alberga espectaculares bosques mixtos de castaños, robles melojos y madroñales relictos, surcados por ríos torrenciales de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37287','espacio','Sierra de las Quilamas / Cañón del río Alagón / Pico del Castillo','Relieve montañoso de transición con vertientes escarpadas y barrancos sinuosos que caen de forma abrupta hacia el lecho del río Alagón. Las laderas orientadas a la umbría atesoran masas compactas de robledal de melojo y castañares dispersos sobre suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37036','espacio','Sierra de Francia (Límite Norte) / Cabecera del río Yeltes','Relieve montañoso de transición con vertientes escarpadas y barrancos sinuosos que dan origen a los primeros aportes fluviales del río Yeltes. Las laderas orientadas a la umbría atesoran masas compactas de robledal de melojo y castañares dispersos sobre suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37288','espacio','Vega del río Tormes / Sotos de San Morales','Sector medio de la llanura de inundación del Tormes caracterizado por depósitos de gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y álamos forman un denso cinturón vegetal continuo de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37289','espacio','Campo Charro / Riberas del río Huebra','Tramo aluvial donde el río Huebra discurre de manera sinuosa sobre depósitos de cantos rodados cuarcíticos en el centro provincial. Las márgenes albergan sotos ripícolas continuos compuestos por sauces negros y fresnos que destacan en mitad del relieve llano adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37291','espacio','Campo Charro / Lomas de Rozados / Sierra de las Quilamas (Faldas)','Elevación orográfica de perfil redondeado que actúa como divisoria de aguas, ofreciendo un relieve expuesto a una intensa insolación. Las vertientes protegidas albergan masas compactas de quejigares y encinares mediterráneos que colonizan el suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37290','espacio','Riberas del río Tormes / Sotos de San Pedro','Valle fluvial aluvial maduro donde el río Tormes discurre entre terrazas cuaternarias de gravas y limos finos. Las márgenes mantienen una franja bien conservada de bosque de ribera con chopos negros y sauces que aportan frescura visual en la penillanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37292','espacio','Cortados del río Ledesma / Monte de San Pelayo / Riberas del Tormes','Tramo donde el río Tormes se encajona en la penillanura labrando pequeños escarpes y cortados rocosos sobre gneis y granitos. Las laderas orientadas al norte conservan manchas dispersas de encinar mediterráneo termoatlántico con sotos fluviales al pie.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37283','espacio','Campo de Ledesma / Riberas del río Huebra','Tramo donde el río Huebra discurre de manera sinuosa sobre depósitos de cantos rodados cuarcíticos en la penillanura occidental. Las márgenes albergan sotos ripícolas   continuos compuestos por sauces negros y fresnos que destacan en mitad del relieve llano adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37293','espacio','Campo de Ledesma / Arroyo de Sando','Topografía de lomas suaves arcillo-arenosas degradadas que marcan la transición hacia las penillanuras del Tormes. Los arroyos de régimen estacional mantienen estrechas franjas de juncos y espadañas que aportan variedad visual al entorno adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37294','espacio','Riberas del río Tormes / Isla del Soto','Amplia vega de inundación aluvial donde el río Tormes ensancha su lecho dejando depósitos masivos de gravas y arenas cuaternarias. Cuenta con sotos ripícolas continuos muy frondosos poblados por álamos blancos, chopos negros y grandes extensiones de carrizal estable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37296','espacio','Riberas del río Mazarros / Lomas de Santiago','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en la comarca de la Tierra de Peñaranda. Ofrece una perspectiva diáfana donde el curso del río aporta una   franja modesta de vegetación ripícola con sauces y juncos dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37297','espacio','Riberas del río Tormes / Berrocal granítico de Santibáñez / Cabeza del Caballo','Entorno de media montaña granítica caracterizado por lomas suaves, lapiaces calcáreos y un relieve caótico de grandes bolos de piedra moldeados por la erosión. El río Tormes discurre encajonado entre el lecho de piedra, escoltado por un denso encinar mixto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37239','espacio','Llanura de La Armuña / Lomas del Pedroso','Topografía completamente horizontal asentada sobre limos y arcillas cuaternarias del neógeno. La escorrentía superficial es de carácter estrictamente temporal, generando pequeñas zonas de humedad estacional cubiertas de gramíneas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37182','espacio','Cuenca alta del río Tormes / Cerros de Martinamor','Elevación orográfica suave sobre materiales graníticos degradados que actúa como divisoria de aguas de la meseta central. Presenta pequeñas manchas de encinar mediterráneo arbustivo adaptadas a suelos pedregosos pobres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37257','espacio','Campo de Vitigudino / Riberas del río Huebra / Dehesa de Pozos','Topografía ondulada sobre la penillanura occidental salmantina, dominada por suelos pedregosos y afloramientos dispersos de bolos graníticos. Alberga dehesas de encina bien estructuradas y pequeñas depresiones higrófilas estacionales que acumulan agua invernal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37260','espacio','Riberas del río Yeltes / Sierra de Francia (Estribaciones norteñas)','Relieve quebrado prepirenaico de transición donde el río Yeltes discurre encajonado de forma sinuosa entre materiales de pizarra y cuarcita. Los márgenes conservan un soto ripícola hiperhúmedo con alisos y sauces que contrasta visualmente con las laderas serranas cubiertas de melojos.   Quinta, La • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37261','espacio','Garganta del río Tormes / Berrocal del Congosto / Sierra de Gredos (Faldas)','Espectacular e imponente encajonamiento fluvial donde el río Tormes corta transversalmente la penillanura granítica en un profundo desfiladero de bloques de   piedra pulidos. El relieve muestra canchales caóticos, rápidos de agua encajonados en la roca y encinas rupícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37303','espacio','Sierra de Gata / Cabecera del río Águeda / Dehesa de El Saúgo','Relieve de media montaña caracterizado por picos redondeados de pizarra y vertientes abruptas cubiertas de piornales de montaña. Los cursos fluviales altos excavan profundas y estrechas canales cubiertas de robledales de melojo de influencia atlántica pura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','espacio','Riberas del río Tormes / Complejo fluvial de Tejares a la Aldehuela','Amplio corredor fluvial aluvial donde el río Tormes ensancha su cauce y genera islas sedimentarias cuaternarias estables. Las márgenes albergan sotos ripícolas continuos muy desarrollados con alisos, chopos negros y sauces, sirviendo de oasis verde contemplativo en la cuenca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37279','espacio','Riberas del río Gavilanes / Dehesa de Sancti-Spíritus / Estribaciones de la Peña de Francia','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas cuarcíticas que drenan hacia la cuenca del Yeltes. El entorno forestal está dominado por un denso rebollar de roble melojo que se integra con las encinas en un paisaje adehesado continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37298','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Riberas del río Alagón / Las Puentes','Profundo encajonamiento fluvial excavado sobre pizarras y cuarcitas donde el río Alagón discurre de forma torrencial con aguas sumamente cristalinas. El relieve destaca por su fuerte pendiente escarpada y umbría, tapizada por densos bosques de castaños, robles y madroñales relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37299','espacio','Campo de Ledesma / Dehesas del norte / Frontera con Zamora','Relieve de penillanura horizontal sobre materiales graníticos con abundantes afloramientos de piedra exenta. Las pequeñas vaguadas acumulan la humedad estacional y dan origen a juncales y espadañares densos que contrastan con el encinar aclarado de la dehesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37300','espacio','Parque Estelar de Los Santos / Canteras históricas (Entorno natural) / Sierra de las Quilamas','Altiplanicie caliza y granítica elevada que ofrece un relieve expuesto a una intensa insolación y horizontes infinitos. Las vertientes protegidas albergan masas compactas de quejigares y encinares mediterráneos que colonizan el suelo pedregoso y las oquedades naturales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37301','espacio','Riberas del Embalse de Almendra / Cañón del río Tormes','Impresionante tajo geológico excavado sobre rocas graníticas antes de la confluencia con el Duero. El relieve está caracterizado por gigantescos escarpes de piedra desnuda y lapiaces que se hunden de forma vertical hacia el lecho encajonado de las aguas mansas embalsadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37302','espacio','Parque Natural de Arribes del Duero / Cañón del río Duero y río Huebra / Salto de Saucelle','Uno de los paisajes geológicos más imponentes y colosales de la frontera internacional, donde el río Duero hiende la penillanura en un cañón granítico con paredes verticales escarpadas. Las umbrías de los cortados rocosos albergan enebros silvestres, alcornoques relictos y madroñales de excepcional valor visual. [1, 2].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37304','espacio','Campo Charro / Riberas del arroyo de la Valmuza','Paisaje penillanura horizontal sobre materiales graníticos y de pizarra del neógeno. Destaca por albergar un bosque adehesado de encinas centenarias bien estructurado, donde el suelo arcillo-pedregoso da paso a pequeñas charcas estacionales y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37305','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Mirador de la la Cruz (Entorno boscoso) / Fraga de Sequeros','Profundo encajonamiento fluvial excavado sobre pizarras y cuarcitas donde el río Francia discurre de forma torrencial con aguas sumamente cristalinas. El relieve destaca por su fuerte pendiente escarpada y umbría, tapizada por densos bosques de castaños, robles y madroñales relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37306','espacio','Sierra de Gata / Valle del río Agueda / Barranco del del Payo','Relieve abrupto de media montaña integrado en la vertiente norte del macizo de Gata, caracterizado por fuertes pendientes sobre pizarras. Las laderas de umbría atesoran masas forestales compactas de robles melojos y pinos silvestres, surcados por arroyos de montaña de aguas sumamente puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37307','espacio','Sierra de Gata / Valle del río Agueda / Barranco del del Payo','Relieve abrupto de media montaña integrado en la vertiente norte del macizo de Gata, caracterizado por fuertes pendientes sobre pizarras. Las laderas de umbría atesoran masas forestales compactas de robles melojos y pinos silvestres, surcados por arroyos de montaña de aguas sumamente puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37310','espacio','Riberas del río Tormes / Cortados graníticos de Sieteiglesias','Tramo donde el río Tormes se encajona levemente entre terrazas de gravas y afloramientos graníticos en la penillanura central. Los márgenes conservan sotos ripícolas bien estructurados con fresnos, alisos y un encinar calcícola perimetral adaptado a las grietas de la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37311','espacio','Parque Natural de Arribes del Duero / Cañón del río Agueda','Espectacular e imponente encajonamiento fluvial donde el río Águeda corta transversalmente la penillanura granítica en un profundo desfiladero de paredes verticales de pizarra. La umbría orográfica y el microclima permiten la proliferación de enclaves relictos de alcornoques, enebros y almendros silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37312','espacio','Sierra de Béjar / Berrocal de Sorihuela / Garganta del del Alagón','Impresionante paisaje kárstico-granítico caracterizado por un relieve caótico de grandes bolos de piedra redondeados y penedos gigantescos debido a la meteorización química. Las laderas descienden con fuerte pendiente, albergando dehesas maduras de encina y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37313','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Meandro del Melero (Río Alagón) / Desembocadura del río Francia','Uno de los enclaves paisajísticos más espectaculares de España, donde el río Alagón dibuja un meandro encajonado perfecto de casi 360 grados sobre paredes verticales de pizarra. El fondo del valle disfruta de un microclima mediterráneo único habitado por alcornoques, madroños y densas alisedas fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37314','espacio','Campo Charro / Dehesas de Tabera','Relieve horizontal propio de la penillanura salmantina central con suelos arcillo-pedregosos cuarcíticos. Las pequeñas vaguadas acumulan la humedad invernal y permiten la existencia de encinares aclarados en régimen de dehesa ganadera tradicional.   Valdecarpinteros       (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37330','espacio','Valle del río Gamo / Lomas de Valdecarros','Paisaje sedimentario horizontal de la Tierra de Alba compuesto por depósitos de arcillas y limos cuaternarios. El cauce modesto del río Gamo aporta una banda estrecha pero continua de carrizales, eneas y pequeños sauces que rompe la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37331','espacio','Riberas del río Sangusín / Lomas de Valdefuentes','Valle de modelado aluvial rodeado por colinas graníticas cubiertas de densa vegetación forestal en la comarca de Béjar. El curso del río Sangusín discurre de forma sinuosa flanqueado por alisos y sauces centenarios que configuran un corredor verde continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37332','espacio','Sierra de Béjar (Estribaciones) / Arroyo de Valdehijaderos','Relieve de media montaña caracterizado por picos redondeados de granito y vertientes abruptas cubiertas de escobares de montaña. Las vaguadas sombrías albergan arroyos torrenciales rodeados por carballeiras bien conservadas de quejigo y melojo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37333','espacio','Sierra de las Quilamas (Faldas meridionales) / Berrocal de Valdelacasa','Paisaje de transición montañosa caracterizado por una elevada densidad de penedos graníticos y bolos de piedra exentos. Las laderas umbrías conservan manchas   forestales jóvenes de roble melojo que colonizan los suelos pedregosos de la serranía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37334','espacio','Sierra de Francia / Cañón del río Alagón / Las laderas de Valdelageve','Paisaje quebrado de media montaña donde el río Alagón se encajona en profundas gargantas esculpidas sobre materiales de pizarra. Las laderas escarpadas presentan una interesante vegetación mediterránea mixta con alcornoques, enebros y encinas de roca de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37335','espacio','Alcornocal de Valdelosa / Arroyo de la Valmuza (Cabecera)','Alberga una de las masas boscosas de alcornoques más extensas, septentrionales y mejor conservadas de toda la Comunidad de Castilla y León, asentada sobre una penillanura silícea de cantos rodados cuarcíticos. El paisaje destaca por su tremenda originalidad biogeográfica y su alto valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37336','espacio','Campo Charro / Dehesa de Valdemierque','Paisaje penillanura horizontal sobre materiales graníticos y de pizarra del neógeno. Destaca por albergar un bosque adehesado de encinas centenarias bien estructurado, donde el suelo arcillo-pedregoso da paso a pequeñas charcas estacionales y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37337','espacio','Vitigudino (Comarca) / Riberas del río Huebra / Cabeza de Diego Gómez','Relieve granítico penillanante caracterizado por la presencia de grandes penedos y bolos de piedra redondeados por la erosión. Las laderas descienden suavemente hacia la cuenca del Huebra, rodeadas de pastizales de la dehesa tradicional de encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37338','espacio','Riberas del arroyo de la Encina / Lomas de Valdunciel','Topografía de lomas suaves arcillo-arenosas degradadas que marcan la transición hacia el norte de la provincia. Los arroyos temporales mantienen estrechas franjas   de juncos y espadañas que aportan variedad cromática al entorno cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37339','espacio','Sierra de las Quilamas / Cañón del río Alagón / Desembocadura del río Quilamas / Garganta de la Hoz','Espectacular anfiteatro geológico encajonado en el fondo de un cañón de pizarra y cuarcitas de verticalidad absoluta. Las laderas de pendientes extremas están cubiertas por una frondosa cubierta vegetal mediterránea de alcornoques, madroños y acebedas, surcada por aguas bravas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37340','espacio','Arribes del río Huebra / Las Arribillas / Dehesa de Valsalabroso','Tramo donde el río Huebra empieza a encajonarse con fuerza entre afloramientos de pizarras y granitos en la penillanura occidental. Los márgenes conservan escarpes rocosos y sotos ripícolas bien estructurados con fresnos, enebros y encinares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37341','espacio','Sierra de Béjar (Piedemonte) / Arroyo de Valverde','Vertiente de pendientes moderadas constituida por materiales graníticos que desciende hacia la cuenca del Alagón. Las faldas montañosas albergan excelentes masas forestales de roble melojo, castañares maduros y pequeños riachuelos de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37342','espacio','Cortados del río Tormes / Sotos de Valverdón / Zorita (Entorno natural)','Imponentes taludes y cortados de areniscas rojizas que caen con fuerte pendiente sobre el margen derecho de la cuenca baja del Tormes. Ofrece una sección geológica perfecta de terrazas aluviales combinada con sotos maduros de sauces y chopos negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37344','espacio','Campo Charro / Arroyo de la Valmuza','Paisaje penillanura horizontal sobre materiales graníticos y de pizarra del neógeno. Destaca por albergar un bosque adehesado de encinas centenarias bien estructurado, donde el suelo arcillo-pedregoso da paso a pequeñas charcas estacionales y pastizales húmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37345','espacio','Riberas del río Tormes / Vega de Tirados','Valle fluvial aluvial maduro donde el río Tormes discurre entre dehesas cuaternarias de gravas y limos finos. Las márgenes mantienen una franja bien conservada de bosque de ribera con chopos negros y sauces que aportan frescura visual en la penillanura.   **V.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37346','espacio','Campo Charro / Lomas de Las Veguillas / Nacimiento del río Zurguén','Altiplanicie de transición caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas orientadas a la umbría conservan masas compactas y bien estructuradas de quejigares y encinares mediterráneos arbustivos donde nacen corrientes menores.   Velasco • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37347','espacio','Cuenca del arroyo de la Encina / Llanura de la Armuña','Paisaje completamente horizontal modelado sobre arcillas y limos neógenos de gran potencia agrícola. Pequeñas vaguadas estacionales retienen la escorrentía invernal, generando cinturones de juncos y gramíneas que rompen la llanura uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37348','espacio','Riberas del río Almar / Vega de Ventosa','Paisaje geomorfológico horizontal de la Tierra de Peñaranda compuesto por terrazas fluviales cuaternarias y depósitos aluviales finos. Ofrece un corredor verde estrecho compuesto por sauces y chopos negros dispersos que aporta variedad al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37349','espacio','Campo de Vitigudino / Riberas del río Uces (Estribaciones) / Arroyo de la del Valle','Topografía ondulada sobre la penillanura occidental salmantina, dominada por suelos pedregosos y afloramientos dispersos de bolos graníticos. Alberga dehesas de encina bien estructuradas y pequeñas depresiones higrófilas estacionales que acumulan agua invernal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37351','espacio','Llanura de la Guareña / Arroyo de Villaflores','Paisaje completamente horizontal asentado sobre sedimentos arcilloso-limosos terciarios en el extremo nororiental de la provincia. Ofrece una perspectiva diáfana rota únicamente por un corredor modesto de vegetación palustre que acompaña las avenidas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37280','espacio','Las Arribes del río Huebra / Lomas de Sanchón','Relieve granítico penillanante que se deprime con suavidad hacia el encajonamiento occidental de la provincia. Muestra penedos y bolos rocosos redondeados rodeados de pastizales y matorral mediterráneo de jara y escoba que coloniza las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37281','espacio','Campo Charro / Arroyo de la Sagrada','Relieve horizontal propio de la penillanura salmantina central con suelos arcillo-pedregosos cuarcíticos. Las pequeñas vaguadas acumulan la humedad invernal y permiten la existencia de encinares aclarados en régimen de dehesa ganadera tradicional.   SanchÓn de de la Solana • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37343','espacio','Sierra de Béjar / El Ventorro / Cabeza de la la Tranca','Relieve alpino de alta montaña dominado por un relieve quebrado de origen glaciar con circos, morrenas e imponentes agujas graníticas desnudas. Alberga inmensos hayedos relictos, pinares silvestres y cascadas de aguas de deshielo que descienden de forma torrencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37352','espacio','Azud de Villagonzalo / Riberas del río Tormes','Amplio valle aluvial donde el Tormes ensancha su cauce y genera una lámina de agua estable debido al represamiento. Los márgenes conservan un frondoso bosque de ribera con abundantes alisos, sauces y un espeso cinturón de eneas y espadañas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37353','espacio','Campo Charro / Dehesa de Villalba / Río Huebra','Relieve horizontal propio de la penillanura salmantina central con suelos arcillo-pedregosos cuarcíticos. Las pequeñas vaguadas acumulan la humedad invernal y permiten la existencia de encinares aclarados en régimen de dehesa ganadera tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37354','espacio','Canteras históricas del Tormes / Riberas del río Tormes','Escarpes de arenisca elocuente de tonos dorados labrados por la erosión fluvial y la antigua actividad extractiva de piedra en los márgenes del Tormes. El pie de   monte conecta con un corredor continuo de saucedas y alamedas maduras. Villanueva de de Cañedo • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37355','espacio','Parque Natural de Las Batuecas-Sierra de Francia / Valle de Villanueva / Arroyo de San Pedro','Impresionante anfiteatro montañoso constituido por pizarras y cuarcitas en la Sierra de Francia, caracterizado por vertientes de fuertes pendientes de perfil escarpado. El relieve alberga masas de madroñales, castaños milenarios y acebedas puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37356','espacio','Campo de Argañán / Dehesas de Villar','Altiplanicie de transición hacia la sierra caracterizada por suelos arcillosos mixtos con cantos rodados cuarcíticos. Las laderas orientadas a la umbría conservan masas compactas y bien estructuradas de quejigares y encinares mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37361','espacio','Riberas del río Huebra / Cañón de Samaniego','Relieve de penillanura granítica hendido por los colectores de la cuenca del Duero, formando las primeras pendientes y escarpes de roca viva. Las vaguadas y laderas umbrías están colonizadas por un denso matorral mediterráneo de jaras y encinares.   Villar de de Peralta • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37359','espacio','Cañón del río Águeda / Estrecho de la Yegua / Siega Verde (Márgenes)','Espectacular y profundo desfiladero fluvial donde el río Águeda corta transversalmente la penillanura caliza y de pizarras, generando farallones verticales de roca grisácea y canchales de ladera. El fondo sombrío alberga una frondosa vegetación mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37362','espacio','Llanura de la Armuña / Lomas de Villares','Paisaje completamente horizontal situado en el norte periurbano, constituido por arcillas y limos miocenos. La escorrentía superficial es de carácter temporal y genera pequeñas franjas higrófilas estacionales que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37363','espacio','Confluencia del río Huebra y río Yeltes','Singular paisaje fluvial donde se unen los dos cauces más importantes de la comarca sobre un lecho de bloques graníticos. El relieve es quebrado y accidentado, enmarcado por densos sotos de fresnos y encinares mediterráneos de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37364','espacio','Parque Natural de Arribes del Duero / Amia / Cañón del Duero y Tormes','Imponente paisaje geológico que alberga la gran confluencia donde el río Tormes entrega sus aguas al Duero en un desfiladero de paredes graníticas de más de trescientos metros de caída vertical. El relieve es totalmente abrupto, salvaje y salpicado de alcornoques relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37365','espacio','Campo de Ledesma / Arroyo de Villarmayor','Suave relieve colinado de la penillanura central compuesto por sedimentos arcillo-arenosos del neógeno. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las lomas presentan tomillares y encinares aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37276','espacio','Tierra de Peñaranda / Arroyo de Mazarros','Topografía de lomas suaves arcillosas degradadas situadas en la zona oriental de la provincia. Presenta pequeños riachuelos estacionales de carácter temporal acompañados de espadañas aisladas que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37319','espacio','Sierra de Béjar (Estribaciones) / Riberas del río Tormes','Vertiente montañosa granítica de pendientes moderadas que sirve de transición hacia el macizo de Béjar. El curso del río Tormes esculpe un valle estrecho poblado por un soto aluvial maduro con sauces negros y alisos entre grandes bolos graníticos de erosión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37320','espacio','Sierra de las Quilamas / Nacimiento del río Huebra / Dehesa de Segoyuela','Relieve de transición montañosa caracterizado por una topografía de suaves cerros y dehesas asentadas sobre sustratos de pizarras y granitos. El término municipal alberga las fuentes del río Huebra en forma de pequeñas turberas y regatos, rodeadas de encinares maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37321','espacio','Campo de Yeltes / Riberas del río Tenebrón','Relieve alomado y suave formado por terrazas de rañas arcillo-pedregosas cuarcíticas que drenan hacia la cuenca del Yeltes. El entorno forestal está dominado por un denso rebollar de roble melojo que se integra con las encinas en un paisaje adehesado continuo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37322','espacio','Campo Charro / Lomas de Terradillos / Arroyo de la Valmuza','Topografía monótona y horizontal sobre sedimentos arcillosos paleógenos, característica de la penillanura ganadera central. Las pequeñas canales de escorrentía estacional permiten el desarrollo de encinares aclarados en régimen de dehesa y pastizales secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37323','espacio','Campo de Ledesma / Riberas del río Cañedo / Pinar de Topas','Relieve de penillanura horizontal sobre materiales graníticos y areniscas con abundantes afloramientos de piedra exenta en el norte provincial. Las vaguadas albergan dehesas bien estructuradas de encina y pequeños núcleos de sauces que acompañan las corrientes de agua temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37324','espacio','Valle del río Gamo / Lomas de Tordillos','Paisaje sedimentario horizontal de la Tierra de Alba compuesto por depósitos de arcillas y limos cuaternarios. El cauce modesto del río Gamo aporta una banda estrecha pero continua de carrizales, eneas y pequeños sauces que rompe la llanura cerealista.   Tornadizos • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37327','espacio','Valle del río Cañedo / Lomas de Torresmenudas','Suave relieve colinado labrado sobre margas y arcillas compactas por arroyos de régimen estacional en la comarca de la Armuña. Los fondos aluviales acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37328','espacio','Parque Natural de Arribes del Duero / Berrocal granítico de Trabanca / Cañón del Tormes','Relieve granítico penillanante que se deprime con fuerza hacia el encajonamiento noroccidental de la provincia. Muestra un paisaje caótico de penedos y bolos rocosos redondeados rodeados de pastizales y un bosque adehesado de encina maduro que asoma a los arribes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37329','espacio','Riberas del río Tormes / Berrocal de Tremedal','Paisaje característico de la penillanura granítica salmantina con abundancia de bloques de piedra redondeados debido a la meteorización química de la roca. Las vaguadas albergan arroyos menores rodeados de dehesas maduras de encina y fresnos ripícolas dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37316','espacio','Sierra de Francia (Piedemonte) / Riberas del río Huebra / Dehesa de Tamames','Paisaje de transición montañosa con un relieve ondulado modelado sobre pizarras y areniscas. El curso del río discurre encajonado de forma sinuosa por el término, flanqueado por dehesas de encina, robledales de quejigo y fresnedas ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37317','espacio','Llanura de La Guareña / Arroyo de la Encina','Paisaje completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37318','espacio','Llanura de La Armuña / Arroyo de la Encina','Paisaje completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37360','espacio','Campo de Ledesma / Berrocal granítico de Peralonso','Paisaje característico de la penillanura granítica con una alta concentración de bloques de piedra redondeados por la meteorización química. Las vaguadas albergan arroyos   menores rodeados de dehesas maduras de encina y fresnos ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37366','espacio','Vitigudino (Comarca) / Arroyo de Villarmuerto / Berrocal granítico','Relieve granítico penillanante caracterizado por la presencia de grandes penedos y bolos de piedra redondeados por la erosión climática. Las laderas descenso suavemente hacia la cuenca del Huebra, rodeadas de pastizales y matorrales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37367','espacio','Riberas del río Huebra / Dehesa de Villasbuenas','Tramo de corredor fluvial encajonado donde el río Huebra discurre entre bloques de pizarra formando rápidos de agua. La ribera conserva una excelente representación de bosque mediterráneo con encinas, fresnos y grandes extensiones de jara.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37368','espacio','Campo de Ledesma / Lomas de Villasdardo','Topografía de lomas suaves arcillosas degradadas en la meseta central de la penillanura. Presenta pequeñas dehesas ganaderas muy aclaradas de encina y matorral arbustivo de tomillo y romero adaptado a la sequía veraniega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37369','espacio','Campo de Ledesma / Arroyo de los Gamitos','Relieve de penillanura ondulada labrado sobre materiales graníticos con afloramientos dispersos de bolos rocosos. Las vaguadas acumulan la humedad estacional y dan origen a pequeños juncales rodeados por un bosque adehesado de encina maduro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37370','espacio','Cañón del río Tormes / Cola del Embalse de Almendra / Cortados de Villaseco','Profunda incisión fluvial tallada por el río Tormes sobre calizas y granitos duros antes de su represamiento masivo. El relieve se caracteriza por la presencia de grandes bloques de piedra desprendidos, paredes verticales y una vegetación xerófila mediterránea relicta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37371','espacio','Sierra de Gata / Valle del río Frio / El Rebollar','Relieve de media montaña integrado en el espacio protegido de El Rebollar, caracterizado por vertientes de pizarras de fuerte pendiente. Las faldas montañosas están cubiertas por una inmensa y frondosa masa forestal de roble melojo de una gran pureza botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37372','espacio','Llanura de la Armuña / Arroyo de la Guareña','Paisaje completamente horizontal de la comarca armuñesa asentado sobre arcillas y limos del neógeno. La escorrentía superficial modesta genera pequeñas áreas higrófilas estacionales que rompen la monotonía de la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37373','espacio','Riberas del río Yeltes / Dehesa de Villavieja','Tramo aluvial donde el río Yeltes discurre de manera sinuosa sobre depósitos de cantos rodados cuarcíticos. Las márgenes albergan sotos ripícolas continuos compuestos por sauces negros y fresnos que destacan en mitad del relieve llano adehesado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37374','espacio','Valle del río Tormes / Vega de Villoria','Paisaje geomorfológico horizontal compuesto por terrazas fluviales cuaternarias y sedimentos finos arcillosos en la comarca de Las Villas. Ofrece una perspectiva diáfana donde el curso del arroyo aporta una franja modesta de sauces y carrizales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37375','espacio','Riberas del río Almar / Vega de Villoruela','Llanura sedimentaria caracterizada por depósitos aluviales y glacis cuaternarios de la cuenca baja del Almar. Los márgenes fluviales conservan sotos ripícolas   estrechos pero bien estructurados con álamos blancos y sauces que rompen la horizontalidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37013','espacio','Cabezo de Vitigudino / Dehesas de la penillanura','Topografía ondulada sobre la penillanura granítica occidental, caracterizada por suaves cerros testigos aislados. Presenta dehesas tradicionales bien conservadas de encina y fresnedas en las zonas bajas húmedas que recogen la escorrentía invernal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37377','espacio','Castro de Yecla (Entorno Natural) / Cañón del río Huebra y río Variza','Espectacular garganta fluvial labrada por el río Huebra al cortar de forma transversal las estructuras de pizarra y granito de la penillanura. El relieve es abrupto, jalonado por grandes canchales y una densa vegetación mediterránea de jara y encinas de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37378','espacio','Campo de Agueda / Riberas del río Agueda','Relieve alomado y quebrado que sirve de transición hacia las altas cumbres de la sierra de Gata, surcado por el río Águeda de aguas cristalinas. Las laderas de fuerte pendiente están densamente cubiertas por encinares y quejigares de gran rusticidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37379','espacio','Campo de Ledesma / Arroyo de Zamayón','Paisaje característico de la penillanura granítica salmantina con abundancia de bloques de piedra redondeados debido a la meteorización química de la roca. Las vaguadas albergan arroyos menores rodeados de dehesas maduras de encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37380','espacio','Lomas de Zarapicos / Arroyo de la Valmuza','Suave relieve colinado de la penillanura central compuesto por sedimentos arcillo-arenosos del neógeno. Los arroyos temporales acumulan eneas y juncos en sus cauces, mientras que las lomas presentan dehesas aclaradas de encina carrasca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37381','espacio','Parque Natural de Arribes del Duero / Desfiladero del río Uces / Cascadas de la Zarza','Impresionante tajo geológico excavado sobre rocas graníticas donde el río Uces fluye fuertemente encajonado antes de verter sus aguas en el Duero. El relieve está caracterizado por gigantescos escarpes de piedra desnuda, pequeñas cascadas e imponentes farallones rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37382','espacio','Llanura cerealista de Peñaranda / Arroyo de Zorita','Paisaje completamente horizontal asentado sobre arcillas y limos terciarios en la llanura oriental salmantina. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales que rompen la llanura uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','espacio','Reserva Natural Especial del Barranco del Infierno y Acantilados de Isora','Espectacular incisión geomorfológica de paredes casi verticales que exhibe potentes coladas basálticas superpuestas de la serie volcánica antigua. La abrupta orografía alberga notables comunidades de cardonaltabaibal y especies rupícolas exclusivas, culminando en un salto de agua permanente en su cabecera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90644','espacio','Paisaje Protegido de las Siete Lomas y Volcán de las Arenas','Entorno geomorfológico dominado por el cono de piroclastos negros y coladas lávicas basálticas asociadas a la erupción histórica de 1705. Las laderas superiores se integran en la corona forestal mediante un denso pinar de pino canario que coloniza los campos de ceniza y picón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90645','espacio','Barranco de Tamadaya y Corona Forestal de las cumbres','Red de barrancos encajonados excavados sobre potentes depósitos de tobas volcánicas e ignimbritas (matorral de pumita blancuzca) de gran singularidad visual. En las cotas altas se desarrolla una masa forestal continua de Pinus canariensis adaptada a condiciones xéricas extremas de sotavento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90776','espacio','Reserva Natural Especial del Malpaís de la Rasca y Monumento Natural de la Montaña de Guaza','Excepcional campo de lavas basálticas recientes que conserva estructuras geomorfológicas intactas como túmulos, lavas cordadas y cuernos de desgasificación. El domo volcánico de Guaza añade vistosidad al conjunto con sus potentes rampas lávicas colgadas sobre acantilados marinos fosilizados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38003','espacio','Parque Rural de Teno / Acantilados de Los Gigantes / Barranco de Masca','Uno de los relieves más antiguos, abruptos y sobrecogedores de Canarias, caracterizado por una colosal red de barrancos encajonados que hienden el macizo basáltico. Culmina en espectaculares paredes verticales de roca desnuda que se desploman seiscientos metros a plomo directamente sobre el océano Atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90778','espacio','Barranco de Chacorche y Paisaje Protegido de Siete Lomas','Escarpada red drenante de barrancos que corta los materiales volcánicos de la cordillera Dorsal, mostrando diques y chimeneas volcánicas exhumadas por la erosión. El dosel vegetal varía bruscamente desde el matorral de costa xerófilo hasta los pinares de la Corona Forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90633','espacio','Monumento Natural de la Montaña de Fasnia y Barranco de Herques','Destaca por un cono de cenizas volcánicas recientes perfectamente conservado en medio de un paisaje árido de pumitas y cenizas blanquecinas. El Barranco de Herques rompe el relieve con sus imponentes paredes rocosas verticales que muestran una estratificación geológica de gran interés didáctico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16085','espacio','Parque Rural de Frontera / Escarpe de El Golfo / Roques de Salmor','Escenografía geológica monumental originada por un megadeslizamiento gravitacional que colapsó la mitad de la isla de El Hierro, generando un anfiteatro colosal con paredes de mil metros de desnivel vertical. El relieve está cubierto por un denso e histórico bosque relicto de laurisilva y sabinas inclinadas por el viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90634','espacio','Monumento Natural de los Volcanes de Teneguía y San Antonio','Escenario de volcanismo histórico subreciente que conserva fisuras eruptivas, campos de lapilli negro, cráteres perfectos y malpaíses vírgenes de basalto. La vegetación colonizadora es escasa pero de gran interés científico, destacando los líquenes y los pinos canarios aislados que rebrotan del picón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','espacio','Monumento Natural del Roque de Garachico y lengua lávica del Volcán de Trevejo (1706)','El roque es un islote basáltico de origen erosivo que constituye un refugio biológico para aves marinas y flora costera canaria. El término está profundamente marcado por la colada de lava histórica que sepultó el antiguo puerto, conformando un malpaís costero de gran valor geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38016','espacio','Reserva Natural Especial de Guelguén y barranco de Izcagua','Territorio sumamente abrupto disecado por gigantescos y profundos barrancos que se hunden de forma rectilínea hacia el mar del norte de La Palma. Custodia espectaculares masas de pinar canario canario y laderas costeras donde la vegetación rupícola cuelga sobre acantilados batidos por el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38017','espacio','Monumento Natural de la Montaña Pelada / Montaña Roja (Sector Oriental)','Singular confor volcánico originado por una erupción hidrovolcánica (freatomagmática) costera, que presenta un cráter circular perfecto de un kilómetro de diámetro. La erosión marina ha labrado acantilados bajos exponiendo una sección perfecta de dunas fósiles calizas y pumitas amarillas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38019','espacio','Monumento Natural de los Volcanes de Chinyero (Sector Sur) / Acantilados de Almacigo','Paisaje de alta montaña volcánica condicionado por coladas basálticas recientes de tipo "aa" (malpaís rugoso)   que contrastan con los pinos canarios aislados. El relieve desciende en laderas escarpadas que albergan notables afloramientos de fonolitas de formas prismáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38020','espacio','Reserva Natural Especial del Malpaís de Güímar y Barranco de Badajoz','Espectacular campo de lavas basálticas recientes salpicado de conos de piroclastos bien conservados y una densa e impresionante población de cardones canarios de gran porte. En contraste, el Barranco de Badajoz ofrece paredes verticales kilométricas que muestran las entrañas geológicas de la isla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38021','espacio','Parque Nacional de Garajonay (vertiente norte) y Monumento Natural de Los Roques','Profundo valle aluvial flanqueado por imponentes estructuras de pitones fonolíticos (como el Roque de Agando) exhumados por la erosión diferencial. El fondo y las cabeceras del valle reciben la humedad constante de los alisios, propiciando un bosque hiperhúmedo de laurisilva único.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38006','espacio','Cueva del Viento, Parque del Drago y Corona Forestal','Alberga uno de los tubos volcánicos más largos y complejos del mundo, excavado por coladas de lavas basálticas procedentes del Pico Viejo. El relieve exterior está dominado por extensas rampas volcánicas cubiertas de pino canario y el ejemplar monumental milenario de Dracaena draco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38018','espacio','Corona Forestal del norte y lavas basálticas de la vertiente de umbría','Paisaje forestal de transición con una fuerte pendiente que desciende desde las cumbres de la dorsal subalpina hacia el mar. El pinar de pino canario convive en sus zonas bajas con reductos de monteverde, formando un ecosistema umbrío de gran belleza visual sobre suelos volcánicos oscuros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38024','espacio','Parque Nacional de la Caldera de Taburiente (Barranco de Las Angustias) / Coladas del volcán Tajogaite','Alberga la espectacular desembocadura natural de la Caldera de Taburiente, un profundo cañón erosivo con paredes rocosas verticales de cientos de metros de altura y llamativos diques basálticos expuestos. El suroeste del municipio muestra el relieve rugoso y dantesco de las coladas volcánicas recientes de 2021.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38025','espacio','Paisaje Protegido de Costa de Acentejo y laderas superiores de la Dorsal','Impresionante acantilado costero de gran altura que muestra la alternancia de coladas de lava y capas de piroclastos de la serie volcánica antigua de la isla. Las laderas superiores están cubiertas por vegetación de monteverde degradada que ofrece amplias panorámicas sobre el mar de nubes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','espacio','Parque Nacional del Teide / Valle de la Orotava / Corona Forestal','Colosal anfiteatro geológico originado por un colapso gravitacional prehistórico que desciende desde la gigantesca pared de las Cañadas del Teide hasta el mar. El relieve incluye pitones volcánicos exentos, inmensos mares de pino canario y las imponentes lavas basálticas negras y rojizas que circundan la base del Teide.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38027','espacio','Parque Nacional de la Caldera de Taburiente / Cumbre Vieja / Pino de la Virgen','Corazón geológico de la isla de La Palma, caracterizado por una inmensa caldera de erosión y colapso de ocho kilómetros de diámetro con paredes verticales caleras que rozan los dos mil metros de caída. Alberga el origen de la dorsal volcánica meridional, con extensos campos de piroclastos y densos pinares endémicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','espacio','Paisaje Protegido de la Costa de El Burgado / Ladera de Martiánez','Pequeña franja costera baja originada por coladas volcánicas suavizadas, delimitada por el imponente acantilado fósil de la Ladera de Martiánez. El relieve litoral destaca por sus entrantes rocosos basálticos negros que interactúan directamente con las corrientes marinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38029','espacio','Barranco de Izcagua (Margen Sur) / Monumento Natural de la Costa de Hiscaguán','Territorio noroccidental palmero esculpido por monumentales ebanos fluviales de gran profundidad vertical que vierten hacia una costa acantilada rectilínea. El relieve presenta una alta densidad de pendientes pronunciadas cubiertas por densos almendrales silvestres y pinos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38030','espacio','Reserva Natural Especial de Guelguén (Sector Oriental) / Cubo de La Galga','Relieve quebrado por barrancos sinuosos que atrapan de manera permanente los vientos alisios en el noreste de La Palma. Destaca el Cubo de La Galga, un angosto y profundo desfiladero cubierto por un exuberante bosque húmedo de laurisilva macaronésica con gigantescos helechos relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38010','espacio','Espacio Natural Protegido de Campeches, Tigaiga y Ruiz / Rambla de Castro','Impresionante relieve modificado por el deslizamiento de la ladera de Tigaiga, que muestra farallones de roca basáltica cortados a pico. Hacia el litoral, destaca la morfología de paleoacantilados costeros cubiertos de densos palmerales nativos de Phoenix canariensis de gran belleza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38032','espacio','Paisaje Protegido de las Lagunetas / Corona Forestal (Sector Oriental)','Rampa orográfica que sirve de transición hacia la cordillera dorsal de Tenerife, modelada por lomas suaves cubiertas de un frondoso bosque mixto de pino canario y monteverde. El relieve presenta pequeños barrancos de umbría con una elevada humedad ambiental estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38033','espacio','Parque Mundial de la Biosfera La Palma (Nacientes de Marcos y Cordero) / Bosque de Los Tilos','Espectacular y abrupto cañón fluvial donde el agua brota verticalmente de las paredes basálticas a través de galerías naturales profundas. El relieve es totalmente salvaje y escarpado, albergando la masa boscosa de laurisilva más pura, madura y monumental de todo el archipiélago.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','espacio','Parque Rural de Anaga (vertiente occidental) y Paisaje Protegido de Las Lagunetas','El macizo de Anaga expone crestas basálticas afiladas, roques exhumados y profundos valles cubiertos por un bosque nublado de laurisilva (laurisilva crestada). El contraste visual entre las laderas batidas por el alisio y los roquetes costeros aislados posee un valor paisajístico internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38034','espacio','Barranco de Ruiz / Acantilados de la Costa Norte','Profunda hendidura erosiva catalogada como sitio de interés científico debido a la espectacularidad de sus paredes basálticas verticales. El relieve costero es escarpado y agreste, mostrando una alternancia de coladas volcánicas antiguas desgastadas por el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38035','espacio','Monumento Natural de la Montaña de Guaza (vertiente este) y dehesas de pumita','Relieve suave de rampas volcánicas cubiertas por depósitos de jable o pumita blanca procedentes de las erupciones ácidas del centro de Tenerife. La vegetación se restringe a comunidades rústicas de cardones y tabaibas que se adaptan a la acusada aridez del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38036','espacio','Parque Natural de Majona / Monumento Natural de Los Roques (Roque de Agando) / Barranco de Santiago','Paisaje gomero caracterizado por colosales pitones fonolíticos que emergen verticalmente como gigantescos monolitos exentos sobre la divisoria de aguas. El relieve se quiebra en barrancos radiales de dimensiones kilométricas y laderas desnudas de tonalidades rojizas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38037','espacio','Barranco de Las Nieves y Parque Natural de Las Nieves (extensión sur)','Gran incisión fluvial-volcánica que drena las cumbres orientales de La Palma, mostrando espectaculares secciones geológicas de diques y coladas. Las cabeceras del barranco están tapizadas por densas manchas de monteverde húmedo que aprovechan la condensación de la niebla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','espacio','Parque Rural de Anaga / Macizo de Anaga / Pitón de Taganana / Roques de Anaga','Uno de los espacios geológicos más espectaculares de Canarias, constituido por un macizo basáltico antiguo sumamente erosionado con crestas afiladas (roquenublos) y profundas gargantas. Destaca por sus colosales acantilados marinos desnudas y los roques que emergen del mar de forma vertical.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38039','espacio','Reserva Natural Especial de Las Palomas y Paisaje Protegido de la Costa de Acentejo','Destaca por albergar en sus cotas medias un reducto catalogado de laurisilva y fayal-brezal en excelente estado de conservación, que sirve de refugio a las palomas turqué y rabiche. El litoral cae bruscamente mediante acantilados basálticos de gran potencial estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38013','espacio','Reserva Natural Especial del Volcán Chinyero y Acantilados de Los Gigantes (borde este)','Paisaje dominado por el cono de piroclastos negros y las coladas lávicas de la erupción del Chinyero (1909), el último volcán activo de Tenerife. Hacia el mar, el relieve se desploma mediante los monumentales acantilados de Los Gigantes, con paredes verticales basálticas de 500 metros de altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38043','espacio','Paisaje Protegido de Costa de Acentejo y bosques de laurisilva de Agua García','El monte de Agua García conserva un reducto relicto de laurisilva de incalculable valor botánico, famoso por sus viñátigos centenarios gigantescos. El sector litoral presenta perfiles acantilados abruptos labrados sobre las series volcánicas más antiguas del norte de la isla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38045','espacio','Acantilados de El Time (borde costero) y desembocadura de la Caldera de Taburiente','Espectacular pared geológica correspondiente al gran escarpe de El Time, que delimita la fractura norte del valle de Aridane con un desnivel vertical imponente sobre el océano. La desembocadura del barranco de Las Angustias aporta un Delta de cantos rodados volcánicos de gran interés visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38046','espacio','Parque Rural de Anaga (sector suroeste) y valles interiores de la cordillera','Municipio interior enclavado en un valle de origen erosivo y tectónico rodeado por los relieves basálticos antiguos del macizo de Anaga. Las laderas sombrías muestran formaciones de monteverde y transiciones botánicas hacia bosques termófilos de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38047','espacio','Monumento Natural de la Costa de Hiscaguán y escarpe de El Time (sector norte)','El relieve está definido por una rampa volcánica continua cortada de forma salvaje por barrancos estrechos que terminan en acantilados marinos verticales. Destaca el escarpe de El Time, una grandiosa estructura tectónica y erosiva visible desde toda la vertiente occidental de La Palma.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38049','espacio','Parque Rural de Valle Gran Rey, Monumento Natural de los Lomo del Carretón','Impresionante valle de erosión caracterizado por imponentes paredes rocosas casi verticales de basalto gris que encajonan el palmeral canario más denso y espectacular de La Gomera. El Lomo del Carretón añade valor geológico con su gigantesco escarpe de fonolitas y traquitas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38050','espacio','Parque Nacional de Garajonay (sector oeste), Monumento Natural de Roque Cano y Los Órganos','Excepcional patrimonio geomorfológico que cuenta con el Roque Cano, un pitón fonolítico monumental que domina el paisaje. En el sector marítimo septentrional destaca el acantilado de Los Órganos, una espectacular columnata basáltica expuesta por la erosión marina que asemeja tubos de órgano gigantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38048','espacio','Monumento Natural de Las Playas (borde norte) y Reserva Natural Especial de Timijiraque','Relieve volcánico abrupto caracterizado por mesetas elevadas que se desploman bruscamente hacia el océano mediante escarpes de deslizamiento. El entorno conserva manchas de monteverde y bosquetes termófilos adaptados a las nieblas constantes que barren las cumbres orientales de El Hierro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','espacio','Parque Natural de la Corona Forestal, Paisaje Protegido de la Resbala y Paisaje Lunar','Municipio a mayor altitud de Canarias, asentado sobre los contrafuertes meridionales de la Caldera de Las Cañadas. Destaca el Paisaje Lunar, una singular formación geomorfológica de chimeneas de hadas labradas por la erosión diferencial sobre potentes depósitos de cenizas volcánicas blancas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38053','espacio','Parque Natural de Cumbre Vieja (Sector Oriental) / Barranco de los Hombres','Rampa volcánica oriental de La Palma caracterizada por un relieve de coladas basálticas antiguas fuertemente encajonadas por barrancos paralelos. Las faldas montañosas altas acumulan espesas choperas y masas compactas de laurisilva en las vaguadas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','espacio','Acantilados de Puerto Calderón / Ensenada de Luaña','Espectacular tramo de costa rasa calcárea configurado por farallones calizos que sufren la erosión constante del mar Cantábrico. El relieve costero muestra un antiguo puerto natural excavado en la roca con galerías e importantes secciones geológicas estratificadas expuestas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','espacio','Canal del río Asón / Gargantas de Marrón','Tramo medio del río Asón donde el cauce fluye encajonado entre laderas escarpadas calcáreas con abundantes formaciones caleras primarias. Destacan sus frondosos sotos aluviales y masas de encinar atlántico calcícola que tapizan los bloques de piedra coluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90244','espacio','Valle de Anievas / Cuenca alta del río Casar','Paisaje de media montaña de transición con un relieve modelado sobre arcillas y areniscas verdes. Las pequeñas vaguadas acumulan la humedad atlántica generando praderas higrófilas permanentes y masas dispersas de robledales autóctonos muy bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','espacio','Parque Natural Saja-Besaya / Canales del río Los Llares','Entorno montañoso quebrado caracterizado por profundos valles fluviales encajonados sobre areniscas del triásico. Las escarpadas laderas de umbría albergan inmensos hayedos puros, robledales de melojo y pequeños arroyos de aguas heladas de carácter salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90635','espacio','Parque Natural de las Marismas de Santoña, Victoria y Joyel / Marisma de Jado','Extensa llanura intermareal y fangosa de carácter estuarino influenciada por las mareas del Cantábrico. El paisaje visual destaca por la horizontalidad de sus canales someros, juncales halófilos y praderas salinas que cambian de fisonomía de forma horaria.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','espacio','Marisma de Joyel / Acantilados de Cabo Quejo','Litoral rocoso agreste expuesto al oleaje directo caracterizado por el Cabo Quejo, una imponente mole caliza de formas afiladas cubierta de encinares atlánticos. El relieve contrasta con la tranquilidad de las aguas de la marisma baja interior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','espacio','Sistema Kárstico del Mortillano / Nacedero del río Asón','Impresionante relieve calizo de alta montaña alpina considerado uno de los complejos de cuevas más profundos y kilométricos del mundo. En la superficie destaca el colosal nacedero del río Asón, donde el agua brota verticalmente de una inmensa pared rocosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90030','espacio','Marismas de Astillero / Ría de Solía','Espacio costero semicerrado de llanura aluvial e intermareal recuperado sobre sedimentos finos arcillosos en la bahía de Santander. Ofrece un paisaje horizontal dominado por vegetación halófila palustre que sirve de oasis en la periferia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10002','espacio','Marismas de Santoña (Sector Occidental) / Ría de Treto','Amplio complejo estuarino modelado por la desembocadura del río Asón en las oscilaciones de las mareas. Destaca por la horizontalidad de sus llanuras de fango y extensos cañaverales que configuran un paisaje de alta productividad biológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','espacio','Parque Natural Saja-Besaya / Garganta del río Torina','Valle fluvial sumamente angosto y encajonado labrado sobre areniscas del Buntsandstein por el curso   torrencial del río Torina. Las vertientes de umbría están tapizadas de hayedos monumentales y grandes masas de helechales hiperhúmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','espacio','Cabo de Ajo / Ría de Castellanos','El punto más septentrional de Cantabria, caracterizado por una colosal meseta caliza cortada por acantilados marinos verticales de gran dureza visual. Los cantiles rocosos sufren la abrasión marina y albergan raras especies de flora rupícola costera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39012','espacio','Diapiro salino de Cabezón / Riberas del río Saja','Singular paisaje geomorfológico originado por un afloramiento triásico de sal y yesos que deforma el relieve local. El río Saja vertebra el término municipal con un soto aluvial maduro compuesto por alisos y sauces de gran porte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39013','espacio','Macizo de Peña Sagra / Cuenca del río Buyón / Sierras calcáreas','Relieve alpino de alta montaña integrado en la comarca de Liébana, caracterizado por moles calizas escarpadas y canchales de piedra desnuda. Las umbrías albergan excelentes bosques mixtos de hayas, encinares de roca y robledales pubescentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','espacio','Parque Natural Saja-Besaya / Valle de Cabuérniga / Monte Aa','Majestuoso paisaje de montaña atlántica con una topografía de suaves lomas forestales y escarpados barrancos secundarios sobre pizarras. Alberga magníficas y maduras masas de robledal pedunculado, hayedos puros y el histórico hayedo del monte Aa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','espacio','Parque Nacional de los Picos de Europa / Macizo de Ándara / Circo Glaciar de Fuente Dé','Uno de los paisajes geológicos más sobrecogedores y colosales del mundo, dominado por un anfiteatro calizo calcáreo vertical que supera los ochocientos metros de desnivel. El relieve muestra agujas monolíticas desnudas, lapiaces y morrenas de origen glaciar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39016','espacio','Ría de Raos / Cueva de El Pendo (Entorno Kárstico)','Relieve colinado bajo calcáreo en el entorno de la bahía de Santander, caracterizado por depresiones y dolinas kársticas superficiales. Los márgenes costeros de la ría conservan una pequeña zona de marisma baja con carrizales estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39027','espacio','Riberas del río Híjar / Cola del Embalse del Ebro','Amplia llanura aluvial de montaña donde confluyen las dinámicas hidrográficas del curso alto del río Híjar. El relieve muestra terrazas pedregosas cuaternarias que entran en contacto con la lámina de agua del embalse, rodeadas de pastizales húmedos permanentes y sauces ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39017','espacio','Embalse del Ebro (Margen Norte) / Península de Lastra / Pastizales húmedos','Paisaje geomorfológico dominado por la inmensa lámina de agua dulce encajada en una gran depresión estructural a más de ochocientos metros de altitud. Las orillas presentan suaves penínsulas de relieve ondulado y un espeso cinturón de turberas y juncales de gran valor contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','espacio','Vega del río Besaya / Monte de Cohicillos','Tramo medio del río Besaya caracterizado por una llanura de inundación aluvial de sedimentación fina cuaternaria. Las faldas del monte de Cohicillos muestran una topografía suave cubierta de pequeños quejigares que contrastan con los sotos de sauces y alisos del fondo del valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','espacio','Cuenca del río Pas / Riberas de Pomaluengo','Paisaje fluvial de relieve muy suave donde el río Pas ensancha su lecho aluvial dejando depósitos de arenas y   gravas finas. Las márgenes mantienen una franja bien conservada de bosque de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','espacio','Acantilados de Cerdigo / Punta de los Cuervos / Ría de Oriñón','Impresionante fachada litoral del extremo oriental cántabro, constituida por colosales e ininterrumpidos muros calizos que sufren el azote directo del mar. Destacan las morfologías de rasa marina erosionada y el encajonamiento calcáreo de la desembocadura de la ría de Oriñón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39021','espacio','Parque Natural Saja-Besaya / Canales de Cieza / Monte de Villasuso','Relieve prepirenaico de fuerte pendiente constituido por pizarras y areniscas, que marca el inicio de la serranía del Besaya. Las laderas orientadas a la umbría atesoran masas forestales densas de hayedos puros y robledales mixtos surcados por arroyos torrenciales de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','espacio','Parque Nacional de los Picos de Europa / Desfiladero de La Hermida / Macizo de Ándara','Uno de los cañones geológicos más sobrecogedores y colosales de la península, donde el río Deva corta de forma transversal las estructuras calizas carboníferas en un desfiladero de paredes verticales que superan los seiscientos metros de caída a plomo. Las grietas albergan encinares atlánticos relictos de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39023','espacio','Parque Natural de las Marismas de Santoña, Victoria y Joyel / Estuario del Asón','Extensa llanura intermareal y fangosa de carácter estuarino influenciada de forma horaria por las   corrientes del Cantábrico. El relieve es totalmente horizontal, dominado por canales someros, juncales halófilos y praderas salinas de un altísimo interés paisajístico y ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','espacio','Parque Natural de Oyambre (Sector Oriental) / Ría de la Rabia / Acantilados de la Garita','Espectacular tramo costero donde la ría de la Rabia genera un estuario interior somero de gran belleza plástica rodeado de marismas fangosas. Hacia el mar abierto, el relieve se fractura en acantilados calizos y areniscas desgastadas por la abrasión marina constante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','espacio','Valle de Toranzo / Riberas del río Pas / Monte Castillo (Faldas)','Amplio corredor fluvial atlántico donde el río Pas discurre encajonado entre laderas forestales de areniscas del triásico. Las márgenes albergan sotos ripícolas continuos muy frondosos compuestos por alisos monumentales y sauces que forman galerías vegetales tupidas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','espacio','Nacedero del río Aguanaz / Sistema Kárstico de Fuente las Varas','Relieve colinado caléreo caracterizado por un modelado kárstico superficial con abundancia de dolinas y sumideros naturales. Destaca la espectacular surgencia kárstica del río Aguanaz, donde el agua brota de forma tranquila entre bloques de roca caliza rodeada de densos encinares atlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39029','espacio','Marisma de Escalante / Ría de Treto (Sector Occidental)','Complejo de llanuras de fango, canales de marea y canales someras integrado en la reserva natural de las marismas de Santoña. Ofrece un paisaje horizontal   cambiante dominado por densas comunidades de vegetación halófila y extensos cañaverales salvajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39030','espacio','Valle del río Agüera / Cortados de Candina / Embalse de El Juncal','Valle de origen erosivo profundamente encajonado entre las imponentes moles calizas de la costa oriental. El río Agüera fluye de forma sinuosa por el fondo aluvial escoltado por un corredor forestal denso de alisos, sauces y encinares de roca en los paredones superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','espacio','Valle del río Campiazo / Lomas de Beranga','Topografía de lomas suaves arcillo-arenosas moldeadas por la erosión diferencial en la cuenca del río Campiazo. El curso fluvial aporta una franja estrecha de vegetación ripícola con sauces negros y espadañas que aporta variedad cromática al entorno de praderías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','espacio','Sierra de Híjar / Nacimiento del río Ebro (Fontibre) / Circo de Tres Mares','Majestuoso entorno alpino de alta montaña caracterizado por un relieve modelado por antiguos procesos glaciares con circos y morrenas desnudas. Destaca Fontibre, la surgencia kárstica perenne donde afloran las aguas subterráneas del río Híjar dando origen formal al río Ebro entre un frondoso bosque mixto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39033','espacio','Desfiladero de La Hermida (Sector Oriental) / Río Nansa / Cueva de El Soplao (Entorno natural)','Relieve calizo sumamente quebrado y accidentado por las cuencas de los ríos Deva y Nansa. El paisaje muestra escarpes verticales de roca calera grisácea y profundos valles umbríos cubiertos por densas masas de hayedos, encinares atlánticos y helechales hiperhúmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39034','espacio','Collado de Hoz / Cuenca alta del río Lamasón / Desfiladero de La Hermida (Estribaciones)','Relieve calizo sumamente quebrado e inhóspito, definido por espectaculares lapiaces y simas verticales del macizo de Peñarrubia. Las umbrías y barrancos secundarios conservan masas muy densas de encinar atlántico calcícola y hayedos que se aferran a las grietas de la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','espacio','Parque Natural de las Marismas de Santoña, Victoria y Joyel / Acantilados de la Atalaya / Ría de Treto','Litoral rocoso y escarpado de origen calizo donde destaca la Atalaya, un cono basáltico y calcáreo erosionado por la abrasión marina que muestra túneles naturales y oquedades fósiles. El relieve se conecta con las llanuras fangosas intermareales del estuario del Asón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','espacio','Valle cerrado de Liendo (Poljé) / Acantilados de Sonabia / Monte Candina','Excepcional depresión kárstica circular (poljé) de fondo totalmente llano y aluvial rodeada por imponentes murallas de roca caliza carbonífera. Los paredones exteriores se desploman de forma vertical sobre el Cantábrico, albergando la única colonia costera de buitres leonados de Europa central.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','espacio','Macizo de las Peñas de Rucandio / Las Tetas de Liérganes (Pico Busampiro) / Río Miera','Imponentes e icónicas moles calizas de perfiles cónicos gemelos que emergen de forma abrupta sobre el curso medio del río Miera. El relieve fluvial es rápido y pedregoso, excavando canales estrechos flanqueados por sotos de ribera bien estructurados y encinares atlánticos calcícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','espacio','Ría de Limpias / Sotos del río Asón','Tramo estuarino encajonado donde la dinámica mareal del Cantábrico penetra en el curso bajo del río Asón, generando llanuras inundables salinas. Cuenta con un corredor continuo de carrizales y espadañares que contrastan con los relieves boscosos de las laderas calcáreas perimetrales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','espacio','Puerto de el Escudo / Valle alto del río Luena / Cumbres del Pas','Paisaje de alta montaña atlántica caracterizado por vertientes de pendientes extremas y profundas canales erosionadas de origen torrencial sobre areniscas. Las faldas montañosas de umbría están cubiertas por majestuosos hayedos puros y extensos pastizales húmedos de altura de gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','espacio','Marisma de Rubayo / Ría de Cubas (Desembocadura del Miera)','Paisaje costero horizontal condicionado por el estuario somero de la ría de Cubas en su encuentro con la bahía de Santander. El relieve está constituido por llanuras intermareales fangosas y canales de marea delimitados por suaves lomas verdes de depósitos limosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','espacio','Sierra de los Solares / Riberas del río Saja','Zona de transición montañosa donde el río Saja ensancha su cauce aluvial, ramificándose en múltiples brazos secundarios con depósitos masivos de cantos rodados cuarcíticos. Las laderas boscosas de la sierra albergan dehesas maduras de cajigas (robles) y quejigos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','espacio','Garganta del río Miera / Sistema kárstico de El Alto del Caracol','Impresionante tajo geológico de paredes calizas totalmente verticales esculpido por la acción del río Miera sobre estructuras calcáreas mesozoicas. El relieve muestra un modelado kárstico superficial extremo con laberintos de lapiaces, canchales de ladera y hayedos colgados relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39044','espacio','Estuario del río Pas (Ría de Mogro) / Acantilados de Cudón / Isla de la Pedrosa','Espectacular y recortado tramo de costa rasa calcárea que incluye la desembocadura trenzada del río Pas entre llanuras intermareales someras y lenguas de arena vivas. Los escarpes rocosos costeros muestran formas de erosión marina extrema expuestas al oleaje constante.   Miera • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39046','espacio','Parque Natural Saja-Besaya (Sector Oriental) / Valle de Iguña / Arroyo de la Helguera','Cuenca de erosión de relieve quebrado profundamente encajonada entre los macizos forestales de la divisoria cantábrica. Las umbrías atesoran manchas muy densas de hayedos, robledales pedunculados y acebedas relictas, surcados por riachuelos torrenciales cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','espacio','Parque Natural de las Marismas de Santoña, Victoria y Joyel / Marisma de Victoria / Punta del Brusco','Espacio lagunar y costero donde la marisma de Victoria conforma una cubeta somera de aguas tranquilas y dulceacuícolas rodeada de kilométricos cañaverales. Hacia el mar abierto, el relieve se cierra bruscamente en los salientes rocosos calizos de la punta del Brusco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','espacio','Macizo de Peña Cabarga (Ladera Sur) / Karst de Arcera','Singular relieve kárstico superficial desmantelado por procesos erosivos e históricas labores extractivas, dejando expuesto un laberinto de agujas y pináculos calizos de un intenso color rojizo debido a la concentración de óxidos de hierro, rodeado de encinares atlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','espacio','Desfiladero de La Hermida / Desfiladero del río Cicera / Mirador de Santa Catalina (Escarpes)','Corazón geológico del mayor cañón de la cordillera Cantábrica, con paredes verticales de roca caliza carbonífera que superan los seiscientos metros de caída a plomo sobre el lecho del río Deva. El relieve es totalmente abrupto, salvaje y cubierto de encinares reliquia de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','espacio','Macizo de Peña Sagra (Vertiente Sur) / Cuenca alta del río Bullón','Paisaje alpino de alta montaña integrado en la comarca de Liébana, caracterizado por escarpadas moles calizas de perfiles afilados y grandes canales de aludes. Las umbrías boscosas albergan masas puras de hayedos, abedulares de altura y acebedas de carácter salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39051','espacio','Garganta del río Besaya / Monte Somaconcha','Angosto desfiladero fluvial donde el río Besaya corta transversalmente las estructuras de areniscas triásicas rojizas. Las faldas montañosas de fuerte pendiente están cubiertas por frondosos bosques de roble melojo y hayedos que colonizan los suelos pedregosos silíceos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','espacio','Parque Natural de las Dunas de Liencres / Estuario del Pas / Costa Quebrada (Urros de Liencres)','Uno de los paisajes geomorfológicos litorales más espectaculares del norte peninsular, constituido por un inmenso campo de dunas vivas acumuladas en la desembocadura del río Pas. El relieve marino adyacente muestra islotes rocosos escarpados (urros) exentos surgidos por el colapso de antiguos acantilados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39053','espacio','Valle alto del río Nansa / Peña Labra / Bosque de Cruz de Cabezuela','Recóndito valle alpino de alta montaña encajonado en el extremo suroccidental, flanqueado por las moles calizas y de arenisca de la cordillera Cantábrica. Las umbrías conservan masas densas de hayedos puros y abedulares subalpinos, surcados por el río Nansa en su fase más torrencial de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39054','espacio','Ría de San Martín de la Arena / Sotos del río Requejada','Relieve colinado bajo calcáreo en el margen derecho del estuario del río Saja-Besaya. Muestra pequeñas zonas de marisma aluvial y llanuras intermareales fangosas que conservan cinturones estables de carrizales e interesantes secciones de terrazas cuaternarias fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','espacio','Confluencia de los ríos Deva y Quiviesa / Cuenca de Liébana','Depresión orográfica y fosa tectónica interior rodeada por los colosales farallones de los Picos de Europa y Peña Sagra. El encuentro de caudales fluviales genera una rica llanura aluvial interior con un microclima particular que permite la proliferación de densos encinares de afinidad mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','espacio','Monte Castillo (Complejo Kárstico) / Riberas del río Pas','Elevación cónica caliza cuna del paleolítico que esconde un espectacular laberinto kárstico subterráneo repleto de galerías, simas y oquedades naturales. A sus pies, el río Pas discurre encajonado de forma sinuosa sobre gravas cuaternarias, rodeado por una densa sauceda y alisedas maduras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','espacio','Pico Gandara / Cañón del río Asón / Cueva de Cullalvera (Entorno Kárstico)','Impresionante anfiteatro calcáreo caracterizado por gigantescos y escarpados farallones rocosos que custodian el desfiladero del río Asón. El subsuelo alberga colosales cavidades fruto del modelado kárstico, mientras la superficie está tapizada por encinares atlánticos calcícolas aferrados a la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39060','espacio','Riberas del río Saja / Altamira (Entorno geológico) / Monte de Helguera','Suave relieve colinado calcáreo donde el río Saja dibuja amplios meandros sobre depósitos de sedimentos finos aluviales. El entorno presenta dolinas superficiales fósiles y laderas umbrías cubiertas por pequeños bosquetes mixtos de quejigo y fresnedas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39059','espacio','Riberas del río Ebro y río Híjar / Vega de Reinosa','Fosa tectónica y llanura de inundación de montaña situada a más de ochocientos metros de altitud, donde confluyen los caudales del Híjar y el Ebro. Presenta terrazas aluviales pedregosas flanqueadas por una franja estrecha pero continua de vegetación ripícola con sauces y pastizales húmedos permanentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','espacio','Acantilados de Loredo y Langre / Cabo de Ajo (Sector Occidental) / Isla de Santa Marina','Espectacular tramo de costa rasa calcárea constituido por colosales e ininterrumpidos muros de areniscas y calizas que caen a plomo sobre el Cantábrico. El relieve litoral sufre una intensa abrasión marina, mostrando plataformas de rasas y cuevas costeras labradas por el oleaje batido.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39062','espacio','Cuenca del río Miera / Cueva de la Garma (Entorno Kárstico) / Lomas de Hoz','Topografía de lomas suaves calcáreas modeladas por la erosión diferencial y la disolución kárstica en el interior de la comarca de Trasmiera. Las pequeñas canales acumulan humedad estacional, permitiendo la presencia de matorral de encina atlántica y praderías de fondo de valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','espacio','Desfiladero del río Nansa / Cueva de El Soplao / Sotos de Celis','Impresionante y quebrado relieve montañoso donde el río Nansa excava profundas e inhóspitas gargantas sobre estratos calizos mesozoicos. En las proximidades se sitúa la cubeta geológica de El Soplao, un territorio superficial rico en afloramientos minerales de gran fuerza visual y geológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39064','espacio','Macizo de las Peñas de Rucandio (Vertiente Oriental) / Cabecera del río Aguanaz','Relieve colinado caléreo caracterizado por escarpadas laderas calcáreas que sirven de piedemonte a las grandes cumbres trasmeranas. Las umbrías y barrancos conservan manchas boscosas jóvenes de encina carrasca y robledales que colonizan el suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39065','espacio','Embalse del Ebro (Margen Sur) / Turberas de Valdearroyo','Paisaje geomorfológico condicionado por la inundación de la gran cuenca sedimentaria del Ebro, que genera un relieve costero interior de ensenadas y lenguas de arena bajas. Cuenta con extensos humedales, carrizales permanentes y turberas húmedas higrófilas de alto valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','espacio','Acantilados de la Garita y Casasola / Ensenada de Fonfría','Fachada litoral rectilínea caracterizada por una crudeza visual extrema, donde las mesetas calizas se desploman de forma vertical sobre el océano en acantilados fósiles bajos. La erosión hidrodinámica ha labrado pequeñas e interesantes ensenadas kársticas encajadas en la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','espacio','Valle de Ruesga / Desfiladero del río Asón / Cuenca de Matienzo','Impresionante y majestuoso tajo geológico con farallones calizos carboníferos verticales esculpido por el río Asón. Limita con la cubeta de Matienzo, una de las depresiones kársticas cerradas (poljé) más grandes e perfectas de Europa, rodeada de encinares de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39066','espacio','Parque Natural Saja-Besaya / Fuentona de Ruente / Hayedo de Ucieda','Alberga la mítica Fuentona de Ruente, una espectacular e incomparable surgencia kárstica intermitente de aguas heladas que brota directamente al pie de una pared caliza. Hacia la sierra, el término se desploma en profundas canales cubiertas por el monumental hayedo de Ucieda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39077','espacio','Valle del río Besaya / Hoces de Santiurde / Monte Lantueno','Zona de transición de la cordillera donde el río Besaya discurre fuertemente encajonado labrando desfiladeros entre las areniscas triásicas. Las laderas montañosas de fuerte pendiente están densamente cubiertas por melojares y robledales caducifolios mixtos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','espacio','Riberas del río Pas / Lomas de Villasevil','Sector medio del valle del Pas caracterizado por una llanura aluvial con grandes depósitos de cantos rodados cuarcíticos. El cauce mantiene un corredor forestal denso e   ininterrumpido de alisos y sauces que forma un cinturón vegetal continuo de alto valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39079','espacio','Parque Natural de las Marismas de Santoña, Victoria y Joyel / Monte Buciero / Acantilado del Caballo','Imponente tómbolo calizo aislado (Monte Buciero) que emerge sobre el Cantábrico unido al continente por lenguas de arena y marismas. Su fachada septentrional presenta acantilados colosales verticales esculpidos por la abrasión marina, cubiertos por el mayor encinar atlántico calcícola del norte español.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39069','espacio','Cuenca del río Besaya / Monte Tejas (Complejo Kárstico)','Depresión aluvial flanqueada por relieves calizos y macizos escarpados que limitan el valle de Buelna. El subsuelo del monte Tejas presenta una red laberíntica de cavidades y lapiaces superficiales cubiertos de encinares mediterráneos y quejigares de gran rusticidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','espacio','Pico Pico Jano / Embalse de Alsa / Nacimiento del río Aguayo','Relieve montañoso abrupto caracterizado por fuertes desniveles sobre areniscas cuarcíticas y materiales silíceos. La cabecera del río se caracteriza por un relieve de fuertes pendientes, bloques de piedra sueltos y riachuelos cristalinos que descienden hacia las aguas mansas embalsadas de Alsa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39071','espacio','Cumbres Pasiegas / Cabecera del río Pas / Hayedo de Vegaloscorrales','Paisaje de alta montaña pasiega caracterizado por vertientes de pendientes extremas y profundas canales erosionadas de origen torrencial en la cabecera del Pas. Las   faldas montañosas de umbría están cubiertas por pequeños pero maduros hayedos puros y extensos prados de altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','espacio','Valle alto del Miera / Portillo de Lunada / Circos Glaciares del Miera','Espectacular e imponente paisaje alpino de alta montaña dominado por un modelado glaciar perfecto con circos escalonados, morrenas y paredes calizas verticales talladas en forma de "U". El relieve es de una crudeza visual sobrecogedora, con riachuelos torrenciales de aguas heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','espacio','Parque Natural de Oyambre / Ría de San Vicente / Ría de Rubín / Cabo de Oyambre','Uno de los paisajes costeros y estuarinos más espectaculares de España, donde las rías de San Vicente y Rubín forman un laberinto de canales de marea, llanuras intermareales someras y marismas fangosas. El relieve costero culmina en el imponente cabo de Oyambre, rodeado de acantilados bajos batidos por el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','espacio','Costa Quebrada (Sector Oriental) / Islote de Virgen del Mar / Acantilados de San Juan de la Canal','Fachada litoral escarpada y recortada de origen calcáreo que forma parte de la Costa Quebrada. El relieve marino muestra una alternancia de escarpes de roca expuestos, urros exentos e islotes rocosos surgidos por el colapso de antiguos acantilados debido al azote del mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','espacio','Valle de Cayón / Riberas del río Pisueña','Suave relieve colinado y aluvial de transición caracterizado por sedimentos arcillosos del neógeno en la comarca del Pisueña. El río aporta una franja estrecha de vegetación ripícola con sauces negros y alisos centenarios en mitad de un paisaje de praderías atlánticas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','espacio','Península de la Magdalena / Cabo Mayor / Isla de Mouro / Acantilados de Cueto','Espectacular fachada marítima y litoral de la capital cántabra, caracterizada por la imponente presencia calcárea del Cabo Mayor, con paredes verticales que sufren el embate directo de las olas. El relieve costero incluye islotes calcáreos exentos (Mouro) y plataformas de abrasión de gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','espacio','Acantilados de Ubiarco / Ensenada de Calderón (Sector Oriental) / Karst de Santillana','Espectacular tramo de costa rasa calcárea configurado por farallones calizos que sufren la erosión constante del mar Cantábrico en la zona norteña. El interior municipal presenta una topografía modelada por la disolución kárstica con abundancia de dolinas y pequeñas depresiones cunas de dehesas.   Santiurde de de Toranzo • (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39081','espacio','Valle de Carriedo / Riberas del río Pisueña / Lomas de Llerana','Topografía de lomas suaves y pequeños valles aluviales de naturaleza arcillo-arenosa en la cuenca alta del Pisueña. El curso fluvial vertebra el territorio con una franja continua de vegetación ripícola con sauces y alisos rodeada de verdes praderas de siega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','espacio','Cumbres de Carriedo / Cabecera del río Pisueña / Campas de la dehesa','Relieve de media montaña atlántica con divisorias de aguas muy marcadas y lomas cubiertas de   helechales verdes y pastizales húmedos de altura. Los pequeños arroyos que bajan hacia el río Pisueña tallan laderas empinadas bajo la sombra de pequeños rodales de hayedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','espacio','Parque Natural de los Collados de Soba / Cañón del río Gándara / Nacimiento del Asón (Vertiente Oriental) / Cueva de Múneras','Majestuoso paisaje de alta montaña caliza caracterizado por colosales lapiaces, simas y poljés de dimensiones kilométricas. Destaca el cañón del río Gándara, un profundo desfiladero de paredes caleras verticales de cientos de metros de caída, enmarcado en hayedos puros e inmensos prados alpinos salvajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39084','espacio','Valle de Solórzano / Riberas del río Campiazo','Relieve colinado de transición caracterizado por pequeños valles de erosión labrados sobre materiales calcáreos y arcillosos de la comarca trasmerana. Las zonas de ladera conservan manchas de carballeiras jóvenes y encinares atlánticos integrados en la dinámica húmeda regional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39085','espacio','Ría de San Martín de la Arena (Desembocadura) / Punta del Dichoso / Acantilados de El Torco','Espectacular estuario fluvial donde confluyen las cuencas de los ríos Saja y Besaya antes de verter sus aguas al océano en un relieve encajonado. El relieve costero destaca por la Punta del Dichoso, un saliente calizo de formas afiladas y escarpadas expuesto a la abrasión marina extrema.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39086','espacio','Parque Natural Saja-Besaya / Valle de Cabuérniga (Sector Alto) / Sotos de Bárcena Mayor / Río Argoza','Espectacular y recóndito paisaje de montaña atlántica en el corazón de la reserva cántabra, caracterizado   por profundas gargantas excavadas por el río Argoza sobre areniscas. Las laderas de fuerte pendiente están completamente tapizadas por densos y maduros hayedos puros y cajigas centenarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','espacio','Confluencia del río Saja y río Besaya / Monte Dobra (Ladera Norte)','Amplia llanura aluvial y de inundación donde confluyen los dos principales ejes fluviales de la provincia sobre depósitos de gravas. El relieve perimetral destaca por las estribaciones calcáreas del monte Dobra, que presenta pequeños escarpes y afloramientos de lapiaces erosionados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39088','espacio','Parque Nacional de los Picos de Europa / Garganta del río Urdón / Desfiladero de La Hermida (Sector Occidental)','Uno de los enclaves de alta montaña caliza más espectaculares, aislados y sobrecogedores de España, colgado literalmente sobre un profundo abismo. El relieve muestra paredes verticales de caliza carbonífera de más de seiscientos metros de caída vertical a plomo sobre el desfiladero del río Urdón, rodeado de hayedos colgados relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39089','espacio','Valle del Nansa / Desfiladero de Peña Bejo / Riberas del río Nansa','Estrecho cañón fluvial de gran belleza plástica y fuerza geológica, donde el río Nansa corta las estructuras calizas y de arenisca en la angostura de Peña Bejo. El entorno conserva una excelente representación de bosque atlántico gallego-cántabro hiperhúmedo con robles y alisos monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','espacio','Sistema Kárstico de las Minas de Udías / Lomas de Udías','Topografía de suaves colinas calcáreas caracterizada por un modelado kárstico interior rico en cavidades colgadas y dolinas de disolución superficial. Las faldas y vaguadas albergan pequeñas dehesas de robles y un matorral de encina atlántica adaptado al suelo calcáreo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39095','espacio','Ría de Tina Mayor / Ría de Tina Menor / Desembocadura del río Deva y río Nansa / Acantilados de Pimiango (Sector Oriental)','Espectacular y recortado tramo costero en el límite occidental de la provincia, donde las desembocaduras de los ríos Deva (Tina Mayor) y Nansa (Tina Menor) forman dos majestuosos estuarios encajonados entre colosales acantilados calizos verticales cubiertos de encinares atlánticos relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','espacio','Parque Natural de Oyambre (Sector Occidental) / Monte Corona / Ría de Capitán','Relieve colinado de transición caracterizado por el Monte Corona, una extensa e histórica masa forestal mixta de frondosas autóctonas asentada sobre materiales arcillosos del triásico. El municipio se abre hacia el litoral en las marismas bajas y canales someras de la ría de Capitán.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39092','espacio','Valle del río Camesa / Lomas de Mataporquera / Formaciones de arenisca','Altiplanicie de transición montañosa hacia la meseta castellana, caracterizada por un relieve suavemente ondulado sobre areniscas del triásico y depósitos aluviales finos del Camesa. Presenta dehesas aclaradas de roble melojo bien adaptadas al clima riguroso continentalizado de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39093','espacio','Garganta del río Polla / Rebollares de Valdeprado / Cumbres de Hormiguera','Relieve de media montaña caracterizado por valles sinuosos de origen torrencial labrados sobre areniscas y pizarras. Las laderas orientadas a la umbría conservan masas forestales densas y continuas de roble melojo y quejigares de gran rusticidad que tapizan el terreno quebrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','espacio','Cañón del río Ebro / Hoces de Valderredible / Tobas de Polientes / Cárcavas de Ruerrero','Impresionante tajo geológico excavado por el río Ebro sobre las plataformas calcáreas del extremo meridional cántabro, generando farallones y cortados rocosos verticales de una gran potencia visual. Destacan las formaciones de tobas calcáreas depositadas por surgencias y las espectaculares cárcavas de erosión arcillosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39096','espacio','Macizo de los Picos de Europa (Piedemonte) / Valle de Cereceda / Cuenca alta del río Quiviesa / Bistruey','Relieve alpino de alta montaña integrado en la comarca de Liébana, dominado por el imponente pico Bistruey y laderas de fuertes pendientes sobre pizarras y cuarcitas. Las faldas montañosas albergan inmensos hayedos, robledales de melojo y pequeños arroyos torrenciales de aguas sumamente puras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','espacio','Cumbres Pasiegas / Nacimiento del río Pas / Castro Valnera (Vertiente Norte)','Paisaje de alta montaña pasiega de gran fuerza geomorfológica, condicionado por un relieve quebrado de fuertes pendientes labrado sobre areniscas calizas bajo el imponente macizo de Castro Valnera. Las vaguadas sombrías conservan pequeños rodales de hayedo y extensos pastizales de altura de gran plasticidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','espacio','Riberas del río Pisueña / Lomas de Villacarriedo','Suave relieve colinado y aluvial de la comarca pasiega central compuesto por sedimentos arcillo-arenosos del neógeno. El curso del río Pisueña aporta un cinturón modesto de saucedas y alisedas, flanqueado por dehesas aclaradas de robles que acompañan las verdes praderas húmedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39099','espacio','Macizo de Peña Cabarga (Ladera Norte) / Karst de Obregón','Singular relieve kárstico superficial caracterizado por un laberinto de agujas, pináculos y pináculos de caliza de un intenso color rojizo debido a la explotación minera histórica de óxidos de hierro. Las grietas e intercolumnios están colonizados de forma natural por encinares atlánticos densos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','espacio','Valle de Toranzo (Sector Oriental) / Lomas de Villafufre / Arroyo de la dehesa','Topografía de lomas suaves arcillosas degradadas orientadas hacia la fosa media de la cuenca del Pas. Las pequeñas canales acumulan humedad estacional permitiendo la presencia de matorral de quejigo y cinturones modestos de carrizal rodeados de prados de siega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','espacio','Valle de Aras / Ría de Rada / Sistema Kárstico del Alto de la Sía','Paisaje quebrado de media montaña calcárea con valles sinuosos que drenan hacia las marismas bajas de la ría de Rada. Las laderas escarpadas presentan afloramientos de lapiaces y cantiles rocosos cubiertos por densas masas de encinar atlántico calcícola bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90116','espacio','Campiña segoviana / Arroyo de la Vega','Paisaje penillanura horizontal sobre materiales arcillosos del terciario eoceno. El terreno es de lomas muy suaves y onduladas con suelos pedregosos, donde la escorrentía estacional genera pequeñas charcas y pastizales secos mediterráneos de baja altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90117','espacio','Valle del río Pirón / Cueva de la Vaquera (Entorno)','Relieve de transición kárstica donde el río Pirón excava una pequeña hoz sobre las calizas cretácicas del piedemonte de la sierra. Las laderas escarpadas presentan afloramientos rocosos cubiertos por encinares de gran valor botánico y vegetación rupícola especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90118','espacio','Valle del río San Juan / Lomas de Aldealcorvo','Topografía ondulada labrada sobre arcillas y margas por arroyos de régimen estacional. Los fondos de valle acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90119','espacio','Parque Nacional de la Sierra de Guadarrama / Puerto de Linera / Montes de Gallegos','Vertiente montañosa de pendientes extremas tallada sobre gneis y granitos, caracterizada por un relieve quebrado de origen torrencial. Las faldas de la sierra están completamente tapizadas por frondosas masas de pino silvestre, hayedos relictos y melojares de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90120','espacio','Sierra de la Serrezuela / Barranco de San Juan','Alineación montañosa caliza de perfil alomado con vertientes erosionadas en el extremo norte de la provincia. Las umbrías y barrancos conservan manchas boscosas de encina carrasca y quejigos calcícolas bien adaptados a suelos pobres y pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90121','espacio','Tierra de Pinares / Riberas del río Voltoya','Llanura sedimentaria caracterizada por grandes depósitos de arenas eólicas y cantos rodados cuarcíticos. El relieve presenta dunas fósiles estabilizadas y está densamente cubierto por masas de pino piñonero adaptadas a la escasez hídrica superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90122','espacio','Valle del arroyo de Aldeasoña / Cortados de las calizas','Pequeño paso angosto esculpido por arroyos de régimen torrencial entre crestas de piedra caliza neógena. Las laderas del estrecho cañón están densamente pobladas por quejigos y encinas que forman túneles vegetales de umbría permanente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90123','espacio','Páramos de Aldehorno / Barranco de Valdehorno','Paisaje típico de páramo fragmentado con escarpes calcáreos y profundas vaguadas de erosión hídrica en el límite con Burgos. Las laderas expuestas muestran   matorrales mediterráneos y tomillares gipsícolas de alta resistencia a la sequía continental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90124','espacio','Cuenca del río Voltoya / Lomas del Codonal','Topografía de lomas suaves arcillo-arenosas con presencia de cantos rodados cuarcíticos finos. Ofrece un paisaje abierto donde el curso del río Voltoya aporta una franja estrecha de vegetación ripícola con sauces y juncos dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90125','espacio','Campiña del río Duratón / Arroyo de San Juan','Paisaje completamente horizontal asentado sobre arcillas y limos terciarios en la llanura central segoviana. La escorrentía superficial modesta genera pequeñas vaguadas higrófilas estacionales que rompen la llanura cerealista uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90126','espacio','Campiña segoviana / Arroyo de la Ermita','Topografía monótona y horizontal sobre arcillas cuaternarias rota únicamente por la incisión de arroyos estacionales. Estos pequeños cauces acumulan humedad suficiente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90127','espacio','Vega del río Eresma / Lomas de Añe','Sector medio del valle del Eresma caracterizado por una llanura aluvial con depósitos de gravas cuaternarias. Cuenta con sotos fluviales continuos bien conservados, donde los sauces y chopos forman un cinturón vegetal de alto valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90128','espacio','Valle del río Santa Águeda / Sabinar de Arahuetes','Escarpada fractura orográfica que corta el páramo calizo calcáreo, generando un profundo barranco de vertientes abruptas. Las zonas protegidas de la insolación conservan uno de los sabinares de Juniperus thurifera más puros y relictos de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42031','espacio','Nacimiento del río Escalote y cortados de la Sierra de Pela','Relieve tectónico marcado por la fractura de las plataformas calcáreas mesozoicas en el extremo sur provincial. La surgencia natural que da vida al río Escalote emerge al pie de imponentes taludes rocosos flanqueados por comunidades mixtas de encina y sabina albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40021','espacio','Valle del río Cega / Cortados de Arevalillo','Angosto cañón calizo labrado por el río Cega al romper las estructuras rocosas que separan los páramos de la sierra. Las paredes verticales albergan una densa masa forestal de encinas y quejigos que se agarran a las repisas de piedra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40022','espacio','Yacimiento de ámbar (Entorno geológico) / Riberas del río Eresma','Relieve aluvial e inundación del río Eresma sobre materiales areniscos del cretácico de gran interés paleontológico. Los márgenes conservan un soto ripícola bien estructurado con sauces y chopos que conviven con campos de dunas fósiles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40024','espacio','Sierra de Ayllón / Cañón del río Aguisejo / Cárcavas de Estebanvela','Impresionante tajo geológico con farallones calizos verticales esculpido por las aguas del río Aguisejo sobre materiales triásicos. El relieve destaca por las   espectaculares cárcavas rojizas de erosión arcillosa extrema y la flora rupícola de ladera. Segovia).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40025','espacio','Entorno fluvial del río Berbellido y cárcavas de la dehesa','Paisaje geomorfológico dominado por la incisión del arroyo sobre terrenos arcillosos, generando formaciones de abarrancamientos de gran vistosidad cromática. La vega asociada mantiene una cobertura modesta pero interesante de vegetación de ribera en un entorno predominantemente agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40026','espacio','Piedemonte de la Sierra de Guadarrama y cañón del río Pirón','Espacio de transición geológica donde las aguas de la sierra cortan las bandas de calizas cretácicas, originando formaciones de lapiaces y pequeñas oquedades. Destacan sus formaciones de encinar carpetano bien conservado y la panorámica limpia de la vertiente norte del sistema montañoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40028','espacio','Praderas del arroyo de la Vega y llanuras cerealistas','Entorno de llanura castellana interrumpido suavemente por una modesta cuenca fluvial estacional, idóneo para observar la uniformidad del relieve de la meseta. La vegetación se restringe a reductos aislados de chopos y álamos que contrastan con los tonos ocres del sustrato sedimentario.   Bermillo de San José (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40030','espacio','Yacimientos de pizarra, cerro del Castillo y ribera del Eresma','Destaca por sus formaciones geomorfológicas de pizarras precámbricas de gran antigüedad, únicas en la comarca por su brillo y disposición laminar. El encajonamiento del río Eresma a su paso por el término aporta una ruptura del relieve con escarpes rocosos y densas manchas de monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40032','espacio','Vega del río Caslilla y dehesas de fresnos','Entorno dominado por llanuras aluviales donde se desarrollan prados húmedos salpicados de fresnos centenarios de alto valor botánico. El contraste entre los suelos cuarcíticos de los llanos superiores y las zonas de umbría del arroyo crea un ecosistema visualmente armónico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40033','espacio','Afloramientos calizos del río polendos y monte de encina','Zona de contacto entre los sedimentos de la meseta y las rocas carbonatadas de la sierra, dando lugar a pequeños afloramientos rocosos cubiertos de matorral aromático. La cobertura vegetal está dominada por encinas xerófilas adaptadas a las duras condiciones del sustrato calizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40034','espacio','Manantiales de las Fuentes de San Frutos y valle del río San Polendos','Valle angosto y protegido donde emergen surgencias naturales de agua cristalina procedentes de acuíferos kársticos profundos. El microclima local permite el desarrollo de una frondosa olmeda y masas arbóreas de ribera con una frescura visual atípica en la penillanura segoviana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40035','espacio','Monte de Mata de Quintanar y ribera del Polendos','Extensa masa forestal integrada por encinas y quejigos que tapizan un relieve suavemente ondulado sobre arenas y arcillas. La densidad de la cubierta vegetal y el aislamiento de sus valles interiores ofrecen una estampa muy representativa del bosque mediterráneo de llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40036','espacio','Lagunas de Cantalejo (extensión sur) y pinares aluviales','Espacio dominado por dunas continentales cubiertas de pino piñonero, donde el agua subterránea aflora creando humedales estacionales sobre arenas. La alternancia paisajística entre las masas forestales continuas y las láminas de agua someras posee una alta singularidad botánica y geomorfológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40037','espacio','Hoces del río Duratón (tramo norte) y cortados calizos','Inicio del tramo encajonado del río Duratón fuera del parque natural oficial, caracterizado por imponentes paredes de roca caliza grisácea. La erosión fluvial ha labrado meandros encajados flanqueados por una vegetación rupícola muy especializada que cuelga de las repisas rocosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40039','espacio','Ribera del río Riaza y llanos cuarcíticos','Paisaje llano caracterizado por suelos cubiertos de cantos rodados cuarcíticos que reflejan la antigua actividad aluvial de la cuenca del Riaza. El curso fluvial aporta una franja verde lineal de chopos que rompe la monotonía del páramo semidesértico circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40040','espacio','Complejo Lagunar de Cantalejo y pinares de repoblación natural','Sistema catalogado de lagunas de origen eólico únicas en la península, asentadas sobre un mar de dunas de arena continental estabilizadas por el pino resinero. El   complejo ofrece una sucesión de cubetas de agua rodeadas de espadañas, juncos y una biodiversidad vegetal acuática de primer orden europeo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40041','espacio','Lagunas efímeras de las dehesas y cuenca del arroyo Polendos','Terreno llano de transición donde se forman pequeños encharcamientos temporales en épocas de lluvia intensa sobre suelos arcillosos impermeables. La vegetación se limita a pastizales húmedos y pies aislados de encina que rompen la horizontalidad del paisaje agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40045','espacio','Sabinar de Casla y las dehesas del somontano','Uno de los bosques de sabina albar (Juniperus thurifera) mejor conservados y más densos de la vertiente norte del Sistema Central, con ejemplares centenarios singulares. El estrato geológico combina las calizas dolomíticas con los materiales silíceos de la sierra, configurando un paisaje abrupto de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40046','espacio','Cañón del río Riaza y cortados de la dehesa','Tramo donde el río Riaza corta los materiales calcáreos pre-serranos, abriendo un valle angosto escoltado por farallones de roca caliza. En las laderas se asientan comunidades mixtas de encina y quejigo, adaptadas a la acusada exposición solar y al suelo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40047','espacio','Fuentes del arrollo de las Praderas y relieve de páramo','Morfología clásica de páramo calizo tabular fuertemente erosionado en sus márgenes, ofreciendo líneas de desprendimientos rocosos y cárcavas. Pequeños manantiales en la base del páramo sostienen praderas húmedas que contrastan vivamente con la aridez de la meseta superior.   Castrodiez de la Peña (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40048','espacio','Arrecife coralino fósil y escarpes del arroyo de la Hoz','Hito geológico excepcional consistente en un paleoarrecife de coral del Cretácico Superior sobreelevado, visible en las formaciones rocosas calizas del relieve. El cañón excavado por el arroyo muestra paredes verticales donde se aprecian con claridad las estructuras biológicas fosilizadas en la roca.   Castroserna de Abajo (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40053','espacio','Curso alto del río Cega y dehesas de la Garganta','Paisaje pre-montano caracterizado por valles excavados en rocas gneisicas y graníticas por las aguas limpias procedentes de la Sierra de Somosierra. Destaca la frondosidad de sus dehesas de robles melojos y la presencia de grandes bloques erráticos graníticos dispersos por el relieve.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40054','espacio','Nacimiento del río Cega, canchales de la Pinilla y robledales','Escenario de alta montaña alpina que engloba circos glaciares degradados y laderas cubiertas por pedreras o canchales de cuarcitas y gneis. Las zonas medias presentan una de las masas forestales de Quercus pyrenaica más maduras de la provincia, sustituida en la cumbre por matorral de piornos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40065','espacio','Tierra de Pinares segoviana y dunas fósiles del río Pirón','Paisaje completamente dominado por formaciones eólicas de arenas cuaternarias que dibujan un relieve suavemente ondulado de dunas estabilizadas. El dosel vegetal continuo de pino piñonero genera una atmósfera forestal homogénea e impresionante por su gran extensión horizontal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40055','espacio','Loma de San Mamés y arroyos estacionales','Paisaje alomado de materiales sedimentarios arcillosos con escasa cobertura arbórea, representativo de la penillanura cerealista desnuda. Su interés radica en la pureza de las líneas del horizonte y la nitidez de los contrastes cromáticos de la tierra labrada según la estación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40056','espacio','Páramo de las Bodegas y cárcavas del arroyo de San Serapio','Terreno erosionado de calizas y margas donde la escorrentía superficial ha modelado un relieve quebrado con taludes de color blanquecino. Escasas poblaciones de encinas achaparradas y tomillares cubren el sustrato, ofreciendo una estampa descarnada de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','espacio','Confluencia de los ríos Eresma y Voltoya, cortados de arcilla','Espectacular confluencia fluvial donde ambos ríos han excavado profundos cañones sobre terrazas de   arenas y arcillas compactas, creando paredes casi verticales de color rojizo. Los densos pinares de resina se asoman a los bordes de los desfiladeros, creando un paisaje de gran contraste cromático y estructural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40058','espacio','Lagunas calcáreas temporales y dehesa de encina','Zona de llanura con pequeñas depresiones endorreicas donde se acumula el agua de lluvia sobre sustratos de caliches y arcillas. Los encinares aclarados del entorno sirven de marco a estos humedales temporales que varían drásticamente de aspecto a lo largo del año.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40059','espacio','Vertiente norte de la Sierra de Guadarrama y arroyo de San Pedro de las Dueñas','Impresionante relieve de montaña que asciende de forma abrupta hacia las cumbres carpetanas, cubierto por un denso tapiz de robledales y pinares de pino silvestre. El arroyo desciende encajonado entre bloques de granito, formando pequeños saltos de agua y pozas de un alto valor estético y pureza ambiental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40060','espacio','Ribera del río San Juan y laderas del sabinar','Valle protegido por relieves alomados donde el río San Juan serpentea entre formaciones calcáreas bien definidas. Las laderas expuestas al norte albergan encinares maduros, mientras que las solanas muestran ejemplares dispersos de sabina albar integrados en un relieve rocoso quebrado.   Corella (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40061','espacio','Paramera de Ayllón y cárcavas del arroyo de la Vega','Paisaje rústico y sumamente llano situado a gran altitud, expuesto a condiciones climáticas extremas que   limitan el crecimiento arbóreo. El relieve destaca por su severidad geológica, interrumpida únicamente por suaves ondulaciones calcáreas y vegetación esteparia xerófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40902','espacio','Lagunas de Cozuelos y pinares de la dehesa','Depresiones del terreno sobre arenas cuaternarias que albergan pequeñas lagunas de carácter endorreico. El entorno forestal de pinos resineros protege el suelo de la erosión eólica, conformando un paisaje recolector de agua en mitad de la llanura segoviana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40062','espacio','Valle del río San Juan y dehesas calcáreas','Pequeño pasillo fluvial excavado en las plataformas calcáreas del somontano de la sierra. El contraste entre los cortados rocosos calizos de las márgenes del valle y el verdor del estrecho fondo aluvial genera una composición paisajística notable y muy equilibrada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','espacio','El Mar de Pinares y escarpes del río Cega','Inmensa llanura arenosa que alberga una de las masas forestales continuas de Pinus pinaster más extensas de la península ibérica, conocida visualmente como un auténtico "mar verde". El límite del término queda marcado por la profunda incisión del río Cega, cuyas laderas muestran perfiles arenosos y arcillosos de gran altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40068','espacio','Cerro de las Tres Cruces y afloramientos de pizarra','Prominente relieve residual caracterizado por un afloramiento masivo de pizarras paleozoicas que han resistido la erosión de la meseta. Las rocas presentan superficies pulidas por los elementos y una tonalidad oscura que genera un fuerte contraste visual con las llanuras arenosas circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40069','espacio','Ribera del río Adaja y terrazas aluviales','Espacio dominado por los depósitos sedimentarios del río Adaja en su tramo bajo segoviano, donde se aprecian niveles de terrazas de cantos rodados. El cauce está escoltado por una franja continua de vegetación ripícola que serpentea rompiendo la horizontalidad del paisaje agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40070','espacio','Valle del río Caslilla y escarpes calizos','Tramo fluvial encajonado en las plataformas calcáreas pre-serranas, donde la disolución del agua ha labrado pequeños frentes rocosos. La vegetación combina   bosquetes mixtos de encina y sabina albar que se asientan directamente sobre las repisas pedregosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40071','espacio','Paramera de Encinas y arroyos estacionales','Relieve típico de páramo tabular calizo a gran altitud, sometido a una intensa erosión eólica y crioclastia. El paisaje muestra una desnudez geológica severa, salpicada únicamente por matorral xerófilo y encinas achaparradas que resisten el clima continental extremo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40072','espacio','Vega del río Eresma y llanura de inundación','Entorno geomorfológico llano constituido por los depósitos cuaternarios del río Eresma al abandonar la zona de la sierra. Destaca por la homogeneidad de su relieve aluvial y la presencia de alineaciones de álamos y chopos que delimitan los antiguos cauces estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40073','espacio','Praderas del arroyo Polendos y llanos arcillosos','Paisaje de transición de la campiña segoviana donde los suelos arcillosos retienen la humedad en las pequeñas vaguadas. La topografía es suavemente ondulada, ofreciendo amplias perspectivas visuales donde la vegetación se concentra en pequeñas dehesas comunales aisladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40074','espacio','El Egido y humedales estacionales de llanura','Depresión topográfica suave sobre sustratos impermeables que propicia la aparición de encharcamientos temporales durante el invierno y la primavera. El entorno está rodeado por pastizales naturales y pies dispersos de encina adaptados a la oscilación hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40075','espacio','Valle del río San Medel y cerros testigo','Conjunto de pequeñas elevaciones calcáreas erosionadas que rompen la penillanura, aislando pequeños valles interiores de gran tranquilidad visual. Las laderas están colonizadas por tomillares, espliegos y encinares degradados de gran valor aromático y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','espacio','Valle de la Fuenfría (vertiente segoviana), Garganta del Río Moros y cumbres del Pasapán','Excepcional entorno de alta montaña granítica integrado en el Parque Nacional de Guadarrama, con imponentes circos glaciares y canchales. Alberga una de las masas forestales de pino silvestre (Pinus sylvestris) más densas y majestuosas de la península, con arroyos torrenciales de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40077','espacio','Piedemonte de la Sierra de Guadarrama y dehesa de Tizneros','Franja de transición geológica o somontano donde se acumulan los canchales y sedimentos gruesos desprendidos de la sierra. El paisaje está dominado por dehesas de encina bien conservadas que enmarcan la imponente silueta de la cordillera al fondo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40078','espacio','Humedales del arroyo de la Vega y dunas eólicas','Paisaje arenoso integrado en la comarca de Tierra de Pinares, caracterizado por el modelado de mantos eólicos cuaternarios. El relieve presenta suaves ondulaciones cubiertas de pino piñonero que fijan el sustrato móvil, complementado por pequeñas depresiones donde aflora el agua subsuperficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40079','espacio','Cárcavas del río Riaza y cerro del Castillo','Impresionante relieve quebrado donde la erosión hídrica ha excavado profundas cárcavas y barrancos sobre arcillas rojizas y margas. La ausencia de vegetación densa en las laderas permite contemplar la compleja estructura geológica y los intensos contrastes cromáticos del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40080','espacio','Manantial de la Fuente del Prado y llanos calcáreos','Espacio dominado por una plataforma de páramo calizo donde se produce una modesta pero constante surgencia natural de agua. La presencia de este recurso hídrico sostiene una pequeña dehesa de fresnos que contrasta vivamente con la aridez geomorfológica del entorno estepario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40081','espacio','Valle del río Cerquilla y escarpes de roca caliza','Estrecho cañón fluvial excavado en la plataforma de la llanura caliza, donde el río discurre   encajonado entre paredes rocosas de notable verticalidad. El fondo del valle alberga una densa cobertura de chopos, álamos y sauces que forman un corredor verde sumamente frondoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40082','espacio','Llanura aluvial del arroyo de la Vega y campos arcillosos','Relieve horizontal de la campiña segoviana donde los suelos arcillosos forman una cubeta sedimentaria de gran uniformidad geológica. Pequeñas alineaciones estacionales de chopos marcan el curso del agua, proporcionando la única ruptura en la línea horizontal del horizonte.   Fuentecambrón (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40083','espacio','Complejo lagunar estacional y pinares calcícolas','Depresión endorreica sobre plataformas calizas que permite la acumulación temporal de aguas de escorrentía, generando lagunas someras de gran interés limnológico. El entorno vegetal se compone de pinos resineros y encinas bajas que colonizan los suelos pedregosos circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40084','espacio','Mar de Pinares y dunas muertas de arenas blancas','Relieve suavemente ondulado por antiguas dunas eólicas cuaternarias hoy estabilizadas por una masa forestal continua de pino piñonero. El suelo de arenas blancas silíceas ofrece una textura geomorfológica muy singular que condiciona una vegetación baja xerófila especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40086','espacio','Humedales de las lagunas del Rincón y monte de pinos','Espacio arenoso donde confluyen flujos subterráneos que alimentan pequeñas láminas de agua dulce de carácter permanente o estacional. Destaca el cinturón de vegetación palustre compuesto por carrizos y juncos que aísla visualmente estos enclaves del entorno agrícola.   Fuentepierre (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40088','espacio','Lagunas de Fuenterebollo y pinares resináceos','Destacable conjunto de más de una decena de lagunas naturales interdunares de aguas limpias integradas en un espeso bosque de pino resinero. El contraste visual entre las masas densas de coníferas y las orillas arenosas de los humedales constituye un paisaje botánico sobresaliente.   Fuenterrebollo (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40089','espacio','Escarpes del arroyo de la Hoz y parameras','Tramo superior de un valle encajonado donde afloran las calizas del Cretácico en forma de pequeños farallones y laderas pedregosas. La vegetación predominante está compuesta por comunidades de sabina albar adaptadas a las duras condiciones de helada y escasez hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40091','espacio','Cañón del arroyo de San Vicente y oquedades calizas','Angosto desfiladero excavado en rocas carbonatadas del Cretácico, con paredes verticales salpicadas de pequeñas cuevas y viseras de disolución kárstica. El fondo del cañón destaca por un microclima húmedo que permite el desarrollo de una vegetación de ribera frondosa y umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','espacio','Hoces del río Duratón (tramo final) y manantial de la Salceda','Impresionante paraje geológico donde el río Duratón rompe definitivamente los estratos de calizas dolomíticas del Mesozoico a través de un cañón escarpado. Las paredes verticales exhiben estructuras kársticas, abrigos rocosos y una flora rupícola muy especializada que desafía los desplomes de la roca.   Fuentecambrón (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40093','espacio','Vertiente norte de la Sierra de Guadarrama y cañón del río Santa Águeda','Relieve pre-montano y de alta montaña sustentado sobre materiales graníticos y gneisicos de gran dureza, tapizado por densos melojares y pinares. El curso fluvial desciende encajonado entre bloques rocosos, labrando pozas de aguas gélidas y saltos de agua de enorme belleza plástica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40094','espacio','Dehesa de Garcillán y llanos arenosos','Paisaje llano del somontano segoviano donde los suelos arenosos cuaternarios permiten el desarrollo de un encinar aclarado bien conservado. El interés contemplativo reside en la sobriedad del monte mediterráneo integrado de forma armónica en la penillanura castellana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40095','espacio','Lagunas interdunares y Mar de Pinares','Sector occidental de las arenas eólicas provinciales donde emergen pequeñas cubetas endorreicas debido a la proximidad del nivel freático. Los perfiles dunares suavizados están completamente cubiertos por una masa uniforme de pino resinero de alto valor paisajístico.   Graiñera (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40097','espacio','Dehesa de melojos y ribera del río Riaza','Zona de contacto entre la llanura de la meseta y las estribaciones de la sierra, caracterizada por dehesas bien conservadas de roble melojo. El río Riaza cruza el término aportando un pasillo verde de vegetación riparia que rompe con el relieve suavemente ondulado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40099','espacio','Parameras de la Serrezuela y masas de sabina albar','Altiplano calizo situado a gran altitud que constituye un reducto relíctico de sabinas (Juniperus thurifera) adaptadas a climas extremos. El paisaje es de una severidad caliza rotunda, con suelos pedregosos y formaciones de lapiaces muy bien expuestos a la contemplación visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40100','espacio','Pozas kársticas del prado y pinar resinero','Paisaje mixto donde las arenas eólicas se asientan sobre un sustrato calizo, permitiendo que la disolución kárstica hunda el terreno creando dolinas o pozas naturales. Estas depresiones retienen agua y rompen la uniformidad del denso manto boscoso circumundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40101','espacio','Terrazas fluviales del río Eresma y escarpes arcillosos','Amplio valle fluvial donde se observan los diferentes niveles de terrazas cuaternarias compuestas por cantos rodados y arenas. En las márgenes, la erosión ha esculpido taludes arcillosos de fuerte pendiente cubiertos de vegetación arbustiva mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40103','espacio','Vega del río Eresma y escarpes arcillosos','Paisaje de ribera caracterizado por el contraste entre el fondo plano y verde de la vega del Eresma y los   cerros arcillosos erosionados que la delimitan. La dinámica fluvial ha labrado pequeños taludes donde se asientan comunidades vegetales de ribera y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40104','espacio','Encinar de la Dehesa Boyal y colinas graníticas','Relieve alomado que marca el inicio de las formaciones graníticas del Sistema Central, con presencia de lapiaces y bolos pétreos dispersos. El paisaje está cubierto por un encinar maduro excelentemente conservado que tapiza las ondulaciones del terreno calcáreo y silíceo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40105','espacio','Confluencia del río Moros y el río Eresma, lanchares graníticos','Espacio geomorfológico de gran interés debido al afloramiento de rocas plutónicas que obligan a los ríos a serpentear entre masas de piedra. Las riberas presentan un excelente estado de conservación, combinando formaciones rocosas desnudas con sotos frondosos de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40106','espacio','Ribera del río Voltoya y pinar de la Casa','El río Voltoya modera aquí su curso, discurriendo sobre un lecho arenoso flanqueado por dehesas de pino piñonero de alto valor paisajístico. El contraste entre los suelos silíceos pálidos y el verde oscuro de las copas aparasoladas de los pinos confiere gran singularidad al entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40107','espacio','Lagunas estacionales de Labajos y llanura de la Transierra','Cuencas endorreicas someras de carácter temporal que acumulan agua sobre materiales arcillosos impermeables, dando nombre al municipio. El paisaje es austero y marcadamente horizontal, interrumpido visualmente por estos humedales que concentran la escasa flora acuática local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40108','espacio','Valle del río Duratón y humedales calcáreos','Sector septentrional donde el río Duratón se ensancha tras abandonar los cañones principales, generando una llanura de inundación con humedales asociados. Los flancos del valle muestran los potentes escarpes calizos del páramo que encuadran un fondo de valle verde y húmedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40109','espacio','Cañón del río Riaza (tramo de Languilla) y cortados calizos','Tramo de alto interés geológico donde el río Riaza corta las estructuras calcáreas mesozoicas originando un desfiladero de paredes verticales y meandros encajados. La umbría de los cortados favorece la presencia de quejigos y vegetación rupícola, aportando un escenario visual de gran fuerza espacial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40110','espacio','Cañón del río Cega, el Serretón y fuentes naturales','Espectacular incisión del río Cega sobre los materiales arenosos y calizos calificados localmente como "El Serretón", creando un valle profundo y umbrío de gran contraste. Abundantes manantiales fluyen por las laderas del cañón, alimentando una frondosa masa forestal de ribera rodeada de densos pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40111','espacio','Cerro de la Horca y llanuras cerealistas de la campiña','Relieve dominantemente plano interrumpido de forma aislada por cerros testigo de materiales sedimentarios más resistentes a la erosión. Paisaje característico de la meseta que destaca por la nitidez de su geomorfología y las texturas visuales que ofrece el terreno labrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40112','espacio','Cuesta de la Lastrilla y cárcavas del arroyo Clamores','Relieve de cuesta caliza que domina los accesos a la capital provincial, donde los procesos de arroyada han modelado cárcavas y pequeños taludes margosos. Su interés radica en la visión panorámica de la transición entre el páramo y la cuenca sedimentaria.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','espacio','Parque Natural de las Hoces del Río Riaza (sector occidental) y cortados del embalse','Aunque condicionado por la lámina de agua artificial, el término municipal engloba los espectaculares farallones rocosos calcáreos que dan inicio al cañón del Riaza. Las paredes de roca caliza exhiben nichos de erosión, cuevas y una vegetación esclerófila donde destacan las sabinas colgadas de los escarpes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40903','espacio','Valle del arroyo de la Vega y campiña arcillosa','Paisaje ondulado suavemente sobre materiales sedimentarios terciarios del sector centro-occidental de la provincia. La vegetación se reduce a pequeñas alineaciones de chopos en el cauce estacional, ofreciendo una panorámica limpia de la llanura cerealista castellana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40118','espacio','Páramo de Marazuela y dehesas de encina','Relieve de transición entre la campiña baja y los primeros llanos calcáreos que preanuncian la sierra. Alberga reductos dispersos de monte bajo mediterráneo adaptados a suelos pobres, destacando por las amplias perspectivas visuales que se obtienen de la lira serrana al fondo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40119','espacio','Cárcavas del arroyo de las Vegas y lomas calcáreas','Pequeños procesos de abarrancamiento originados por la erosión en las laderas de las lomas sedimentarias que circundan el casco urbano. El sustrato neógeno blanquecino queda expuesto, configurando un microrrelieve de pequeñas crestas y surcos erosivos visualmente llamativos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40120','espacio','Ribera del río Voltoya y llanuras aluviales de la desembocadura','Llanura de inundación situada en el límite provincial, donde el río Voltoya aporta sedimentos finos   originando suelos profundos. El curso fluvial está flanqueado por una alameda densa que rompe cromáticamente con la aridez de las terrazas agrícolas superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40121','espacio','Entorno fluvial del río Voltoya y dehesa del monte','Relieve plano característico de la llanura castellana meridional modificado por la terraza aluvial del curso del río Voltoya. La vegetación se agrupa en un encinar aclarado de llanura y en la línea verde forestal que marca el recorrido sinuoso de las aguas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40122','espacio','Pinar de las dehesas y masas de encinar','Extensa llanura de arenas silíceas donde confluyen masas forestales mixtas de pino piñonero y encina mediterránea de gran madurez botánica. El suelo cubierto de arena fina genera un paisaje de sotobosque limpio dominado por plantas aromáticas como el tomillo y el cantueso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40124','espacio','Ribera del río Cega (tramo bajo) y dunas fósiles','Zona de desembocadura del río Cega hacia la cuenca del Duero, caracterizada por suaves ondulaciones de arenas estabilizadas por el bosque. La vegetación de ribera se funde de forma gradual con el pinar, creando un ecotono de gran interés visual y forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40123','espacio','Sierra de Guadarrama (vertiente norte), sabinar de Matabuena y cueva de la Fuente','Relieve montañoso de gran espectacularidad que combina los canchales de gneis de las cumbres con una franja caliza en el piedemonte donde prospera un sabinar albar de alta densidad. El entorno kárstico subterráneo cuenta con notables formaciones de disolución y surgencias de agua de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40125','espacio','San Roque y dehesas calcáreas del páramo','Plataforma estructural de calizas dolomíticas sometida a procesos de disolución kárstica superficial, originando pequeños campos de lapiaces y dolinas. La vegetación dominante está formada por encinas achaparradas y estepas adaptadas a inviernos prolongados y suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40126','espacio','Afloramientos de pizarra y ribera del río Voltoya','Paisaje de la campiña segoviana donde emergen pequeñas bandas de pizarras precámbricas de tonos oscuros que rompen los suelos arenosos. El río Voltoya aporta una franja húmeda con formaciones lineales de chopos que contrastan fuertemente con la aridez mineral exterior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40127','espacio','Cañón del arroyo de la Hoz y fuentes kársticas','Hermoso desfiladero excavado en el páramo calizo septentrional, caracterizado por escarpes rocosos verticales y la presencia de surgencias de agua en la base del cañón. La exuberancia de la vegetación de ribera en el fondo del desfiladero contrasta vivamente con la desnudez calcárea de la meseta superior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40128','espacio','Cerros graníticos y canteras históricas de pizarra','Interesante zona de contacto geológico donde emergen lomas de granito y formaciones laminares de pizarra que dotan al relieve de texturas ásperas y geomorfologías singulares. El matorral mediterráneo y las encinas bajas se extienden entre los afloramientos rocosos desnudados por la erosión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40129','espacio','Llanuras arenosas de Tierra de Pinares','Relieve plano modificado de forma sutil por acumulaciones dunares cuaternarias suavizadas por la acción   eólica histórica de la submeseta norte. El paisaje está dominado por la regularidad de las masas forestales de pino piñonero asentadas sobre suelos silíceos permeables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40130','espacio','Parque Natural de las Hoces del Río Riaza y Refugio de Rapaces','Uno de los hitos paisajísticos y geológicos más formidables de la submeseta norte, consistente en un profundo y monumental cañón excavado por el río Riaza en las calizas de la Serrezuela. Los paredones verticales alcanzan alturas impresionantes, exhibiendo un modelado kárstico perfecto con agujas, nichos y repisas donde la vegetación rupícola convive con masas de sabina albar.   Monzonillo (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40131','espacio','Ribera del río Moros y dehesas calcáreas','Relieve suave de campiña donde las aguas del río Moros han modelado una vega aluvial flanqueada por lomas cubiertas de encinar mediterráneo. El paisaje destaca por la pureza de sus líneas y la alternancia de pastizales naturales con zonas de monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40132','espacio','Enebral del Santuario de Hornuez y lomas de la Serrezuela','Paraje botánico de primer orden caracterizado por un bosque adehesado de sabinas albares (Juniperus thurifera) con ejemplares milenarios de portes gigantescos y copas monumentales. El relieve es quebrado, compuesto por calizas y dolomías que afloran en la superficie del terreno de forma abrupta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40134','espacio','Vega del río Pirón y pinares de las Arenas','Punto de transición donde el río Pirón se adentra en la comarca arenosa, labrando un valle amplio rodeado de dunas estabilizadas por el pino piñonero. El contraste entre los cultivos de regadío de la vega, el bosque de ribera y el pinar suprayacente posee un alto valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40135','espacio','Encinar de la dehesa de Muñopedro y curso alto del río Voltoya','Paisaje pre-serrano caracterizado por una topografía suavemente alomada sobre rocas plutónicas que forman pequeños berrocales de granito. El término destaca por la notable extensión y densidad de su encinar mediterráneo, que se mantiene en un estado de conservación excelente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40136','espacio','Ribera del río Cega y encinar de la dehesa','Tramo medio del río Cega caracterizado por el encajonamiento del cauce sobre los materiales arenosos y calizos del somontano de la sierra. Las márgenes albergan un dosel denso de vegetación de ribera, flanqueado en las zonas elevadas por encinares mediterráneos típicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40141','espacio','El Mar de Pinares de Navalmanzano y arroyo de Polendos','Espacio liso cubierto por un manto continuo de arenas eólicas cuaternarias que sustentan densas masas forestales de pino resinero destinados a la producción de miera. El paisaje destaca por la pureza de sus masas arboladas y el relieve dunar suave que ondula el suelo del bosque.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40139','espacio','Parque Nacional de la Sierra de Guadarrama, El Chorro de Navafría y pinar de los Neveros','Espectacular entorno de alta montaña silícea que alberga uno de los bosques de pino silvestre (Pinus sylvestris) más excelsos y productivos de Europa, conocido como Pinar de Navafría. El arroyo de El Chorro desciende por la fractura del granito originando una cascada vertical de gran altura y una sucesión de saltos de agua encajonados de soberbio valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40140','espacio','Parque Natural de las Hoces del Río Duratón (límite norte) y pinares calcícolas','El término municipal toca los bordes superiores del cañón del Duratón, ofreciendo perspectivas de la profunda incisión fluvial sobre las parameras de calizas grisáceas. El páramo superior está densamente poblado por pinos resineros que se adaptan a los suelos rocosos de origen kárstico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40145','espacio','Lagunas de Navas de Oro y llanos arenosos de la Tierra de Pinares','Complejo de cubetas endorreicas de origen eólico situadas en claros del inmenso pinar resinero que domina el territorio municipal del entorno. Las láminas de agua presentan variaciones estacionales acusadas, albergando una vegetación hidrófila palustre muy especializada sobre las arenas limpias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40904','espacio','Parque Nacional de Guadarrama, Bosque de Riofrío y El Caloco','Privilegiado entorno de piedemonte que alberga un bosque adehesado de encinas, quejigos y fresnos excelentemente conservado gracias al aislamiento histórico. El relieve asciende suavemente hacia las laderas graníticas de la sierra aportando panorámicas de gran equilibrio natural y pureza ecológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40146','espacio','Dehesa de la Cepeda y praderas del piedemonte granítico','Entorno de montaña media ubicado en la vertiente septentrional del Sistema Central, caracterizado por extensos pastizales naturales salpicados de grandes bloques de granito. La abundancia de agua de escorrentía estacional genera un paisaje verde prístino encajado entre las elevaciones de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40148','espacio','Pinares de Nieva y afloramientos de arenas cuarcíticas','Territorio forestal dominado por el pino piñonero que coloniza extensos depósitos de arenas eólicas de gran espesor. El paisaje es liso y homogéneo, destacando el valor botánico de sus ejemplares arbóreos aislados y la nitidez lumínica que genera el reflejo del sustrato arenoso claro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40149','espacio','Páramo de Olombrada y encinares de la llanura tabular','Paisaje calcáreo de páramo estructural situado en el norte de la provincia, caracterizado por una marcada horizontalidad geológica superficial. Pequeñas depresiones o dolinas rompen el relieve, sirviendo de refugio para bosquetes de encina y quejigo que resisten el clima riguroso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40150','espacio','Valle del río San Juan y escarpes de Orejana','Sinuoso valle fluvial encajonado en las calizas dolomíticas pre-serranas, flanqueado por taludes pedregosos cubiertos de matorral mediterráneo aromático. El fondo del valle cuenta con un curso de agua límpido rodeado de prados húmedos y fresnedas de gran frescura visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40151','espacio','Ribera del río Eresma y escarpes de arcilla y arena','Tramo donde el río Eresma discurre encajonado entre terrazas fluviales profundas, dejando al descubierto paredes verticales de sedimentos sueltos de color ocre. El bosque de galería ofrece una franja verde continua que contrasta con la aridez de las tierras superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40901','espacio','Berrocal de Ortigosa, río Peces y vertiente del Guadarrama','Formidable paisaje geomorfológico dominado por un caos granítico o berrocal con grandes formaciones de piedras caballeras y bloques esculpidos por los elementos. El río Peces desciende de la sierra labrando un valle angosto cubierto de densos encinares y robledales que arropan las formaciones rocosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40152','espacio','Cerro de San Benito, canchales de la dehesa y canteras de calcona','Complejo paisaje pre-serrano donde entran en contacto los materiales graníticos de la sierra con las calizas cretácicas del somontano, generando una gran diversidad litológica. Destacan los escarpes rocosos de San Benito y las dehesas mixtas de encina, enebro y fresno asentadas sobre suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40155','espacio','Valle alto del río Eresma, laderas de la Atalaya y pinar de Gamones','Espectacular entorno de piedemonte y montaña integrado parcialmente en el Parque Nacional de Guadarrama, donde el río Eresma desciende encajonado en rocas graníticas. Las laderas están cubiertas por densas masas de roble melojo y pino silvestre que ofrecen una panorámica de gran valor forestal y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','espacio','Valle del río Vadillo y cortados de la meseta caliza','Impresionante espolón rocoso calizo labrado por la confluencia de los arroyos Vadillo y San Miguel, configurando un relieve escarpado de gran verticalidad. Las laderas calizas basales están colonizadas por encinares, enebros y una frondosa vegetación riparia que tapiza el fondo del estrecho valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40157','espacio','Ribera del río San Medel y dehesa calcárea','Pequeña cuenca fluvial excavada en las plataformas calcáreas del piedemonte segoviano, con relieves suavemente alomados cubiertos de monte bajo. El cauce mantiene un bosque de galería bien conservado que aporta frescura y contraste cromático con los tomillares del entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40158','espacio','Arroyo de la Vega y llanuras cerealistas de la Tierra de Pinares','Pequeño término municipal asentado sobre la penillanura sedimentaria arcillosa en el límite de los campos arenosos. El relieve es sumamente suave y desnudado, ofreciendo amplias perspectivas del horizonte castellano donde destaca la limpieza de las formas geomorfológicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40159','espacio','Arenales de Pinarejos y masas forestales de pino resinero','Paisaje forestal continuo caracterizado por el relieve de dunas continentales asimétricas fijadas por la vegetación arbórea de Pinus pinaster. La uniformidad del bosque se interrumpe de forma sutil por pequeños claros arenosos desprovistos de suelo orgánico, mostrando la naturaleza eólica del sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40160','espacio','Mar de Pinares y lagunas del Pozo de la Carrera','Paisaje de llanura arenosa integrado en el núcleo de la comarca forestal segoviana, con pequeñas cubetas endorreicas de agua estacional. El dosel boscoso homogéneo de Pinus pinaster genera una atmósfera forestal continua interrumpida únicamente por las orillas de los humedales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40162','espacio','El Acebal de Prádena, Cueva de los Enebralejos y cumbres de la Sierra de Somosierra','Alberga uno de los bosques de acebo (Ilex aquifolium) más extensos, densos y meridionales de Europa, constituyendo una joya botánica indiscutible de umbría húmeda. El subsuelo cuenta con la espectacular Cueva de los   Enebralejos, un complejo kárstico de profusa ornamentación de estalactitas y estalagmitas de gran valor geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40163','espacio','Ribera del río Cega y encinar de las lomas','Tramo donde el río Cega discurre encajado entre lomas de materiales sueltos, flanqueado por un bosque de galería muy denso y umbrío. Las laderas circundantes conservan manchas maduras de encinar mediterráneo adaptado a suelos pedregosos y pendientes acusadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40164','espacio','Ribera del río Adaja y dehesa de Rapariegos','Amplia llanura aluvial labrada por el río Adaja en el extremo occidental de la provincia, caracterizada por depósitos de terrazas con cantos rodados. El cauce mantiene un cinturón lineal de vegetación de ribera dominado por chopos y sauces que contrasta con la aridez circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','espacio','Parque Nacional de Guadarrama, Valle de Valsaín, Peñalara (vertiente segoviana), Chorro Grande y Boca del Asno','Paisaje natural de la máxima excelencia alpina, con circos y lagunas glaciares bajo las cumbres de Peñalara y los Siete Picos. El bosque de Valsaín constituye una de las masas de pino silvestre más espectaculares y maduros del continente, surcado por el río Eresma que desciende encajonado entre formaciones graníticas monumentales y saltos de agua gigantescos como el Chorro Grande.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40166','espacio','Confluencia del río Pirón con el Cega y arenales limítrofes','Extremo septentrional de la provincia donde confluyen ambos cursos fluviales sobre una llanura baja de arenas eólicas sueltas. El interés paisajístico radica en la confluencia de los ecosistemas ribereños y la inmensidad horizontal del paisaje de arenas y pinares piñoneros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40168','espacio','Ribera del río Riaza y llanos cuarcíticos','Tramo del río Riaza caracterizado por un relieve de llanura aluvial baja donde abundan los depósitos de cantos rodados de cuarcita. La vegetación riparia forma una banda continua y fresca que destaca cromáticamente sobre los tonos ocres del terreno agrícola de la meseta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40170','espacio','Macizo de Ayllón, Hayedo de la Pedrosa y curso alto del río Riaza','Paisaje de alta montaña silícea de excepcional valor botánico que alberga el Hayedo de la Pedrosa, uno de los bosques de hayas (Fagus sylvatica) más meridionales de Europa. El relieve incluye cumbres de cuarcita y pizarra por encima de los dos mil metros de altitud y valles torrenciales de aguas cristalinas de gran belleza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40171','espacio','Cárcavas de Ribota y piedemonte de la Sierra de Ayllón','Paisaje geomorfológico quebrado caracterizado por intensos procesos de abarrancamiento y cárcavas sobre arcillas rojas y margas sedimentarias de la sierra. El modelado erosivo ha creado crestas afiladas y agujeros de gran vistosidad cromática debido a la oxidación del hierro del sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40087','espacio','Valle de San Juan y escarpes del páramo','Morfología clásica de mesa o páramo tabular donde el relieve desciende hacia el valle de forma abrupta a través de taludes margosos. La escasez de vegetación arbórea permite observar con nitidez la estratificación geológica y los efectos de la erosión diferencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40113','espacio','Parque Nacional de la Sierra de Guadarrama, berrocal de la Losa y río Frío','Entorno de alta montaña alpina caracterizado por un colosal berrocal granítico con formas de erosión en bolas, lanchares y bloques de gran plasticidad. El río Frío desciende impetuoso entre un denso dosel de robles melojos y pinos silvestres, configurando un paisaje de altísima calidad estética y pureza natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40138','espacio','Pino de las Tres Garras y humedales de las lagunas de las Eras','Territorio integrado en la llanura arenosa segoviana que alberga singulares ejemplares de pino piñonero de porte monumental y formas escultóricas. Cuenta con depresiones topográficas donde aflora el agua subterránea, rompiendo la aridez del sustrato arenoso con láminas acuáticas efímeras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40172','espacio','Puerto de la Quesera y nacimiento del río Riaza','Impresionante escenario geomorfológico de origen glaciar con laderas escarpadas que superan los 1.500 metros de altitud sobre sustratos puramente silíceos. La vegetación de alta montaña está dominada por brezales, piornales y brezales-brezales de repoblación natural, junto a saltos de agua encajonados de gran belleza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40173','espacio','Terrazas fluviales del río Eresma','Relieve plano de la campiña segoviana constituido por depósitos aluviales cuaternarios arenosos y de cantos rodados. El interés contemplativo radica en la franja lineal de vegetación de ribera (chopos y sauces) que rasga la uniformidad geomorfológica del paisaje agrícola circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40174','espacio','Cuesta de San Bernardo y cañón del arroyo de la Hoz','Paisaje clásico de páramo calizo fuertemente erosionado, donde la disolución kárstica ha labrado un pequeño cañón con paredes verticales y abrigos rocosos. Las laderas y la meseta superior albergan comunidades de sabina albar y encina adaptadas a la extrema sequedad del sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40176','espacio','Valle encajonado del río Carracillo y dunas del pinar','Interesante tramo fluvial donde un modesto curso de agua ha logrado excavar un vallejo en mitad de la inmensa llanura de arenas eólicas continentales. El relieve muestra perfiles arenosos inestables coronados por masas forestales compactas de pino piñonero de alto valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40177','espacio','Escarpes del arroyo de Cuéllar y llanos arenosos','Zona de contacto donde los llanos de arenas eólicas caen bruscamente hacia la cuenca del arroyo, dejando al descubierto taludes arcillosos de gran potencia. La vegetación arbórea se restringe a pinos resineros aislados y formaciones ripícolas modestas en el fondo del valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40178','espacio','Llanura aluvial del río Trabancos','Geomorfología monótona y horizontal representativa de la llanura cerealista castellana sobre sedimentos arcillosos del Mioceno. Su valor radica en la nitidez cromática estacional y la amplitud del horizonte, apenas interrumpido por la vegetación arbustiva asociada al cauce estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40906','espacio','Piedemonte serrano y cuenca del río Eresma','Franja de somontano caracterizada por una topografía suavemente alomada compuesta por la desorganización de sedimentos gruesos de la sierra. Ofrece una panorámica visual limpia de la vertiente norte del macizo de Guadarrama, enmarcada por encinares aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40182','espacio','Lagunas de Mudrián y dunas continentales','Relieve eólico suave caracterizado por depresiones endorreicas interdunares que acumulan agua de forma estacional sobre arenas cuaternarias. El entorno forestal de Pinus pinaster envuelve estos humedales someros, creando un micropaisaje botánico de gran singularidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40184','espacio','Dehesa somera y llanos calcáreos','Meseta caliza horizontal donde el suelo es escaso y afloran costras calcáreas lavadas por la escorrentía superficial. El paisaje está dominado por una dehesa de encina achaparrada y sabina albar de lento crecimiento, adaptada a las severas condiciones climáticas de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40189','espacio','Llanos de arenas eólicas y ribera del río Voltoya','Acumulaciones de dunas fósiles estabilizadas en el extremo occidental de la provincia, flanqueadas por el curso del río Voltoya. El río aporta una ruptura húmeda en el paisaje arenoso, con formaciones de sauces y álamos que rompen la homogeneidad del pinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40190','espacio','Cañón del río Pirón y piedemonte granítico','Zona de fractura geológica donde el río Pirón abandona el granito de la sierra y corta las bandas de calizas cretácicas, abriendo un cañón angosto. El relieve presenta lapiaces, cavidades naturales y una densa cobertura de encinar carpetano colgado de las paredes calizas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40191','espacio','Puerto de Somosierra (vertiente segoviana) y peña del Chorro','Escenario de montaña tectónica sobre materiales graníticos y gneisicos que se eleva abruptamente sobre el somontano de la meseta. Destaca por las formaciones de canchales fósiles, los saltos de agua estacionales debidos al deshielo y un frondoso bosque mixto de robles y acebedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40192','espacio','Cuenca del arroyo de San Miguel y cerros margosos','Relieve suavemente quebrado constituido por materiales arcillosos y margas blanquecinas sometidas a procesos de erosión laminar. La vegetación arbórea es escasa, reduciéndose a encinares aclarados en las zonas altas que controlan la escorrentía del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','espacio','Valles de los ríos Eresma y Clamores, y peña del Grajero','Cinturón geomorfológico verde que rodea el casco urbano, caracterizado por la incisión de ambos ríos sobre el sustrato calizo cretácico, formando un relieve en proa. Destacan los farallones calcáreos de la peña del Grajero y el denso dosel arbóreo aluvial que tapiza el fondo de los valles encajados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','espacio','Hoces del río Duratón y cañón del río Caslilla','Punto de inicio de las monumentales hoces, donde la confluencia de los ríos Duratón y Caslilla ha esculpido un relieve escarpado de farallones calizos y meandros de gran profundidad. La espectacularidad geológica de las paredes verticales se combina con un ecosistema forestal de ribera sumamente encajonado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40199','espacio','Piedemonte de la Sierra de Guadarrama y dehesa de Sotosalbos','Paisaje de transición montañosa con una topografía alomada sobre materiales silíceos degradados. Destaca por su extensa y frondosa dehesa de roble melojo (Quercus pyrenaica), que tapiza el somontano ofreciendo una cobertura vegetal densa bajo las cumbres carpetanas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40200','espacio','Llanura cerealista del arroyo Polendos','Uniformidad geomorfológica sobre depósitos sedimentarios arcillosos del centro de la provincia, con un relieve apenas ondulado. Su interés es puramente   contemplativo por la pureza de las líneas del horizonte y los contrastes de luz sobre el suelo labrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40201','espacio','Cerro de Tolocirio y llanura occidental','Destaca por la presencia de un cerro testigo o resalte aislado de materiales paleozoicos que rompe la horizontalidad de la llanura abulense-segoviana. Ofrece una magnífica perspectiva geomorfológica para contemplar la inmensidad de la penillanura sedimentaria desde una atalaya natural rocosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40206','espacio','Valle del río Cega y laderas de la Sierra de Guadarrama','Valle de montaña encajonado donde el río Cega desciende con fuerza entre formaciones de gneis y granito. Las laderas orientadas a la umbría albergan un denso y espectacular bosque de roble melojo y acebedos, coronado en las zonas altas por matorrales alpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40202','espacio','Fuentes del arroyo de Valdehornos y cárcavas calizas','Paisaje de páramo erosionado donde nacen pequeños cursos fluviales de carácter torrencial que han labrado cárcavas profundas en el frente calcáreo. El relieve quebrado está salpicado por pies dispersos de sabina albar y densos tomillares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40203','espacio','Canchales de la dehesa y piedemonte del Puerto de Malafría','Paisaje de somontano granítico cubierto por extensas formaciones de matorral de piorno y escasales de encina, fruto de la degradación del suelo serrano. Destaca la disposición de grandes bloques y acumulaciones de cantos rodados graníticos desprendidos de las cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40165','espacio','Dehesa de Rebollo y cañón del río San Juan','Paisaje pre-serrano caracterizado por una densa cubierta de quejigos y robles melojos que ocupan un relieve quebrado y pedregoso. El río San Juan se encaja en el término abriendo pequeños desfiladeros calcáreos de gran valor estético e interés geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40154','espacio','Cañón del río de la Hoz y lomas calcáreas','Pequeño desfiladero excavado por un arroyo estacional sobre los materiales calizos pre-serranos, que genera paredes rocosas modestas pero abruptas. La vegetación rupícola y los matorrales de tomillo y espliego colonizan las pendientes, ofreciendo un entorno áspero y recóndito.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40179','espacio','Arenales de Sanchonuño y Mar de Pinares','Paisaje completamente horizontal dominado por mantos de arenas eólicas cuaternarias fijadas por el pino resinero (Pinus pinaster). La densidad y la homogeneidad de la masa forestal generan una perspectiva visual infinita de gran valor estético por su pureza forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40183','espacio','Hoces del río Duratón (tramo medio) y embalse de las Vencías','Espectacular cañón calizo donde el río Duratón realiza profundos meandros encajados entre paredes verticales de roca caliza dolomítica. La disolución kárstica genera chimeneas y abrigos rocosos de gran vistosidad geológica, colonizados por vegetación rupícola especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40180','espacio','Campo Azálvaro (extensión norte) y dehesa boyal','Penillanura silícea de topografía suave y horizontal donde afloran pequeños bolos graníticos aislados por la erosión diferencial. El paisaje se caracteriza por pastizales naturales y encinas dispersas que configuran una estampa típica de la campiña segoviana occidental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40185','espacio','Pizarrales de Ochando y dehesas de encina','Zonas llanas rotas por afloramientos lineales de pizarras paleozoicas que generan pequeñas elevaciones crestadas en el relieve. La vegetación dominante es un encinar denso mediterráneo de gran valor ecológico que coloniza los suelos esqueléticos arcillo-pizarrosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40186','espacio','Escarpes del río Caslilla y paramera caliza','Plataforma calcárea tabular cortada lateralmente por la incisión del río Caslilla, originando taludes pedregosos y frentes de roca grisácea. En las grietas del roquedo y las laderas se asientan rodales mixtos de sabina albar, encina y matorral aromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40193','espacio','Parque Natural de las Hoces del Río Duratón y meandro de San Frutos','Uno de los hitos paisajísticos y geológicos más espectaculares de la submeseta norte, donde el río Duratón excava un cañón sinuoso con paredes verticales de más de 100 metros de altura. Los cortados calizos de tonalidades ocres albergan comunidades vegetales rupícolas únicas y masas de sabina albar colgadas del vacío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40198','espacio','Paramera de la Serrezuela y cárcavas del Duratón','Relieve de páramo tabular calizo a gran altitud que sufre procesos de abarrancamiento en sus bordes debido a la erosión hídrica estacional. Las laderas están colonizadas por sabinas albares rústicas y matorrales xerófilos calcícolas de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40204','espacio','Valle del arroyo de la Hoz y pinares de resina','Entorno integrado en la comarca arenosa pero que presenta pequeñas incisiones fluviales que alcanzan el sustrato calizo subyacente. Los pinares de Pinus pinaster dominan el relieve ondulado, asomándose a pequeños escarpes rocosos calizos de interés geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40205','espacio','Cañón de los ríos Viejo y Pirón','Espectacular tramo fluvial donde ambos ríos discurren encajonados en profundas gargantas excavadas sobre calizas del Cretácico. Las paredes rocosas presentan cuevas, oquedades kársticas y una vegetación de ribera muy umbría que contrasta con la aridez de la meseta superior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40207','espacio','Vertiente norte del Parque Nacional de Guadarrama y arroyo de San Camilo','Paisaje de alta montaña que asciende de forma abrupta hacia la cuerda de las cumbres carpetanas, con fuerte presencia de canchales graníticos y gneisicos. Las zonas bajas presentan dehesas de encina que dan paso a matorrales subalpinos y piornales bien conservados en la línea de cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40211','espacio','Garganta del río Moros y escarpes graníticos','El río Moros labra a su paso por este término un pasillo angosto flanqueado por formaciones graníticas fracturadas de gran vistosidad geológica. La cobertura vegetal está dominada por encinares carpetanos que se adaptan a las superficies rocosas y los canchales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40212','espacio','Parque Natural de las Hoces del Río Riaza','Paisaje de cortados y farallones calizos monumentales modelados por la erosión del río Riaza en las parameras del norte provincial. El entorno destaca por sus   bosques relictos de sabina albar de gran antigüedad y la espectacularidad visual de las paredes de roca caliza colonizadas por flora rupícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40213','espacio','Valle del río San Juan y cerros calcáreos','Relieve alomado compuesto por plataformas calizas degradadas que encajonan el curso modesto del río San Juan. Las laderas presentan una alternancia de pastizales secos, tomillares y pies aislados de encina que ofrecen un paisaje de media montaña calcárea muy equilibrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40218','espacio','Valle del río Duratón y antiguas minas de yeso natural','Singularidad geomorfológica caracterizada por un valle excavado donde afloran potentes estratos de yesos y margas del Terciario, con tonalidades blancas y rojizas. La erosión ha creado perfiles quebrados y taludes inestables de gran interés visual por su rareza litológica en la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40219','espacio','Vega del río Cega y dehesa de San Miguel','Amplia llanura aluvial modelada por el río Cega en su tramo bajo, caracterizada por potentes depósitos de arenas y limos fluviales. El cauce mantiene un bosque de galería muy frondoso con álamos blancos y sauces que contrasta con los llanos arenosos colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40220','espacio','Monte de la Dehesa y arroyos del somontano','Terreno de transición suavemente ondulado cubierto por dehesas mixtas de encina y quejigo sobre sustratos detríticos pre-serranos. El paisaje ofrece una gran tranquilidad visual con pequeñas vaguadas donde la humedad permite el desarrollo de pastizales frescos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40221','espacio','Paramera caliza y lomas del arroyo de la Hoz','Relieve tabular calizo sometido a procesos de desmantelamiento erosivo, originando una topografía de cerros aplanados y laderas pedregosas. La vegetación está dominada por tomillares y sabinas dispersas adaptadas a las severas condiciones de insolación y viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40214','espacio','Cuenca del arroyo San Medel y campiña arcillosa','Paisaje típicamente plano de la campiña central segoviana, desarrollado sobre arcillas y areniscas terciarias. Su valor estético reside en las amplias cuencas visuales hacia la Sierra de Guadarrama y el modelado suave de sus laderas agrícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40215','espacio','Páramos del norte y escarpes del arroyo de la Vega','Paisaje de transición hacia la ribera del Duero caracterizado por plataformas calcáreas tabulares elevadas a más de 900 metros. El borde del páramo se rompe en escarpes rocosos donde se desarrollan encinares termófilos y matorrales aromáticos sobre suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40216','espacio','Terrazas del río Eresma y dehesa de Mazuelos','Espacio geomorfológico plano constituido por los niveles de terrazas fluviales de cantos rodados del Eresma. Presenta dehesas de encina bien conservadas que suavizan el relieve y actúan como miradores naturales hacia el encajonamiento del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40222','espacio','Ribera del río Cega y pinares aluviales','Punto donde el río Cega corta las terrazas arenosas de la meseta, generando una llanura de inundación con suelos húmedos. Destacan los pinares de pino piñonero asentados sobre arenas finas que llegan hasta el mismo borde del cauce fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40223','espacio','Cañón del río Moros y caleras geológicas','Zona de alto interés geológico donde el río Moros excava un desfiladero sobre calizas cretácicas y relieves de falla. El paisaje muestra imponentes farallones rocosos, lapiaces y una vegetación densa de encinar mediterráneo calcícola asentado en las grietas de la roca.   Ventas de Alcolea (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40228','espacio','Tierra de Pinares profunda y arroyo de la Dehesa','Paisaje puramente forestal caracterizado por un mar de dunas eólicas continentales cubiertas por completo de pino resinero (Pinus pinaster). La uniformidad geomorfológica de la arena y el dosel verde continuo generan una atmósfera de gran aislamiento y pureza natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40229','espacio','Parque Natural de las Hoces del Río Riaza (tramo superior)','Paisaje espectacular dominado por el profundo cañón calizo del río Riaza, con cortados verticales de roca caliza rojiza de más de 80 metros de altura. Aloja una de las reservas de sabina albar más densas y puras del Sistema Ibérico-Central, con un altísimo valor botánico y geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40230','espacio','Ribera del río Eresma (tramo final) y lagunas arenosas','Extremo noroccidental de la provincia donde el río Eresma divaga sobre arenas cuaternarias formando meandros llanos y playas de sedimentos finos. El entorno presenta pequeños humedales estacionales interdunares de gran interés botánico por su flora hidrófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40231','espacio','Confluencia del río Eresma y el río Milanillos','Espacio geomorfológico plano de carácter aluvial donde se unen ambos cursos de agua, generando una amplia llanura de inundación. El paisaje visual está definido por las alineaciones densas de chopos y álamos que marcan la red hidrológica sobre la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40233','espacio','Bosque de la Dehesa y piedemonte silíceo de la Sierra de Guadarrama','Espacio de transición pre-montano caracterizado por un relieve suavemente quebrado sobre granitos y gneises. Alberga un encinar mediterráneo maduro y denso, mezclado con ejemplares de enebro de la miera, que tapiza los suelos pedregosos del somontano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40234','espacio','Tierra de Pinares oriental y lomas de arena fósil','Paisaje dominado por mantos de arenas eólicas estabilizadas que dibujan pequeñas lomas y vaguadas cubiertas por una masa forestal homogénea de pino resinero. El interés radica en la pureza del relieve dunar continental y la inmensidad horizontal del bosque.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90630','espacio','Monumento Natural de Roque Blanco y laderas septentrionales de Garajonay','Impresionante pitón de traquita-fonolita desmantelado por la erosión diferencial que destaca sobre el relieve abrupto del norte de La Gomera. Alberga uno de los reductos más puros y maduros de laurisilva con madroños canarios, beneficiado por el constante aporte de humedad de los vientos alisios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90775','espacio','Paisaje Protegido de Orone, Monumento Natural de la Caldera e Imada','Complejo relieve volcánico caracterizado por una fosa tectónica y escarpes de erosión profundos que exponen antiguos depósitos de piroclastos. El paisaje destaca por la aridez de sus laderas colonizadas por comunidades   xerófilas ricas en endemismos y la imponente estructura geomorfológica de la Caldera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90631','espacio','Reserva de la Biosfera de El Canal y Los Tiles (vertiente norte) y piscinas naturales de La Fajana (entorno de acantilados fosilizados)','Impresionante relieve norteño caracterizado por profundos barrancos cubiertos por un denso e impenetrable bosque de laurisilva canaria. Los escarpes marinos muestran potentes secciones de coladas basálticas antiguas erosionadas por el fuerte oleaje del Atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90632','espacio','Cumbre Nueva y Monumento Natural de los Dragos de San José','Ladera oriental montañosa de la isla de La Palma caracterizada por la constante presencia del mar de nubes generado por los vientos alisios. El entorno alberga majestuosos ejemplares centenarios de Dracaena draco y un denso sotobosque de monteverde húmedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90777','espacio','Monumento Natural de la Montaña de la Breña y costa fósil de El Socorro','Prominente cono freatomagmático que constituye un hito visual y geológico cubierto por vegetación termófila en proceso de recuperación. Los perfiles litorales exhiben espectaculares coladas lávicas rugosas del tipo malpaís que contrastan con los acantilados marinos bajos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38051','espacio','Espacio Protegido de la Costa de Acentejo (sector central) y pinares de cumbre','Relieve abrupto de vertiente norte caracterizado por perfiles acantilados marinos fósiles colonizados por aves coloniales y plantas rupícolas especializadas. Las zonas altas conectan de forma lineal con la masa forestal de la Corona Forestal, bajo la influencia directa del alisio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38042','espacio','Parque Rural de Teno (vertiente septentrional) y Monte del Agua','El Monte del Agua constituye uno de los macizos forestales de laurisilva y fayal-brezal más estables y mejor conservados del sector occidental de Tenerife. El relieve presenta profundos barrancos encajonados que se abren hacia una plataforma costera baja de origen volcánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38901','espacio','Reserva Marina del Mar de las Calmas y Pinar de El Julan','Inmensa rampa volcánica estructural inclinada hacia el mar de las Calmas, cubierta por un denso e histórico pinar de pino canario. Las zonas bajas presentan campos de lavas cordadas y escorias basálticas negras impecables que caen directamente hacia el litoral acantilado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90747','espacio','Vega del río Blanco y lomas de la campiña','Paisaje típicamente horizontal de la campiña sevillana sobre depósitos sedimentarios del Mioceno. Su interés visual radica en el modesto cauce del río Blanco, que introduce una línea de vegetación riparia con álamos y tarajes que rompe la llanura agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40001','espacio','Parque Natural Sierra Norte de Sevilla, ribera del Benalija y dehesas del Parroso','Relieve alomado de Sierra Morena constituido por materiales metamórficos paleozoicos. Destaca por sus extensas dehesas maduras de encinas y alcornoques de alto valor botánico, interrumpidas por el encajonamiento del arroyo Benalija y sus singulares afloramientos calizos calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40002','espacio','Ribera del Guadaíra, pinares de Oromana y acuífero de Los Alcores','Escarpe geomorfológico calcáreo perteneciente a la formación de Los Alcores que domina la vega del río Guadaíra. El curso fluvial está flanqueado por densos bosques de galería y una masa forestal seminatural de pino piñonero asentada sobre arenas sedimentarias finas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90451','espacio','Vega del Guadalquivir y terrazas aluviales cuaternarias','Geomorfología fluvial plana caracterizada por los potentes depósitos de limos, arcillas y gravas del río Guadalquivir en su tramo medio inferior. El interés contemplativo reside en la amplitud del cauce fluvial y la densa vegetación arbustiva lineal que escolta sus márgenes de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90452','espacio','Confluencia del río Corbones con el Guadalquivir y escarpes de arcilla','Punto de articulación fluvial donde el río Corbones se une a la arteria principal del Guadalquivir, generando una llanura aluvial muy dinámica. El paisaje visual destaca por los pequeños taludes erosivos arcillosos y los rodales estacionales de tarajes y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90748','espacio','Llanura aluvial del Guadalquivir y madre vieja del río','Relieve extremadamente horizontal representativo de las llanuras de inundación de la depresión bética. El valor visual estriba en el antiguo meandro o madre vieja del río, que conforma un humedal lineal modesto colonizado por vegetación palustre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90453','espacio','Parque Natural Sierra Norte de Sevilla, berrocal de San Bartolomé y ribera del Cala','Excepcional patrimonio geológico caracterizado por un espectacular berrocal granítico con bloques redondeados por erosión diferencial (bolos y piedras caballeras). Las laderas montañosas están cubiertas por bosques densos de encina, quejigo y matorral noble mediterráneo junto al encajonamiento del río Cala.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90454','espacio','Entorno del arroyo de Riopudio y llanos del Aljarafe','Relieve suavemente alomado correspondiente a la plataforma sedimentaria del Aljarafe sevillano. La sutil cuenca del arroyo Riopudio introduce la única ruptura topográfica con pastizales estacionales y ejemplares aislados de acebuches rústicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90455','espacio','Cuenca del río Guadaira (tramo oriental) y dehesa de la Torrecilla','Paisaje ondulado de transición entre la campiña baja y las estribaciones de la sierra sur, asentado sobre arcillas y yesos. Alberga pequeños reductos de dehesas boyales que conservan encinas centenarias aisladas de gran valor estético en un entorno desarbolado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41012','espacio','Espacio Natural de Doñana (Pinar de la Puebla y Aznalcázar) y marismas del Guadiamar','Impresionante mosaico ecológico y paisajístico donde el pinar centenario de Pinus pinaster y Pinus ya contacta de forma limpia con las llanuras aluviales de la marisma. Ofrece una transición botánica espectacular de alcornocales, sabinas de duna y humedales estacionales de alto interés internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41013','espacio','Corredor Verde del Guadiamar y estribaciones de Sierra Morena occidental','Zona de sutura geológica entre la llanura bética y los materiales antiguos de la sierra, caracterizada por relieves alomados cubiertos de pizarras y jarales. El curso alto del río Guadiamar funciona como un pasillo ecológico frondoso con un bosque de galería en regeneración natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41014','espacio','Reserva Natural del Malpasillo y cañón del río Genil','Espectacular desfiladero donde el río Genil corta las formaciones calcáreas de las Subbéticas, creando escarpes rocosos imponentes. Las riberas albergan un frondoso bosque de galería con sauces y álamos blancos, complementado por láminas de agua protegidas de alto interés limnológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41015','espacio','Cárcavas del Guadiamar y cornisa del Aljarafe','Quiebro topográfico abrupto donde la plataforma del Aljarafe cae hacia la vega del río Guadiamar mediante cárcavas arcillosas de tonos rojizos. La vegetación destaca por bosquetes dispersos de acebuches y matorral mediterráneo adaptado a la escorrentía estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41017','espacio','Cuenca del arroyo de Riopudio y dehesas relictas','Paisaje suavemente ondulado sobre arenas y arcillas terciarias del Aljarafe central. El interés visual se limita   a la modesta restauración botánica del lecho del arroyo, rodeado de pastizales y pies aislados de olmo y chopo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41018','espacio','Meandro del Guadalquivir y llanura de inundación','Relieve estrictamente horizontal caracterizado por las terrazas aluviales más bajas del río Guadalquivir. Ofrece un paisaje contemplativo centrado en la dinámica fluvial del cauce, estabilizado por formaciones lineales de cañaverales, tarajes y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41019','espacio','La Madroña y estribaciones de Sierra Morena','Zona de contacto geológico donde la vega del Guadalquivir choca con las primeras elevaciones graníticas de la sierra. El paisaje se define por un relieve alomado cubierto por un denso encinar, dehesas mixtas y grandes bolos pétreos dispersos de gran plasticidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41020','espacio','Complejo Endorreico de Espera (Lagunas de Taraje y Charca del Sapo) y lomas calizas','Conjunto de cubetas e hidromorfías de carácter endorreico dispuestas sobre materiales arcillosos y yesíferos de la campiña baja. Las láminas de agua estacionales están orladas por un denso cinturón de vegetación palustre (carrizos, castañuelas y tarajes) de gran contraste cromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41021','espacio','Cerro del Carambolo y vega del Guadalquivir','Promontorio geológico que funciona como una atalaya natural sobre la gran llanura aluvial del río Guadalquivir. El relieve muestra las terrazas fluviales superiores y pequeños escarpes arcillosos colonizados por tuneras, acebuches y matorral rústico mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41022','espacio','Valle del arroyo de Santa Marina y dehesa de la Campana','Paisaje ondulado que caracteriza la transición entre la campiña cordobesa y sevillana sobre depósitos sedimentarios del Mioceno. La monotonía agrícola se rompe visualmente por pequeños encinares adehesados e incisiones fluviales estacionales de aguas arcillosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41023','espacio','Desembocadura del río Viar y escarpes del Guadalquivir','Punto de articulación fluvial de gran belleza geomorfológica donde el río Viar deposita sus sedimentos gruesos en el Guadalquivir. El entorno presenta cortes verticales de arcillas compactas y una vega aluvial con densas alamedas y saucedas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','espacio','Escarpado de la Cornisa de Los Alcores y Vega del Corbones','Monumental y abrupto frente geológico constituido por calcarenitas y alizas del Terciario que domina con un fuerte desnivel la inmensa depresión del Guadalquivir. En las laderas del escarpe se desarrollan comunidades vegetales de acebuche, lentisco y palmito de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41025','espacio','Cuenca del arroyo de la Cárcava y llanos sedimentarios','Paisaje horizontal de la comarca del Campo de Tejada, asentado sobre arcillas pliocénicas impermeables. La escorrentía superficial genera un relieve suavemente modelado por vaguadas donde resisten pequeños pastizales y pies aislados de encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41026','espacio','Ribera del río Yeguas y cerro de la Atalaya','El río Yeguas labra un valle encajonado sobre materiales subbéticos margoyesíferos de vivos colores rojizos y blanquecinos. El cauce mantiene un bosque de galería   aceptable con tarajes y adelfas, escoltado por relieves alomados cubiertos de monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41027','espacio','Parque Natural Sierra Norte de Sevilla, ribera del Cala y Dehesa de San Benito','Paisaje típicamente de media montaña llanera sobre el batolito granítico de Sierra Morena. Ofrece inmensas extensiones de dehesas maduras de encina y alcornoque, con abundantes cursos fluviales encajonados repletos de adelfas, tamujos y vegetación riparia densa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41029','espacio','Cornisa oriental del Aljarafe','Fractura tectónica y escarpe erosivo suave que separa la plataforma aljarafeña de la vega del Guadalquivir. Visualmente destaca por la panorámica geológica que ofrece del valle aluvial, con vertientes colonizadas por matorral mediterráneo degradado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41028','espacio','Balcón del Aljarafe y laderas del arroyo de la Heliche','Sector septentrional del escarpe calcarenítico de Los Alcores-Aljarafe, con desniveles pronunciados hacia la llanura de inundación bética. Las laderas están cubiertas por matorral noble de acebuche, palmito y retama, proporcionando una ruptura visual de gran fuerza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41030','espacio','Arroyo de Guadiamar (límite oeste) y campos del Campo de Tejada','Relieve plano con suaves ondulaciones desarrollado sobre margas azules del Guadalquivir. La cobertura vegetal arbórea original se reduce a las formaciones ripícolas de los arroyos estacionales, dominadas por cañaverales y tarajales rústicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','espacio','Ribera del Huéznar, Cascadas del Huéznar y Monumento Natural de las Formaciones de Travertino','Impresionante entorno fluvial en el corazón de Sierra Morena, donde el río Huéznar desciende formando espectaculares saltos de agua y pozas cristalinas sobre costras de travertinos calcáreos. Las riberas albergan un bosque de galería monumental con galería de sauces, alisos y fresnos de valor botánico excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41033','espacio','Parque Natural Sierra Norte, Cerro del Hierro (extensión este) y robledales de la umbría','Relieve quebrado calcáreo y pizarroso que alberga las masas más maduras de quejigos y robles melojos de la provincia debido a su microclima húmedo. Presenta valles umbríos profundos, formaciones kársticas menores y un dosel arbóreo continuo de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41034','espacio','Brazo de la Torre (Doñana norte) y escarpe del Guadalquivir','Punto geográfico donde el río Guadalquivir ensancha su cauce y comienza su transición hacia las marismas atlánticas. El relieve destaca por el imponente escarpe arcilloso de la margen derecha y el inicio de las llanuras aluviales de marea colonizadas por almajos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41035','espacio','Monumento Natural Chaparro de la Vega y cañón del río Guadalporcún','Entorno subbético abrupto donde destaca el Chaparro de la Vega, una encina (Quercus ilex) monumental de más de 700 años y copa colosal. El río Guadalporcún excava un espectacular desfiladero calizo con paredes verticales cubiertas de vegetación rupícola mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41036','espacio','Dehesa de las Aguzaderas y cuenca del arroyo de las Mujeres','Paisaje alomado de la campiña alta que presenta afloramientos aislados de calizas y yesos. Conserva rodales de dehesa mediterránea bien estructurada con encinas maduras que salpican un relieve suave erosionado por las aguas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41037','espacio','Nacimiento del río de la Puebla y Sierra de la Estepa','Relieve quebrado perteneciente a las estribaciones de los sistemas subbéticos, con presencia de calizas y dolomías. El paisaje destaca por los pequeños manantiales kársticos que dan origen a arroyos permanentes, flanqueados por matorrales de adelfas y tomillares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41038','espacio','Brazo del Este (Marismas del Guadalquivir) y dehesa de la Corchuela','Inmensa llanura aluvial correspondiente a un antiguo cauce modificado del Guadalquivir, hoy convertido en un humedal de primer orden internacional. La dehesa de la Corchuela aporta una masa madura de acebuches, alcornoques y encinas que frena el avance de la marisma arcillosa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','espacio','Ribera del río Genil y terrazas miocénicas de la campiña','Amplio valle aluvial excavado por el río Genil en las potentes arcillas de la campiña sevillana. El cauce fluvial muestra meandros abandonados, islas sedimentarias y una densa vegetación de galería que contrasta vigorosamente con las áridas y extensas lomas del entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41040','espacio','Dehesas del Aljarafe norte y cuenca del arroyo de Majalbarra','Topografía de llanura elevada con pendientes muy suaves sobre sedimentos arenosos marinos del Plioceno. Los atractivos naturales se restringen a bosquetes aislados de   encina y acebuche integrados en antiguas dehesas de uso comunal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41041','espacio','Sierra de Estepa (Cerro de San Cristóbal y Sierra de la Roda)','Prominente anticlinal calcáreo calizo que emerge de forma abrupta como un hito visual sobre la horizontalidad de la campiña sevillana. Presenta escarpes rocosos limpios, fenómenos de disolución kárstica (lapiaces y pequeñas cuevas) y vegetación xerófila mediterránea rústica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41042','espacio','Valle del río Corbones y lomas de arcilla azul','Relieve ondulado y suave caracterizado por la presencia de margas y arcillas de la depresión bética. El río Corbones aporta un corredor verde lineal con tarajes y carrizales que rompe la uniformidad cromática y estructural de la penillanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41043','espacio','Sierra del Pedroso y cuenca del río Guadiamar (curso alto)','Paisaje pre-montano de Sierra Morena con laderas cubiertas por pizarras, cuarcitas y extensos jarales de Cistus ladanifer. El relieve quebrado alberga dehesas densas de encina y un encajonamiento fluvial limpio con presencia de adelfares y tamujales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41044','espacio','Cornisa del Aljarafe de Gelves y ribera del Guadalquivir','Notable escarpe tectónico donde la plataforma pliocénica cae bruscamente sobre el lecho del Guadalquivir, generando un frente con nacientes de agua subterránea. La vegetación de ladera está compuesta por un frondoso acebuchal mezclado con algarrobos y matorral noble.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41045','espacio','Berrocal de Gerena y canteras geológicas de granito','Hito geológico singular consistente en un afloramiento masivo de granito plutónico (plutón de Gerena) en la base de Sierra Morena. El relieve muestra espectaculares formas de erosión con bolos graníticos redondeados y dehesas asentadas sobre suelos arenosos silíceos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41046','espacio','Sierra de Gilena, Ojo de Gilena y cañada del Aceituno','Relieve montañoso integrado en los sistemas subbéticos calizos, caracterizado por una notable surgencia kárstica natural conocida como el Ojo. El entorno forestal destaca por pinares de repoblación naturalizada y matorral mediterráneo rico en especies aromáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41047','espacio','Vaguada del arroyo de la Regajera','Término municipal reducido y muy antropizado sobre la plataforma sedimentaria del Aljarafe. Cuenta con pequeñas vaguadas arcillosas donde afloran modestas comunidades de pastizales y vegetación nitrófila estacional sin relieve prominente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41048','espacio','Parque Natural Sierra Norte, cumbre de La Capitana y ribera del Sotillo','Contiene el punto más alto de la provincia (La Capitana, 960 m), ofreciendo una impresionante perspectiva geomorfológica de pliegues hercínicos. Las vertientes albergan un denso pinar, encinares maduros y un bosque de galería muy bien conservado con adelfas y sauces en la ribera del Sotillo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41049','espacio','Rivera de Huelva, embalse de El Gergal y dehesas de la Rivera','El río Rivera de Huelva labra un profundo encajonamiento sobre pizarras y pizarras paleozoicas antes de abrirse a la llanura. El paisaje visual destaca por la imponente masa de agua encajonada entre laderas abruptas cubiertas de encinas, alcornoques y densos jarales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41050','espacio','Cuenca del río Genil (borde norte) y lomas yesíferas','Paisaje ondulado de la campiña este caracterizado por el afloramiento de yesos y margas de la cuenca bética. La escorrentía genera sutiles badlands de colores blanquecinos colonizados por vegetación gipsícola muy especializada y matorral xerófilo de degradación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41051','espacio','Valle del río Guadiamar (tramo medio) y dehesa del Aljarafe occidental','Terreno de transición donde la plataforma arcillosa desciende hacia la cuenca del Guadiamar. El interés paisajístico radica en la presencia de dehesas mixtas de encina y acebuche que controlan la erosión de los suelos arenosos cuaternarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41902','espacio','Parque Natural de Doñana (Marismas de Isla Mayor y Brazo de la Torre)','Relieve plano absoluto que conforma el corazón de las marismas del Guadalquivir, un ecosistema de colmatación estuarina único. El valor contemplativo reside en la inmensidad horizontal del paisaje palustre y limnológico, inundado estacionalmente y colonizado por densas masas de castañuelas y almajos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41053','espacio','Complejo Endorreico de Lebrija (Lagunas de Cigarrera, Gato y Taraje) y marismas de la marisma','Notable sistema de lagunas asentadas sobre arcillas y depósitos salinos que retienen el agua de lluvia. El paisaje transita de forma limpia hacia las marismas bajas del   Guadalquivir, ofreciendo horizontes infinitos orlados por vegetación adaptada a la salinidad (salicornias y tarajes).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41054','espacio','Sierra de la Roda (borde norte) y cuenca del arroyo de la Salinosilla','Estribación montañosa caliza del sistema subbético que rompe la horizontalidad de la llanura mediante vertientes pedregosas. La vegetación está dominada por tomillares, romerales y pies aislados de encina rústica adaptada a suelos esqueléticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41055','espacio','Ribera del Guadalquivir, dehesa de Matallana y estribaciones de Sierra Morena','Término de gran diversidad paisajística que abarca desde la llanura de inundación del Guadalquivir hasta las primeras lomas de pizarras de la sierra. Destaca la dehesa de Matallana, un alcornocal y encinar maduro sobre arenas detríticas de alto valor contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41056','espacio','El Desierto y complejos endorreicos estacionales de la campiña','Extensa llanura horizontal desarrollada sobre las margas de la cuenca bética. Presenta pequeñas depresiones endorreicas someras que acumulan agua en invierno, creando un paisaje de humedales efímeros rodeados de pastizales naturales xerófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41057','espacio','Cuenca alta del río Guadiamar, jarales del Berrocal y masas de alcornoque','Paisaje montañoso abrupto integrado en el sector más occidental de Sierra Morena sevillana, con suelos silíceos de pizarras y areniscas. Destaca por albergar inmensas masas continuas de jarales aromáticos y alcornocales maduros que tapizan un relieve quebrado y virgen.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41058','espacio','Cornisa de Los Alcores de Mairena y cuenca del arroyo alcornoque','Tramo central del escarpe calcarenítico de Los Alcores, caracterizado por sus llamativos perfiles sedimentarios de color arenoso y sus acuíferos colgados. Las laderas mantienen formaciones estables de matorral mediterráneo con palmitos, acebuches y lentiscos rústicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41059','espacio','Arroyo de Porzuna y entorno adehesado relicto','Topografía alomada suave representativa de la plataforma del Aljarafe sometida a presión urbana. Los reductos naturales contemplativos se reducen al entorno del arroyo Porzuna, que conserva una modesta cubierta forestal mixta de encinas y acebuches.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41061','espacio','Cuenca del río Blanco y lomas de la campiña este','Paisaje eminentemente horizontal desarrollado sobre arcillas y margas de la campiña sevillana. El río Blanco aporta una leve ruptura del relieve con una banda verde modesta de vegetación riparia palustre que destaca en el paisaje desarbolado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41060','espacio','Valle del río Corbones, lomas de la dehesa y lagunas yesíferas','Relieve ondulado modelado por la cuenca del río Corbones sobre materiales arcillo-yesíferos del Mioceno. Cuenta con pequeñas lagunas estacionales de alta salinidad e incisiones fluviales flanqueadas por tarajes y carrizales densos de interés geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41062','espacio','Reserva Natural de la Laguna del Gosque','Impresionante laguna endorreica de carácter hipersalino asentada sobre los llanos del piedemonte   subbético. Ofrece una lámina de agua de gran vistosidad cromática debido a las costras de sal estacionales, rodeada por un cinturón botánico de tarajes, carrizos y salicornias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41063','espacio','Arroyo de la duna y lomas de la campiña de Utrera','Paisaje de transición suavemente ondulado compuesto por depósitos arcillosos y arenas del Terciario. La vegetación natural es escasa y queda relegada a pastizales estacionales y pies dispersos de encina rústica en las líneas de lindes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41064','espacio','Sierra de Montellano, tajo de la Cancha y ribera del Guadaíra (curso alto)','Destacado macizo calizo calizo de las Subbéticas que emerge con fuerza, presentando paredes verticales y escarpes rocosos de gran valor estético (tajo de la Cancha). El relieve está cubierto por un denso monte bajo mediterráneo y un pinar de repoblación naturalizada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41065','espacio','Sierra de Morón, cañón del río Guadaíra y escarpes de la calera','Relieve quebrado dominado por potentes formaciones de calizas jurásicas escarpadas que marcan el inicio de los sistemas béticos. El río Guadaíra discurre encajonado entre frentes rocosos grises cubiertos de vegetación rupícola, acebuchales y matorral noble.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41066','espacio','Parque Natural Sierra Norte, ribera del Ciudadeja y dehesas del Alcornocal','Entorno montañoso abrupto de Sierra Morena caracterizado por valles profundos y encajonados excavados por la red fluvial sobre pizarras paleozoicas. Alberga alcornocales continuos y maduros, con un bosque de galería en la ribera del Ciudadeja rico en alisos, fresnos y adelfas salvajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41067','espacio','Ribera del río Guadiamar (Corredor Verde) y cornisa del Aljarafe norte','El término limita con el canal de inundación del río Guadiamar, aportando un paisaje de llanura aluvial escoltado por el escarpe suave de la plataforma del Aljarafe. La vegetación combina bosque de galería en regeneración con matorrales de ribera y acebuchales rústicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','espacio','Sierra de Osuna, canteras geológicas de calcarenita y arroyo de las Mujeres','Paisaje contrastado que combina las llanuras arcillosas de la campiña con los relieves de calcarenitas erosionadas del subbético. Las antiguas canteras exhuman frentes de roca porosa dorada de gran impacto visual, rodeadas por encinares dispersos y monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41069','espacio','Humedal de la Laguna de El Pantano y Marismas del Guadalquivir (borde este)','Zona de contacto entre las terrazas cuaternarias arenosas del Guadalquivir y las arcillas de la marisma baja. Presenta depresiones topográficas estables que retienen agua, conformando humedales rodeados de eneas, carrizos y vegetación halófila de gran interés limnológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41070','espacio','Cornisa baja del Aljarafe y vega del Guadalquivir','Escarpe suave sobre arenas y arcillas que define el límite de la terraza superior del Aljarafe frente a la gran llanura fluvial. La vegetación natural cuenta con pequeños acebuchales y pastizales estacionales que se asoman al cauce del Guadalquivir.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41071','espacio','Cuenca del arroyo de la Jarda y lomas de la campiña','Paisaje suavemente alomado constituido por margas azules miocénicas de la depresión del Guadalquivir. La red de drenaje estacional genera vaguadas arcillosas donde se asientan matorrales xerófilos de degradación y pies muy aislados de encina rústica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41072','espacio','Sierra de la Cruz, canteras de caliza y cuenca del río Yeguas','Estribación montañosa subbética caracterizada por afloramientos macizos de calizas blancas y grises explotadas históricamente. El paisaje natural destaca por los perfiles escarpados de la sierra, colonizados por romerales, tomillares y encinares degradados de gran valor aromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41073','espacio','Parque Natural Sierra Norte, Berrocal de las Cardonchas y ribera del Huéznar (tramo bajo)','Espectacular paisaje geomorfológico dominado por un extenso berrocal granítico con caprichosas formaciones de bolos, piedras caballeras y lapiaces graníticos. El entorno está cubierto por dehesas continuas de alcornoque y encina, con una ribera fluvial densa y bien conservada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41074','espacio','Ribera del Guadalquivir, desembocadura del río Retortillo y escarpes de Sierra Morena','Punto de contacto geológico estricto donde el río Retortillo sirve de frontera sobre pizarras paleozoicas antes de fundirse con el Guadalquivir. El paisaje ofrece un contraste rotundo entre los escarpes montañosos jarosos de la sierra y la horizontalidad aluvial de la vega bética.   Pila (La) (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41075','espacio','Arroyo de Alcarayón y dehesas de arenas de Doñana','Paisaje horizontal dominado por mantos de arenas finas cuaternarias que conectan con el entorno de Doñana. El arroyo de Alcarayón excava un suave valle aluvial cubierto por acebuchales, matorral de arenas (jaguarzos y lentiscos) y pinares dispersos de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41076','espacio','Sierra del Tablón, cumbre del Terril y nacimiento del río Corbones','Alberga el techo geográfico de la provincia de Sevilla (El Terril, 1.129 m), integrado en un macizo calizo de las Subbéticas de relieves abruptos y crestas afiladas. Las vertientes muestran laderas pedregosas descarnadas de gran fuerza visual, colonizadas por encinares rústicos y matorral noble mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41077','espacio','Embalse de la Puebla y desfiladero del río Corbones','El río Corbones corta los materiales subbéticos calcáreos y arcillosos antes de salir a la campiña, abriendo un pasillo angosto encajonado entre laderas pronunciadas. El paisaje visual destaca por la gran masa de agua encajada flanqueada por densos jarales y encinares de monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41078','espacio','Parque Natural Sierra Norte de Sevilla, embalse de José Torán y dehesas del encinar','Paisaje de media montaña sobre pizarras, gneises y calizas paleozoicas que configuran relieves alomados cubiertos de densas dehesas. El embalse de José Torán se integra estéticamente en el relieve serrano, rodeado por densos jarales de flor blanca y manchas de alcornocal maduro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41079','espacio','Espacio Natural de Doñana (Marismas del Guadalquivir, Cañada de los Pájaros y Dehesa de Abajo)','Excepcional encrucijada ecológica y paisajística donde las dunas y dehesas de acebuches centenarios   contactan con la inmensidad horizontal de la marisma alta. Aloja lagunas estables de gran valor botánico y limnológico, cubiertas de castañuelas, eneas y densos almajales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41080','espacio','Parque Natural Sierra Norte, ribera del Cala (tramo alto) y dehesas de la Sierra','Relieve serrano maduro desarrollado sobre pizarras y grauvacas que dibujan valles y lomas continuas cubiertas por un dosel adehesado impecable de encina y alcornoque. La ribera del Cala aporta un entorno contemplativo limpio con presencia de saucedas, fresnedas y adelfares densos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41081','espacio','Madre Vieja del Guadalquivir y terrazas aluviales','Geomorfología fluvial de llanura absoluta sobre limos y arcillas cuaternarias de la cuenca bética. El atractivo se concentra en los antiguos brazos o meandros estrangulados del Guadalquivir, que forman humedales lineales someros poblados por cañas y tarajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41082','espacio','Ribera del río Yeguas y lomas calcáreas del subbético','Paisaje de transición ondulado condicionado por la cuenca del río Yeguas, que erosiona materiales arcilloyesíferos y calizos. El curso de agua genera una banda verde lineal de tarajales y adelfares que destaca estéticamente en medio de las lomas desarboladas de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41083','espacio','Rivera de Huelva, embalse de La Minilla y barrancos de la dehesa','Relieve abrupto y quebrado de Sierra Morena occidental, donde el río Huelva discurre profundamente encajonado entre laderas pizarrosas de pendientes pronunciadas. El paisaje visual destaca por la combinación de   grandes láminas de agua encajonadas y vertientes cubiertas de densos jarales y encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41084','espacio','Valle del río Blanco y lomas de la campiña central','Topografía monótona y horizontal desarrollada sobre sedimentos arcilloso-margosos del Mioceno. El río Blanco constituye el único elemento de ruptura del relieve, aportando un corredor biológico modesto con vegetación de ribera palustre y pastizales temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41085','espacio','Cornisa del Aljarafe norte y cuenca del arroyo de la Agrio','Sector septentrional de la plataforma sedimentaria del Aljarafe, con pendientes que descienden suavemente hacia el Corredor Verde del Guadiamar. Conserva pequeños escarpes arcillo-arenosos colonizados por matorral mediterráneo rústico y pies aislados de acebuche.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41086','espacio','Monumento Natural de la Cornisa del Aljarafe de San Juan y río Guadalquivir','Destacado frente tectónico y erosivo calcarenítico que domina visualmente de forma directa el cauce principal del río Guadalquivir. Las laderas del escarpe albergan formaciones degradadas pero visibles de acebuchal y palmitar rústico, funcionando como un mirador geológico natural.   **San Nicolás del Puerto - Puntuación: 92.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41088','espacio','Monumento Natural Cerro del Hierro y Cascadas del Huesna','Impresionante paleokarst donde la disolución de las calizas del Cámbrico, combinada con una antigua explotación minera, ha esculpido un paisaje laberíntico de agujas, simas y túneles calcáreos. Muy cerca, las aguas del río Huéznar descienden entre formaciones de travertinos musgosos, originando saltos de agua y pozas de gran valor estético dentro de un denso bosque de galería. [1, 2, 3].','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41089','espacio','Terrazas bajas de la vega del Guadalquivir','Geomorfología fluvial de carácter plano y horizontal constituida por sedimentos finos y limos cuaternarios acumulados por la dinámica del río. Su interés se limita a la horizontalidad del paisaje de llanura y a la observación de la transición hacia las primeras lomas arcillosas del Aljarafe norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41090','espacio','Valles del río Corbones y del arroyo de la Mezquitilla','Relieve quebrado y abrupto perteneciente a la subbética sevillana, caracterizado por lomas formadas por margas, arcillas y yesos de vivos colores. Las laderas expuestas a la solana están pobladas por densos acebuchares y matorral mediterráneo que retienen los suelos de la erosión hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41092','espacio','Llanura aluvial del Guadalquivir y madre vieja de Los Rosales','Paisaje completamente horizontal dominado por las terrazas sedimentarias del Guadalquivir en su tramo medio. Pequeños humedales lineales estacionales o antiguos brazos del río cortan la llanura, albergando comunidades de eneas, carrizos y tarajes dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41093','espacio','Cornisa del Aljarafe y cabecera del arroyo de la Fuente','Tramo oriental de la plataforma sedimentaria pliocena que desciende de forma empinada hacia la vega fluvial sevillana. El escarpe muestra estratos de arenas finas de color amarillento, colonizados de forma relíctica por matorrales mediterráneos y bosquetes aclarados de olivos silvestres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41094','espacio','Llanos calcáreos del Aljarafe central','Meseta horizontal con una suave pendiente hacia el sur, caracterizada por suelos ricos en carbonatos y depósitos detríticos finos. La homogeneidad del relieve de la plataforma se rompe únicamente por sutiles vaguadas estacionales que recogen la escorrentía superficial de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','espacio','Complejo Endorreico de Utrera (Lagunas de Alcaparrosa, Arjona y Zarracatín)','Excepcional conjunto de lagunas estacionales de origen tectónico y endorreico asentadas sobre yesos y arcillas de la campiña baja. Destaca especialmente Zarracatín por sus aguas hipersalinas, donde la vegetación halófila periférica y las costras blancas de sal en verano configuran un paisaje de gran valor geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41096','espacio','Cornisa norte del Aljarafe y cuenca visual de la Vega','Sector elevado de la plataforma del Aljarafe que ofrece una panorámica limpia de la llanura de inundación del Guadalquivir y del inicio de Sierra Morena. Las pendientes del escarpe muestran cárcavas arcillosas naturales cubiertas de pastizales y matorral xerófilo rústico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41097','espacio','Entorno de Doñana, Dehesa de Boyal y marismas del Guadiamar','Espacio de altísimo valor paisajístico donde las arenas eólicas cuaternarias de Doñana dan paso de forma natural a la marisma arcillosa del Guadalquivir. Cuenta con espectaculares masas forestales de pino piñonero mezcladas con alcornocales centenarios y fresnedas asociadas a los cauces de agua estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41100','espacio','Cañón del río Corbones y laderas de la Sierra de la Mocha','Relieve premontano y quebrado de la Sierra Sur sevillana donde el río Corbones ha excavado una profunda garganta sobre calizas jurásicas. El desfiladero presenta paredes rocosas verticales de gran interés geológico, cubiertas por un denso encinar y matorral noble mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41098','espacio','Penillanura sedimentaria del Aljarafe alto','Paisaje completamente llano sobre materiales arenoso-arcillosos pliocenos, representativo del interior de la comarca del Aljarafe. El interés del relieve radica en la uniformidad geomorfológica de la meseta, carente de grandes accidentes topográficos o redes fluviales encajonadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41099','espacio','Ribera del Huesna, lago del Arenal y afloramientos carboníferos','Zona de contacto geológico donde el río Huéznar corta los materiales paleozoicos antes de morir en el Guadalquivir, formando un valle umbrío de gran belleza. El   entorno cuenta con relieves quebrados con presencia de antiguas formaciones continentales del Carbonífero y un denso dosel de bosque mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41101','espacio','Siete Pozas del arroyo de San Pedro y ribera del Guadalquivir','Singular tramo torrencial donde el arroyo de San Pedro desciende encajonado por las primeras estribaciones de Sierra Morena, labrando sobre la roca una sucesión de marmitas de gigante y saltos de agua naturales. El paisaje contrasta fuertemente con la llanura aluvial del Guadalquivir situada pocos kilómetros aguas abajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41102','espacio','Escarpe de Los Alcores y vega del Guadaíra','Tramo central de la elevación calcarenítica de Los Alcores, un hito geomorfológico que se levanta de forma lineal sobre la llanura de la campiña. El talud expone rocas sedimentarias ricas en fósiles marinos del Mioceno, colonizadas por acebuches y matorrales aromáticos adaptados al sustrato calizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90806','espacio','Embalse de la Cuerda del Pozo (margen sur) y pinares de la dehesa','Zona de transición geológica donde las arenas continentales sustentan extensas masas de Pinus sylvestris y Pinus pinaster. La proximidad de la lámina de agua estabiliza un paisaje forestal de llanura ondulada de gran valor puramente contemplativo por su densidad y horizontes verdes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','espacio','Moncayo soriano, barranco del río Val y cañón de Valdeascones','Impresionante relieve tectónico de la vertiente norte del macizo del Moncayo, constituido por conglomerados y calizas mesozoicas. El río Val ha excavado un cañón profundo con paredes verticales de fuerte cromatismo rojizo, albergando una vegetación umbría de quejigos y avellanos de alto valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90273','espacio','Ribera del río Rituerto y lomas del Duero','Paisaje típicamente alomado sobre sedimentos terciarios arcillosos del centro de la provincia. La modesta vega del río Rituerto introduce una nota de verdor lineal mediante sauces y juncos que rompe la horizontalidad cromática de la llanura cerealista.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90274','espacio','Ribera del río Pilde y lomas del somontano calizo','Relieve ondulado de la planicie del sudoeste soriano donde afloran frentes calizos desgastados. El río Pilde mantiene un corredor ripícola flanqueado por ejemplares maduros de encina y quejigo que se adaptan bien a la acusada oscilación térmica del páramo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90807','espacio','Barranco del río Bordecorex y cortados calcáreos','Paisaje de páramo calizo tabular donde la incisión fluvial ha labrado pequeños desfiladeros e hitos de roca exhumada. Las repisas de las paredes rocosas albergan comunidades vegetales rupícolas especializadas y matorrales aromáticos de gran severidad y fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90275','espacio','Vaguadas del arroyo de Henar y llanura de la dehesa','Geomorfología monótona y horizontal sobre arcillas miocenas representativa de la meseta soriana meridional. Su interés contemplativo radica en la pureza de las líneas del horizonte y los sutiles encharcamientos temporales en los prados bajos durante el deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90276','espacio','Alto de la Cruz y cabeceras de arroyos estacionales','Pequeña elevación divisoria de aguas en la comarca de Almarza, caracterizada por un relieve esquelético pedregoso. Alberga pastizales de montaña y arbustos espinosos adaptados a vientos intensos, ofreciendo una visual descarnada de la alta planicie.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90277','espacio','Paramera de Aldealpozo y cuenca del río Moñigón','Plataforma calcárea elevada expuesta a una intensa crioclastia y erosión eólica que limitan el crecimiento forestal. El paisaje destaca por su sobriedad geológica, con una vegetación esteparia rústica que acentúa la sensación de inmensidad horizontal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90278','espacio','Lomas de la Sierra de San Miguel y dehesa comunal','Relieve de media montaña con laderas suaves labradas sobre materiales silíceos degradados. Conserva un encinar mixto con quejigos de crecimiento lento que tapiza el   relieve, proporcionando un marco forestal muy equilibrado frente a los páramos des nudos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90279','espacio','Altos de la dehesa y arroyo de la Vega','Topografía de lomas suaves de naturaleza detrítica arcillo-arenosa situadas al pie de las grandes sierras del norte. La vegetación arbórea está representada por pies aislados de encina y matorrales xerófilos de gran simplicidad estructural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90281','espacio','Altos del Morro y llanadas arcillosas','Paisaje de transición hacia el valle del Jalón, definido por plataformas arcillo-margosas erosionadas en sus bordes. La escasez de vegetación arbórea resalta las formas de los taludes y la uniformidad geomorfológica del terreno sedimentario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90282','espacio','Llanos del río Rituerto y paramera baja','Exponente clásico de la penillanura cerealista soriana central sobre depósitos terciarios completamente horizontales. Su valor radica en la nitidez cromática estacional de la tierra desnuda y la amplitud del arco celeste observable desde su llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42017','espacio','Ribera del río Merdancho y llanos aluviales','Entorno llano constituido por terrazas aluviales del río Merdancho en su aproximación al Duero. El río introduce un pasillo verde de chopos y sauces que contrasta vivamente con la aridez de las lomas marginales deforestadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42018','espacio','Barranco del río Regacho y cárcavas de yeso','Interesante relieve quebrado donde la erosión hídrica ha excavado profundas cárcavas y taludes blanquecinos sobre potentes estratos de margas y yesos. El contraste cromático de los minerales expuestos y la vegetación gipsícola rústica crean un paisaje de gran fuerza geológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42019','espacio','Acebal de Garagüeta, dehesa de Santosonario y ribera del Tera','Alberga una de las mayores masas forestales continuas de acebo (Ilex aquifolium) de la península ibérica, que forma un dosel umbrío y laberíntico de alto valor botánico. El río Tera complementa el relieve con un valle pre-serrano frondoso rodeado de extensos prados e hidrófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42020','espacio','Ribera del río Duero, sotos de la Arboleda y dehesa de Tejeriza','Amplio pasillo fluvial modelado por el río Duero donde se desarrollan potentes terrazas de cantos rodados y limos. Mantiene un denso bosque de galería maduro con álamos blancos, fresnos y sauces que serpentea rompiendo la uniformidad de la planicie.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42021','espacio','Nacimiento del río Henar y relieves de la Sierra de Deza','Zona de transición geomorfológica donde los relieves calcáreos de la sierra se hunden bajo los materiales arcillosos del llano. Pequeños manantiales kársticos   estacionales sostienen praderas húmedas de gran nitidez ambiental en un entorno fundamentalmente seco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42022','espacio','Campo de Almenar y lagunas estacionales de la dehesa','Llanura sedimentaria con pequeñas cubetas endorreicas someras que acumulan agua superficial en periodos de lluvia intensa. La topografía horizontal ofrece amplias panorámicas interrumpidas únicamente por rodales dispersos de encinas centenarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42023','espacio','Páramos de Alpanseque y nacimiento del río Torete','Paisaje severo de páramo tabular calizo situado a gran altitud, sometido a intensos procesos de crioclastia invernal. El relieve se rompe en suaves vaguadas calcáreas donde brotan fuentes modestas rodeadas de tomillares y sabinas albares rústicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42024','espacio','Sierra de la Frentes (estribación este) y ribera del río Chaorna','Entorno caracterizado por escarpes calizos bien definidos que delimitan las plataformas elevadas del centro de la provincia. La vegetación combina encinares xerófilos en las zonas rocosas con una franja riparia de sauces que escolta el curso modesto del río Chaorna.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42025','espacio','Hoces del río Jalón (sector Somaen), desfiladero de la Hoz y parameras de Layna','Impresionante garganta fluvial excavada por el río Jalón sobre materiales calizos y dolomíticos del Triásico, mostrando espectaculares pliegues y frentes rocosos rojizos. En las parameras elevadas se conserva una vegetación esteparia relicta adaptada a condiciones climáticas extremas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42026','espacio','Valle del río Talegones y dehesas calcáreas','Suave pasillo aluvial tallado sobre las plataformas de calizas mesozoicas del sur de Soria. El fondo del valle mantiene praderas naturales frescas y alineaciones de chopos que contrastan con los encinares aclarados de las laderas pedregosas colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42027','espacio','Acebal de Garagüeta (extensión norte) y dehesa de Gallinero','Paisaje pre-serrano de alta montaña silícea que comparte el núcleo principal del espectacular acebal de Garagüeta. El relieve presenta laderas suaves tapizadas de brezales, piornales y dehesas de robles melojos que muestran una excelente conservación medioambiental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42028','espacio','Sierra de Alba y cabeceras del río Merdancho','Relieve montañoso de la cordillera Ibérica con cumbres aplanadas y laderas erosionadas compuestas por areniscas y matorrales. El paisaje destaca por su severidad y amplitud visual, ofreciendo extensas panorámicas sobre el somontano soriano septentrional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42029','espacio','Altos de Baraona y parameras calizas de la dehesa','Exponente cumbre de la paramera calcárea esteparia ibérica a gran altitud, sometida a procesos de disolución Kárstica somera y crioclastia extrema. El relieve exhibe campos de piedras descarnados y lapiaces cubiertos   por tomillares y cambroneras de altísima singularidad botánica y severidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42030','espacio','Vega del río Duero y dehesa de robles','Llanura aluvial modelada por los depósitos cuaternarios del río Duero en su curso medio soriano. La uniformidad del terreno sedimentario queda interrumpida por un bosque de galería bien conservado y pequeños reductos de robledales que aportan variedad cromática al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42032','espacio','Pinares del río Bayubas y dunas fósiles de arena','Paisaje completamente dominado por mantos de arenas continentales que forman suaves lomas eólicas estabilizadas por el pino resinero. El modesto río Bayubas aporta humedad al sustrato arcillo-arenoso, generando un dosel forestal continuo y homogéneo de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42033','espacio','El Pinar y arroyo de la Vega','Extensión septentrional de las llanuras de arena sorianas fijadas por densas masas forestales de Pinus pinaster. La topografía es suavemente ondulada, ofreciendo una perspectiva lineal de bosque mediterráneo continental interrumpida únicamente por las vegas de arroyos temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42034','espacio','Cruz de Canto, nacimiento del río Isuela y hayedo de Beratón','El municipio más alto de la provincia, enclavado en las faldas del Moncayo sobre materiales silíceos muy estables. Cuenta con escarpes rocosos imponentes y un hayedo relicto en umbría que convive con masas maduras de roble melojo, ofreciendo un paisaje alpino de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','espacio','Hoz del río Escalote, garganta del río Talegones y altos calizos','Impresionantes cañones excavados por ambos ríos sobre las plataformas calcáreas mesozoicas, mostrando farallones verticales de roca grisácea y meandros encajados. Las repisas de los cortados albergan una rica vegetación rupícola, flanqueada por densos encinares calcícolas en las parameras superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42037','espacio','Valle del río Nágima y cárcavas arcillosas','Relieve quebrado labrado sobre materiales sedimentarios blandos del Terciario (margas y arcillas rojizas) debido a la intensa erosión hídrica superficial. El paisaje destaca por sus contrastes cromáticos y la escasez forestal que acentúa las formas esculpidas del sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42038','espacio','Arroyo de los Caños y campos de la campiña','Topografía horizontal representativa de la llanura arcillosa soriana central con una suave inclinación hacia la cuenca del Duero. La vegetación se restringe a pequeñas alineaciones de arbustos espinosos y pastizales que colonizan las cunetas y divisorias de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42039','espacio','Macizo de la Tablada, cañón del río Manubles y mina de oligisto','Relieve de alta montaña perteneciente al Sistema Ibérico, caracterizado por crestas de cuarcitas palezoicas de gran dureza y resistencia a la erosión. El río Manubles baja encajonado entre desfiladeros rocosos, flanqueados por una densa vegetación montana de quejigos y melojos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42041','espacio','Vega del río Rituerto y praderas del páramo','Relieve plano de materiales finos cuaternarios acumulados por la actividad aluvial del río Rituerto. Su valor contemplativo se reduce a la horizontalidad del paisaje y a las sutiles variaciones de la vegetación palustre que delimita el cauce estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42042','espacio','Vega del río Merdancho y llanos detríticos','Entorno llano constituido por terrazas aluviales suaves en las proximidades de las sierras del norte provincial. La red fluvial mantiene pequeños sotos estacionales que contrastan con los tonos pajizos de los pastizales secos y cultivos del entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','espacio','Cañón del río Ucero, hoz de la peña de la Guía y confluencia con el Abión','Espectacular entrada del río Ucero al abandonar las estribaciones calcáreas de la sierra, abriendo un desfiladero con paredes de roca vertical y formaciones de lapiaces. La confluencia con las aguas cristalinas del río Abión genera una amplia y frondosa llanura aluvial de alto valor paisajístico.   Caballero (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','espacio','Espacio Natural del Sabinar de Calatañazor y cañón del río Milanos','Alberga uno de los bosques de sabina albar (Juniperus thurifera) más densos, maduros y mejor conservados del planeta, con ejemplares monumentales que superan los 300 años sobre suelos calcáreos. El río Milanos corta la plataforma caliza formando un desfiladero rocoso imponente que flanquea el entorno forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42048','espacio','Desfiladero del río Bordecorex, peña de San Baudelio y altos de la dehesa','Paisaje de transición donde las plataformas calcáreas son seccionadas por la red drenante del Bordecorex, dando lugar a un estrecho desfiladero de paredes rocosas ocres. Las laderas albergan un encinar mediterráneo bien conservado que convive con sabinas y matorrales aromáticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42049','espacio','Cerros de la dehesa y arroyo de las Vegas','Topografía de lomas suaves y llanuras sedimentarias compuestas por materiales arcillo-arenosos en el centro-este provincial. La cobertura arbórea está limitada a encinas dispersas que salpican los pastizales naturales y zonas de escorrentía estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42051','espacio','Valle del río Carabantes y escarpes de arcilla y yeso','Incisión fluvial en los materiales blandos del sector oriental, modelando un paisaje quebrado de cárcavas y laderas de vivos colores debido a los estratos de yeso   expuestos. El fondo del pequeño valle alberga una franja verde de chopos que resalta sobre la aridez del relieve.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42052','espacio','Cañón del río Caracena (Hoz de las Gargantas) y cortados calizos del páramo','Monumental desfiladero de origen kárstico tallado de forma salvaje por el río Caracena sobre las calizas mesozoicas, con paredes verticales calcáreas que superan los 60 metros de desnivel. El cañón presenta cuevas, abrigos rocosos y una densa vegetación de sabina albar, encina y flora rupícola muy especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42053','espacio','Ribera del río Caracena y dehesa calcárea de los llanos','Valle aluvial protegido donde el río Caracena suaviza su curso tras abandonar los cañones, permitiendo el desarrollo de huertas y fresnedas. Las laderas exteriores muestran el perfil horizontal del páramo superior cubierto por encinares aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42054','espacio','Sierra de Alba y cabeceras del arroyo de la Vega','Relieve de media montaña integrado en el Sistema Ibérico soriano sobre materiales fundamentalmente silíceos. Las laderas están cubiertas por tapices continuos de brezales y piornales que dan paso en las zonas bajas a praderas de diente de alta calidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42055','espacio','Parque Natural del Cañón del Río Lobos (sector central) y pinares de la umbría','El municipio aporta una sección espectacular al Cañón del Río Lobos, con farallones calizos de coloración rojiza y ocre modelados por karstificación. Las plataformas superiores y laderas están cubiertas por densas e impresionantes masas de Pinus sylvestris y sabina albar que hunden sus raíces en la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42056','espacio','Sierra de Alba, altos de la dehesa y cuenca alta del río Cidacos','Entorno caracterizado por relieves esqueléticos sobre areniscas y pizarras a gran altitud, representativo de las Tierras Altas sorianas. Los valles altos presentan praderas naturales frescas rodeadas de matorrales xerófilos espinosos adaptados a vientos intensos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42058','espacio','Valle del río Riaza (tramo soriano) y dehesas calcáreas','El río Riaza corta en este sector los materiales calcáreos de la llanura occidental, abriendo un valle escoltado por taludes pedregosos y frentes rocosos calizos. Las laderas cuentan con una notable cobertura de encinar mixto con quejigos adaptados a los suelos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42057','espacio','Estribaciones de la Sierra del Moncayo y barranco del río Añamaza','Relieve de transición pre-serrano caracterizado por una topografía quebrada de arenas y conglomerados rojos. El curso del río Añamaza genera una pequeña fractura en el terreno con taludes erosivos cubiertos de matorral mediterráneo y quejigares degradados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42059','espacio','Ribera del río Duero y llanos arcillosos','Espacio dominado por la vega aluvial del río Duero, que introduce una franja arbolada de gran densidad biológica en medio de la penillanura sedimentaria. El cauce mantiene depósitos de terrazas de cantos rodados visibles en las márgenes del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42060','espacio','Cañón del río Alhama y Tierras Altas','Paisaje quebrado y severo del norte soriano, donde el río Alhama ha labrado un desfiladero angosto sobre materiales paleozoicos. La fuerte pendiente de las laderas expone los estratos de roca y está colonizada por comunidades de matorral mediterráneo de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42061','espacio','Sierra de Cabrejas, pico Frentes y pinares de la dehesa','Impresionante relieve calizo que culmina en la imponente proa rocosa del Pico Frentes, hito visual inconfundible del centro soriano. Las laderas y llanos superiores están densamente cubiertos por masas forestales maduras de Pinus sylvestris y encinares de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42062','espacio','Cañón del río Alhama (límite provincial) y escarpes de roca rojiza','El punto más bajo de la provincia de Soria, donde el río Alhama excava una profunda garganta entre imponentes farallones de conglomerados y areniscas triásicas de un vivo color rojo. El microclima local permite la presencia de vegetación de influencia mediterránea termófila en las paredes del desfiladero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42063','espacio','Cañón del río Henar y acantilados calizos del castillo','Estrecho pasillo fluvial encajonado entre farallones calizos dolomíticos de gran altura en el extremo oriental de la provincia. La disolución kárstica ha modelado el relieve de las laderas en formas apuntadas, colonizadas por tomillares y vegetación rupícola muy especializada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42064','espacio','Cañón del río Manubles, cueva de la Mora y peñas calizas','Impresionante desfiladero fluvial excavado por el río Manubles sobre las estructuras calcáreas de la Sierra de Deza, ofreciendo farallones rocosos verticales y oquedades de   disolución kárstica. La vegetación del cañón es densa y umbría, con quejigos, encinas y sauces en el fondo aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42065','espacio','Valle del río Almarza y prados húmedos','Pequeña cuenca aluvial de materiales detríticos rodeada de lomas suaves desarboladas. El interés estético reside en el verdor estacional de las praderas del fondo del valle, alimentadas por la escorrentía de las sierras ibéricas septentrionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42068','espacio','Cuenca del río Escalote y campos de la campiña','Topografía monótona y horizontal sobre arcillas y arenas del Terciario, representativa de la llanura central soriana. El interés visual se concentra en el cauce estacional del Escalote, escoltado por tarajes y sauces dispersos que rompen la horizontalidad de la llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42069','espacio','Parque Natural de la Laguna Negra y Circos Glaciares de Urbión, curso alto del río Duero y Pinar Grande','Excepcional escenario alpino de alta montaña silícea constituido por imponentes circos glaciares, bloques de conglomerados gigantescos y canchales bajo las cumbres de Urbión. Alberga el mayor y más denso bosque continuo de pino silvestre (Pinus sylvestris) de Europa, surcado por las aguas torrenciales e impecables del río Duero en su nacimiento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42070','espacio','Sabinar de Cubilla y lomas calcáreas','Extensión septentrional de las plataformas calcáreas que conectan con el sabinar de Calatañazor. El relieve alomado está cubierto por ejemplares dispersos de sabina albar adaptados a suelos esqueléticos, configurando una estampa descarnada de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42071','espacio','Ribera del río Duero, soto de Almarail y cañón del río Rituerto','El río Duero labra a su paso por este término un pasillo fluvial sinuoso escoltado por un bosque de galería bien   conservado de álamos y sauces. El río Rituerto aporta en su desembocadura un tramo encajonado de interés geomorfológico sobre materiales detríticos compactos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42073','espacio','Cumbre del Moncayo (vertiente soriana), cueva de los Murciélagos y nacimiento del río Transmoncayo','Impresionante escenario alpino y glaciar que engloba las cotas más altas del macizo del Moncayo sobre cuarcitas y pizarras paleozoicas. Alberga una notable cavidad natural de origen kárstico profunda y un dosel de vegetación de alta montaña compuesto por piornales y brezales mixtos relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42075','espacio','Cañón del río Añamaza y huertas del valle','Espectacular desfiladero tallado por el río Añamaza sobre calizas del Jurásico que presenta paredes verticales grises de gran potencia visual. La presencia del agua subterránea sostiene un frondoso bosque de galería con sauces y chopos que destaca sobre la aridez del páramo superior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42076','espacio','Desfiladero del río Henar, Sierra de Deza y lomas de yeso natural','Relieve quebrado y de fuerte personalidad geológica constituido por los plegamientos calcáreos de la sierra que encajonan al río Henar. El entorno presenta imponentes taludes de yesos y margas de colores blanquecinos y grisáceos, poblados por comunidades gipsícolas especializadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42078','espacio','Nacimiento del río Duero, Picos de Urbión, Castroviejo y cueva de la Serena','Patrimonio geológico y paisajístico monumental de nivel internacional, donde el paraje de Castroviejo exhibe espectaculares formaciones lapiáceas y bloques de arenisca esculpidos por la erosión eólica y el hielo (formas fantásticas).   El río Duero nace a gran altitud discurriendo entre cascadas y circos glaciares rodeados del mayor bosque continuo de pino silvestre de la península.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42079','espacio','Altos de la dehesa y llanos arcillosos','Paisaje típicamente alomado sobre sedimentos terciarios arcillosos del sur de la provincia. La topografía horizontal ofrece amplias perspectivas visuales donde la vegetación se concentra en pequeñas manchas aisladas de encinar mediterráneo de lento crecimiento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42080','espacio','Desfiladero de la Hoz de Espeja, costras calizas y pinares del río Espeja','Impresionante desfiladero calcáreo angosto con paredes casi verticales de gran altura, modelado por disolución kárstica. El entorno está cubierto por extensas masas de pino silvestre y negral que se asientan directamente sobre el sustrato pedregoso mesozoico, ofreciendo una alta calidad paisajística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42081','espacio','Sierra de Costanazo, canteras de mármol antiguo y pinares de la umbría','Relieve montañoso caracterizado por potentes afloramientos de calizas recristalizadas y dolomías de gran vistosidad cromática. Las laderas septentrionales albergan un denso y frondoso bosque de Pinus sylvestris integrado en el sector norte de la serranía de la Demanda-Urbión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42082','espacio','Sierra de Montes Claros y dehesa de sabinas','Relieve de media montaña caliza en el norte provincial, caracterizado por suelos esqueléticos y pedregosos lavados por la lluvia. Alberga pequeñas comunidades de sabina albar de lento crecimiento y tomillares que le confieren un aspecto estepario severo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42083','espacio','Cuenca del río Izana y llanuras sedimentarias','Topografía horizontal de la campiña central soriana sobre materiales arcillo-arenosos miocenos. El sutil curso del río Izana introduce la única ruptura geomorfológica con pastizales estacionales y ejemplares aislados de chopos que rompen la horizontalidad agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42084','espacio','Valle del río Caracena (tramo medio) y escarpes calcáreos','Pasillo fluvial tallado sobre las plataformas de calizas mesozoicas del sur provincial. El contraste entre los cortados rocosos calizos de las márgenes del valle y el verdor del estrecho fondo aluvial genera una composición paisajística notable y muy equilibrada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42085','espacio','Cuenca del río Cebras y dehesa de quejigos','Relieve ondulado de arenas y arcillas que conecta con las estribaciones de la Sierra de Pobos. Alberga dehesas bien conservadas de quejigo (Quercus faginea) que forman manchas boscosas compactas, controlando la erosión hídrica superficial del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42086','espacio','Paramera de Fuentecambrón y barranco del arroyo de la Vega','Morfología clásica de páramo tabular calizo fuertemente erosionado en sus márgenes, ofreciendo líneas de desprendimientos rocosos y cárcavas. Escasas poblaciones de encinas achaparradas y tomillares cubren el sustrato, ofreciendo una estampa descarnada de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42087','espacio','Llanos de Fuentecantos y arroyo de la dehesa','Geomorfología monótona y horizontal sobre arcillas y arenas terciarias del centro de la provincia. Su interés contempla la pureza de las líneas del horizonte de la   meseta y los pequeños encharcamientos temporales en los prados bajos durante la primavera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42088','espacio','Cuenca del río Nágima y cárcavas de margas','Terreno erosionado de materiales blandos arcillo-margosos donde la escorrentía superficial ha modelado un relieve quebrado con taludes de color blanquecino y ocre. Escasas poblaciones de encinas achaparradas y tomillares cubren el sustrato, ofreciendo una estampa descarnada de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42089','espacio','Sierra de Carcaña (estribación este) y arroyo de la Vega','Zona de contacto entre los sedimentos de la llanura central y las rocas silíceas de la sierra, dando lugar a pequeños afloramientos rocosos cubiertos de matorral aromático. Las laderas presentan dehesas de encina que dan paso a pastizales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42090','espacio','Valle del río Fuentepinilla y dehesa boyal de encina','Suave pasillo fluvial excavado en las plataformas calcáreas y arcillosas del centro-sur soriano. El contraste entre los taludes arcillosos de las márgenes del valle y el verdor del estrecho fondo aluvial genera una composición paisajística notable y muy equilibrada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42092','espacio','Yacimiento geológico de icnitas de Regumiel, cañón del río Alhama y Tierras Altas','Relieve quebrado del norte provincial constituido por areniscas y pizarras del Cretácico que exponen capas geológicas con huellas fósiles de dinosaurios. El paisaje es abrupto y descarnado, con una fuerte personalidad geológica dominada por matorrales de montaña y encinas escarpadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42093','espacio','Barranco del arroyo del campo y estribaciones de la Sierra de Alcarama','Paisaje quebrado caracterizado por procesos de abarrancamiento en laderas arcillo-pizarrosas debido a la acción de tormentas estacionales. Las laderas están colonizadas por matorrales xerófilos calcícolas y cambroneras de gran interés botánico y geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','espacio','Confluencia de los ríos Duero y Tera, y cerro de la Muela de Numancia','Destacadísimo nudo fluvial donde el río Tera vierte sus aguas en el Duero, generando una amplia llanura de inundación con potentes terrazas aluviales. El cerro de la Muela se levanta de forma lineal sobre la vega, ofreciendo una nítida perspectiva geomorfológica del valle del Duero alto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42095','espacio','Monte de Valonsadero (sector oeste), cañón del río Carbonera y Pico Frentes (vertiente sur)','Paisaje que combina el relieve calizo tabular del Pico Frentes con las extensiones arenosas de Valonsadero, pobladas por dehesas maduras de rebollo y encina. El río Carbonera ha excavado un pequeño cañón con formaciones rocosas de interés para la contemplación visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42096','espacio','Campo de Gómara y cuenca alta del río Rituerto','Exponente clásico de la gran llanura cerealista soriana oriental sobre depósitos terciarios completamente horizontales. Su valor radica en la nitidez cromática estacional de la tierra desnuda y la inmensidad del horizonte, apenas interrumpido por sutiles ondulaciones.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42097','espacio','Cerro de Gormaz y ribera del río Duero','Impresionante cerro testigo calcáreo de morfología tabular y laderas escarpadas que se eleva de forma monumental sobre la llanura aluvial del Duero. El río a sus pies aporta una amplia franja verde lineal de sotos y sauces que contrasta vivamente con la aridez del cerro rocoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42098','espacio','Parque Natural del Cañón del Río Lobos, mirador natural de la Galiana (entorno de roca) y sabinar de Herrera','El municipio ocupa una posición central en el monumental cañón calizo, mostrando impresionantes farallones verticales de más de 100 metros de altura esculpidos por la disolución kárstica. En las plataformas superiores se extiende un sabinar albar de altísimo valor botánico que cuelga sobre el abismo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42100','espacio','Paramera de Hinojosa y arroyos estacionales','Paisaje rústico y sumamente llano situado a gran altitud, expuesto a condiciones climáticas extremas que limitan el crecimiento arbóreo. El relieve destaca por su severidad geológica, interrumpida únicamente por sutiles ondulaciones calcáreas y vegetación esteparia xerófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','espacio','Ribera del río Duero (tramo occidental), altos de la dehesa y cerros calizos','Amplio pasillo fluvial modelado por el río Duero a su salida de la provincia, caracterizado por potentes terrazas de cantos rodados y limos. Mantiene un bosque de galería maduro con álamos blancos y sauces que serpentea rompiendo la uniformidad de los páramos calizos colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42105','espacio','Altos de Liceras y barranco del arroyo de la Vega','Relieve de páramo tabular calizo fuertemente erosionado en sus márgenes en el confín sudoccidental de la provincia. Las laderas muestran taludes pedregosos y líneas de desprendimientos rocosos colonizadas por sabinas albares rústicas y matorral aromático.   Losilla (La) (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42106','espacio','Sierra de la Carcaña y cabeceras de arroyos silíceos','Paisaje pre-serrano caracterizado por relieves alomados compuestos por areniscas y pizarras degradadas de la cordillera Ibérica. Las vertientes altas muestran mantos de matorral noble mediterráneo con jarales y brezales de gran homogeneidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42107','espacio','Cañón del río Alhama y relieves quebrados de Tierras Altas','Espectacular garganta fluvial excavada por el río Alhama sobre materiales paleozoicos (pizarras y areniscas) del norte de Soria, mostrando laderas de fuerte pendiente. El entorno presenta una severidad geológica imponente, colonizada por comunidades de matorral de montaña y encinas escarpadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42108','espacio','Altos de Maján y llanadas arcillosas','Monotonía geomorfológica sobre depósitos sedimentarios del Mioceno en el centro-sur soriano. El relieve destaca por su horizontalidad y la pureza de sus líneas, ofreciendo amplias perspectivas visuales apenas interrumpidas por la vegetación arbustiva de las divisorias.   Manzanares de Terraba (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','espacio','Valle del río Jalón, nacimiento del río Blanco, salinas de Arbujuelo y páramo de Medinaceli','Excepcional encrucijada geomorfológica donde las plataformas calcáreas tabulares elevadas se rompen de forma abrupta hacia el valle del Jalón mediante imponentes escarpes de erosión. El término cuenta con surgencias de aguas salobres que dan lugar a ecosistemas halófilos relictos singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42115','espacio','Valle del río Mitón y yacimiento geológico de Ambrona (entorno de la dehesa)','Suave pasillo aluvial tallado sobre las plataformas de calizas mesozoicas del sur de Soria, famoso por sus lagunas kársticas del Pleistoceno fósiles. El fondo del valle mantiene praderas naturales frescas y alineaciones de chopos que contrastan con los encinares aclarados de las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42116','espacio','Vega del río Madre y lomas calizas del somontano','Paisaje geomorfológico dominado por suaves plataformas calcáreas erosionadas que descienden hacia la cuenca del Duero. El fondo del valle alberga comunidades vegetales ripícolas modestas que introducen un vivo contraste lineal frente a los tonos ocres del páramo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42117','espacio','Curso alto del río Duero, embalse de la Cuerda del Pozo y pinares de Urbión','Impresionante entorno forestal y fluvial de la comarca de Pinares, caracterizado por densas masas continuas de Pinus sylvestris. El río Duero discurre limpio sobre lechos de cantos rodados graníticos, conformando un paisaje umbrío de gran pureza y altísimo valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42118','espacio','Lomas de Momblona y campiña arcillosa','Topografía suavemente ondulada sobre depósitos sedimentarios del Mioceno en el entorno de la comarca de Almazán meridional. El interés del relief estriba en la uniformidad de sus formas y los contrastes de luz otoñal sobre las amplias cuencas labradas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42110','espacio','Sierra del Madero (vertiente este) y cuenca del río Somatón','Zona de transición geomorfológica donde los relieves calcáreos de la sierra se hunden bajo los materiales arcillosos del llano de Ágreda. Las laderas presentan una alternancia de pastizales secos, tomillares y pies aislados de encina que ofrecen un paisaje equilibrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42111','espacio','Cuenca del río Izana y Mar de Pinares central','Extensa llanura arenosa de origen continental que alberga masas forestales continuas de Pinus pinaster y Pinus sylvestris de gran valor forestal. El río Izana aporta una ruptura húmeda en el paisaje arenoso, con formaciones de sauces y álamos que rompen la homogeneidad del pinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','espacio','Embalse de Monteagudo y lagunas de la dehesa arcillosa','Interesante humedal catalogado asentado sobre una llanura de arcillas y margas, que constituye un oasis visual en la árida comarca oriental soriana. La lámina de agua está rodeada por un cinturón denso de vegetación palustre (carrizos y espadañas) de alto interés ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42120','espacio','Yacimiento geológico de Tiermes (entorno de areniscas rojizas) y cañón del río Manzanares','Espectacular paisaje geomorfológico dominado por la erosión sobre potentes bancos de areniscas y conglomerados de un vivo color rojizo. El río Manzanares ha excavado un pequeño cañón con paredes verticales donde la vegetación de encinas y sabinas se asienta en las repisas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42121','espacio','Puerto de Santa Inés, curso alto del río Mayor y pinares alpinos','Impresionante escenario de alta montaña ibérica integrado en la Sierra de Urbión, con pendientes que superan los 1.600 metros de altitud sobre sustratos de pizarras. El tapiz vegetal es de una densidad forestal sobrecogedora, dominado por pino silvestre y hayedos umbríos en las vaguadas profundas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42123','espacio','Valle del río Morón y dehesa de quejigos','Suave pasillo aluvial tallado sobre las plataformas de calizas y arcillas mesozoicas del centro-sur soriano. El fondo del valle mantiene praderas naturales   frescas y alineaciones de chopos que contrastan con los quejigares maduros de las laderas pedregosas colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42044','espacio','Paramera de Cabrejas y cuenca del río Moñigón','Paisaje llano de gran altitud situado en la cuenca del Rituerto, caracterizado por una alta exposición a los elementos y suelos pedregosos calcáreos. Muestra una vegetación esteparia rústica y tomillares que reflejan la dureza climática de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42045','espacio','La Fuentona de Muriel (borde sur), cañón del río Avenco y Sabinar de Cabrejas','Impresionante relieve kárstico compuesto por una inmensa plataforma de calizas cretácicas erosionada por el agua, que genera dolinas, simas y lapiaces monumentales. El sabinar albar (Juniperus thurifera) cubre de forma densa el sustrato rocoso, constituyendo un bosque relicto de valor internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42050','espacio','Relieves de la Sierra de Deza y barranco del arroyo de la Vega','Paisaje premontano en el confín oriental de la provincia, caracterizado por lomas de calizas y margas mesozoicas replegadas. Pequeños taludes rocosos y matorrales xerófilos de cambroneras configuran un relieve severo de gran interés geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42124','espacio','Monumento Natural de la Fuentona y Sabinar de Calatañazor','Uno de los monumentos geológicos más impactantes de España, consistente en una surgencia kárstica profunda (ojo de mar) de aguas hipertransparentes que brota de un cañón calizo. El entorno está flanqueado por un bosque relicto de sabina albar (Juniperus thurifera) con ejemplares monumentales milenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42125','espacio','Valle del río Muriel y pinares de la Sierra de Cabrejas','Paisaje forestal umbrío encajonado entre los farallones calizos de la vertiente norte de la Sierra de Cabrejas. El dosel arbolado continuo de pino silvestre cubre por completo el relieve fracturado, generando un ambiente de gran aislamiento visual y pureza acústica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42127','espacio','Paramera de Nafría y barrancos marginales del río Lobos','Relieve severo de páramo calizo tabular fuertemente modelado por procesos de disolución kárstica en superficie (dolinas y campos de lapiaces). La vegetación arbórea es dispersa, reduciéndose a sabinas rústicas que soportan las duras condiciones del páramo pedregoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42128','espacio','Loma de San Miguel y cuenca del río Almarza','Topografía de lomas suaves de naturaleza detrítica situadas al pie de las grandes sierras del norte. La vegetación arbórea es escasa, reduciéndose a encinares aclarados en las zonas altas que controlan la escorrentía superficial del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42129','espacio','Bosque de la Comarca de Pinares, arroyo de Navaleno y roquedos graníticos','Inmensa masa forestal de Pinus sylvestris que tapiza un relieve ondulado de arenas continentales al pie de la Sierra de la Demanda. El dosel forestal es homogéneo y de un verdor infinito, interrumpido únicamente por pequeños afloramientos rocosos y prados húmedos de fondo de valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42130','espacio','Llanuras cerealistas del río Morón','Geomorfología monótona y horizontal sobre arcillas del Mioceno, representativa de la llanura agrícola central de la provincia. Su valor visual estriba en los limpios contrastes cromáticos de la tierra labrada y la nitidez absoluta de la línea del horizonte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42131','espacio','Altos de Nolay y cuenca del río Escalote','Plataforma calcárea elevada expuesta a una intensa crioclastia y erosión eólica que limitan el desarrollo arbóreo. El paisaje destaca por su sobriedad geológica, con una vegetación esteparia rústica que acentúa la sensación de inmensidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42132','espacio','Paramera de Noviercas, lagunas del Campo y escarpe de la Sierra del Moncayo','Extensa llanura de gran altitud situada a la sombra pluvial del macizo del Moncayo, donde se forman pequeñas lagunas endorreicas temporales. El paisaje destaca por su severidad y amplitud visual, ofreciendo una de las perspectivas más limpias de la vertiente occidental del Moncayo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','espacio','Sierra de la Muela, mina de Petra y encinares de Toranzo','Relieve quebrado montañoso de la cordillera Ibérica con potentes afloramientos calizos y cuarcíticos fallados. Destaca el entorno forestal de Toranzo por albergar una masa madura de encinar de montaña adaptada a suelos pedregosos y condiciones climáticas severas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42135','espacio','Puerto de Oncala, cabecera del río Linares y dehesas de Tierras Altas','Paisaje descarnado de alta montaña ibérica caracterizado por lomas aplanadas tapizadas por extensas manchas de matorral de montaña (brezos y piornos). El curso alto del río Linares modela valles de erosión profundos que muestran la severidad geológica de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42139','espacio','Llanos del Campo y arroyo de la Vega','Relieve completamente llano sobre materiales sedimentarios arcillo-arenosos del centro de la provincia. El interés del relieve radica en la uniformidad geomorfológica de la meseta, carente de grandes accidentes topográficos o redes fluviales encajonadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42140','espacio','Paramera alta de Portillo y vertiente del río Henar','Plataforma caliza tabular elevada que marca la separación de cuencas fluviales, expuesta a una intensa erosión eólica. Muestra un paisaje austero desprovisto de árboles, poblado de comunidades esteparias rústicas de gran valor botánico especializado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42142','espacio','Paramera de Pozalmuro y ribera del río Masegoso','Paisaje de páramo calizo tabular donde la disolución kárstica ha modelado un relieve rústico de lapiaces y pequeñas dolinas. El río Masegoso aporta una nota húmeda con alineaciones de chopos que contrastan con los encinares aclarados de las zonas rocosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42144','espacio','Ribera del río Izana, pinares de la dehesa y fuentes calcáreas','Paisaje suavemente ondulado dominado por mantos de arenas continentales que albergan densas masas de pino resinero y pino silvestre. El río Izana aporta un corredor de gran frescura visual, con pequeños depósitos de travertinos musgosos en sus fuentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42145','espacio','Ribera del río Duero y dunas fósiles de la dehesa','Entorno modelado por las terrazas fluviales del Duero y depósitos de arenas eólicas continentales estabilizadas por el pino piñonero. Ofrece un paisaje de gran contraste entre la frondosidad de la vega y la aridez de los llanos arenosos colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42148','espacio','Llanos de la cuenca del río Carabán','Relieve horizontal de la meseta oriental soriana compuesto por sedimentos finos arcillosos del Terciario. El interés paisajístico es netamente contemplativo por la pureza de sus líneas horizontales y la inmensidad del arco celeste.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42149','espacio','Cañón del río Duero, embalse de Los Rábanos y escarpes calizos','Espectacular tramo donde el río Duero excava un profundo cañón sobre las calizas del Cretácico, mostrando meandros encajonados flanqueados por imponentes paredes rocosas de tonalidades grises. Las repisas albergan vegetación rupícola y un denso sotobosque mediterráneo umbrío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42151','espacio','Vertiente sur de la Sierra de Alba y robledales del río Merdancho','Paisaje pre-serrano caracterizado por dehesas maduras y frondosas de roble melojo que tapizan un relieve suavemente alomado. La densidad de la cubierta vegetal y el aislamiento de sus pequeños valles interiores ofrecen una estampa muy representativa de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42152','espacio','Hoces del río Caracena (tramo final) y páramos calizos','El río Caracena corta las plataformas calcáreas tabulares del sur de la provincia antes de unirse al Duero, generando pequeños cortados de roca caliza gris. En las laderas pedregosas se asientan rodales mixtos de sabina albar y encina de lento crecimiento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42153','espacio','Cañón del río Escalote y páramo de Rello','Espectacular paisaje kárstico donde el río Escalote ha excavado un cañón profundo de paredes verticales calizas sobre el páramo soriano meridional. El desfiladero muestra chimeneas de hadas, lapiaces y una vegetación rupícola colgada de las grietas rocosas de altísimo valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42154','espacio','Ribera del río Merdancho y lomas de la dehesa','Terreno de lomas suaves arcillo-arenosas situadas al noreste de la capital provincial. El río Merdancho rompe la topografía agraria introduciendo un corredor verde con chopos, sauces y pastizales húmedos de gran contraste cromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','espacio','Parameras de Retortillo, nacimiento del río Talegones y escarpes de la Sierra de Pela','Impresionante relieve de páramo a gran altitud que se rompe bruscamente hacia el sur mediante los escarpes de la Sierra de Pela. Muestra una severidad geológica notable con una vegetación esteparia y sabinares rústicos expuestos a condiciones climáticas extremas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42156','espacio','Altos de Reznos y estribaciones de la Sierra de la Bigornia','Relieve quebrado de media montaña sobre materiales silíceos y areniscas, caracterizado por una fuerte pendiente de sus laderas. La vegetación dominante es un matorral espeso de jara y brezo con pies aislados de encina de crecimiento lento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42157','espacio','Cañón del río Escalote (tramo medio) y cortados calizos','Continuación del desfiladero excavado por el río Escalote, donde la erosión fluvial y la disolución kárstica muestran paredes de gran altura y abrigos rocosos de gran vistosidad cromática. Las laderas cuentan con una notable densidad de sabinas albares y tomillares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42158','espacio','Valle del río Sequillo y sabinares de la Sierra de Cabrejas (borde sur)','Suave pasillo fluvial flanqueado por las plataformas calcáreas donde se asientan rodales puros de Juniperus thurifera. El contraste entre el verdor del estrecho fondo aluvial y la aridez de los sabinares calizos confiere al paisaje un alto equilibrio estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42159','espacio','Valle de la Vega y dehesas calcáreas de la comarca de El Valle','Entorno paisajístico muy fresco y húmedo, protegido por los relieves montañosos del norte. Destaca por sus praderas naturales perennes flanqueadas por setos vivos de quejigos y vegetación de ribera de un alto valor botánico y frescura visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42160','espacio','Sierra de Car things (Cebollera sur), cascada de la Chorrera y ribera del Duero','Excepcional entorno alpino caracterizado por laderas cubiertas de densos bosques de pino silvestre y robledales que ascienden hacia las cumbres del macizo de Cebollera. La cascada de la Chorrera vierte sus aguas cristalinas en un paraje de roquedo granítico de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42161','espacio','Curso alto del río Duero y pinares de umbría','Paisaje fluvial típicamente serrano donde el río Duero discurre encajonado entre bloques graníticos y terrazas boscosas. Las laderas están tapizadas por completo por una masa forestal continua e imponente de Pinus sylvestris que genera una atmósfera de gran aislamiento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','espacio','Ribera del río Duero, sotos de la dehesa y escarpes de arenisca','Amplio corredor fluvial modelado por el río Duero, flanqueado por escarpes de areniscas rojizas que muestran formas de erosión alveolar. Mantiene un bosque de galería muy maduro con álamos blancos y sauces que rompe la monotonía del paisaje de la ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42163','espacio','Cañón del río Alhama y relieves de la Sierra de Alcarama','El río Alhama labra a su paso por este término un pasillo angosto flanqueado por formaciones calcáreas fracturadas de gran vistosidad geológica. La cobertura vegetal está dominada por matorrales xerófilos y sabinas que se adaptan a las superficies rocosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42164','espacio','Parque Natural del Cañón del Río Lobos (borde norte) y pinares de Navaleno-San Leonardo','Impresionante paisaje donde las gruesas plataformas calizas cretácicas sustentan una de las masas de Pinus sylvestris más densas de la península. El relieve se quiebra en sus márgenes meridionales anunciando los primeros y monumentales desfiladeros calcáreos del cañón del río Lobos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42165','espacio','Valle del río Linares, desfiladero de San Pedro y dehesas de robles','Paisaje descarnado y quebrado típico de Tierras Altas, donde el río Linares ha excavado una profunda garganta sobre calizas y areniscas mesozoicas. Las laderas expuestas muestran perfiles erosivos muy acusados, mitigados de forma aislada por dehesas de quejigos y melojos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42166','espacio','Sierra de Cameros (vertiente soriana), curso alto del río Baos y hayedos de la umbría','Paisaje silíceo de alta montaña caracterizado por la presencia de pequeños arroyos torrenciales de aguas cristalinas. Las laderas orientadas al norte albergan rodales maduros de Fagus sylvatica y abedulares que configuran un oasis botánico umbrío de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42168','espacio','Parque Natural del Cañón del Río Lobos (interior) y pinar de las Hoyas','El término se integra plenamente en el sector central del cañón, mostrando espectaculares cortados calizos de más de 100 metros de altura, cuevas naturales y campos de dolinas. Las parameras superiores están densamente pobladas por sabina albar y pino laricio de gran singularidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42167','espacio','Ribera del río Jalón y parameras de la Sierra de Solorio','Amplio pasillo fluvial en el extremo oriental de la provincia donde el río Jalón divaga sobre una llanura aluvial flanqueada por los imponentes frentes calizos del páramo.   Destaca la vegetación de ribera y los perfiles escarpados de las lomas calcáreas que delimitan el valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42171','espacio','Valle del río Nágima y cárcavas arcillosas de la campiña','Geomorfología caracterizada por lomas arcillomargosas del Terciario sometidas a una intensa erosión hídrica en forma de cárcavas y abarrancamientos de color rojizo. La escasez arbórea resalta la plasticidad y las formas del relieve modelado por la escorrentía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42172','espacio','Altos de Soliedra y arroyo de la dehesa','Relieve alomado de materiales sedimentarios arcillosos con escasa cobertura arbórea, representativo de la penillanura cerealista del sur soriano. Su interés radica en la pureza de las líneas del horizonte y la nitidez de los contrastes cromáticos de la tierra labrada según la estación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','espacio','Monte Valonsadero, cañón del río Duero (San Saturio) y Sierra de Santa Ana','Extraordinario patrimonio geomorfológico que cuenta con Valonsadero, un paisaje de areniscas esculpidas por la erosión con dehesas comunales de rebollo. Aguas abajo, el Duero se encajona entre los imponentes farallones calizos de la Sierra de Santa Ana, conformando una estampa de gran fuerza visual y botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42174','espacio','Sierra de Cebollera, nacimiento del río Razoncillo y hayedos de la umbría','Excepcional entorno de alta montaña silícea dominado por circos glaciares degradados y lagunas glaciares estacionales. Las laderas orientadas al norte exhiben bosques mixtos de hayas, pinos silvestres y acebedos hiperhúmedos de un valor botánico y contemplativo extraordinario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42176','espacio','Paramera de Tajahuerce y arroyo de la Vega','Paisaje típicamente plano del centro de la provincia desarrollado sobre arcillas y caliches del Terciario. El interés estético reside en las amplias cuencas visuales hacia las sierras del norte y el modelado suave de sus laderas agrícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42177','espacio','Pinares de Tajueco y cuenca del río Duero (tramo medio)','Terreno arenoso ondulado integrado en la comarca de la Comunidad de Villa y Tierra de Almazán, cubierto por pinos resineros de alta densidad. El dosel forestal continuo protege los suelos sueltos de la erosión eólica, conformando un paisaje forestal homogéneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42178','espacio','Sabinar de Talveila, cañón del río Chico y Sierra de Cabrejas','Destaca por albergar un sabinar albar (Juniperus thurifera) excelentemente conservado sobre las plataformas calizas de la sierra. El río Chico ha labrado un pequeño desfiladero con lapiaces y formaciones de disolución kárstica de gran interés geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42181','espacio','El Mar de Pinares de Tardelcuende y ribera del río Izana','Inmensa llanura arenosa que alberga una de las masas forestales continuas de pino resinero más densas y aprovechadas históricamente para la resina. El río Izana introduce una ruptura lineal de gran frescura visual con formaciones de sotos y praderas húmedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42182','espacio','Altos de Taroda y cuenca del río Escalote','Relieve alomado constituido por materiales arcillosos sometidos a procesos de erosión laminar en el sur de la provincia. La vegetación arbórea es escasa, reduciéndose a encinares aclarados en las zonas altas que controlan de forma modesta la escorrentía del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42183','espacio','Ribera del río Rituerto y lomas de la dehesa','Paisaje de campiña ondulada desarrollado sobre arcillas y areniscas terciarias del centro-sur soriano. El cauce del río Rituerto aporta una franja húmeda con formaciones de sauces que rompen la homogeneidad del paisaje de cultivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42184','espacio','Barranco del río Carabán y cárcavas de yeso de Torlengua','Singular relieve quebrado donde la erosión ha modelado taludes blanquecinos y cárcavas profundas sobre potentes estratos de margas y yesos del Terciario. Presenta comunidades vegetales gipsícolas altamente especializadas de gran interés botánico y visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42185','espacio','Sabinar de Torreblacos y arroyo del Val','Pequeño pasillo fluvial excavado en las plataformas calcáreas donde se desarrollan pies dispersos de sabina albar de lento crecimiento. El contraste entre los cortados rocosos calizos de las márgenes del valle y el verdor del arroyo genera una composición notable.   Torremediana   (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42187','espacio','Paramera de Torrubia y llanos del Campo Gómara','Relieve extremadamente horizontal representativo de la llanura cerealista del Campo de Gómara sobre sedimentos arcillosos. Su interés radica en la inmensidad del paisaje y la nitidez de los contrastes cromáticos de la tierra labrada según la estación del año.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42188','espacio','Sierra de Madero, barranco del río Manzano y dehesa de encina','Relieve montañoso de la cordillera Ibérica sobre materiales silíceos y calizos que configuran una topografía de fuertes pendientes. El barranco presenta una vegetación umbría que contrasta con los encinares xerófilos y los matorrales de jara de las laderas expuestas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42189','espacio','Entrada monumental al Parque Natural del Cañón del Río Lobos, nacimiento del río Ucero y canal del albergue','Uno de los hitos paisajísticos más espectaculares de Soria, donde el río Lobos confluye con el Ucero rompiendo las gruesas plataformas calizas mediante farallones verticales de más de 120 metros de altura. Cuenta con espectaculares surgencias kársticas, cavidades naturales e imponentes masas de sabina albar colgadas del vacío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42190','espacio','Pinares de Vadillo y estribaciones de la Sierra de Cabrejas','Paisaje plenamente forestal caracterizado por un relieve de arenas y calizas cubierto por masas densas y continuas de pino silvestre. El dosel arbolado genera una atmósfera de gran aislamiento y pureza natural, interrumpida por pequeños afloramientos de roquedo calizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42191','espacio','Valle del río Tera, vertiente sur de la Sierra de Cebollera y acebales de la dehesa','Impresionante paisaje de montaña silícea que tapiza la comarca de El Valle con un dosel forestal continuo de melojos y acebedos. El río Tera modela un valle de gran frescura con praderas naturales perennes y setos vivos de gran equilibrio botánico y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42192','espacio','Sierra del Madero (estribación oeste) y cabeceras del río Rituerto','Relieve de media montaña con laderas suaves labradas sobre materiales calizos degradados de la Sierra del Madero. El paisaje destaca por su severidad y amplitud visual, ofreciendo extensas panorámicas interrumpidas por encinares de montaña aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42193','espacio','Relieves de la Sierra de Moncayo occidental y barranco del agua','Escenario de transición geomorfológica caracterizado por relieves quebrados de calizas y margas mesozoicas que descienden del macizo del Moncayo. Pequeños riachuelos temporales sostienen franjas verdes que rompen la aridez de las laderas pedregosas colindantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42194','espacio','Parque Natural del Cañón del Río Lobos (sector oriental) y ribera del río Ucero','Comparte el patrimonio geológico del cañón del río Lobos, mostrando un relieve de cortados y farallones calizos grises esculpidos por la disolución kárstica. El fondo aluvial presenta sotos de chopos y álamos que aportan un contraste verde lineal de gran belleza estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42195','espacio','Sabinares de Valdenebro y cuenca del río Duero (tramo medio)','Plataforma calcárea horizontal donde el suelo es escaso y afloran costras calcáreas lavadas por la escorrentía, sustentando un bosque puro de sabina albar (Juniperus thurifera). El paisaje destaca por su severidad geológica y el alto valor botánico de sus ejemplares centenarios.   Valdegeña (.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42196','espacio','Valle del río Alhama y relieves de las Tierras Altas orientales','Relieve quebrado y abrupto caracterizado por lomas formadas por calizas y areniscas sometidas a procesos de erosión laminar muy acusados. La vegetación se limita a matorrales rústicos de cambroneras y tomillares que acentúan la fuerza visual de la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42197','espacio','Valle del río Sequillo y dehesas calcáreas','Suave pasillo fluvial excavado en las plataformas calcáreas del sudoeste provincial. El contraste entre los cortados rocosos calizos de las márgenes de la dehesa y el verdor del arroyo genera una composición paisajística notable y muy equilibrada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42198','espacio','Altos de Valtajeros y estribaciones de la Sierra de Alba','Paisaje severo de alta montaña ibérica a más de 1.200 metros de altitud, expuesto a condiciones climáticas extremas que limitan el crecimiento forestal. El relieve destaca por su desnudez geológica, interrumpida únicamente por matorrales de montaña y pastizales secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42200','espacio','Escarpes del río Duero y páramos de Velamazán','Tramo donde el río Duero corta los materiales calcáreos de la meseta meridional, abriendo un valle   escoltado por farallones de roca caliza y lomas arcillosas. En las laderas se asientan comunidades de encina y matorral mediterráneo adaptadas al suelo pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42201','espacio','Cuenca del río Merdancho y cerros testigo','Conjunto de pequeñas elevaciones calcáreas erosionadas que rompen la penillanura soriana central, aislando pequeñas vaguadas interiores. Las laderas están colonizadas por tomillares y encinares degradados de gran valor aromático y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42204','espacio','Ribera del río Duero (tramo medio soriano) y llanos agrícolas','Paisaje plano constituido por terrazas aluviales de cantos rodados y limos acumulados por la dinámica del río Duero. El río introduce un pasillo verde arbolado que serpentea rompiendo la uniformidad geomorfológica de la planicie del centro de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42205','espacio','Sierra de Cabrejas, pico Frentes y sabinares de Villaciervos','Impresionante relieve calizo tabular que culmina en el pico Frentes, un hito geomorfológico con un frente de escarpe calizo muy espectacular. El término alberga densas masas de sabina albar de gran valor botánico asentadas sobre suelos calcáreos esqueléticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42206','espacio','Páramo de Gormaz y vaguadas del arroyo de la Vega','Relieve tabular calizo sometido a procesos de desmantelamiento erosivo, originando una topografía de cerros aplanados y laderas pedregosas. La vegetación está dominada por tomillares y sabinas dispersas adaptadas a las severas condiciones de insolación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42207','espacio','Sierra de Carcaña, dehesa de robles y nacimiento del río Tera','Entorno pre-serrano dominado por materiales silíceos de la cordillera Ibérica, donde se desarrolla una dehesa muy densa y madura de roble melojo (Quercus pyrenaica). El relieve quebrado cuenta con pequeños arroyos de aguas limpias y canchales graníticos que aportan una gran riqueza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42202','espacio','Altos de Velilla y llanos de Campo Gómara','Geomorfología monótona y horizontal sobre arcillas miocenas representativa de la meseta cerealista oriental des nuda. Su interés radica en la pureza de las líneas del horizonte y los contrastes de luz sobre el suelo labrado según la estación del año.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42208','espacio','Praderas del arroyo de la Vega y lomas del somontano del Moncayo','Paisaje de transición caracterizado por relieves suaves y alomados sobre materiales fundamentalmente detríticos y arcillosos. La modesta cuenca fluvial estacional rompe la uniformidad con pastizales secos y pequeños reductos aislados de matorral mediterráneo rústico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42209','espacio','Cañón del río Cidacos, yacimientos paleoicnológicos y escarpes de las Tierras Altas','Paisaje geomorfológico espectacular de las Tierras Altas sorianas, donde el río Cidacos ha excavado profundas gargantas sobre calizas y caliches del Cretácico. El interés contemplativo destaca por sus impresionantes perfiles rocosos descarnados, sus estratificaciones desnudas y la presencia de icnitas de dinosaurio fosilizadas en la propia roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42211','espacio','Sierra de San Juan y dehesa del Tera (zona sur)','Relieve alomado que marca la transición entre la llanura central y las montañas del norte soriano. Cuenta con vertientes suaves cubiertas por pastizales de montaña y encinares aclarados que ofrecen una visual limpia y equilibrada del somontano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42212','espacio','Páramos de Villasayas y nacimiento del río Torete','Paisaje sumamente severo de páramo tabular calizo a gran altitud, expuesto a una intensa erosión eólica y crioclastia. La vegetación está dominada por sabina albar rústica y tomillares xerófilos calcícolas, configurando una estampa descarnada de gran fuerza geológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42213','espacio','Paramera de Arciel y campos de la dehesa','Geomorfología monótona y horizontal sobre arcillas miocenas representativa de la meseta cerealista oriental. Su interés contemplativo radica en la pureza de las líneas rectas del horizonte y en los nítidos contrastes cromáticos de la tierra labrada según los ciclos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','espacio','Parque Natural de la Laguna Negra y Circos Glaciares de Urbión, curso alto del río Duero','Uno de los escenarios de alta montaña alpina y modelado glaciar más majestuosos del Sistema Ibérico, caracterizado por impresionantes paredes de cuarcita gris, circos y lagunas de origen glaciar. Las laderas están tapizadas   por un imponente y continuo dosel forestal de pino silvestre (Pinus sylvestris) centenario, surcado por arroyos torrenciales cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42216','espacio','Tierras Altas de Soria y dehesa de robles de Villaseca bajera','Paisaje abrupto y descarnado de montaña caliza perteneciente a la comarca de las Tierras Altas. Muestra laderas fuertemente erosionadas donde la vegetación se concentra en dehesas mixtas de quejigo y robledales que resisten el clima continental extremo de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42217','espacio','Nacimiento del río Queiles, Moncayo soriano y cañón del Queiles','Alberga el espectacular nacedero kárstico del río Queiles, una surgencia de agua monumental donde el agua brota a borbotones directamente de una gran oquedad en la base de la roca caliza del Moncayo. El río discurre encajonado de inmediato en un desfiladero umbrío flanqueado por quejigos, sauces y avellanos de gran vistosidad botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','espacio','Valle del río Cidacos (tramo norte) y monte de hayas y pinos','Garganta fluvial profunda excavada por el río Cidacos al norte de las Tierras Altas, en el límite con La Rioja. El relieve presenta vertientes empinadas de areniscas y calizas cubiertas por bosques mixtos donde los pinos silvestres conviven con reductos umbríos de hayas y matorrales nobles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42219','espacio','Cerros testigo de Yelo y cárcavas del arroyo de la Vega','Conjunto de pequeñas elevaciones calcáreas fuertemente erosionadas que sobresalen de forma prominente en la llanura sedimentaria bardeada. Las laderas muestran   taludes de margas blanquecinas y canchales calcáreos colonizados por matorrales aromáticos de gran interés geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','espacio','Alcornocales de las Montañas de Prades. Descubren una masa forestal singular de Quercus suber asentada sobre suelos silíceos excepcionales para la provincia. Su valor botánico radica en el contraste c','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90731','espacio','Niu de l''Àliga. Poza natural de aguas cristalinas alimentada por el río Glorieta, encajonada en un anfiteatro calizo calcificado. Destaca por sus formaciones de toba calcárea y la cascada que vierte e','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43015','espacio','Gorgs del Riu Arbolí. Sucesión de pozas profundas y marmitas de gigante esculpidas de forma continua sobre la roca sedimentaria. La erosión fluvial ha generado un microambiente húmedo de alto valor co','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43025','espacio','Coves de Meravelles. Complejo kárstico subterráneo con una densidad extraordinaria de espeleotemas excéntricos, estalactitas y estalagmitas. Destaca geológicamente por la abundancia de formaciones mac','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43040','espacio','Paraje Kárstico de la Vall de la Llena. Desfiladero flanqueado por colosales paredes calizas con caprichosas formas de aguja debidas a la disolución meteórica. Presenta una vegetación de umbría que co','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43045','espacio','Cova del Llamp y faldas de la Mola. Fractura tectónica y oquedad natural abierta en la mole caliza calva que domina el paisaje. Su interés radica en la imponente morfología del relieve de cuesta y el ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43049','espacio','Riscos de Siurana y desfiladero del río Siurana. Impresionantes acantilados verticales de calizas dolomíticas de tonalidades rojizas y ocre que caen a plomo sobre el cauce fluvial. Un relieve tabular ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43104','espacio','Cova de les Calobres. Oquedad natural de origen kárstico situada en un entorno semiárido calcáreo con un desarrollo interno notable de formaciones litoquímicas primitivas. Su interés reside en su morf','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43057','espacio','Els Avencs de la Febró. Gran grieta tectónica abierta en la roca de unos 250 metros de longitud y hasta 30 metros de profundidad. Su microclima interno alberga formaciones vegetales de umbría y musgos','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43124','espacio','Estrechos del Río Brugent. Angosto desfiladero fluvial donde el río ha excavado paredes verticales de roca caliza del Triásico. Destaca por la pureza de sus aguas calcáreas y las formaciones tobáceas ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90918','espacio','Desfiladero de las Calzadas y Congost de Margalef. Cañón escarpado excavado por el río Montsant en potentes bancos de conglomerados oligocenos de formas redondeadas. Su fisonomía geológica es singular','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43091','espacio','Fuentes del río Glorieta y Forat de la Micola. Nacimiento fluvial en un entorno kárstico abrupto caracterizado por surgencias intermitentes y una enorme oquedad rocosa natural. El relieve abrupto gene','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43102','espacio','Nacimiento de San Roque y anfiteatro de Els Ports. Impresionante circo rocoso semicircular de calizas jurásicas donde   brotan múltiples fuentes de agua limpia. La verticalidad del relieve y la frondo','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43116','espacio','Roca Foradada. Monumental formación geológica esculpida por la erosión eólica e hídrica sobre areniscas rojas del Triásico (Buntsandstein). El arco natural resultante enmarca el paisaje forestal circu','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43117','espacio','Estrechos de la Fontcalda (tramo compartido). Angosto cañón fluvial labrado por el río Canaletes entre imponentes paredes de caliza jurásica calada. Destaca visualmente por el fuerte modelado kárstico','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43133','espacio','Barranco de Lloret y crestas de Els Ports. Profundo tajo montañoso flanqueado por murallones calcáreos y escarpadas agujas de roca caliza en pleno macizo montañoso. Alberga formaciones botánicas de pi','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43150','espacio','Barranco de la Foig. Estrecho desfiladero y chimenea kárstica natural con paredes verticales pulidas por las avenidas torrenciales de agua. Ofrece una espectacular morfología de cañón seco con estrato','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43155','espacio','Coll de Redó y Barranco de la Galera. Cuenca de recepción torrencial con un relieve abrupto de bloques fallados y laderas cubiertas de palmitos, la única palmera autóctona europea. Geológicamente mues','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43156','espacio','Sierra de Montsià (Vertiente de roca desnuda). Vertiente montañosa abrupta dominada por el modelado kárstico superficial (lapiaces y canchales) orientada hacia el Delta del Ebro. Destaca por su geomor','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43162','espacio','Cova del Llop Marí. Cavidad marina excavada por la acción constante del oleaje en los acantilados rocosos de la costa del municipio. Presenta una galería inundada con una playa interior de guijarros i','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43169','espacio','Riscos de la Mussara. Impresionantes escarpes calizos verticales que delimitan de forma abrupta la meseta de las Montañas de Prades. Destacan por sus caprichosas formas erosivas de aguja y los fenómen','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43177','espacio','Pas de l''Ase (Desfiladero del Ebro). Estrechamiento natural del río Ebro al abrirse paso de forma violenta a través de la cordillera Prelitoral Catalana. El contraste entre la gran masa de agua en mov','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','espacio','Pinares de Rodeno. Formación boscosa resinera asentada sobre un espectacular relieve de areniscas rojas continentales del Pérmico-Triásico. La meteorización ha modelado callejones de roca, bloques caó','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90874','espacio','Sima de la Moheda. Cavidad de origen kárstico con una gran boca vertical abierta en la roca caliza del Maestrazgo. Destaca por su geomorfología de colapso estructural y por albergar un microclima umbr','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','espacio','Salada de Alcañiz. Complejo endorreico de lagunas salobres estacionales ubicadas en una cuenca de evaporación bajo un clima semiárido. Presenta costras de sal brillantes sobre el sustrato margoso y co','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44017','espacio','Parque Geológico de Aliaga (Pliegues y Porche). Impresionante registro de pliegues en abanico, cabalgamientos y estratos verticales de calizas cretácicas expuestos por la erosión fluvial. Considerado ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44022','espacio','El Castelillo y lapiaces de arcilla. Formaciones erosivas de badlands donde las arcillas y yesos oligocenos han sido abarrancados de forma extrema por las aguas torrenciales. Ofrece un paisaje desnudo','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44033','espacio','El Arguilay. Barranco encajonado donde la disolución kárstica y las surgencias de agua han creado grandes depósitos de toba calcárea. El agua ha esculpido pequeñas cascadas fósiles adosadas a la roca ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','espacio','El Parrizal (Estrechos del río Matarraña). Desfiladero fluvial donde el río se encajona en paredes calizas verticales de más de 60 metros de altura y apenas un par de metros de ancho. Destaca por sus ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44052','espacio','Cascada Batida de Calomarde. Impresionante salto de agua del río Blanco que cae sobre una gigantesca formación de toba calcárea y musgo. La acumulación continua de carbonatos ha generado bóvedas y cav','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','espacio','Muela de Cantavieja y cantiles calizos. Relieve tabular imponente delimitado por acantilados escarpados de caliza cretácica que caen a plomo sobre el valle. Destaca por su geomorfología estructural de','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','espacio','Monumento Natural de los Órganos de Montoro. Colosales agujas y estratos calcáreos del Cretácico que la tectónica levantó verticalmente simulando los tubos de un órgano gigante. La erosión diferencial','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44092','espacio','Estrechos del río Ebrón. Profundo cañón calizo labrado por la acción fluvial con paredes verticales extraplomadas que impiden la entrada directa del sol. El fondo del desfiladero destaca por la pureza','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44103','espacio','Sabinar de la Umbría del río Mijares. Masa forestal densa y relicta de Juniperus thurifera (sabina albar) que coloniza suelos esqueléticos calizos a gran altitud. Son ejemplares centenarios adaptados ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44109','espacio','Nacimiento del río Tajo. Surgencia hídrica en un entorno de alta montaña donde el agua brota de un acuífero kárstico entre pastizales alpinos y pinares de pino albar. La cubeta   geomorfológica inicia','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44114','espacio','Coveta del Agua. Cavidad freática con un desarrollo horizontal notable que alberga una gran densidad de formaciones de estalactitas y goteos activos. Su interés radica en la pureza de sus depósitos ca','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44115','espacio','Yacimiento geológico de ribera y meandros del Alfambra. Formaciones sedimentarias continentales del tránsito JurásicoCretácico expuestas por el encajamiento del río Alfambra. Visualmente destaca por l','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44121','espacio','Cañada de la Virgen y faldas de peña Selva. Valle glaciar y kárstico colgado de alta montaña con un relieve descarnado calizo rodeado de masas de pino negro. Presenta formaciones de lapiaces gigantes ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','espacio','Barranco del Regallo. Tajo erosivo excavado sobre materiales yesíferos y margosos del terciario que muestra una marcada estratificación evaporítica. El paisaje es de una aridez extrema, destacando los','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44126','espacio','Barranco de las Calzadas. Garganta abrupta de origen tectónico y fluvial que corta las muelas calcáreas del Maestrazgo. Presenta un relieve escarpado con fracturas limpias en la roca donde se asientan','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44135','espacio','Peñas de Libros y escarpes del Turia. Formaciones de yesos y arcillas rojas con estratos completamente verticales labrados por el río Turia. El paisaje destaca por el violento contraste cromático entr','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44137','espacio','El pino del Escobón y el barranco de las Umbrías. Paraje que alberga un pino laricio monumental de dimensiones extraordinarias insertado en un cañón de umbría húmeda. Geobotánicamente destaca por la c','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44143','espacio','Nacimiento del río Paraíso y Gavilanes. Manantial kárstico de aguas termales subordinadas que brota con fuerza entre bloques calcáreos fracturados. El entorno está flanqueado por altas paredes de aguj','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','espacio','Muela de Monchén (Vertiente norte). Imponente frente de ladera escalonado por potentes bancos de calizas marinas del Cretácico. Visualmente muestra de forma nítida la estructura de la plataforma caliz','','inventario_naturaleza_pdf');
