INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44191','espacio','Llanos de yesos de la Venta de la Pintada. Planicie esteparia dominada por afloramientos de yesos terciarios con micro-relieves de lapiaces evaporíticos. Su valor es puramente paisajístico por la refr','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44201','espacio','Fosa tectónica y ribera del río Rubielos. Cuenca de sedimentación lacustre del Mioceno que muestra capas finamente estratificadas ricas en materia orgánica y restos vegetales fósiles. El relieve circu','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44206','espacio','Pozo de la Fonseca y Estrechos del río Maimona. Cañón calizo estrecho donde las aguas limpias del río se estancan en una   poza profunda rodeada de paredes verticales cubiertas de hiedras silvestres. ','','inventario_naturaleza_pdf');
