INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44238','espacio','Crestones de las Parras de Martín (Hocino del Pajazo). Tajo fluvial estrecho que corta transversalmente una alineación de estratos calcáreos verticales cretácicos. Alberga una cascada y una poza encaj','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','espacio','Crestas de la Caixa y desfiladero del Tastavins. Singular formación rocosa de conglomerados terciarios con forma de cofre o caja que domina el horizonte debido a la erosión diferencial. Sus laderas mu','','inventario_naturaleza_pdf');
