INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44260','espacio','Cañón del río Guadalope y Puente de la Fonseca. Monumental desfiladero de paredes calizas escarpadas donde el agua ha excavado un arco natural de toba calcárea (puente natural). El entorno combina una','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44263','espacio','Santuario de Peñalba (Formación rocosa). Crestón escarpado de calizas y margas erosionadas que presenta   oquedades naturales y lapiaces fruto de la disolución meteórica. Su perfil aserrado destaca vi','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44264','espacio','Cascadas y cañón del Barranco del Tranco. Estrecho y sinuoso desfiladero arcilloso-calcáreo excavado por avenidas torrenciales, caracterizado por sus paredes verticales pulidas. Cuenta con resaltos pé','','inventario_naturaleza_pdf');
