INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46038','espacio','Barranco de la loba y picos calizos. Desfiladero abrupto rodeado de crestas calcáreas jurásicas colonizadas por ejemplares dispersos de sabina albar. Su interés contemplativo radica en la severidad de','','inventario_naturaleza_pdf');
