INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46099','espacio','Muela de Cortes y los Chorradores de Otonel. Impresionante relieve tabular calizo cortado a plomo por el cañón del Júcar, del que emanan numerosas cascadas estacionales (Otonel) que salvan desniveles ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46115','espacio','Cañón del río Júcar y laderas de la Muela de Dos Aguas. Desfiladero fluvial de dimensiones tectónicas caracterizado por paredes de caliza gris desnudas y bloques caóticos caídos por colapso gravitator','','inventario_naturaleza_pdf');
