INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46133','espacio','Peña María y garganta del río Turia. Monumental mole caliza vertical que domina el cauce del río Turia a modo de espolón alpino. El entorno presenta fuentes kársticas de gran caudal como los "Ojos del','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46142','espacio','Cueva de Don Juan. Cavidad kárstica situada en los cañones del Júcar con un desarrollo interior excepcional de espeleotemas activos (estalactitas, estalagmitas y columnas). Destaca por la pureza de su','','inventario_naturaleza_pdf');
