INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50221','espacio','Barranco de la Virgen y muelas calcáreas del Parque Natural del Moncayo. Impresionante cañón de alta montaña caracterizado por un relieve de muelas calizas fracturadas y desfiladeros kársticos rudos. ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','espacio','Meandro de Melero del Ebro (Meandro de Sástago). El meandro encajonado más espectacular de la cuenca del Ebro,   donde el río describe una curva cerrada de casi 360 grados esculpida sobre una platafor','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','espacio','Circo de San Miguel y cumbres de cuarcita del Moncayo. Impresionante anfiteatro de origen periglacial y de desmantelamiento gravitatorio tallado sobre las duras cuarcitas paleozoicas de la cumbre del ','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50250','espacio','Barranco de Valdeherrera y Peñas de Herrera. Alineación de espectaculares torreones y escarpes calizos que simulan las ruinas de un castillo medieval debido a la intensa erosión diferencial. El reliev','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','espacio','Galacho de Juslibol y escarpe de yesos de Alfocea. Singular meandro abandonado originado en la gran inundación de 1961, flanqueado de forma imponente por un colosal farallón vertical de yesos y margas','','inventario_naturaleza_pdf');
